local fs = require("@lune/fs")
local luau = require("@lune/luau")
local hasSerde, serde = pcall(require, "@lune/serde")
local hasNet, net = pcall(require, "@lune/net")
local lune_task = select(2, pcall(require, "@lune/task"))
local REAL_START_CLOCK = os.clock()
-- DateTime values need millisecond precision but must remain stable across a
-- tight pcall loop.  Anchor a real Unix epoch once, then advance it from the
-- monotonic process clock rather than repeatedly rounding os.time() to seconds.
local DATETIME_EPOCH_MILLIS = os.time() * 1000
local TIMEOUT_SECONDS = 60
local args = process.args
local dumperState
local flushPartialOutput
local AUTOFLUSH_LINES = 200

local inputKey = args[3] or "NoKey"
local DEBUG_MODE = args[4] == "true"
local ALLOW_INF_LOOPS = args[5] == "true"
local RECONSTRUCT_MODE = args[6] == "true"
local HOOKOP_MODE = args[7] == "true"
local PREDEFINE_ARG = args[8] or ""
local RUNTIME_LOGS = args[9] == "true"
