local check_timeout
do
    -- [v1.6] besides the wall-clock limit, stop gracefully (and save the partial dump) when the live Lua heap
    -- passes ~2 GiB: a script spinning with ALLOW_INF_LOOPS used to grow until the OS killed the process
    local _cg, _calls, _next, _limitKb = collectgarbage, 0, 4096, 2048 * 1024
    check_timeout = function()
        local reason
        if (os.clock() - REAL_START_CLOCK) >= TIMEOUT_SECONDS then
            reason = "Execution exceeded " .. tostring(TIMEOUT_SECONDS) .. " seconds; partial dump saved."
        else
            _calls = _calls + 1
            if _calls >= _next then
                _calls, _next = 0, 4096
                local okc, kb = pcall(_cg, "count")
                if okc and type(kb) == "number" and kb > _limitKb then
                    pcall(_cg, "collect") -- garbage is not live data: only a heap that survives a full collection counts
                    okc, kb = pcall(_cg, "count")
                    if okc and type(kb) == "number" and kb > _limitKb then
                        reason = "Memory limit reached (" .. tostring(math.floor(kb / 1024)) .. " MB); partial dump saved."
                    else
                        _next = 65536
                    end
                end
            end
        end
        if reason then
            if dumperState and not dumperState.limit_reached then
                dumperState.limit_reached = true
                if flushPartialOutput then
                    pcall(flushPartialOutput, reason, true, true)
                end
            end
            -- process.exit(0) cannot be caught by pcall/xpcall unlike error().
            -- env-check scripts detect the sandbox and enter a crash loop inside
            -- nested pcalls; error() just gets absorbed there, process.exit() does not.
            process.exit(0)
        end
    end
end

local debugLibrary = debug
-- Capture this script's own path/directory now (before debug/getfenv are
-- overridden) so HookOP can locate the bundled patched-Lune binary +
-- `hookop.luau` next to envlogger regardless of the process working directory.
local _selfScriptPath = (select(2, pcall(function() return debugLibrary.info(1, "s") end)))
local _selfScriptDir = (type(_selfScriptPath) == "string" and _selfScriptPath:match("^(.*[/\\])")) or nil
local rawGetfenv = getfenv -- real getfenv, captured before _G.getfenv is overridden
local rawSetfenv = setfenv -- real setfenv, captured before _G.setfenv is overridden.
                           -- Lune's native setfenv DOES rebind a Luau closure's
                           -- environment (verified), so calling it makes setfenv
                           -- observably take effect (dtc89/dtc90) instead of the
                           -- old debug.setupvalue path, which is dead code under
                           -- Lune (debug only exposes info/traceback).

-- ===========================================================================
-- Patched-Lune VM primitives (see lune-fork). The patched runtime exposes
-- executor-grade primitives (in-place closure replacement, proto/constant/
-- upvalue read+write) on the writable `_G` table as `_G.lvm`. They are exactly
-- what we need to patch detections universally -- but if the *analyzed*
-- (hostile) script could reach them it would be a sandbox escape: unfiltered
-- closure-walking leaks the host fs/process/net libraries the dumper captures
-- (-> source / host file disclosure), and replaceclosure/setconstant let it
-- tamper with the dumper's own closures. So we capture them into a private
-- `_vm` here and delete `_G.lvm` before any analyzed script can run. (The
-- runtime intentionally does NOT place them on the global environment or the
-- `debug` table, so there is no frozen-fallback copy to leak.)
local _vm = {}
do
    local prims = {"replaceclosure", "getprotos", "getproto", "getconstants",
                   "getconstant", "setconstant", "getupvalue", "setupvalue",
                   "getlocal", "setlocal"}
    local nativeLvm = rawget(_G, "lvm")
    if type(nativeLvm) == "table" then
        for _, k in ipairs(prims) do _vm[k] = rawget(nativeLvm, k) end
    end
    -- Revoke it everywhere the script could observe it.
    pcall(rawset, _G, "lvm", nil)
    local okEnv, genv = pcall(rawGetfenv, 0)
    if okEnv and type(genv) == "table" then pcall(rawset, genv, "lvm", nil) end
end
-- Values that must never be returned through the emulated debug.getupvalue /
-- getconstants (those now resolve real captured values via the patched
-- runtime). Handing any of these to a hostile script would breach the sandbox.
local _poisoned = setmetatable({}, {__mode = "k"})
do
    local function poison(v) if v ~= nil then _poisoned[v] = true end end
    poison(_G); poison(fs); poison(process); poison(net)
    poison(luau); poison(serde); poison(lune_task); poison(_vm)
    for _, fn in pairs(_vm) do poison(fn) end
end

-- Shared sandbox guard for values handed back through debug.getconstant /
-- getconstants / getupvalue. Never leak the host libraries, the private VM
-- primitives, or the dumper's own state -- doing so would let a hostile
-- script reach fs/process/net and disclose source / host files.
local function _vmValueIsSafe(val)
    if _poisoned[val] then return false end
    local t = type(val)
    if t == "table" and (val.readFile or val.cwd or val.request) then return false end
    if t == "function" then
        local ok, src = pcall(debug.info, val, "s")
        if ok and type(src) == "string" and src:match("@lune") then return false end
    end
    return true
end
-- Universal getconstant: read the real i-th constant of a function via the
-- patched runtime (so it works on any closure -- including obfuscated input --
-- without hardcoding). dtc2 expects debug.getconstant(f,1) == "print".
local function _vmGetConstant(func, i)
    if type(func) ~= "function" then
        error("invalid argument #1 to 'getconstant' (function expected)", 2)
    end
    if not _vm.getconstant then return nil end
    local ok, val = pcall(_vm.getconstant, func, i)
    if not ok then return nil end
    if not _vmValueIsSafe(val) then return nil end
    return val
end

-- Inliner multi-return support. A builtin like identifyexecutor() returns more
-- than one value (name, version). When those values are spread as the trailing
-- arguments of a call we want the dump to show the single source expression
-- `identifyexecutor()` rather than expanding every individual return (e.g.
-- `print(identifyexecutor(), "2.714.1077")`). The builtin still returns its real
-- values so the analysed script's own logic (table.pack, concat, ...) is
-- unaffected. Registration is keyed by value sequence so it is universal across
-- any multi-return builtin we inline -- nothing about the names is hardcoded
-- into the collapse logic.
local function registerInlineMultiret(display, ...)
    if INLINER and select("#", ...) >= 2 then
        local n = select("#", ...)
        local vals = {}
        for i = 1, n do vals[i] = (select(i, ...)) end
        dumperState.multiret_groups = dumperState.multiret_groups or {}
        table.insert(dumperState.multiret_groups, {values = vals, n = n, display = display})
    end
    return ...
end
-- Given the raw argument values and their already-serialized forms, collapse any
-- consecutive run that exactly matches a registered multi-return group into that
-- group's single display expression.
local function collapseInlineMultiret(vals, n, items)
    if not (INLINER and dumperState.multiret_groups) then return items end
    local out = {}
    local i = 1
    while i <= n do
        local matched = false
        for _, g in ipairs(dumperState.multiret_groups) do
            if g.n >= 2 and i + g.n - 1 <= n then
                local ok = true
                for k = 1, g.n do
                    if vals[i + k - 1] ~= g.values[k] then ok = false break end
                end
                if ok then
                    out[#out + 1] = g.display
                    i = i + g.n
                    matched = true
                    break
                end
            end
        end
        if not matched then
            out[#out + 1] = items[i]
            i = i + 1
        end
    end
    return out
end

