    local _pack, _unpack = string.pack, string.unpack
    robloxApi.f32round = function(n) return (_unpack("f", _pack("f", n))) end
    -- true when `class` (or an ancestor) declares `key` as a float property
    robloxApi.isF32 = function(class, key)
        local cat, c, g = robloxApi.f32, class, 0
        while c and g < 64 do
            local set = cat[c]
            if set and set[key] then return true end
            c = robloxApi.super[c]; g = g + 1
        end
        return false
    end
end
local function apiClassChainHas(category, className, member)
    if not robloxApi or not className then return false end
    local cat = robloxApi[category]
    if not cat then return false end
    local c, guard = className, 0
    while c and guard < 64 do
        local set = cat[c]
        if set and set[member] then return true end
        c = robloxApi.super[c]
        guard = guard + 1
    end
    return false
end
