-- [PATCH:CHILD-ORDER] Insertion-ordered parent map.
-- `Instance:GetChildren()` / `GetDescendants()` / `FindFirstChild` must return
-- children in the order they were parented (a re-parented child goes to the end),
-- exactly like the engine. The emulator used to keep parent links in a plain
-- hash table, so every run enumerated children in a different, random order --
-- trivially detectable (`GetChildren()[1] ~= firstCreatedChild`, or two runs
-- disagreeing). Reads/writes keep the old `parent_map[obj]` syntax; the
-- `pairsFunction` wrapper (below) iterates in insertion order.
robloxApi._pmState = setmetatable({}, {__mode = "k"})
robloxApi.newParentMap = function()
    local pm = {}
    local st = {store = {}, seq = {}, counter = 0, version = 0, cache = nil, cacheVersion = -1}
    robloxApi._pmState[pm] = st
    setmetatable(pm, {
        __index = function(_, k) return st.store[k] end,
        __newindex = function(_, k, v)
            if v == nil then
                if st.store[k] ~= nil then
                    st.store[k] = nil; st.seq[k] = nil; st.version = st.version + 1
                end
            else
                if st.store[k] ~= v then
                    st.counter = st.counter + 1
                    st.seq[k] = st.counter
                    st.store[k] = v
                    st.version = st.version + 1
                end
            end
        end,
    })
    return pm
end
