-- [v1.6] LoopGuard tuning + state. The old guard counted raw yields/pump ticks per thread and killed the
-- script (false triggers on finite loops, main-thread waits, shared counters). The new guard only
-- reacts to loops that are *stagnating* (nothing new is being logged) and cuts the offending loop
-- instead of killing the whole script. (Single table: the main chunk is at Luau's 200-local limit.)
local LG = {
    cfg = {
        RECENT = 192,          -- distinct recent output lines remembered (novelty window)
        STAG_YIELDS = 100,     -- yields at one call site with nothing new logged => the loop is spinning
        SITE_CAP = 1500,       -- absolute yields at one call site (per thread) before the loop is cut
        THREAD_CAP = 25000,    -- absolute yields per thread
        STAG_EMITS = 50000,    -- already-seen lines emitted back to back
        IDLE_TICKS = 50000000, -- loop iterations with no new output at all (pure compute spin)
        PENDING_GRACE = 40,    -- yields tolerated while a loop cut is pending but no loop header consumed it
        SITE_REQS = 6,         -- loop cuts at one call site before the thread is terminated instead
        SWALLOW_LIMIT = 150,   -- INFINITE_LOOP_TERMINATED errors swallowed by script pcalls before we exit
        -- [v1.6 HookOP v2] VM profile: a compare site is HOT (all of its lines removed at finalize) once it
        -- fires more than this many times within one epoch (between two guest-visible output lines).
        -- Decryptor / deserializer / per-instruction helper sites exceed it; guest checks do not.
        -- Env HOOKOP_RETRO_CAP overrides (1..64). Higher = more recall, less precision.
        HOOK_RETRO_CAP = 1,
    },
    parents = {}, -- loop id -> id of the lexically enclosing loop (filled by the instrumenter)
    bound = {},   -- loop id -> iteration count of a numeric `for` with literal bounds (provably finite)
}
function LG.newState()
    local s = {
        novel = 0, stag_emits = 0, seen = {}, ring = {}, ring_pos = 0,
        pump_n = 0, pump_next = 1024, idle_mark = 0, idle_ticks = 0,
        skip = setmetatable({}, {__mode = "k"}), ty = setmetatable({}, {__mode = "k"}),
        anyskip = false, swallowed = 0, flushed = false,
    }
    dumperState.lg = s
    return s
end
-- [v1.6] repeated-line suppression keeps exact counts: the `--[ repeated lines ]` marker is
-- rewritten to `--[ repeated lines xN ]` (N = number of suppressed copies) when the run ends.
function LG.finalizeRepeat(final)
    local sl = dumperState and dumperState.rep_slot
    if sl then
        local extra = (dumperState.repetition_count or 0) - configuration.MAX_REPEATED_LINES
        if extra > 0 and sl.out[sl.idx] == sl.text then
            sl.text = sl.prefix .. "--[ repeated lines x" .. extra .. " ]"
            sl.out[sl.idx] = sl.text
        end
        if final then dumperState.rep_slot = nil end
    end
end

-- [v1.6 HookOP v2] Reconstruction runtime (built from src/hookop_rt.luau; keep in sync).
-- Shared by every sandbox env (real_env / senv / dump_string) through LG.installHookOp.
LG.hookRT = (function()
local M = {}

-- captured at load, before a host replaces these globals for its sandbox
local _info, _status, _running = debug.info, coroutine.status, coroutine.running

-- transient marker appended to runtime-emitted lines: " --[[hk:<kind><seq>]]"
--   s = structural (if/elseif/else/end)   v = vm compare   c = vm error/assert
M.MARK_PAT = " %-%-%[%[hk:%a%d+%]%]"
function M.strip(text) return (string.gsub(text, M.MARK_PAT, "")) end

local function apply(op, a, b)
  if op == "<" then return a < b
  elseif op == "<=" then return a <= b
  elseif op == ">" then return a > b
  elseif op == ">=" then return a >= b
  elseif op == "==" then return a == b
  elseif op == "~=" then return a ~= b end
  return false
end

function M.new(host, opts)
  opts = opts or {}
  local retroCap = math.max(1, math.floor(tonumber(opts.retroCap) or 1))
  local profile = opts.profile or "lexical"
  local doVM = (profile == "vm" or profile == "both" or profile == "all")
  local info = opts.info or _info
  local coStatus = opts.status or _status
  local running = host.running or _running
  local marking, finalized = true, false
  local seq = 0
  local function mark(kind)
    if not marking then return "" end
    seq = seq + 1
    return " --[[hk:" .. kind .. seq .. "]]", seq
  end

  -- position prefix of errors raised inside THIS chunk (to re-raise compare
  -- errors at the guest's position instead of ours)
  local selfPrefix
  do
    local _, e = pcall(function() local _ = 1 < {} end)
    selfPrefix = type(e) == "string" and string.match(e, "^(.-:)%d+: ") or nil
  end

  ---------------------------------------------------------------- activation
  local hint = 8
  -- number of stack levels visible from rawDepth itself (level 1 = rawDepth)
  local function rawDepth()
    local d = hint
    if info(d, "f") then
      if not info(d + 1, "f") then return d end
      local lo, hi = d + 1, d + 8
      while info(hi, "f") do lo = hi; hi = hi * 2 end
      while hi - lo > 1 do local mid = (lo + hi) // 2; if info(mid, "f") then lo = mid else hi = mid end end
      hint = lo; return lo
    end
    local lo, hi = 1, d
    while hi - lo > 1 do local mid = (lo + hi) // 2; if info(mid, "f") then lo = mid else hi = mid end end
    hint = lo; return lo
  end

  local stacks = setmetatable({}, { __mode = "k" })   -- thread -> frames (push order)
  local open = setmetatable({}, { __mode = "k" })     -- buffer -> realized frames (realization order)
  local busy = false
  local epoch, selfEmit = 0, false   -- guest-visible emissions so far; VM line in flight
  local function stackFor(th) local s = stacks[th]; if not s then s = {}; stacks[th] = s end return s end

  local function closeLine(fr)
    local tag = mark("s")
    host.emitAt(fr.buf, fr.ind, "end" .. tag)
    host.indent(-1)
    fr.realized = false; fr.realizedUpto = 0
  end

  -- Close, from the top of the CURRENT buffer's open list, every frame that is
  -- dead, belongs to a suspended/dead thread, or whose body indent is no longer
  -- reached (an enclosing host block was closed, e.g. pcall(function() ... end)
  -- after an error unwound through the if).
  local function drain()
    local B = host.buffer()
    local L = open[B]
    if not L or #L == 0 then return end
    local T = running()
    while #L > 0 do
      local fr = L[#L]
      -- A frame only ever contains lines of its OWN thread: when any other
      -- thread (suspended, dead, or "normal" = it resumed us / pumps a
      -- scheduler inside task.wait) writes here, the frame is closed; it
      -- re-opens lazily when its thread writes again.
      local close = fr.dead or fr.th ~= T
      if not close and fr.ind + 1 > host.getIndent() then close = true end
      if not close then break end
      L[#L] = nil
      closeLine(fr)
    end
  end

  -- Frame pool: a popped frame that was never realized is referenced by
  -- nothing else, so it is recycled (no allocation per executed `if` in hot
  -- loops). Realized frames stay owned by their buffer's open list.
  local pool, poolN = {}, 0
  local function retire(fr)
    if fr.realized then fr.dead = true
    elseif poolN < 256 then
      table.clear(fr.clauses); fr.fn = nil
      poolN = poolN + 1; pool[poolN] = fr
    end
  end
  local function popRetire(s)
    local fr = s[#s]; s[#s] = nil
    retire(fr)
  end

  -- realize pending headers of thread stack `s` into the current buffer
  local function realize(s, th)
    local B
    for i = 1, #s do
      local fr = s[i]
      if not fr.realized and fr.selected then
        B = B or host.buffer()
        fr.buf = B; fr.ind = host.getIndent(); fr.th = th; fr.dead = false
        -- clauses[i] = condition text (if/elseif) or false (else)
        for ci = 1, fr.selected do
          local cl = fr.clauses[ci]
          if ci == 1 then host.emit("if " .. cl .. " then" .. mark("s")); host.indent(1)
          elseif cl then host.indent(-1); host.emit("elseif " .. cl .. " then" .. mark("s")); host.indent(1)
          elseif cl == false then host.indent(-1); host.emit("else" .. mark("s")); host.indent(1) end
        end
        fr.realized = true; fr.realizedUpto = fr.selected
        local L = open[B]; if not L then L = {}; open[B] = L end
        L[#L + 1] = fr
      end
    end
  end

  -- pop frames of `s` whose activation no longer exists (error unwinding)
  local function validateTop(s)
    local D = rawDepth() - 1            -- levels visible from validateTop
    while #s > 0 do
      local top = s[#s]
      local lv = D - top.a + 1
      if lv >= 2 and info(lv, "f") == top.fn then break end
      popRetire(s)
    end
  end

  -- Host hook: called first thing for every body line. Every host line that
  -- is not HookOP's own VM line starts a new EPOCH (VM burst accounting).
  local function pending()
    if busy or finalized then return end
    if not selfEmit then epoch = epoch + 1 end
    busy = true
    local th = running()
    local s = stacks[th]
    if s and #s > 0 then validateTop(s) end
    drain()
    if s and #s > 0 then realize(s, th) end
    busy = false
  end

  -- Shared reconcile for hooks called DIRECTLY by guest code. `D` = levels
  -- visible from the HOOK, `a` = guest absolute index, `fn` = guest function.
  -- Pops frames of exited activations; keeps live caller frames. (Levels seen
  -- from inside reconcile are one deeper than from the hook: +2 not +1.)
  local function reconcile(s, D, a, fn, fs)
    local n = #s
    if n == 0 then return end
    local top = s[n]
    if top.a == a and top.fn == fn and (fs == nil or (top.fs < fs and fs < top.fe)) then return end
    while #s > 0 do
      local top = s[#s]
      if top.a == a then
        if top.fn == fn and (fs == nil or (top.fs < fs and fs < top.fe)) then break end
      elseif top.a < a then
        if info(D - top.a + 2, "f") == top.fn then break end
      end
      popRetire(s)
    end
  end

  -- __HKIF(cond, text, fid, fs, fe, single): cond evaluated exactly once by the
  -- guest. A false single-clause if (no elseif/else) can never produce a body
  -- line, so it needs no frame (fast path: no stack walk, no allocation).
  local function hkif(cond, text, fid, fs, fe, single)
    if single and not cond then return cond end
    local D = rawDepth() - 1
    local a, fn = D - 1, info(2, "f")
    local s = stackFor(running())
    reconcile(s, D, a, fn, fs)
    local fr
    if poolN > 0 then
      fr = pool[poolN]; pool[poolN] = nil; poolN = poolN - 1
      fr.fid, fr.fs, fr.fe, fr.a, fr.fn = fid, fs, fe, a, fn
      fr.clauses[1] = text
      fr.selected = cond and 1 or nil; fr.realized = false; fr.realizedUpto = 0
      fr.dead = false; fr.buf = nil; fr.ind = nil; fr.th = nil
    else
      fr = { fid = fid, fs = fs, fe = fe, a = a, fn = fn, clauses = { text },
             selected = cond and 1 or nil, realized = false, realizedUpto = 0 }
    end
    s[#s + 1] = fr
    return cond
  end
  local function findFrame(s, fid, a)
    for i = #s, 1, -1 do local fr = s[i]; if fr.fid == fid and fr.a == a then return fr, i end end
    return nil
  end
  local function hkei(cond, text, fid)
    local D = rawDepth() - 1
    local a, fn = D - 1, info(2, "f")
    local s = stackFor(running())
    reconcile(s, D, a, fn, nil)
    local fr = findFrame(s, fid, a)
    if fr then
      local cl = fr.clauses
      cl[#cl + 1] = text
      if cond and not fr.selected then fr.selected = #cl end
    end
    return cond
  end
  local function hkelse(fid)
    local D = rawDepth() - 1
    local a, fn = D - 1, info(2, "f")
    local s = stackFor(running())
    reconcile(s, D, a, fn, nil)
    local fr = findFrame(s, fid, a)
    if fr then
      local cl = fr.clauses
      cl[#cl + 1] = false
      if not fr.selected then fr.selected = #cl end
    end
  end
  -- close frame `fid` of the calling activation and everything above it
  local function closeTo(s, fid, a)
    local _, idx = findFrame(s, fid, a)
    if not idx then return end
    local anyRealized = false
    while #s >= idx do
      if s[#s].realized then anyRealized = true end
      popRetire(s)
    end
    -- only a realized frame needs its `end` written now
    if anyRealized and not busy then busy = true; drain(); busy = false end
  end
  -- true when the current thread has no frame for if `fid` (cheap pre-check
  -- that lets hkend/hkx/hkxr skip the stack walk for frameless ifs)
  local function noFrame(fid)
    local s = stacks[running()]
    if not s then return true end
    for i = #s, 1, -1 do if s[i].fid == fid then return false end end
    return true
  end
  local function hkend(fid)
    if noFrame(fid) then return end
    local D = rawDepth() - 1
