function finalizeHookopIfs(final)
    -- [v1.6 HookOP v2] final=true (dump is about to be saved): close every
    -- realized if-frame in every buffer (a matching `end` for each header),
    -- drop hot VM sites, strip transient markers, and verify the structured
    -- dump compiles (flat rendering + diagnostic if it does not).
    -- final=nil (top-level error path): close frames in the current buffer so
    -- the error comment lands at top level; guest tasks may still run.
    local hk = dumperState and dumperState.hookop_rt
    if hk then
        if final then
            dumperState.hookop_rt = nil
            local okF, st = pcall(hk.finalize, dumperState.output, function(t) return (pcall(luau.compile, t)) end)
            if not okF then
                pcall(printFunction, "[HookOP] finalize failed: " .. tostring(st))
            elseif st == "flat" then
                pcall(emitComment, "[HookOP] reconstructed if-structure failed the compile check; structural lines were emitted as comments")
            elseif st == "unverified" then
                pcall(printFunction, "[HookOP] dump does not compile independently of HookOP structure (structure kept)")
            end
        else
            pcall(hk.closeAll)
        end
    end
    local stack = dumperState and dumperState.hookop_ifs
    while stack and #stack > 0 do
        local state = stack[#stack]
        if state and state.selected and not state.saw_else and type(state.rawElse) == "string" and #state.rawElse > 0 then
            dumperState.indent = math.max(0, dumperState.indent - 1)
            emitOutput("else")
            dumperState.indent = dumperState.indent + 1
            for line in (state.rawElse .. "\n"):gmatch("([^\n]*)\n") do
                if line:match("%S") then emitOutput(line) end
            end
        end
        dumperState.indent = math.max(0, dumperState.indent - 1)
