flushPartialOutput = function(reason, silent, force)
    if not force and not RUNTIME_LOGS then
        return false
    end

    if not dumperState or type(dumperState.output) ~= "table" then
        return false
    end

    local out_path = dumperState.out_path or (args and args[2]) or configuration.OUTPUT_FILE or "output.lua"

    if reason and reason ~= "" and dumperState._last_flush_reason ~= reason then
        dumperState._last_flush_reason = reason
        table.insert(dumperState.output, "")
        table.insert(dumperState.output, "-- [Dumper] " .. tostring(reason))
    end

    if force and dumperState.limit_reached and dumperState.hookop_rt then
        pcall(finalizeHookopIfs, true) -- [v1.6 HookOP v2] process exits after this flush
    end
    local _hkrt, _hkSaved = dumperState.hookop_rt, nil
    if _hkrt and RECONSTRUCT_MODE then
        -- reconstruct engine must see marker-free lines (copy; live table untouched)
        _hkSaved = dumperState.output
        local c = {}
        for i = 1, #_hkSaved do
            local l = _hkSaved[i]
            c[i] = (type(l) == "string" and string.find(l, "--[[hk:", 1, true)) and _hkrt.strip(l) or l
        end
        dumperState.output = c
    end
    local ok, err = pcall(function()
        LG.finalizeRepeat(false)
        local payload
        if RECONSTRUCT_MODE and getFullOutput then
            local okR, res = pcall(getFullOutput)
            if okR and type(res) == "string" then payload = res end
        end
        payload = payload or table.concat(dumperState.output, "\n")
        if _hkrt then payload = _hkrt.strip(payload) end -- [v1.6 HookOP v2] transient markers
        local gate = _vm.rvc_gate
        if gate then
            payload = gate(payload, false)
        else
            pcall(printFunction, "[RVC] gate missing from the private stash"
                .. " -- refusing to write the dump.")
            payload = _vm.rvc_marker or "-vuln attempt"
        end
        fs.writeFile(out_path, payload)
    end)
    if _hkSaved then dumperState.output = _hkSaved end

    if not ok and not silent then
        print("[Dumper] Failed to write partial output: " .. tostring(err))
    end

    return ok
end
