local pairsFunction
do
    local rawPairsFunction = pairs
    local pmState = robloxApi._pmState
    pairsFunction = function(t, ...)
        local st = pmState[t]
        if not st then return rawPairsFunction(t, ...) end
        if st.cacheVersion ~= st.version or not st.cache then
            local list = {}
            for k in rawPairsFunction(st.store) do list[#list + 1] = k end
            local seq = st.seq
            table.sort(list, function(a, b) return seq[a] < seq[b] end)
            st.cache, st.cacheVersion = list, st.version
        end
        local list, i, store = st.cache, 0, st.store
        return function()
            while true do
                i = i + 1
                local k = list[i]
                if k == nil then return nil end
                local v = store[k]
                if v ~= nil then return k, v end
            end
        end, t, nil
    end
end
