    {"Head", "MeshPart", 2, 1, 1, 6.9},
    {"LeftUpperArm", "MeshPart", 1, 1.2, 1, 5.9, -1.5}, {"LeftLowerArm", "MeshPart", 1, 1.1, 1, 4.9, -1.5}, {"LeftHand", "MeshPart", 1, 0.3, 1, 4.2, -1.5},
