    if not cc then cc = {}; dumperState.child_cache[char] = cc end
    if cc[name] ~= nil then return cc[name] end
    for _, d in ipairsFunction(robloxApi.r15Parts) do
        if d[1] == name then
            local part = createProxyObject(name, false, char)
            local pos = Vector3.new(d[7] or 0, d[6], 0)
            dumperState.property_store[part] = {
                Name = name, ClassName = d[2], Size = Vector3.new(d[3], d[4], d[5]), Position = pos,
                CFrame = CFrame.new(pos.X, pos.Y, pos.Z), Anchored = false, CanCollide = (name == "Head" or name == "UpperTorso" or name == "LowerTorso"),
            }
            dumperState.parent_map[part] = char
