robloxApi.typedDefault = function(token, key, className)
    if token == nil then return nil end
    local c = string.sub(token, 1, 1)
    if token == "b" then return false end
    if token == "n" then return 0 end
    if token == "s" then return "" end
    if token == "nil" or token == "I" then return nil end
    if c == "E" then return robloxApi.enumItem(string.sub(token, 3)) end
    if c == "D" then
        local t = string.sub(token, 3)
        local ok, v = pcall(function()
            if t == "Vector3" then
                if key == "Size" then return Vector3.new(4, 1.2, 2) end
                return Vector3.new(0, 0, 0)
            elseif t == "Vector2" then return Vector2.new(0, 0)
            elseif t == "Vector3int16" then return Vector3int16.new(0, 0, 0)
            elseif t == "Vector2int16" then return Vector2int16.new(0, 0)
            elseif t == "CFrame" then return CFrame.new()
            elseif t == "Color3" then return Color3.fromRGB(163, 162, 165)
            elseif t == "BrickColor" then return BrickColor.new("Medium stone grey")
            elseif t == "UDim" then return UDim.new(0, 0)
            elseif t == "UDim2" then return UDim2.new(0, 0, 0, 0)
            elseif t == "NumberRange" then return NumberRange.new(0)
            elseif t == "NumberSequence" then return NumberSequence.new(0)
            elseif t == "ColorSequence" then return ColorSequence.new(Color3.new(1, 1, 1))
            elseif t == "Ray" then return Ray.new(Vector3.new(0, 0, 0), Vector3.new(0, 0, 0))
            elseif t == "Rect" then return Rect.new(0, 0, 0, 0)
            elseif t == "Region3" then return Region3.new(Vector3.new(0, 0, 0), Vector3.new(0, 0, 0))
            elseif t == "Region3int16" then return Region3int16.new(Vector3int16.new(0, 0, 0), Vector3int16.new(0, 0, 0))
            elseif t == "TweenInfo" then return TweenInfo.new(1)
            elseif t == "PhysicalProperties" then return PhysicalProperties.new(0.7, 0.3, 0.5)
            elseif t == "Font" then return Font.new("rbxasset://fonts/families/SourceSansPro.json")
            elseif t == "Axes" then return Axes.new()
            elseif t == "Faces" then return Faces.new()
            elseif t == "NumberSequenceKeypoint" then return NumberSequenceKeypoint.new(0, 0)
            elseif t == "ColorSequenceKeypoint" then return ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1))
            elseif t == "PathWaypoint" then return PathWaypoint.new(Vector3.new(0, 0, 0), Enum.PathWaypointAction.Walk)
            elseif t == "DateTime" then return DateTime.now()
            elseif t == "CatalogSearchParams" then return CatalogSearchParams.new()
            elseif t == "RaycastParams" then return RaycastParams.new()
            elseif t == "OverlapParams" then return OverlapParams.new()
            elseif t == "FloatCurveKey" then return FloatCurveKey.new(0, 0, Enum.KeyInterpolationMode.Cubic)
            elseif t == "RotationCurveKey" then return RotationCurveKey.new(0, CFrame.new(), Enum.KeyInterpolationMode.Cubic)
            elseif t == "Path2DControlPoint" then return Path2DControlPoint.new(UDim2.new(0, 0, 0, 0))
            elseif t == "ValueCurveKey" then return ValueCurveKey.new(0, 0, Enum.KeyInterpolationMode.Cubic)
            elseif t == "Random" then return Random.new()
            elseif t == "Content" then local C = rawget(_G, "Content"); return C and C.none
            end
            return nil
        end)
        if ok then return v end
        return nil
    end
