robloxApi.resolveMember = function(className, key)
    if not className or not robloxApi.proptypes then return false, nil end
    local c, guard = className, 0
    while c and guard < 64 do
        local set = robloxApi.proptypes[c]
        if set and set[key] ~= nil then return true, set[key] end
        c = robloxApi.psuper and robloxApi.psuper[c]
        guard = guard + 1
    end
    return false, nil
end
-- [PATCH:SIGNALS] Per-instance event bus. Signal callbacks used to be keyed by the *display path*
-- of the owner (`"Part.ChildAdded"`), so every `Instance.new("Part")` shared one callback list
-- (events leaked between unrelated instances), Destroy did not disconnect, and most hierarchy
-- events (ChildRemoved, DescendantAdded/Removing, AncestryChanged, AttributeChanged ...) never
-- fired. Created instances now get a unique key; singletons/services keep their path key.
robloxApi.sigKey = function(inst, name)
    local base
    if typeFunction(inst) == "table" and rawget(inst, "__created_instance") then
        local u = dumperState.inst_uid
        if not u then u = setmetatable({}, {__mode = "k"}); dumperState.inst_uid = u; dumperState.inst_uid_n = 0 end
        if not u[inst] then dumperState.inst_uid_n = dumperState.inst_uid_n + 1; u[inst] = dumperState.inst_uid_n end
        base = "~" .. u[inst]
    else
        base = dumperState.registry[inst]
        if typeFunction(base) ~= "string" then base = "?" end
    end
