    if not cbs or #cbs == 0 then return end
    local snap = {}
    for i = 1, #cbs do snap[i] = cbs[i] end
    local args = table.pack(...)
    for i = 1, #snap do
        xpcallFunction(snap[i], function() end, table.unpack(args, 1, args.n))
    end
end
robloxApi.fireKey = function(key, ...)
    local all = dumperState.event_callbacks
    local cbs = all and all[key]
    if not cbs or #cbs == 0 then return end
    local snap = {}
    for i = 1, #cbs do snap[i] = cbs[i] end
