robloxApi.hierEvents = function(inst, oldParent, newParent)
    if not dumperState.event_callbacks then return end
    local pm = dumperState.parent_map
    -- ancestors (starting at `start`) that actually have a listener for `evName`
    local function listeners(start, evName)
        local out, cur, n = {}, start, 0
        local cbsAll = dumperState.event_callbacks
        while cur and n < 200 do
            local l = cbsAll[robloxApi.sigKey(cur, evName)]
            if l and #l > 0 then out[#out + 1] = cur end
            cur = pm[cur]; n = n + 1
        end
        return out
    end
    if oldParent then
        robloxApi.fireSig(oldParent, "ChildRemoved", inst)
        local ls = listeners(oldParent, "DescendantRemoving")
        if #ls > 0 then
            -- the removed subtree: the instance itself first, then each of its descendants
            local subtree = {inst}
            for _, d in ipairsFunction(robloxApi.descendantsOf(inst)) do subtree[#subtree + 1] = d end
            for _, d in ipairsFunction(subtree) do
                for _, anc in ipairsFunction(ls) do robloxApi.fireSig(anc, "DescendantRemoving", d) end
            end
        end
    end
    robloxApi.fireSig(inst, "AncestryChanged", inst, newParent)
    if (dumperState.anc_listeners or 0) > 0 then
        for _, d in ipairsFunction(robloxApi.descendantsOf(inst)) do robloxApi.fireSig(d, "AncestryChanged", inst, newParent) end
    end
    if newParent then
        robloxApi.fireSig(newParent, "ChildAdded", inst)
        local ls = listeners(newParent, "DescendantAdded")
        if #ls > 0 then
            local subtree = {inst}
            for _, d in ipairsFunction(robloxApi.descendantsOf(inst)) do subtree[#subtree + 1] = d end
            for _, d in ipairsFunction(subtree) do
                for _, anc in ipairsFunction(ls) do robloxApi.fireSig(anc, "DescendantAdded", d) end
