        if ps then ps.Connected = false end
        local key, fn = rawget(c, "__cb_signal"), rawget(c, "__cb_fn")
        local cbs = key and dumperState.event_callbacks and dumperState.event_callbacks[key]
        if cbs then for i = #cbs, 1, -1 do if cbs[i] == fn then table.remove(cbs, i) end end end
    end
