        elseif tag == "V2" then return Vector2.new(nums[1], nums[2])
        elseif tag == "C3" then return Color3.new(nums[1], nums[2], nums[3])
        elseif tag == "U2" then return UDim2.new(nums[1], nums[2], nums[3], nums[4])
        elseif tag == "U1" then return UDim.new(nums[1], nums[2])
        elseif tag == "CF" then return CFrame.new(table.unpack(nums, 1, 12))
        elseif tag == "NR" then return NumberRange.new(nums[1], nums[2])
        elseif tag == "RC" then return Rect.new(nums[1], nums[2], nums[3], nums[4])
        elseif tag == "BC" then return BrickColor.new(nums[1])
        elseif tag == "NS" then
            local kps = {}
            for i = 1, #nums, 3 do kps[#kps + 1] = NumberSequenceKeypoint.new(nums[i], nums[i + 1], nums[i + 2]) end
            return NumberSequence.new(kps)
        elseif tag == "CS" then
            local kps = {}
            for i = 1, #nums, 4 do kps[#kps + 1] = ColorSequenceKeypoint.new(nums[i], Color3.new(nums[i + 1], nums[i + 2], nums[i + 3])) end
            return ColorSequence.new(kps)
        elseif tag == "FN" then
            local fam, w, s = payload:match("^([^;]*);([^;]*);([^;]*)$")
            return Font.new(fam, Enum.FontWeight[w], Enum.FontStyle[s])
        elseif tag == "FA" or tag == "AX" then
            local mask, list = nums[1] or 0, {}
            local names = tag == "FA" and {"Right", "Top", "Back", "Left", "Bottom", "Front"} or {"X", "Y", "Z"}
            for i, n in ipairsFunction(names) do
