robloxApi.needEnumItem = function(v, enumName, fname, idx)
    local ok, et = pcallFunction(function() return v.EnumType end)
    local E = rawget(_G, "Enum")
    if not (ok and et ~= nil and E ~= nil and et == E[enumName]) then
        if v == nil then error("Argument " .. idx .. " missing or nil", 3) end
        error("Unable to cast value to Enum." .. enumName, 3)
    end
end
robloxApi.httpUrlCheck = function(url, fname)
    if typeFunction(url) ~= "string" then
        error("invalid argument #1 to '" .. fname .. "' (string expected, got " .. (url == nil and "nil" or typeFunction(url)) .. ")", 3)
    end
    if not (url:find("^https?://[^/%s]") ) then error("HttpService: invalid URL", 3) end
end
robloxApi.jsonCheck = function(v, depth)
    local t = typeFunction(v)
    if t == "function" or t == "thread" or t == "userdata" or t == "buffer" then error("Can't convert " .. t .. " to JSON", 3) end
    if t == "table" then
        if depth > 0 and isProxy(v) then error("Can't convert Instance to JSON", 3) end
        if depth == 0 and isProxy(v) then error("Can't convert Instance to JSON", 3) end
        if depth > 100 then error("Can't convert table to JSON (too deep)", 3) end
        for k, x in pairsFunction(v) do
            local kt = typeFunction(k)
            if kt ~= "string" and kt ~= "number" then error("Can't convert table with " .. kt .. " keys to JSON", 3) end
            robloxApi.jsonCheck(x, depth + 1)
        end
    end
end
robloxApi.advanceClock = function(sec)
    virtual_time_offset = virtual_time_offset + (tonumber(sec) or 0)
end
robloxApi.resolveClass = function(proxy, pathName, formattedName)
    local ps = dumperState.property_store[proxy]
    if ps and type(ps.ClassName) == "string" and ps.ClassName ~= "" then return ps.ClassName end
    if proxy == game then return "DataModel" end
    if proxy == workspace then return "Workspace" end
    if proxy == script then return "LocalScript" end
    local svc = (type(pathName) == "string" and pathName:match("^game%.([%w_]+)$")) or formattedName
    if svc and serviceNames and serviceNames[svc] then return svc end
    if svc and robloxApi.proptypes and robloxApi.proptypes[svc] then return svc end
    return nil
end
