    local function put(t, c, n, v) local s = t[c]; if not s then s = {}; t[c] = s end; s[n] = v end
    for row in ROWS:gmatch("[^\n]+") do
        local c, n, k, tk, fl, rt = row:match("^([^|]*)|([^|]*)|([^|]*)|([^|]*)|([^|]*)|?(.*)$")
        if k == "C" then
            A.super[c] = n; A.psuper[c] = n; A.msuper[c] = n
            A.members[c] = A.members[c] or {}
        else
            put(A.members, c, n, 1)
            if k == "f" then
                put(A.methods, c, n, 1)
                local r1, r2 = rt:match("^([^~]*)~(.*)$")
                if r1 and r1 ~= "" then put(A.methodret, c, n, r1) end
                if r2 and r2 ~= "" then put(A.methodret2, c, n, r2) end
            elseif k == "e" then
                put(A.events, c, n, 1)
            elseif k == "p" then
                if fl:find("u", 1, true) then
                    -- scriptable in 0.742 although the bundled tables hid it (e.g. Model.LevelOfDetail)
                    for _, t in ipairs({A.hiddenprops, A.notscript}) do if t[c] then t[c][n] = nil end end
                    put(A.proptypes, c, n, tk)
                elseif fl:find("h", 1, true) then put(A.hiddenprops, c, n, tk)
                else put(A.proptypes, c, n, tk) end
                if fl:find("n", 1, true) then put(A.notscript, c, n, 1) end
                if fl:find("r", 1, true) then put(A.readonly, c, n, 1) end
            end
        end
    end
end
