    local function put(t, c, n, v) local s = t[c]; if not s then s = {}; t[c] = s end; s[n] = v end
    local function del(t, c, n) local s = t[c]; if s then s[n] = nil end end
    local STATE = {A.methods, A.events, A.proptypes, A.hiddenprops, A.notscript, A.readonly, A.methodret, A.methodret2}
    for row in ROWS:gmatch("[^\n]+") do
        local c, n, k, tk, fl, rt = row:match("^([^|]*)|([^|]*)|([^|]*)|([^|]*)|([^|]*)|?(.*)$")
        if k == "C" then
            -- class (new, or its superclass changed): n holds the superclass
            A.super[c] = n; A.psuper[c] = n; A.msuper[c] = n
            A.members[c] = A.members[c] or {}
        elseif k == "T" then
            -- token-only update: keep the existing flags / table (e.g. Content-typed properties)
            for _, t in ipairs({A.proptypes, A.hiddenprops}) do if t[c] and t[c][n] ~= nil then t[c][n] = tk end end
        else
            -- assign semantics: the dump's current definition replaces whatever state the tables held
            for _, t in ipairs(STATE) do del(t, c, n) end
            put(A.members, c, n, 1)
            if k == "f" then
                put(A.methods, c, n, 1)
                local r1, r2 = rt:match("^([^~]*)~(.*)$")
                if r1 and r1 ~= "" then put(A.methodret, c, n, r1) end
                if r2 and r2 ~= "" then put(A.methodret2, c, n, r2) end
            elseif k == "e" then
                put(A.events, c, n, 1)
            elseif k == "p" then
                if fl:find("h", 1, true) then put(A.hiddenprops, c, n, tk) else put(A.proptypes, c, n, tk) end
                if fl:find("n", 1, true) then put(A.notscript, c, n, 1) end
                if fl:find("r", 1, true) then put(A.readonly, c, n, 1) end
            end
        end
    end
    -- void functions: the engine returns no value (the emulator used to hand back a proxy / a number)
    for row in VOIDS:gmatch("[^\n]+") do
        local c, list = row:match("^([^=]*)=(.*)$")
        for n in list:gmatch("[^,]+") do
            put(A.members, c, n, 1); put(A.methods, c, n, 1)
            del(A.methodret, c, n); put(A.methodret2, c, n, "V")
        end
    end
    for row in REMOVED:gmatch("[^\n]+") do
        local c, n = row:match("^([^|]*)|(.*)$")
        if n == "*" then
            for _, t in ipairs({A.members, A.methods, A.events, A.proptypes, A.readonly, A.notscript, A.hiddenprops, A.methodret, A.methodret2, A.super, A.psuper, A.msuper}) do t[c] = nil end
        else
            for _, t in ipairs({A.members, A.methods, A.events, A.proptypes, A.readonly, A.notscript, A.hiddenprops, A.methodret, A.methodret2}) do del(t, c, n) end
        end
    end

end
-- [MANUAL] Newer public methods that the bundled API dump predates but a real
-- client exposes; the detection suite reads them and expects a function value
-- (dtc102..112). Register them so the foreign-member guard admits them and they
-- resolve to a traced method.
do
    local _extra = {
        AnalyticsService = {"LogJourneyEvent"},
        AvatarCreationService = {"PromptCreateMakeupAsync"},
        CaptureService = {"CheckUploadCaptureStatusAsync"},
        Players = {"GetProfileConfigurationFromUserIdAsync"},
        RunService = {"IsResimulating"},
        TestService = {"GetTestControlSchema", "GetTestControls", "ResetTestControl",
                       "SetTestControl", "StartVideoCaptureAsync", "StopVideoCaptureAsync"},
    }
    for cls, ms in pairs(_extra) do
        robloxApi.members[cls] = robloxApi.members[cls] or {}
        robloxApi.methods = robloxApi.methods or {}
        robloxApi.methods[cls] = robloxApi.methods[cls] or {}
        for _, m in ipairs(ms) do robloxApi.members[cls][m] = 1; robloxApi.methods[cls][m] = 1 end
    end
end
-- [API-GUARD] Global member-name universe (union of every class's members) so a
-- single O(1) lookup tells us whether a key is a real Roblox member *somewhere*.
-- Keys that are not members of any class (real child names, executor globals,
-- internal __fields) are never guarded, so the dumper keeps tracing normally.
do
    local uni = {}
    for _cls, set in pairs(robloxApi.members) do
        for m in pairs(set) do uni[m] = true end
    end
    robloxApi.universe = uni
end
-- True iff `key` is a member of `className` anywhere in its inheritance chain.
robloxApi.classHasMember = function(className, key)
    local c, g = className, 0
    while c and g < 128 do
        local set = robloxApi.members[c]
        if set and set[key] then return true end
        c = robloxApi.msuper[c] or (robloxApi.super and robloxApi.super[c]) or (robloxApi.psuper and robloxApi.psuper[c])
        g = g + 1
    end
    return false
end
-- Resolve the class we should strictly guard for this proxy, or nil to stay
-- permissive. We only guard proxies whose Roblox class we positively know:
-- Instance.new() results (property_store.ClassName), the game/workspace/script
-- singletons, and top-level services (registry path "game.<Service>").
robloxApi.foreignGuardClass = function(proxy, formattedName, pathName)
    -- [PATCH:FABRICATED] children the emulator invented on demand (WaitForChild /
    -- FindFirstChild for something that only exists on the real server) have an
    -- UNKNOWN real class -- never reject members on them.
    if rawget(proxy, "__fabricated") then return nil end
    local ps = dumperState.property_store[proxy]
    local cn = ps and type(ps.ClassName) == "string" and ps.ClassName ~= "" and ps.ClassName or nil
    if cn and robloxApi.members[cn] then return cn end
    if proxy == game then return "DataModel" end
    if proxy == workspace then return "Workspace" end
    if proxy == script then return "LocalScript" end
    local pn = pathName or dumperState.registry[proxy]
    local svc = (type(pn) == "string" and pn:match("^game%.([%w_]+)$")) or formattedName
    if svc and robloxApi.members[svc] then return svc end
    return nil
end
-- [API-ALIAS] Roblox keeps deprecated case-variant member aliases: reading the
-- alias returns EXACTLY the canonical member's value on a real client, so
-- `LocalPlayer.userId == LocalPlayer.UserId`, `game.workspace == game.Workspace`,
-- `part.className == part.ClassName`, `Players.numPlayers == Players.NumPlayers`,
-- and so on for every case-only pair (the emulator used to serve the alias a
-- separate fabricated value, which the anti-emulator suites fingerprint). We
-- build the map straight from the embedded API dump: within a class's OWN merged
-- member set (members + proptypes + readonly + methods + events) a lowercase-
-- initial name whose uppercase-initial, case-insensitively-equal sibling is also
-- present is a deprecated alias of that sibling. A handful of singleton aliases
-- (`game.lighting`, `game.workspace`) point at a child service the dump does not
-- list as a reflected member, so they are added explicitly.
do
    local perClass = {}
    local function merge(tbl)
        if type(tbl) ~= "table" then return end
        for cls, set in pairs(tbl) do
            if type(set) == "table" then
                local dst = perClass[cls]
                if not dst then dst = {}; perClass[cls] = dst end
                for name in pairs(set) do
                    if type(name) == "string" then dst[name] = true end
                end
            end
        end
    end
    merge(robloxApi.members)
    merge(robloxApi.proptypes)
    merge(robloxApi.readonly)
    merge(robloxApi.methods)
    merge(robloxApi.events)
    local aliasmap = {}
    local flat = {}
    local function isUpperInit(s) local b = string.byte(s, 1); return b and b >= 65 and b <= 90 end
    local function isLowerInit(s) local b = string.byte(s, 1); return b and b >= 97 and b <= 122 end
    for cls, names in pairs(perClass) do
        local byLower = {}
        for n in pairs(names) do
            local l = string.lower(n)
            local bucket = byLower[l]
            if not bucket then bucket = {}; byLower[l] = bucket end
            bucket[#bucket + 1] = n
        end
        for _, variants in pairs(byLower) do
            if #variants >= 2 then
                local canon
                for _, v in ipairs(variants) do
                    if isUpperInit(v) then canon = v; break end
                end
                if canon then
                    for _, v in ipairs(variants) do
                        if v ~= canon and isLowerInit(v) then
                            local m = aliasmap[cls]
                            if not m then m = {}; aliasmap[cls] = m end
                            m[v] = canon
                            flat[v] = true
                        end
                    end
                end
            end
        end
    end
    -- Singleton lowercase aliases whose canonical is a child service, not a
    -- reflected member (so the ci-pair scan above cannot find them).
    aliasmap.DataModel = aliasmap.DataModel or {}
    if not aliasmap.DataModel.lighting then aliasmap.DataModel.lighting = "Lighting"; flat.lighting = true end
    if not aliasmap.DataModel.workspace then aliasmap.DataModel.workspace = "Workspace"; flat.workspace = true end
    robloxApi.aliasmap = aliasmap
    robloxApi.aliasflat = flat
end
-- Resolve `key` to its canonical member name for `className` (walking the
-- inheritance chain, since e.g. `className`/`isA` live on Object), or nil when
-- `key` is not a deprecated alias for this class.
robloxApi.resolveAlias = function(className, key)
    if not className or not robloxApi.aliasmap then return nil end
    local c, g = className, 0
    while c and g < 128 do
        local m = robloxApi.aliasmap[c]
        if m and m[key] then return m[key] end
        c = robloxApi.msuper[c] or (robloxApi.super and robloxApi.super[c]) or (robloxApi.psuper and robloxApi.psuper[c])
        g = g + 1
    end
    return nil
end
-- [PATCH] True iff `cn` is BasePart-derived (the classes that own an assembly
-- velocity / mass / can be simulated under gravity).
robloxApi.isPartLikeClass = function(cn)
    local c, g = cn, 0
    while c and g < 64 do
        if c == "BasePart" then return true end
        c = robloxApi.psuper and robloxApi.psuper[c]
        g = g + 1
    end
    return false
end
-- Assembly mass = bounding volume * density (Roblox default density 0.7), plus
-- the principal Y inertia of the box, used so ApplyImpulse / ApplyAngularImpulse
-- divide by mass / inertia exactly like the engine (a raw impulse magnitude is
-- physically impossible -- dtc12/dtc13).
robloxApi.partMass = function(props)
    local x, y, z = 4, 1.2, 2
    local sz = props and props.Size
    if type(sz) == "table" then
        if type(sz.X) == "number" then x = sz.X end
        if type(sz.Y) == "number" then y = sz.Y end
        if type(sz.Z) == "number" then z = sz.Z end
    end
    local mass = robloxApi.f32round(math.max(0.01, x * y * z * 0.7))
    local inertiaY = math.max(0.01, mass * (x * x + z * z) / 12)
    return mass, inertiaY
end
-- Simulate AssemblyLinearVelocity / AssemblyAngularVelocity for an unanchored
-- BasePart: movers (LinearVelocity / BodyVelocity / AngularVelocity) drive the
-- velocity directly, forces (VectorForce / BodyForce / Torque) accelerate the
-- assembly, and a free body falls under gravity -- mirroring real physics so a
-- velocity read after task.wait reflects motion (dtc6-13, dtc15, dtc111).
-- Read a component of a Vector3-like value regardless of whether it is stored
-- as an emulated proxy (table) or a native datatype (userdata).
local function _vaxis(v, axis)
    local t = type(v)
    if t == "table" or t == "userdata" then
        local ok, c = pcall(function() return v[axis] end)
        if ok and type(c) == "number" then return c end
    end
    return 0
end
-- A mover's force/velocity vector is "active" when its enabling magnitude
-- (MaxForce / MaxTorque) is non-zero (a scalar, a Vector3, or math.huge).
local function _moverActive(limit)
    if limit == nil then return true end
    local t = type(limit)
    if t == "number" then return limit > 0 end
    if t == "table" or t == "userdata" then
        return _vaxis(limit, "X") ~= 0 or _vaxis(limit, "Y") ~= 0 or _vaxis(limit, "Z") ~= 0 or limit == math.huge
    end
    return true
end
robloxApi.assemblyVelocity = function(proxy, key)
    local props = dumperState.property_store[proxy]
    if not props then return Vector3.new(0, 0, 0) end
    local angular = (key == "AssemblyAngularVelocity" or key == "RotVelocity")
    if props.Anchored == true then return Vector3.new(0, 0, 0) end
    -- [PATCH:PHYSICS-SCOPE] only parts that are in the Workspace are simulated; an unparented
    -- Instance.new("Part") has no physics (velocity stays 0, nothing falls).
    if rawget(proxy, "__created_instance") then
        local _w, _g = dumperState.parent_map[proxy], 0
        local _inWs = false
        while _w ~= nil and _g < 128 do
            if _w == workspace then _inWs = true; break end
            _w = dumperState.parent_map[_w]; _g = _g + 1
        end
        if not _inWs then return props[key] or Vector3.new(0, 0, 0) end
    end
    local base = props[key]
        or (angular and props.RotVelocity or props.Velocity)
        or Vector3.new(0, 0, 0)
    local bx, by, bz = _vaxis(base, "X"), _vaxis(base, "Y"), _vaxis(base, "Z")
    -- gather child movers. A child's parent is recorded either in parent_map
    -- (Instance.new(cls, parent)) or in its property_store .Parent (`x.Parent=p`).
    local linMover, bodyVel, angMover
    local fx, fy, fz, tx, ty, tz = 0, 0, 0, 0, 0, 0
    local hasLinForce, hasAngForce = false, false
    for obj, cp in pairs(dumperState.property_store) do
        if cp and (cp.Parent == proxy or dumperState.parent_map[obj] == proxy) then
            local ccn = cp.ClassName
            if ccn == "LinearVelocity" then linMover = cp
            elseif ccn == "BodyVelocity" then bodyVel = cp
            elseif ccn == "AngularVelocity" or ccn == "BodyAngularVelocity" then angMover = cp
            elseif ccn == "VectorForce" or ccn == "BodyForce" or ccn == "BodyThrust" then
                fx = fx + _vaxis(cp.Force, "X"); fy = fy + _vaxis(cp.Force, "Y"); fz = fz + _vaxis(cp.Force, "Z")
                hasLinForce = true
            elseif ccn == "Torque" then
                tx = tx + _vaxis(cp.Torque, "X"); ty = ty + _vaxis(cp.Torque, "Y"); tz = tz + _vaxis(cp.Torque, "Z")
                hasAngForce = true
            end
        end
    end
    local now = get_virtual_clock()
    local mass, inertiaY = robloxApi.partMass(props)
    if angular then
        if angMover and angMover.AngularVelocity ~= nil and _moverActive(angMover.MaxTorque) then
            return angMover.AngularVelocity
        end
        local t0 = props._physAngT0 or props._phys_t0
        if not hasAngForce or t0 == nil then return base end
        local dt = math.max(0.0001, now - t0)
        return Vector3.new(bx + (tx / inertiaY) * dt, by + (ty / inertiaY) * dt, bz + (tz / inertiaY) * dt)
    else
        if linMover and linMover.VectorVelocity ~= nil and _moverActive(linMover.MaxForce) then
            return linMover.VectorVelocity
        end
        if bodyVel and bodyVel.Velocity ~= nil and _moverActive(bodyVel.MaxForce) then
            return bodyVel.Velocity
        end
        local t0 = props._physVelT0 or props._phys_t0
        if t0 == nil then return base end
        local dt = math.max(0.0001, now - t0)
        if hasLinForce then
            return Vector3.new(bx + (fx / mass) * dt,
                by + (fy / mass - 196.2) * dt,
                bz + (fz / mass) * dt)
        end
        return Vector3.new(bx, by - 196.2 * dt, bz)
    end
end
local function createProxyInstance(bm)
    local proxy, meta = createProxy()
    rawset(proxy, proxyMarker, true)
    rawset(proxy, "__value", bm)
    dumperState.registry[proxy] = toStringFunction(bm)
    meta.__tostring = function() return toStringFunction(bm) end
    meta.__index = function(tbl, key)
        if key == proxyList or key == "__proxy_id" or key == proxyMarker or key == "__value" then
            return rawget(tbl, key)
        end
        return createProxyInstance(0)
    end
    meta.__newindex = function() end
    meta.__call = function() return bm end
    local function op(symbol)
        return function(a, b)
            local valA = typeFunction(a) == "table" and rawget(a, "__value") or a or 0
            local valB = typeFunction(b) == "table" and rawget(b, "__value") or b or 0
            local res
            if symbol == "+" then res = valA + valB
            elseif symbol == "-" then res = valA - valB
            elseif symbol == "*" then res = valA * valB
            elseif symbol == "/" then res = valB ~= 0 and valA / valB or 0
            elseif symbol == "%" then res = valB ~= 0 and valA % valB or 0
            elseif symbol == "^" then res = valA ^ valB
            else res = 0 end
            return createProxyInstance(res)
        end
    end
    meta.__add = op("+")
    meta.__sub = op("-")
    meta.__mul = op("*")
    meta.__div = op("/")
    meta.__mod = op("%")
    meta.__pow = op("^")
    meta.__unm = function(a) return createProxyInstance(-(rawget(a, "__value") or 0)) end
    meta.__eq = function(a, b)
        local valA = typeFunction(a) == "table" and rawget(a, "__value") or a
        local valB = typeFunction(b) == "table" and rawget(b, "__value") or b
        return valA == valB
    end
    meta.__lt = function(a, b)
        local valA = typeFunction(a) == "table" and rawget(a, "__value") or a
        local valB = typeFunction(b) == "table" and rawget(b, "__value") or b
        return valA < valB
    end
    meta.__le = function(a, b)
        local valA = typeFunction(a) == "table" and rawget(a, "__value") or a
        local valB = typeFunction(b) == "table" and rawget(b, "__value") or b
        return valA <= valB
    end
    meta.__len = function() return 0 end
    return proxy
end
local function executeFunction(func, args)
    if typeFunction(func) ~= "function" then
        return {}
    end
    local outputCount = #dumperState.output
    local previousIteratorState = dumperState.pending_iterator
    dumperState.pending_iterator = false
    xpcallFunction( function() func(table.unpack(args or {})) end, function() end )
    while dumperState.pending_iterator do
        dumperState.indent = dumperState.indent - 1
        emitOutput("end")
        dumperState.pending_iterator = false
    end
    dumperState.pending_iterator = previousIteratorState
    local capturedLines = {}
    for i = outputCount + 1, #dumperState.output do
        table.insert(capturedLines, dumperState.output[i])
    end
    for i = #dumperState.output, outputCount + 1, -1 do
        table.remove(dumperState.output, i)
    end
    return capturedLines
end
createProxyMethod = function(methodName, parentProxy)
    -- [API-CASE] Return one stable method object per (instance, method name). A
    -- real client hands back the same function for repeated reads of a member
    -- method, so `part.GetConnectedParts == part.GetConnectedParts` holds -- and,
    -- with first-letter case-insensitive resolution, so does
    -- `part.getConnectedParts == part.GetConnectedParts`. Without this, methods
    -- resolved off the API dump (rather than the hand-written serviceMethods,
    -- which already cache) produced a fresh function each read, so both the
    -- same-case and lowercase-vs-uppercase identity checks fingerprinted the
    -- emulator. Signals are intentionally excluded: Roblox creates a fresh bound
    -- method for sig.Wait/Connect each time.
    local _mSig = formatValue(methodName)
    local _cacheable = parentProxy ~= nil and not (typeFunction(parentProxy) == "table" and rawget(parentProxy, "__is_signal"))
    if _cacheable then
        dumperState.proxymethod_cache = dumperState.proxymethod_cache or setmetatable({}, {__mode = "k"})
        local _mc = dumperState.proxymethod_cache[parentProxy]
        if _mc and _mc[_mSig] ~= nil then return _mc[_mSig] end
    end
    local proxy, meta = createProxy()
    rawset(proxy, "__is_method", true)
    local parentName = dumperState.registry[parentProxy] or "object"
    local methodSignature = _mSig
    dumperState.registry[proxy] = parentName .. "." .. methodSignature

    -- [PATCH] Resolve this method's Roblox return type from the API dump so the
    -- call yields a correctly-typed value (e.g. Stats:GetHarmonyQualityLevel()->
    -- number, Camera:GetRenderCFrame()->CFrame) instead of a generic proxy. Only
    -- concrete scalar/datatype/enum returns are substituted; object / tuple /
    -- array returns keep the traced proxy so chained access still works.
    local _retToken
    do
        local _pcn = robloxApi.resolveClass(parentProxy, parentName,
            (type(parentName) == "string" and parentName:match("([%w_]+)$")) or nil)
        if _pcn then
            -- Prefer methodret2 (API-dump return kinds for void / array / signal /
            -- key datatypes -- makes i:Abort()==nil, i:GetAccessories()=={}, etc.)
            -- then fall back to methodret (scalar/datatype/enum returns).
            local cc, g = _pcn, 0
            while cc and g < 64 do
                local s2 = robloxApi.methodret2 and robloxApi.methodret2[cc]
                if s2 and s2[methodSignature] ~= nil then _retToken = s2[methodSignature]; break end
                local s = robloxApi.methodret and robloxApi.methodret[cc]
                if s and s[methodSignature] ~= nil then _retToken = s[methodSignature]; break end
                cc = (robloxApi.msuper and robloxApi.msuper[cc]) or (robloxApi.psuper and robloxApi.psuper[cc])
                g = g + 1
            end
        end
    end

    local function isInstanceLikeParent()
        if parentProxy == game or parentProxy == workspace or parentProxy == script then
            return true
        end
        local pn = dumperState.registry[parentProxy]
        if type(pn) ~= "string" then return false end
        -- Anything rooted under game./workspace./script. is a real Instance path.
        if pn:match("^game[%.:]") or pn:match("^workspace[%.:]") or pn:match("^script[%.:]") then
            return true
        end
        -- Top-level service access (e.g. the `Players` proxy itself).
        if serviceNames and serviceNames[pn] then return true end
        return false
    end

    meta.__call = function(self, firstArg, ...)
        local args
        if firstArg == proxy or firstArg == parentProxy or isProxy(firstArg) then
            args = {...}
        elseif not isInstanceLikeParent() then
            -- Userland table (UI lib, `loaded`, etc.) — dot-call is fine, pass through as-is.
            args = {firstArg, ...}
        else
            error("Expected ':' not '.' calling member function " .. methodSignature, 2)
        end
        local lowerMethod = methodSignature:lower()
        local uiPrefix = nil
        for _, uiEntry in ipairsFunction(uiNamingConvention) do
            if lowerMethod:find(uiEntry.pattern) then
                uiPrefix = uiEntry.prefix
                break
            end
        end
        local callbackFunc, callbackKey, callbackIndex = nil, nil, nil
        for i, val in ipairsFunction(args) do
            if typeFunction(val) == "function" then
                callbackFunc = val
                break
            elseif typeFunction(val) == "table" and not isProxy(val) then
                for k, v in pairsFunction(val) do
                    local keyStr = toStringFunction(k):lower()
                    if keyStr == "callback" and typeFunction(v) == "function" then
                        callbackFunc = v
                        callbackKey = k
                        callbackIndex = i
                        break
                    end
                end
            end
        end
        local defaultParam, dummyArgs = "value", {}
        if callbackFunc then
            if lowerMethod:match("toggle") then
                defaultParam = "enabled"
                dummyArgs = {true}
            elseif lowerMethod:match("slider") then
                defaultParam = "value"
                dummyArgs = {50}
            elseif lowerMethod:match("dropdown") then
                defaultParam = "selected"
                dummyArgs = {"Option"}
            elseif lowerMethod:match("textbox") or lowerMethod:match("input") then
                defaultParam = "text"
                dummyArgs = {inputKey or "input"}
            elseif lowerMethod:match("keybind") or lowerMethod:match("bind") then
                defaultParam = "key"
                dummyArgs = {robloxApi.enumByPath("Enum.KeyCode.E")}
            elseif lowerMethod:match("color") then
                defaultParam = "color"
                dummyArgs = {Color3.fromRGB(255, 255, 255)}
            elseif lowerMethod:match("button") then
                defaultParam = "\\"
                dummyArgs = {}
            end
        end
        local callbackLines = {}
        if callbackFunc then
            callbackLines = executeFunction(callbackFunc, dummyArgs)
        end
        local newProxy = createProxyObject(uiPrefix or methodSignature, false, parentProxy)
        local varName = registerVariable(newProxy, uiPrefix or methodSignature, nil, methodSignature)
        local argStrings = {}
        for i, val in ipairsFunction(args) do
            if typeFunction(val) == "table" and not isProxy(val) and i == callbackIndex then
                local tableParts = {}
                for k, v in pairsFunction(val) do
                    local keyStr
                    if typeFunction(k) == "string" and k:match("^[%a_][%w_]*$") then
                        keyStr = k
                    else
                        keyStr = "[" .. serializeValue(k) .. "]"
                    end
                    if k == callbackKey and #callbackLines > 0 then
                        local funcSignature = defaultParam ~= '"' and "function(" .. "bI" .. ")" or "function()"
                        local indent = string.rep("    ", dumperState.indent + 2)
                        local funcBody = {}
                        for _, line in ipairsFunction(callbackLines) do
                            table.insert(funcBody, indent .. (line:match("^%s*(.*)$") or line))
                        end
                        local baseIndent = string.rep("    ", dumperState.indent + 1)
                        table.insert(tableParts, keyStr .. " = " .. funcSignature .. "\n" .. table.concat(funcBody, "\n") .. "\n" .. baseIndent .. "end")
                    elseif k == callbackKey then
                        local funcDef = defaultParam ~= "\\" and "function(" .. defaultParam .. ") end" or "function() end"
                        table.insert(tableParts, keyStr .. " = " .. funcDef)
                    else
                        table.insert(tableParts, keyStr .. " = " .. serializeValue(v))
                    end
                end
                table.insert(argStrings, "{\n" .. string.rep("    ", dumperState.indent + 1) .. table.concat(tableParts, ",\n" .. string.rep("    ", dumperState.indent + 1)) .. "\n" .. string.rep("    ", dumperState.indent) .. "}")
            elseif typeFunction(val) == "function" then
                if #callbackLines > 0 then
                    local funcSignature = defaultParam ~= '"' and "function(" .. defaultParam .. ")" or "function()"
                    local indent = string.rep("    ", dumperState.indent + 1)
                    local funcBody = {}
                    for _, line in ipairsFunction(callbackLines) do
                        table.insert(funcBody, indent .. (line:match("^%s*(.*)$") or line))
                    end
                    table.insert(argStrings, funcSignature .. "\n" .. table.concat(funcBody, "\n") .. "\n" .. string.rep("    ", dumperState.indent) .. "end")
                else
                    local funcDef = defaultParam ~= '"' and "function(" .. defaultParam .. ") end" or "function() end"
                    table.insert(argStrings, funcDef)
                end
            else
                table.insert(argStrings, serializeValue(val))
            end
        end
        emitOutput(string.format("local %s = %s:%s(%s)", varName, parentName, methodSignature, table.concat(argStrings, ", ")))
        if _retToken == "V" then
            -- Void method: Roblox returns no value at all (dtc120..). Returning a
            -- proxy here is the tell-tale of an emulator, so return nil.
            return nil
        elseif _retToken == "A" then
            -- Array / dictionary / instance-list return: Roblox hands back a Lua
            -- table (typeof == "table"). Return a real empty table (dtc157..).
            return {}
        elseif _retToken == "SIG" then
            -- Signal-returning method (e.g. GetStyledPropertyChangedSignal):
            -- typeof must be "RBXScriptSignal" (dtc220..).
            local sig = createProxyObject(methodSignature, false, parentProxy)
            rawset(sig, "__is_signal", true)
            return sig
        elseif _retToken then
            local _rv = robloxApi.typedDefault(_retToken, methodSignature, nil)
            if _rv ~= nil then return _rv end
        end
        return newProxy
    end
    meta.__index = function(tbl, key)
        if key == proxyList or key == "__proxy_id" then
            return rawget(tbl, key)
        end
        return createProxyMethod(key, proxy)
    end
    meta.__tostring = function() return methodAddrString(proxy) end
    -- [MANUAL] A real Roblox method reads back as a value of type "function"
    -- (dtc102..112). Return a real function that forwards to the tracing proxy so
    -- calls are still logged and typed, while type()/tostring look like a function.
    local fn = function(...) return proxy(...) end
    proxyStore[fn] = true
    dumperState.registry[fn] = dumperState.registry[proxy]
    rawset(proxy, "__method_fn", fn)
    if _cacheable then
        local _mc = dumperState.proxymethod_cache[parentProxy]
        if not _mc then _mc = {}; dumperState.proxymethod_cache[parentProxy] = _mc end
        _mc[methodSignature] = fn
    end
    return fn
end
local function shared_proxy_eq(a, b)
    if rawEqualFunction(a, b) then return true end
    local regA = typeFunction(a) == "table" and dumperState.registry[a]
    local regB = typeFunction(b) == "table" and dumperState.registry[b]
    if regA and regB and regA == regB then
        return true
    end
    return false
end
-- Ordering metamethods MUST be a single shared reference: Luau (Lua 5.1
-- semantics) only invokes __lt/__le when the two operands' metatables differ
-- if BOTH carry the *same* metamethod closure. Per-proxy closures therefore
-- fall through to the native "attempt to compare table < table" error, leaking
-- the raw Lua type. Sharing one closure makes proxy<proxy raise the engine's
-- "attempt to compare two Instance values" instead (dtc91, 92).
-- [PATCH:DT-OPS2] the message names the typeof of each operand (EnumItem, NumberRange,
-- RBXScriptSignal, ...), "two X values" only when both are the same type.
robloxApi.opTn = function(v)
    local okT, r = pcall(_G.typeof, v)
    if okT and typeFunction(r) == "string" then return r end
    return typeFunction(v)
end
-- [PATCH:TASK-SCHED] task.delay/delay record the virtual time at which they become due;
-- the scheduler runs due tasks ordered by due time (stable for equal times).
robloxApi.nativeCG = collectgarbage
robloxApi.taskDue = setmetatable({}, {__mode = "k"})
robloxApi.takeDue = function(now, force)
    local pending = dumperState.deferred_tasks or {}
    local run, keep = {}, {}
    for _, fn in ipairs(pending) do
        local due = robloxApi.taskDue[fn]
        if due and not force and due > now then keep[#keep + 1] = fn else run[#run + 1] = fn end
    end
    for i, fn in ipairs(run) do run[i] = {fn, robloxApi.taskDue[fn] or -math.huge, i} end
    table.sort(run, function(x, y) if x[2] ~= y[2] then return x[2] < y[2] end return x[3] < y[3] end)
    for i, e in ipairs(run) do run[i] = e[1] end
    dumperState.deferred_tasks = keep
    return run
end
robloxApi.easeValue = function(alpha, sn, dn)
        local pi, sin, cos, sqrt = math.pi, math.sin, math.cos, math.sqrt
        local function bounceOut(t)
            if t < 1 / 2.75 then return 7.5625 * t * t
            elseif t < 2 / 2.75 then t = t - 1.5 / 2.75; return 7.5625 * t * t + 0.75
            elseif t < 2.5 / 2.75 then t = t - 2.25 / 2.75; return 7.5625 * t * t + 0.9375
            else t = t - 2.625 / 2.75; return 7.5625 * t * t + 0.984375 end
        end
        local F = {
            Linear = function(t) return t end,
            Quad = function(t) return t * t end,
            Cubic = function(t) return t * t * t end,
            Quart = function(t) return t * t * t * t end,
            Quint = function(t) return t * t * t * t * t end,
            Sine = function(t) return 1 - cos(t * pi / 2) end,
            Exponential = function(t) if t <= 0 then return 0 end return 2 ^ (10 * t - 10) end,
            Circular = function(t) return 1 - sqrt(1 - t * t) end,
            Back = function(t) return t * t * (2.70158 * t - 1.70158) end,
            Bounce = function(t) return 1 - bounceOut(1 - t) end,
            Elastic = function(t)
                if t <= 0 then return 0 elseif t >= 1 then return 1 end
                return -(2 ^ (10 * (t - 1))) * sin((t - 1.075) * 2 * pi / 0.3)
            end,
        }
        local f = F[sn] or F.Linear
        if alpha <= 0 then return 0 elseif alpha >= 1 then return 1 end
        if sn == "Linear" then return alpha end
        if dn == "In" then return f(alpha)
        elseif dn == "Out" then return 1 - f(1 - alpha)
        else
            if alpha < 0.5 then return f(2 * alpha) / 2 end
            return 1 - f(2 * (1 - alpha)) / 2
        end
end
-- [PATCH:TWEEN-ENGINE] Tweens interpolate over simulated frames (task.wait / Completed:Wait()),
-- honouring Time, EasingStyle/Direction, DelayTime, RepeatCount and Reverses; Completed fires with the
-- final PlaybackState. Properties are written through the instance proxy so change events fire.
robloxApi.activeTweens = {}
robloxApi.frameWork = function()
    return dumperState.event_callbacks ~= nil or next(robloxApi.renderFns) ~= nil or #robloxApi.activeTweens > 0
end
robloxApi.lerpVal = function(a, b, x)
    local ta = robloxApi.opTn(a)
    if ta == "number" and typeFunction(b) == "number" then return a + (b - a) * x end
    if ta == "UDim" then return UDim.new(a.Scale + (b.Scale - a.Scale) * x, a.Offset + (b.Offset - a.Offset) * x) end
    if ta == "boolean" or ta == "string" or ta == "EnumItem" or ta == "BrickColor" or ta == "Instance" then return x >= 1 and b or a end
    local ok, r = pcallFunction(function() return a:Lerp(b, x) end)
    if ok then return r end
    return x >= 1 and b or a
end
robloxApi.tweenWrite = function(tw, st, alphaOrFinal, final)
    local old, oldIndent, oldLast = dumperState.output, dumperState.indent, dumperState.last_emitted_line
    dumperState.output = {}
    for k, to in pairsFunction(st.to) do
        local v = final and alphaOrFinal(k, to) or robloxApi.lerpVal(st.from[k], to, alphaOrFinal)
        pcallFunction(function() st.target[k] = v end)
    end
    if LG.hkLeave then LG.hkLeave(dumperState.output) end -- [v1.6 HookOP v2]
    dumperState.output, dumperState.indent, dumperState.last_emitted_line = old, oldIndent, oldLast
end
robloxApi.tweenSet = function(tw, stateName)
    local ps = dumperState.property_store[tw]
    ps.PlaybackState = robloxApi.enumByPath("Enum.PlaybackState." .. stateName)
end
robloxApi.tweenFinish = function(tw, stateName)
    local ps = dumperState.property_store[tw]
    local st = ps._tw
    for i = #robloxApi.activeTweens, 1, -1 do if robloxApi.activeTweens[i] == tw then table.remove(robloxApi.activeTweens, i) end end
    robloxApi.tweenSet(tw, stateName)
    if st then st.done = true end
    local old, oldIndent, oldLast = dumperState.output, dumperState.indent, dumperState.last_emitted_line
    dumperState.output = {}
    robloxApi.fireSig(tw, "Completed", ps.PlaybackState)
    if LG.hkLeave then LG.hkLeave(dumperState.output) end -- [v1.6 HookOP v2]
    dumperState.output, dumperState.indent, dumperState.last_emitted_line = old, oldIndent, oldLast
end
robloxApi.tweenInfoOf = function(tw)
    local ps = dumperState.property_store[tw]
    local ti = ps.TweenInfo
    local g = function(k, d) local ok, v = pcallFunction(function() return ti[k] end) if ok and v ~= nil then return v end return d end
    local style, dir = g("EasingStyle"), g("EasingDirection")
    return {time = g("Time", 1), style = style and style.Name or "Quad", dir = dir and dir.Name or "Out",
        reps = g("RepeatCount", 0), rev = g("Reverses", false), delay = g("DelayTime", 0)}
end
robloxApi.tweenPlay = function(tw)
    local ps = dumperState.property_store[tw]
    local st = ps._tw
    local cur = ps.PlaybackState and ps.PlaybackState.Name
    if cur == "Playing" or cur == "Delayed" then return end
    if cur == "Paused" and st and not st.done then
        robloxApi.tweenSet(tw, st.elapsed < st.info.delay and "Delayed" or "Playing")
        robloxApi.activeTweens[#robloxApi.activeTweens + 1] = tw
        return
    end
    st = {elapsed = 0, from = {}, to = {}, target = ps._target, info = robloxApi.tweenInfoOf(tw)}
    for k, v in pairsFunction(ps._properties) do
        local ok, c = pcallFunction(function() return st.target[k] end)
        if ok and c ~= nil then st.from[k] = c; st.to[k] = v end
    end
    ps._tw = st
    robloxApi.tweenSet(tw, st.info.delay > 0 and "Delayed" or "Playing")
    robloxApi.activeTweens[#robloxApi.activeTweens + 1] = tw
end
robloxApi.tweenPause = function(tw)
    local ps = dumperState.property_store[tw]
    local cur = ps.PlaybackState and ps.PlaybackState.Name
    if cur ~= "Playing" and cur ~= "Delayed" then return end
    for i = #robloxApi.activeTweens, 1, -1 do if robloxApi.activeTweens[i] == tw then table.remove(robloxApi.activeTweens, i) end end
    robloxApi.tweenSet(tw, "Paused")
end
robloxApi.tweenCancel = function(tw)
    local ps = dumperState.property_store[tw]
    local cur = ps.PlaybackState and ps.PlaybackState.Name
    if cur ~= "Playing" and cur ~= "Delayed" and cur ~= "Paused" then return end
    robloxApi.tweenFinish(tw, "Cancelled")
end
robloxApi.stepTweens = function(dt)
    local list = {}
    for i, tw in ipairsFunction(robloxApi.activeTweens) do list[i] = tw end
    for _, tw in ipairsFunction(list) do
        local ps = dumperState.property_store[tw]
        local st = ps and ps._tw
        local cur = ps and ps.PlaybackState and ps.PlaybackState.Name
        if st and (cur == "Playing" or cur == "Delayed") then
            local info = st.info
            st.elapsed = st.elapsed + dt
            local e = st.elapsed - info.delay
            if e < 0 then
                robloxApi.tweenSet(tw, "Delayed")
            else
                if cur == "Delayed" then robloxApi.tweenSet(tw, "Playing") end
                local cycle = info.time * (info.rev and 2 or 1)
                local total = cycle * (info.reps + 1)
                if info.time <= 0 or (info.reps >= 0 and e >= total) then
                    robloxApi.tweenWrite(tw, st, function(k, to) if info.rev and info.time > 0 then return st.from[k] end return to end, true)
                    robloxApi.tweenFinish(tw, "Completed")
                else
                    local ce = e % cycle
                    local x = ce / info.time
                    if x > 1 then x = 2 - x end
                    robloxApi.tweenWrite(tw, st, robloxApi.easeValue(x, info.style, info.dir))
                end
            end
        end
    end
end
robloxApi.finishTweens = function()
    local list = {}
    for i, tw in ipairsFunction(robloxApi.activeTweens) do list[i] = tw end
    for _, tw in ipairsFunction(list) do
        local ps = dumperState.property_store[tw]
        local st = ps and ps._tw
        if st and st.info.reps >= 0 then
            local info = st.info
            robloxApi.tweenWrite(tw, st, function(k, to) if info.rev and info.time > 0 then return st.from[k] end return to end, true)
            robloxApi.tweenFinish(tw, "Completed")
        end
    end
end
-- [PATCH:RENDERSTEP] frame dispatcher: per frame RenderStepped phase (bound steps by priority, then
-- PreRender/RenderStepped), PreAnimation, Stepped, PreSimulation, PostSimulation, Heartbeat.
robloxApi.renderFns = {}
robloxApi.renderSeq = 0
robloxApi.phaseCache = {}
robloxApi.framePhase = function(path)
    local c = robloxApi.phaseCache[path]
    if c ~= nil then return c or nil end
    local ph = false
    if path:find("RenderStepped", 1, true) or path:find("PreRender", 1, true) then ph = 2
    elseif path:find("PreAnimation", 1, true) then ph = 3
    elseif path:find("PreSimulation", 1, true) then ph = 5
    elseif path:find("PostSimulation", 1, true) then ph = 6
    elseif path:find("Stepped", 1, true) then ph = 4
    elseif path:find("Heartbeat", 1, true) then ph = 7 end
    robloxApi.phaseCache[path] = ph
    return ph or nil
end
robloxApi.runBound = function(e, dt)
    if e.block then
        local block = e.block
        e.block = nil
        local old_output, old_indent, old_last = dumperState.output, dumperState.indent, dumperState.last_emitted_line
        local captured = {}
        dumperState.output = captured
        dumperState.indent = e.indent + 1
        dumperState.last_emitted_line = nil
        pcallFunction(e.func, dt)
        if LG.hkLeave then LG.hkLeave(dumperState.output) end -- [v1.6 HookOP v2]
        dumperState.output, dumperState.indent, dumperState.last_emitted_line = old_output, old_indent, old_last
        for i = 1, #dumperState.output do
            if dumperState.output[i] == block then
                table.remove(dumperState.output, i)
                for k = #captured, 1, -1 do table.insert(dumperState.output, i, captured[k]) end
                break
            end
        end
    else
        pcallFunction(e.func, dt)
    end
end
robloxApi.flushBound = function()
    local list = {}
    for _, e in pairsFunction(robloxApi.renderFns) do if e.block then list[#list + 1] = e end end
    table.sort(list, function(a, b) if a.priority ~= b.priority then return a.priority < b.priority end return a.seq < b.seq end)
    for _, e in ipairsFunction(list) do robloxApi.runBound(e, 1 / 60) end
end
robloxApi.runFrames = function(frames, dt, advance)
    for _ = 1, frames do
        local curDt = dt + math.random() * 0.0005
        if advance then advance(curDt) end
        if #robloxApi.activeTweens > 0 then robloxApi.stepTweens(curDt) end
        local buckets = {}
        local all = dumperState.event_callbacks
        if all then
            local paths = {}
            for path in pairsFunction(all) do
                if typeFunction(path) == "string" and robloxApi.framePhase(path) then paths[#paths + 1] = path end
            end
            table.sort(paths)
            for _, path in ipairsFunction(paths) do
                local ph = robloxApi.framePhase(path)
                local b = buckets[ph]; if not b then b = {}; buckets[ph] = b end
                for _, cb in ipairsFunction(all[path]) do b[#b + 1] = {path, cb} end
            end
        end
        local bound = {}
        for _, e in pairsFunction(robloxApi.renderFns) do bound[#bound + 1] = e end
        table.sort(bound, function(a, b) if a.priority ~= b.priority then return a.priority < b.priority end return a.seq < b.seq end)
        for _, e in ipairsFunction(bound) do
            if robloxApi.renderFns[e.name] == e then robloxApi.runBound(e, curDt) end
        end
        for ph = 2, 7 do
            local b = buckets[ph]
            if b then
                for _, pc in ipairsFunction(b) do
                    local cb = pc[1] and pc[2]
                    if ph == 4 then pcallFunction(function() cb(get_virtual_clock(), curDt) end)
                    else pcallFunction(function() cb(curDt) end) end
                end
            end
        end
    end
end
robloxApi.aabbOf = function(cf, sz)
    local lo, hi
    for sx = -1, 1, 2 do for sy = -1, 1, 2 do for sz2 = -1, 1, 2 do
        local c = cf * Vector3.new(sx * sz.X / 2, sy * sz.Y / 2, sz2 * sz.Z / 2)
        if not lo then lo = Vector3.new(c.X, c.Y, c.Z); hi = Vector3.new(c.X, c.Y, c.Z)
        else
            lo = Vector3.new(math.min(lo.X, c.X), math.min(lo.Y, c.Y), math.min(lo.Z, c.Z))
            hi = Vector3.new(math.max(hi.X, c.X), math.max(hi.Y, c.Y), math.max(hi.Z, c.Z))
        end
    end end end
    return lo, hi
end
robloxApi.treeCount = function()
    local n = 0
    for obj in pairsFunction(dumperState.parent_map) do
        if rawget(obj, "__created_instance") and robloxApi.inDataModel(obj) then n = n + 1 end
    end
    return n
end
robloxApi.cmpLt = function(a, b) robloxApi.cmpErr(a, b) end
robloxApi.cmpErr = function(a, b)
    local ta, tb = robloxApi.opTn(a), robloxApi.opTn(b)
    if ta == tb then error("attempt to compare two " .. ta .. " values", 3) end
    error("attempt to compare " .. ta .. " with " .. tb, 3)
end
local function shared_proxy_lt(a, b)
    if isProxy(a) or isProxy(b) then robloxApi.cmpErr(a, b) end
    return false
end
local function shared_proxy_le(a, b)
    if isProxy(a) or isProxy(b) then robloxApi.cmpErr(a, b) end
    return false
end

createProxyObject = function(objName, isGlobal, parentProxy)
    local proxy, meta = createProxy()
    local formattedName = formatValue(objName)
    dumperState.property_store[proxy] = {}
    
    if isGlobal then
        dumperState.registry[proxy] = formattedName
        dumperState.names_used[formattedName] = true
    elseif parentProxy then
        dumperState.parent_map[proxy] = parentProxy
        local path = (dumperState.registry[parentProxy] or "object") .. "." .. formattedName
        dumperState.registry[proxy] = path
        rawset(proxy, "__temp_path", path)
    end
    local serviceMethods = {}
    -- [PATCH:SELF-DISPATCH] remember every proxy's own method table so the shared
    -- singleton method objects (game/workspace/script share one function object per
    -- member, like the engine) can dispatch on the actual `self`.
    dumperState.sm_by_proxy = dumperState.sm_by_proxy or setmetatable({}, {__mode = "k"})
    dumperState.sm_by_proxy[proxy] = serviceMethods
    local function getCachedEnum(path)
        return robloxApi.enumByPath(path)
    end
    serviceMethods.GetCollisionGroupId = function(self, name)
        -- PhysicsService:GetCollisionGroupId returns a numeric id; "Default" is 0.
        return 0
    end
    serviceMethods.GetLastInputType = function(self)
        return getCachedEnum("Enum.UserInputType.Keyboard")
    end
    serviceMethods.IsTenFootInterface = function(self)
        return false
    end
    serviceMethods.GetServerTimeNow = function(self)
        return get_virtual_time()
    end
    -- [PATCH:TEXTSIZE] argument validation, proportional glyph widths, word wrapping at frameSize.X
    serviceMethods.GetTextSize = function(self, text, textSize, font, frameSize)
        if typeFunction(text) ~= "string" then error("invalid argument #1 to 'GetTextSize' (string expected, got " .. (text == nil and "no value" or robloxApi.argTn(text)) .. ")", 2) end
        if typeFunction(textSize) ~= "number" then error("invalid argument #2 to 'GetTextSize' (number expected, got " .. (textSize == nil and "no value" or robloxApi.argTn(textSize)) .. ")", 2) end
        robloxApi.needEnumItem(font, "Font", "GetTextSize", 3)
        if robloxApi.opTn(frameSize) ~= "Vector2" then error("invalid argument #4 to 'GetTextSize' (Vector2 expected, got " .. (frameSize == nil and "no value" or robloxApi.opTn(frameSize)) .. ")", 2) end
        local sz = textSize
        local narrow, wide = "iljtfI.,:;!|' ", "mwMW@%&"
        local function cw(c)
            if c == " " then return 0.25 * sz end
            if narrow:find(c, 1, true) then return 0.27 * sz end
            if wide:find(c, 1, true) then return 0.82 * sz end
            if c:match("%u") then return 0.62 * sz end
            return 0.5 * sz
        end
        local function ww(w) local t = 0 for ch in w:gmatch(".") do t = t + cw(ch) end return t end
        local maxW, lines = 0, 0
        for para in (text .. "\n"):gmatch("([^\n]*)\n") do
            lines = lines + 1
            local cur = 0
            for word, sp in para:gmatch("(%S*)(%s*)") do
                if word ~= "" or sp ~= "" then
                    local w = ww(word)
                    if cur > 0 and cur + w > frameSize.X then
                        if cur > maxW then maxW = cur end
                        lines = lines + 1; cur = 0
                    end
                    cur = cur + w + ww(sp)
                end
            end
            if cur > maxW then maxW = cur end
        end
        if text == "" then return Vector2.new(0, sz) end
        return Vector2.new(math.ceil(math.min(maxW, math.max(frameSize.X, 0))), lines * sz)
    end
    serviceMethods.GetMass = function(self)
        -- Agree with the Mass / AssemblyMass property (dtc76): both come from the
        -- shared bounding-volume * density formula.
        local m = robloxApi.partMass(dumperState.property_store[proxy])
        return m
    end
    serviceMethods.GetScale = function(self)
        -- A model with no explicit scale reports 1, never 0 (dtc77); ScaleTo stores the factor [PATCH:MODEL-GEOM]
        local ps = dumperState.property_store[proxy]
        return ps and rawget(ps, "_scale") or 1
