    serviceMethods.GetNumAwakeParts = function(self)
        local n = 0
        for p, ps in pairsFunction(dumperState.property_store) do
            if type(ps) == "table" and rawget(p, "__created_instance")
                and type(ps.ClassName) == "string" and robloxApi.isPartLikeClass(ps.ClassName)
                and ps.Anchored ~= true and (dumperState.parent_map[p] ~= nil or ps.Parent ~= nil) then
                n = n + 1
