    -- mirror the real FloatCurve method contracts from the API dump so an
    -- insert-then-read-back round-trip reports faithful values (goofy anti-tamper
    -- (g)): SetKeys returns the number of keys inserted, Length reflects the
    -- count, and GetKeyAtIndex hands back the actual stored key.
    local function _fcKeyTime(k) local ok, v = pcall(function() return k.Time end); return (ok and tonumber(v)) or 0 end
    local function _fcSortKeys(keys)
        local out = {}
        for _, k in ipairsFunction(keys) do out[#out + 1] = k end
        table.sort(out, function(a, b) return _fcKeyTime(a) < _fcKeyTime(b) end)
        -- Stable removal of duplicate-time keys (keep the first at each time).
        local deduped, seen = {}, {}
        for _, k in ipairsFunction(out) do
            local t = _fcKeyTime(k)
            if not seen[t] then seen[t] = true; deduped[#deduped + 1] = k end
        end
        return deduped
    end
    serviceMethods.SetKeys = function(self, keys)
        local ps = dumperState.property_store[proxy]
        if type(keys) ~= "table" then return 0 end
