    serviceMethods.InsertKey = function(self, key)
        local ps = dumperState.property_store[proxy]
        if not ps then return {true, 0} end
        ps.__fc_keys = ps.__fc_keys or {}
        local t = _fcKeyTime(key)
        local replaced, atIndex = false, nil
        for i, k in ipairsFunction(ps.__fc_keys) do
            if _fcKeyTime(k) == t then ps.__fc_keys[i] = key; replaced = true; atIndex = i; break end
        end
        if not replaced then
            ps.__fc_keys[#ps.__fc_keys + 1] = key
            ps.__fc_keys = _fcSortKeys(ps.__fc_keys)
