        local keys = ps and ps.__fc_keys
        if type(keys) ~= "table" then return 0 end
        local start = tonumber(startingIndex) or 1
        local n = tonumber(count) or 1
        local removed = 0
        for _ = 1, n do
            if keys[start] ~= nil then table.remove(keys, start); removed = removed + 1 else break end
        end
        return removed
    end
    serviceMethods.GetKeyIndicesAtTime = function(self, t)
        local ps = dumperState.property_store[proxy]
        local keys = ps and ps.__fc_keys
        local out = {}
        if type(keys) ~= "table" then return out end
        t = tonumber(t) or 0
        for i, k in ipairsFunction(keys) do
            if _fcKeyTime(k) == t then out[#out + 1] = i end
        end
