    end
    serviceMethods.GetValueAtTime = function(self, t)
        local ps = dumperState.property_store[proxy]
        -- Only FloatCurve returns a scalar; other curve types (Vector3Curve, ...)
        -- return an array/tuple, so hand back a table for them (dtc225).
        if not (ps and ps.ClassName == "FloatCurve") then return {} end
        local keys = ps and ps.__fc_keys
        t = tonumber(t) or 0
        if type(keys) ~= "table" or #keys == 0 then return 0 end
        local function kt(k) local ok, v = pcall(function() return k.Time end); return (ok and tonumber(v)) or 0 end
        local function kv(k) local ok, v = pcall(function() return k.Value end); return (ok and tonumber(v)) or 0 end
        if t <= kt(keys[1]) then return kv(keys[1]) end
        if t >= kt(keys[#keys]) then return kv(keys[#keys]) end
        for i = 2, #keys do
            local a, b = keys[i - 1], keys[i]
            local ta, tb = kt(a), kt(b)
            if t >= ta and t <= tb then
                if tb == ta then return kv(a) end
                return kv(a) + (kv(b) - kv(a)) * (t - ta) / (tb - ta)
            end
        end
        return kv(keys[#keys])
    end
    serviceMethods.GetRealPhysicsFPS = function(self) return 60 end
    -- Stats memory reporters: a live client always reports a positive working
    -- set (in MB), never zero (dtc110).
