        dumperState.fake_mem_mb = dumperState.fake_mem_mb or (260 + math.random() * 180)
        local v = dumperState.fake_mem_mb + (robloxApi.nativeCG("count") or 0) / 1024
        if dumperState.mem_hi and v < dumperState.mem_hi then v = dumperState.mem_hi + math.random() * 0.01 end
        dumperState.mem_hi = v
        return v
    end
