    -- AudioFilter:GetGainAt(freq) -- frequency response of the configured filter.
    -- A lowpass passes lows and attenuates highs (so gain(low) > gain(high)),
    -- a highpass the reverse, etc. (dtc103).
    serviceMethods.GetGainAt = function(self, freq)
        local ps = dumperState.property_store[proxy] or {}
        local cutoff = tonumber(ps.Frequency) or 1000
        freq = tonumber(freq) or cutoff
        local ftName = "Lowpass12dB"
        local ft = ps.FilterType
        if ft ~= nil then
            local reg = (type(ft) == "table" and dumperState.registry[ft]) or tostring(ft)
            ftName = tostring(reg):match("([^%.]+)$") or "Lowpass12dB"
        end
        local lname = ftName:lower()
        local slope = lname:match("24") and 24 or (lname:match("6db") and 6 or 12)
        local octaves = math.log(math.max(freq, 1e-6) / math.max(cutoff, 1e-6)) / math.log(2)
        local db = 0
        if lname:match("lowpass") then
            db = octaves > 0 and -slope * octaves or 0
        elseif lname:match("highpass") then
            db = octaves < 0 and slope * octaves or 0
        elseif lname:match("bandpass") then
            db = -slope * math.abs(octaves)
        elseif lname:match("notch") then
            db = -math.max(0, 24 - slope * math.abs(octaves))
        end
        return 10 ^ (db / 20)
    end
