    -- [PATCH:TWEEN-EASING] TweenService:GetValue(alpha, EasingStyle, EasingDirection) evaluates the
    -- real easing curves (Penner equations) instead of echoing alpha.
    serviceMethods.GetValue = function(self, alpha, style, dir)
        if typeFunction(alpha) ~= "number" then
            error("invalid argument #1 to 'GetValue' (number expected, got " .. (alpha == nil and "no value" or _G.typeof(alpha)) .. ")", 2)
        end
        local function enumName(v, want, idx)
            local okT, tn = pcall(_G.typeof, v)
            if not okT or tn ~= "EnumItem" then
                error("invalid argument #" .. idx .. " to 'GetValue' (" .. want .. " expected, got " .. (v == nil and "no value" or tostring(tn)) .. ")", 3)
            end
            local okE, et = pcall(function() return v.EnumType end)
            if okE and et ~= Enum[want] then
                error("invalid argument #" .. idx .. " to 'GetValue' (" .. want .. " expected)", 3)
            end
            return v.Name
        end
        local sn, dn = enumName(style, "EasingStyle", 2), enumName(dir, "EasingDirection", 3)
        return robloxApi.easeValue(alpha, sn, dn)
    end
