    serviceMethods.GetService = function(self, serviceName)
        -- [PATCH:ARGCHECK] Roblox method argument error
        if serviceName == nil then error("Argument 1 missing or nil", 2) end
        local parentPath = dumperState.registry[proxy] or "game"
        local resolvedName = formatValue(serviceName)
        if typeFunction(resolvedName) == "string" then
            resolvedName = resolvedName:match("^([^%z]*)")
        end
        
        if not serviceNames[resolvedName] then
            scriptError(resolvedName .. " is not a valid Service")
        end

        -- Studio-only services are inaccessible from LocalScript context
        local _studioOnlyServices = {StudioService=true, DebuggerManager=true, ScriptEditorService=true, StudioAssetService=true, StudioPublishService=true, PluginGuiService=true}
        if configuration.CLIENT and _studioOnlyServices[resolvedName] then
            error(resolvedName .. " is not accessible from LocalScript", 2)
        end

        dumperState.service_cache = dumperState.service_cache or {}
        local childProxy = dumperState.service_cache[resolvedName]
        if not childProxy then
            childProxy = createProxyObject(resolvedName, false, proxy)
            dumperState.service_cache[resolvedName] = childProxy
        end

        local varName = registerVariable(childProxy, resolvedName)
        emitOutput(string.format("local %s = %s:GetService(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
        return childProxy
    end
