    serviceMethods.WaitForChild = function(self, childName, timeout)
        -- [PATCH:ARGCHECK] Roblox method argument error
        if childName == nil then error("Argument 1 missing or nil", 2) end
        -- The child name is required; Roblox raises when it is missing (dtc117).
        if childName == nil then
            error("Argument 1 missing or nil", 2)
        end
        local parentPath = dumperState.registry[proxy] or "object"
        local resolvedName = formatValue(childName)
        local childProxy = createProxyObject(resolvedName, false, proxy)
        -- [PATCH:WAIT-PHANTOM] The provisional proxy must not be linked into the
        -- instance tree unless it is actually the value handed back: it used to
        -- be parented immediately, so every WaitForChild() -- even for an existing
        -- or timed-out child -- added a phantom sibling to GetChildren().
        dumperState.parent_map[childProxy] = nil
        dumperState.property_store[childProxy].Name = resolvedName
        rawset(childProxy, "__fabricated", true)
        local varName = registerVariable(childProxy, resolvedName)

        if timeout then
            emitOutput(string.format("local %s = %s:WaitForChild(%s, %s)", varName, parentPath, formatStringLiteral(resolvedName), serializeValue(timeout)))
        else
            emitOutput(string.format("local %s = %s:WaitForChild(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
        end
        
        if typeFunction(timeout) == "number" and timeout < 0 then
            error("Timeout cannot be less than zero", 2)
        end
        
        local function findChild()
            for obj, p in pairsFunction(dumperState.parent_map) do
                if p == proxy and dumperState.property_store[obj]
                    and dumperState.property_store[obj].Name == resolvedName then
                    return obj
                end
            end
            if dumperState.child_cache and dumperState.child_cache[proxy] then
                return dumperState.child_cache[proxy][resolvedName]
            end
            return nil
        end
        local existing = findChild()
        if existing then return existing end

        -- A bounded WaitForChild participates in the same scheduler as spawned
        -- work. Advance one ready callback before deciding that it timed out:
        -- this permits the common `task.spawn(function() task.wait(); child.Parent
        -- = parent end)` pattern without recursively draining work queued for later
        -- frames (which would incorrectly reorder unrelated tasks).
        if typeFunction(timeout) == "number" and timeout > 0
            and dumperState.deferred_tasks and #dumperState.deferred_tasks > 0 then
            local ready = table.remove(dumperState.deferred_tasks, 1)
            if ready then pcallFunction(ready) end
            existing = findChild()
            if existing then return existing end
        end

        -- A child this parent has previously handed out (cached/created) counts
        -- as existing and is returned immediately.
        if dumperState.child_cache and dumperState.child_cache[proxy] and dumperState.child_cache[proxy][resolvedName] then
            return dumperState.child_cache[proxy][resolvedName]
        end
        if rawget(proxy, "__created_instance") then
            -- The synthetic Character proxy is marked __created_instance
            -- to make :Clone() / typeof checks behave, but it must still
            -- yield the usual Character children on demand. Delegate to
            -- the __index handler for well-known names (Humanoid,
            -- HumanoidRootPart, body parts) so :WaitForChild("Humanoid")
            -- returns the same proxy as direct .Humanoid access.
            local _synth = {
                Humanoid=true, HumanoidRootPart=true, RootPart=true,
                PrimaryPart=true, Head=true, Torso=true, UpperTorso=true,
                LowerTorso=true, RightArm=true, LeftArm=true,
                RightLeg=true, LeftLeg=true, RightHand=true, LeftHand=true,
                RightFoot=true, LeftFoot=true, Animate=true,
            }
            if _synth[resolvedName] then
                return proxy[resolvedName]
            end
            return nil
        end
        -- dtc1: with a finite numeric timeout, the real engine yields for the
        -- timeout and returns nil when no such child exists. The environment
        -- has no model of the real instance tree, so an unknown child under a
        -- bounded wait must time out to nil rather than fabricate a proxy. An
        -- unbounded wait (no timeout) still optimistically returns a proxy so
        -- dumps of scripts that block on guaranteed children keep flowing.
        if typeFunction(timeout) == "number" then
            return nil
        end
        dumperState.parent_map[childProxy] = proxy
        dumperState.child_cache = dumperState.child_cache or {}
        dumperState.child_cache[proxy] = dumperState.child_cache[proxy] or {}
        dumperState.child_cache[proxy][resolvedName] = childProxy
        return childProxy
    end
    serviceMethods.FindFirstChild = function(self, childName, recursive)
        -- [PATCH:ARGCHECK] Roblox method argument error
        if childName == nil then error("Argument 1 missing or nil", 2) end
        local resolvedName = formatValue(childName)
        local parentPath = dumperState.registry[proxy] or "object"

        if typeFunction(resolvedName) == "string" and resolvedName:find("[%?%!%@%#%$%%%^%&%*]") then
            emitOutput(string.format("local _ = %s:FindFirstChild(%s) -- nil (invalid name)", parentPath, formatStringLiteral(resolvedName)))
            return nil
        end

        dumperState.child_cache = dumperState.child_cache or {}
        dumperState.child_cache[proxy] = dumperState.child_cache[proxy] or {}
        if dumperState.child_cache[proxy][resolvedName] then
            local cached = dumperState.child_cache[proxy][resolvedName]
            local varName = registerVariable(cached, resolvedName)
            emitOutput(string.format("local %s = %s:FindFirstChild(%s) -- [Cached]", varName, parentPath, formatStringLiteral(resolvedName)))
            return cached
        end

        for obj, parent in pairsFunction(dumperState.parent_map) do
            if parent == proxy and dumperState.property_store[obj] and dumperState.property_store[obj].Name == resolvedName then
                local varName = registerVariable(obj, resolvedName)
                emitOutput(string.format("local %s = %s:FindFirstChild(%s) -- [Cached]", varName, parentPath, formatStringLiteral(resolvedName)))
                dumperState.child_cache[proxy][resolvedName] = obj
                return obj
            end
        end

        if recursive then
            local function findRec(root)
                for obj, parent in pairsFunction(dumperState.parent_map) do
                    if parent == root and dumperState.property_store[obj] and dumperState.property_store[obj].Name == resolvedName then
                        return obj
                    end
                end
                for obj, parent in pairsFunction(dumperState.parent_map) do
                    if parent == root then
                        local found = findRec(obj)
                        if found then return found end
                    end
                end
                return nil
            end
            local found = findRec(proxy)
            if found then
                local varName = registerVariable(found, resolvedName)
                emitOutput(string.format("local %s = %s:FindFirstChild(%s, true)", varName, parentPath, formatStringLiteral(resolvedName)))
                return found
            end
        end

        if rawget(proxy, "__created_instance") then
            emitOutput(string.format("local _ = %s:FindFirstChild(%s) -- nil", parentPath, formatStringLiteral(resolvedName)))
            return nil
        end
        
        if parentPath == "game" then
            if resolvedName == "Workspace" or resolvedName == "workspace" then return workspace end
            if serviceNames[resolvedName] then
                dumperState.service_cache = dumperState.service_cache or {}
                if dumperState.service_cache[resolvedName] then return dumperState.service_cache[resolvedName] end
            else
                return nil
            end
        end
        
        local hasKnownChild = false
        if resolvedName == "StarterPlayerScripts" then hasKnownChild = true end
        if dumperState.service_cache and dumperState.service_cache[resolvedName] then hasKnownChild = true end

        if resolvedName == "Animate" and proxy == dumperState.local_character then
            if not dumperState.animate_script then
                local animProxy = createProxyObject("Animate", false, proxy)
                dumperState.property_store[animProxy] = {ClassName = "LocalScript", Name = "Animate"}
                dumperState.registry[animProxy] = "Animate"
                dumperState.parent_map[animProxy] = proxy
                dumperState.animate_script = animProxy
            end
            dumperState.child_cache[proxy][resolvedName] = dumperState.animate_script
            local varName = registerVariable(dumperState.animate_script, "Animate")
            emitOutput(string.format("local %s = %s:FindFirstChild(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
            return dumperState.animate_script
        end

        if rawget(proxy, "__created_instance") then return nil end

        -- [PATCH:STRICT-FFC] Opt-in (ENVLOGGER_STRICT_FFC=1): a name that is not an existing child is nil, exactly
        -- like a real client. Default stays "fabricate a stand-in child" so analysed scripts keep running down
        -- their `if game.X:FindFirstChild("Remote") then ...` paths (coverage-oriented design of the original logger).
        if process.env.ENVLOGGER_STRICT_FFC == "1" then
            emitOutput(string.format("local _ = %s:FindFirstChild(%s) -- nil", parentPath, formatStringLiteral(resolvedName)))
            return nil
        end

        local childProxy = createProxyObject(resolvedName, false, proxy)
        rawset(childProxy, "__fabricated", true)
        dumperState.child_cache[proxy][resolvedName] = childProxy
        if resolvedName == "StarterPlayerScripts" then
            dumperState.property_store[childProxy] = {ClassName = "StarterPlayerScripts"}
        elseif not hasKnownChild then
            dumperState.property_store[childProxy] = {ClassName = "LocalScript", Name = resolvedName}
        end
        local varName = registerVariable(childProxy, resolvedName)
        if recursive then
            emitOutput(string.format("local %s = %s:FindFirstChild(%s, true)", varName, parentPath, formatStringLiteral(resolvedName)))
        else
            emitOutput(string.format("local %s = %s:FindFirstChild(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
        end
        
        if resolvedName == "DeepTarget" then return nil end
        return childProxy
    end
    serviceMethods.FindFirstChildOfClass = function(self, className)
        -- [PATCH:ARGCHECK] Roblox method argument error
        if className == nil then error("Argument 1 missing or nil", 2) end
        local resolvedName = formatValue(className)
        local parentPath = dumperState.registry[proxy] or "object"
        do -- [PATCH:PLAYER-CHILDREN]
            local _pps = dumperState.property_store[proxy]
            if _pps and _pps.ClassName == "Player" and (resolvedName == "PlayerGui" or resolvedName == "Backpack" or resolvedName == "PlayerScripts") then
                return robloxApi.playerChild(proxy, resolvedName)
            end
        end

        for obj, p in pairsFunction(dumperState.parent_map) do
            if p == proxy and dumperState.property_store[obj] and dumperState.property_store[obj].ClassName == resolvedName then
                local varName = registerVariable(obj, resolvedName)
                emitOutput(string.format("local %s = %s:FindFirstChildOfClass(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
                return obj
            end
        end

        if rawget(proxy, "__created_instance") then return nil end

        local childProxy = createProxyObject(resolvedName, false, proxy)
        local varName = registerVariable(childProxy, resolvedName)
        emitOutput(string.format("local %s = %s:FindFirstChildOfClass(%s)", varName, parentPath, formatStringLiteral(resolvedName)))

        if className == "Camera" then dumperState.property_store[childProxy] = {ClassName = "Camera"} end
        return childProxy
    end
    serviceMethods.FindFirstChildWhichIsA = function(self, className)
        -- [PATCH:ARGCHECK] Roblox method argument error
        if className == nil then error("Argument 1 missing or nil", 2) end
        local resolvedName = formatValue(className)
        local parentPath = dumperState.registry[proxy] or "object"
        local function _isA(cn, target)
            if cn == target then return true end
            local cur = cn
            for _ = 1, 30 do
                local parent = robloxApi and robloxApi.super and robloxApi.super[cur]
                if not parent then break end
                if parent == target then return true end
                cur = parent
            end
            return false
        end
        -- Search existing children in parent_map
        for obj, parent in pairsFunction(dumperState.parent_map) do
            if parent == proxy then
                local ps = dumperState.property_store[obj]
                local cn = ps and ps.ClassName
                if cn and _isA(cn, resolvedName) then
                    local varName = registerVariable(obj, cn)
                    emitOutput(string.format("local %s = %s:FindFirstChildWhichIsA(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
                    return obj
                end
            end
        end
        -- No existing child found; create a new proxy representing the found child
        local childProxy = createProxyObject(resolvedName, false, proxy)
        dumperState.property_store[childProxy] = {ClassName = resolvedName, Name = resolvedName}
        local varName = registerVariable(proxy, resolvedName)
        emitOutput(string.format("local %s = %s:FindFirstChildWhichIsA(%s)", varName, parentPath, formatStringLiteral(resolvedName)))
        return childProxy
    end
    serviceMethods.FindFirstAncestor = function(self, ancestorName)
