    end
    serviceMethods.GetChildren = function(self)
        local parentPath = dumperState.registry[proxy] or "object"
        do -- [PATCH:PLAYER-CHILDREN] a Player always has its four standard containers
            local _gps = dumperState.property_store[proxy]
            if _gps and _gps.ClassName == "Player" then
                for _, _n in ipairsFunction({"Backpack", "PlayerGui", "PlayerScripts", "StarterGear"}) do robloxApi.playerChild(proxy, _n) end
            end
        end

        local result
        if parentPath == "game" then
            local all = {}
            local seen = {}
            for s, _ in pairsFunction(serviceNames) do
                dumperState.service_cache = dumperState.service_cache or {}
                if not dumperState.service_cache[s] then
                    dumperState.service_cache[s] = createProxyObject(s, false, proxy)
                end
                table.insert(all, dumperState.service_cache[s])
                seen[dumperState.service_cache[s]] = true
            end
            for obj, p in pairsFunction(dumperState.parent_map) do
                if p == proxy and not seen[obj] then
                    table.insert(all, obj)
                end
            end
            result = all
        else
            local children = {}
            for obj, p in pairsFunction(dumperState.parent_map) do
                -- [PATCH:NO-SIGNAL-CHILDREN] event signals are not children
                if p == proxy and not rawget(obj, "__is_signal") then table.insert(children, obj) end
            end
            local ghostChildCount = (dumperState.child_counts and dumperState.child_counts[proxy]) or 0
            if ghostChildCount > 0 then
                local filler = next(dumperState.ghost_proxies or {})
                if filler then filler = dumperState.ghost_proxies[filler] end
                if not filler then
                    filler = createProxyObject("ghostChild", false)
                    rawset(filler, "__ghost", true)
                end
                local base = #children
                local cap = math.min(ghostChildCount, 200000 - base)
                for i = 1, cap do children[base + i] = filler end
            end
            if #children > 0 then
                result = children
            elseif parentPath:match("StarterPlayerScripts") then
                local s1 = createProxyObject("PlayerModule", false, proxy)
                local s2 = createProxyObject("RbxCharacterSounds", false, proxy)
                result = {s1, s2}
            elseif rawget(proxy, "__created_instance") then
                result = {}
            else
                result = { createProxyObject("Child", false, proxy) }
            end
        end

        if INLINER and dumperState.inliner_map then
            dumperState.registry[result] = parentPath .. ":GetChildren()"
        else
            local resultProxy = createProxyObject("children", false)
            local varName = registerVariable(resultProxy, "children")
            emitOutput(string.format("local %s = %s:GetChildren()", varName, parentPath))
        end

        return result
    end
    serviceMethods.GetDescendants = function(self)
        local parentPath = dumperState.registry[proxy] or "object"

        local result
        if parentPath == "game" then
            local all = {}
            local seen = {}
            for s, _ in pairsFunction(serviceNames) do
                dumperState.service_cache = dumperState.service_cache or {}
                if not dumperState.service_cache[s] then
                    dumperState.service_cache[s] = createProxyObject(s, false, proxy)
                end
                table.insert(all, dumperState.service_cache[s])
                seen[dumperState.service_cache[s]] = true
            end
            for obj, p in pairsFunction(dumperState.parent_map) do
                if p == proxy and not seen[obj] then
                    table.insert(all, obj)
                    seen[obj] = true
                end
            end
            local function _addDesc(parentObj)
                for obj, p in pairsFunction(dumperState.parent_map) do
                    if p == parentObj and not seen[obj] and not rawget(obj, "__created_instance") then
                        table.insert(all, obj)
                        seen[obj] = true
                        _addDesc(obj)
                    end
                end
            end
            for i = 1, #all do _addDesc(all[i]) end
            if dumperState.local_player and not seen[dumperState.local_player] then
                table.insert(all, dumperState.local_player)
                seen[dumperState.local_player] = true
                _addDesc(dumperState.local_player)
            end
            if dumperState.local_character and not seen[dumperState.local_character] then
                table.insert(all, dumperState.local_character)
                seen[dumperState.local_character] = true
            end
            result = all
        else
            local all = {}
            local seen = {}
            local MAX_REAL = 5000
            local function _addDesc(parentObj)
                if #all >= MAX_REAL then return end
                for obj, p in pairsFunction(dumperState.parent_map) do
                    if p == parentObj and not seen[obj] then
                        seen[obj] = true
                        if not rawget(obj, "__ghost") and not rawget(obj, "__is_signal") then -- [PATCH:NO-SIGNAL-CHILDREN]
                            table.insert(all, obj)
                            _addDesc(obj)
                        end
                    end
                end
            end
            _addDesc(proxy)
            local ghostTotal = (dumperState.child_counts and dumperState.child_counts[proxy]) or 0
            if ghostTotal > 0 then
                -- Fill the array with a shared ghost sentinel so # works correctly.
                -- Luau's # ignores __len on tables; an actual sequence is required.
                local filler = next(dumperState.ghost_proxies or {})
                if filler then filler = dumperState.ghost_proxies[filler] end
                if not filler then
                    filler = createProxyObject("ghostDesc", false)
                    rawset(filler, "__ghost", true)
                end
                local base = #all
                local cap = math.min(ghostTotal, 200000 - base)
                for i = 1, cap do all[base + i] = filler end
            end
            if #all == 0 then
                local descProxy = createProxyObject("Descendant", false, proxy)
                dumperState.property_store[descProxy] = {Name = "Ball", ClassName = "Part", Size = Vector3.new(1, 1, 1)}
                result = { descProxy }
            else
                result = all
            end
        end

        if INLINER and dumperState.inliner_map then
            dumperState.registry[result] = parentPath .. ":GetDescendants()"
        else
            local resultProxy = createProxyObject("descendants", false)
            local varName = registerVariable(resultProxy, "descendants")
            emitOutput(string.format("local %s = %s:GetDescendants()", varName, parentPath))
        end

        return result
    end
    serviceMethods.Clone = function(self)
        if dumperState.property_store[proxy] and dumperState.property_store[proxy].Archivable == false then
            return nil
        end
        
        local parentPath = dumperState.registry[proxy] or "object"
        if parentPath == "game" or parentPath == "workspace" then
            error("Cannot Clone " .. parentPath, 2)
        end
        
        local cloneProxy = createProxyObject((formattedName or "object") .. "Clone_" .. tostring(math.random(1000, 9999)), false)
        -- [PATCH:CLONE] A clone owns an independent copy of the property bag (the original
        -- code shared ONE table, so renaming/recoloring the clone silently changed the
        -- source), starts with Parent == nil, and carries a copy of every Archivable
        -- descendant (in parenting order).
        local function _copyBag(src)
            local c = {}
            if src then for k, v in next, src do c[k] = v end end
            c.Parent = nil
            return c
        end
        dumperState.property_store[cloneProxy] = _copyBag(dumperState.property_store[proxy])
        if type(dumperState.property_store[cloneProxy].ClassName) == "string" then
            rawset(cloneProxy, "__created_instance", true)
        end
        local function _cloneKids(from, to)
            local kids = {}
            for obj, par in pairsFunction(dumperState.parent_map) do
                if par == from then kids[#kids + 1] = obj end
            end
            for _, obj in ipairsFunction(kids) do
                local ops = dumperState.property_store[obj]
                if not (ops and ops.Archivable == false) then
                    local kid = createProxyObject((ops and ops.Name) or "Child", false, to)
                    dumperState.property_store[kid] = _copyBag(ops)
                    if type(dumperState.property_store[kid].ClassName) == "string" then rawset(kid, "__created_instance", true) end
                    dumperState.parent_map[kid] = to
                    dumperState.property_store[kid].Parent = to
                    _cloneKids(obj, kid)
                end
            end
        end
        _cloneKids(proxy, cloneProxy)
        local varName = registerVariable(cloneProxy, (formattedName or "object") .. "Clone")
        emitOutput(string.format("local %s = %s:Clone()", varName, parentPath))
        return cloneProxy
    end
    -- [PATCH:LEGACY-METHODS] deprecated spellings that are NOT first-letter case variants
    -- and therefore need explicit aliases: Instance:children(), Instance:Remove(),
    -- ServiceProvider:service(), Players:players().
    serviceMethods.children = function(self) return serviceMethods.GetChildren(self) end
    serviceMethods.Remove = function(self)
        local parentPath = dumperState.registry[proxy] or "object"
        if proxy == game or proxy == workspace then error("The Parent property of " .. (proxy == game and "Ugc" or "Workspace") .. " is locked", 0) end
        emitOutput(string.format("%s:Remove()", parentPath))
        dumperState.parent_map[proxy] = nil
        local ps = dumperState.property_store[proxy]
        if ps then ps.Parent = nil end
    end
    serviceMethods.service = function(self, name) return serviceMethods.GetService(self, name) end
    serviceMethods.players = function(self) return serviceMethods.GetPlayers(self) end
    serviceMethods.Destroy = function(self)
        local parentPath = dumperState.registry[proxy] or "object"
        local isService = (proxy == game)

        local checkName = parentPath:match("^game%.([%w_]+)$") or parentPath
        for name, _ in pairsFunction(serviceNames) do
            if checkName:lower() == name:lower() then
                isService = true
                break
            end
        end

        if isService then
            local displayName = checkName:match("^game%.([%w_]+)$") or checkName
            if displayName == "workspace" then displayName = "Workspace" end
            -- level 0: no file-path prefix, matches Roblox C-level error format
            error("The Parent property of " .. displayName .. " is locked", 0)
        end

        emitOutput(string.format("%s:Destroy()", parentPath))
        dumperState.destroyed_instances = dumperState.destroyed_instances or {}
        dumperState.destroyed_instances[proxy] = true

        if dumperState.event_callbacks and parentPath then
            local prefix = parentPath .. "."
            for sigPath in pairsFunction(dumperState.event_callbacks) do
                if sigPath == parentPath or sigPath:sub(1, #prefix) == prefix then
                    dumperState.event_callbacks[sigPath] = nil
                end
            end
        end

        local function destroyRecursive(target)
            for childProxy, parentRef in pairsFunction(dumperState.parent_map) do
                if parentRef == target then
                    dumperState.parent_map[childProxy] = nil
                    if dumperState.property_store[childProxy] then
                        dumperState.property_store[childProxy].Parent = nil
                    end
                    dumperState.destroyed_instances[childProxy] = true
                    destroyRecursive(childProxy)
                end
            end
        end
        destroyRecursive(proxy)

        dumperState.parent_map[proxy] = nil
        if dumperState.property_store[proxy] then
            dumperState.property_store[proxy].Parent = nil
        end
    end
    serviceMethods.SetItem = function(self, key, value)
        local servicePath = dumperState.registry[proxy] or "MemStorageService"
        emitOutput(string.format("%s:SetItem(%s, %s)", servicePath, serializeValue(key), serializeValue(value)))
        dumperState.mem_storage = dumperState.mem_storage or {}
        dumperState.mem_storage[key] = value
    end
    serviceMethods.GetItem = function(self, key)
        local servicePath = dumperState.registry[proxy] or "MemStorageService"
        local resultProxy = createProxyObject("item", false)
        local varName = registerVariable(resultProxy, "item")
        emitOutput(string.format("local %s = %s:GetItem(%s)", varName, servicePath, serializeValue(key)))
        dumperState.mem_storage = dumperState.mem_storage or {}
        return dumperState.mem_storage[key] or ""
    end
    serviceMethods.GetTagged = function(self, tag)
        local servicePath = dumperState.registry[proxy] or "CollectionService"
        local resultProxy = createProxyObject("tagged", false)
        local varName = registerVariable(resultProxy, "tagged")
        emitOutput(string.format("local %s = %s:GetTagged(%s)", varName, servicePath, serializeValue(tag)))
        
        dumperState.collection_tags = dumperState.collection_tags or {}
        local tagged_instances = {}
        if dumperState.collection_tags[tag] then
            for inst, _ in pairsFunction(dumperState.collection_tags[tag]) do
                table.insert(tagged_instances, inst)
            end
        end
        return tagged_instances
    end
    serviceMethods.RemoveTag = function(self, inst, tag)
        local servicePath = dumperState.registry[proxy] or "CollectionService"
        emitOutput(string.format("%s:RemoveTag(%s, %s)", servicePath, serializeValue(inst), serializeValue(tag)))
        if dumperState.collection_tags and dumperState.collection_tags[tag] then
            local _had = dumperState.collection_tags[tag][inst]
            dumperState.collection_tags[tag][inst] = nil
            if _had then robloxApi.fireKey("CS:Removed:" .. tostring(tag), inst) end -- [PATCH:COLLECTION-SIGNALS]
        end
    end
    serviceMethods.HasTag = function(self, p1, p2)
        local inst, tag = (typeFunction(p1) == "string") and proxy or p1, (typeFunction(p1) == "string") and p1 or p2
        return (dumperState.collection_tags and dumperState.collection_tags[tag] and dumperState.collection_tags[tag][inst]) == true
    end
    serviceMethods.AddTag = function(self, p1, p2)
        local inst, tag = (typeFunction(p1) == "string") and proxy or p1, (typeFunction(p1) == "string") and p1 or p2
        local path = dumperState.registry[proxy] or "Instance"
        local instPath = dumperState.registry[inst] or serializeValue(inst)
        emitOutput(string.format("%s:AddTag(%s, %s)", path, instPath, serializeValue(tag)))
        dumperState.collection_tags = dumperState.collection_tags or {}
        dumperState.collection_tags[tag] = dumperState.collection_tags[tag] or {}
        local _had = dumperState.collection_tags[tag][inst]
        dumperState.collection_tags[tag][inst] = true
        -- [PATCH:COLLECTION-SIGNALS] GetInstanceAddedSignal fires for instances inside the DataModel
        if not _had and robloxApi.inDataModel(inst) then robloxApi.fireKey("CS:Added:" .. tostring(tag), inst) end
    end
    serviceMethods.GetTags = function(self, tagOrInst)
        local inst = (typeFunction(tagOrInst) == "table" and isProxy(tagOrInst)) and tagOrInst or proxy
        local path = dumperState.registry[proxy] or "Instance"
        emitOutput(string.format("%s:GetTags()", path))
        local tags = {}
        if dumperState.collection_tags then
            for t, instances in pairsFunction(dumperState.collection_tags) do
                if instances[inst] then table.insert(tags, t) end
            end
        end
        return tags
    end
    serviceMethods.GetInstanceAddedSignal = function(self, tag)
        local servicePath = dumperState.registry[proxy] or "CollectionService"
        dumperState.collection_signals = dumperState.collection_signals or {}
        
        if dumperState.collection_signals[tag] then
            local cachedProxy = dumperState.collection_signals[tag]
            local varName = registerVariable(cachedProxy, tag .. "Added")
            emitOutput(string.format("local %s = %s:GetInstanceAddedSignal(%s)", varName, servicePath, serializeValue(tag)))
            return cachedProxy
        end
        
        local sigProxy = createProxyObject(tag .. "Added", false)
        rawset(sigProxy, "__is_signal", true) -- [PATCH:COLLECTION-SIGNALS]
        rawset(sigProxy, "__sig_key", "CS:Added:" .. tostring(tag))
        rawset(sigProxy, "__sig_owner", proxy); rawset(sigProxy, "__no_immediate", true)
        local varName = registerVariable(sigProxy, tag .. "Added")
        emitOutput(string.format("local %s = %s:GetInstanceAddedSignal(%s)", varName, servicePath, serializeValue(tag)))
        
        dumperState.registry[sigProxy] = servicePath .. ":GetInstanceAddedSignal(" .. serializeValue(tag) .. ")"
        dumperState.collection_signals[tag] = sigProxy
        return sigProxy
    end
    serviceMethods.GetInstanceRemovedSignal = function(self, tag)
        local servicePath = dumperState.registry[proxy] or "CollectionService"
        dumperState.collection_removed_signals = dumperState.collection_removed_signals or {}
        if dumperState.collection_removed_signals[tag] then
            local cachedProxy = dumperState.collection_removed_signals[tag]
            local varName = registerVariable(cachedProxy, tag .. "Removed")
            emitOutput(string.format("local %s = %s:GetInstanceRemovedSignal(%s)", varName, servicePath, serializeValue(tag)))
            return cachedProxy
        end
        local sigProxy = createProxyObject(tag .. "Removed", false)
        rawset(sigProxy, "__is_signal", true)
        rawset(sigProxy, "__sig_key", "CS:Removed:" .. tostring(tag))
        rawset(sigProxy, "__sig_owner", proxy); rawset(sigProxy, "__no_immediate", true)
        local varName = registerVariable(sigProxy, tag .. "Removed")
        emitOutput(string.format("local %s = %s:GetInstanceRemovedSignal(%s)", varName, servicePath, serializeValue(tag)))
        dumperState.registry[sigProxy] = servicePath .. ":GetInstanceRemovedSignal(" .. serializeValue(tag) .. ")"
        dumperState.collection_removed_signals[tag] = sigProxy
        return sigProxy
    end
    serviceMethods.Connect = function(self, func)
        local signalPath = dumperState.registry[proxy] or "signal"
        -- [PATCH:SIGNALS] Connect() validates its argument; callbacks are keyed per owner instance
        local _cbKey = rawget(proxy, "__sig_key") or signalPath
        local _sigOwner = rawget(proxy, "__sig_owner")
        local _ownerCreated = (_sigOwner ~= nil and typeFunction(_sigOwner) == "table" and rawget(_sigOwner, "__created_instance")) or rawget(proxy, "__no_immediate") -- [PATCH:COLLECTION-SIGNALS]
        if rawget(proxy, "__is_signal") and typeFunction(func) ~= "function" then
            local _okf = false
            if typeFunction(func) == "table" then
                local _mt = getMetatableFunction(func)
                _okf = isProxy(func) or (type(_mt) == "table" and _mt.__call ~= nil)
            end
            if not _okf then
                error(func == nil and "Argument 1 missing or nil" or "Attempt to connect failed: Passed value is not a function", 2)
            end
        end
        -- Cap connections per signal to avoid O(n) emitOutput floods from loop-connecting.
        local MAX_CONNECTIONS_PER_SIGNAL = 500
        dumperState.signal_conn_counts = dumperState.signal_conn_counts or {}
        dumperState.signal_conn_counts[signalPath] = (dumperState.signal_conn_counts[signalPath] or 0) + 1
        if dumperState.signal_conn_counts[signalPath] > MAX_CONNECTIONS_PER_SIGNAL then
            -- Bulk connection: register callback silently using a shared proxy, skip all output.
            if typeFunction(func) == "function" then
                dumperState.event_callbacks = dumperState.event_callbacks or {}
                dumperState.event_callbacks[_cbKey] = dumperState.event_callbacks[_cbKey] or {}
                if #dumperState.event_callbacks[_cbKey] < MAX_CONNECTIONS_PER_SIGNAL then
                    table.insert(dumperState.event_callbacks[_cbKey], func)
                end
            end
            if not dumperState.bulk_conn_proxy then
                local bp = createProxyObject("connection", false)
                rawset(bp, "__is_connection", true)
                dumperState.property_store[bp] = {Connected = false}
                dumperState.bulk_conn_proxy = bp
            end
            return dumperState.bulk_conn_proxy
        end
        local connectionProxy = createProxyObject("connection", false)
        rawset(connectionProxy, "__is_connection", true)
        rawset(connectionProxy, "__cb_fn", func)
        rawset(connectionProxy, "__cb_signal", _cbKey)
        dumperState.property_store[connectionProxy] = {Connected = true}
        if _sigOwner ~= nil then
            dumperState.conns_by_inst = dumperState.conns_by_inst or setmetatable({}, {__mode = "k"})
            local _cl = dumperState.conns_by_inst[_sigOwner]
            if not _cl then _cl = {}; dumperState.conns_by_inst[_sigOwner] = _cl end
            _cl[#_cl + 1] = connectionProxy
            local _sn = rawget(proxy, "__sig_name")
            if _sn == "AncestryChanged" or _sn == "DescendantAdded" or _sn == "DescendantRemoving" then dumperState.anc_listeners = (dumperState.anc_listeners or 0) + 1 end
        end
        local varName = registerVariable(connectionProxy, "conn")
        local signalName = signalPath:match("%.([^%.]+)$") or signalPath
        local args = {"..."}
        local dummyArgs = {}

        local function getCachedEnum(path)
        return robloxApi.enumByPath(path)
        end

        if signalName:match("InputBegan") or signalName:match("InputEnded") or signalName:match("InputChanged") then
            args = {"input", "gameProcessed"}
            local inputObj = createProxyObject("input", false)
            dumperState.property_store[inputObj] = {
                UserInputType = getCachedEnum("Enum.UserInputType.Keyboard"),
                KeyCode = getCachedEnum("Enum.KeyCode.E"),
                UserInputState = getCachedEnum("Enum.UserInputState.Begin")
            }
            dummyArgs = {inputObj, false}
        elseif signalName:match("CharacterAdded") or signalName:match("CharacterRemoving") then
            args = {"character"}
            dummyArgs = {createProxyObject("Character", false)}
        elseif signalName:match("PlayerAdded") or signalName:match("PlayerRemoving") then
            args = {"player"}
            dummyArgs = {createProxyObject("Player", false)}
        elseif signalName:match("Touched") then
            args = {"hit"}
            local hitPart = createProxyObject("HitPart", false)
            dumperState.property_store[hitPart] = { Parent = createProxyObject("Character", false) }
            dummyArgs = {hitPart}
        elseif signalName:match("Heartbeat") or signalName:match("RenderStepped") or signalName:match("Stepped")
            or signalName == "PreRender" or signalName == "PreSimulation" or signalName == "PostSimulation" or signalName == "PreAnimation" then
            args = (signalName == "Stepped") and {"time", "deltaTime"} or {"deltaTime"}
            dummyArgs = (signalName == "Stepped") and {get_virtual_clock(), 0.016} or {0.016}
        elseif signalName:match("Changed") then
            args = {"property"}
            dummyArgs = {"Value"}
        elseif signalName:match("ChildAdded") or signalName:match("ChildRemoved") then
            args = {"child"}
            dummyArgs = {createProxyObject("Child", false)}
        elseif signalName:match("DescendantAdded") or signalName:match("DescendantRemoving") then
            args = {"descendant"}
            dummyArgs = {createProxyObject("Descendant", false)}
        elseif signalName:match("FocusLost") then
            args = {"enterPressed", "inputObject"}
            dummyArgs = {true, createProxyObject("input", false)}
        elseif signalName:match("Died") or signalName:match("MouseButton") or signalName:match("Activated") then
            args = {}
            dummyArgs = {}
        elseif signalName == "AnimationClipDataUpdated" then
            args = {}
            dummyArgs = {}
        end
        if _sigOwner ~= nil or signalName == "Event" or signalName == "OnInvoke" or signalName == "Changed" or signalName == "MessageReceived" or signalName == "ChildAdded" or signalName == "ChildRemoved" or signalName == "DescendantAdded" or signalName == "DescendantRemoving" or signalPath:match("GetPropertyChangedSignal") or signalName:match("Heartbeat") or signalName:match("RenderStepped") or signalName:match("Stepped") or signalName == "PreRender" or signalName == "PreSimulation" or signalName == "PostSimulation" or signalName == "PreAnimation" then
            dumperState.event_callbacks = dumperState.event_callbacks or {}
            dumperState.event_callbacks[_cbKey] = dumperState.event_callbacks[_cbKey] or {}
            if typeFunction(func) == "function" then table.insert(dumperState.event_callbacks[_cbKey], func) end
        end

        emitOutput(string.format("local %s = %s:Connect(function(%s)", varName, signalPath, table.concat(args, ", ")))
        dumperState.indent = dumperState.indent + 1
        
        local _noImmediateFire = {
            -- Animation signals (Humanoid/AnimationTrack)
            AnimationPlayed=true,AnimationStopped=true,AnimationPaused=true,
            AnimationResumed=true,AnimationLooped=true,AnimationEnded=true,
            DidLoop=true,KeyframeReached=true,
            -- Sound signals
            SoundPlayed=true,SoundStopped=true,SoundPaused=true,
            SoundResumed=true,SoundEnded=true,SoundLooped=true,Played=true,
            Paused=true,Resumed=true,Ended=true,Looped=true,
            -- RunService signals
            Heartbeat=true,RenderStepped=true,Stepped=true,PreRender=true,
            PreSimulation=true,PostSimulation=true,PreAnimation=true,
            -- Input signals (UserInputService/GuiObject)
            InputBegan=true,InputEnded=true,InputChanged=true,
            TouchStarted=true,TouchEnded=true,TouchMoved=true,
            TouchTap=true,TouchLongPress=true,TouchPan=true,
            TouchPinch=true,TouchRotate=true,TouchSwipe=true,
            KeyDown=true,KeyUp=true,Button1Down=true,Button1Up=true,
            Button2Down=true,Button2Up=true,WindowFocused=true,
            WindowFocusReleased=true,TextBoxFocused=true,
            TextBoxFocusReleased=true,JumpRequest=true,
            GamepadConnected=true,GamepadDisconnected=true,
            LastInputTypeChanged=true,DeviceAccelerationChanged=true,
            DeviceGravityChanged=true,DeviceRotationChanged=true,
            StatusBarTapped=true,
            -- Mouse signals
            MouseButton1Click=true,MouseButton1Down=true,MouseButton1Up=true,
            MouseButton2Click=true,MouseButton2Down=true,MouseButton2Up=true,
            MouseEnter=true,MouseLeave=true,MouseMoved=true,
            MouseWheelForward=true,MouseWheelBackward=true,
            -- GUI signals
            Activated=true,Deactivated=true,FocusLost=true,FocusGained=true,
            Focused=true,SelectionChanged=true,TextChanged=true,
            ReturnPressedFromOnScreenKeyboard=true,
            -- BasePart signals
            Touched=true,TouchEnded=true,
            -- Humanoid state signals
            Died=true,FreeFalling=true,GettingUp=true,Jumping=true,
            Running=true,Seated=true,Swimming=true,StateChanged=true,
            HealthChanged=true,MoveToFinished=true,Climbing=true,
            PlatformStanding=true,Strafing=true,Ragdoll=true,
            -- Player/Character signals
            CharacterAdded=true,CharacterRemoving=true,
            CharacterAppearanceLoaded=true,PlayerAdded=true,
            PlayerRemoving=true,Chatted=true,Idled=true,
            FriendStatusChanged=true,OnTeleport=true,
            -- Hierarchy signals
            AncestryChanged=true,AttributeChanged=true,
            ChildAdded=true,ChildRemoved=true,
            DescendantAdded=true,DescendantRemoving=true,
            -- Tween/animation tracks
            Completed=true,Stopped=true,Triggered=true,TriggerEnded=true,
            -- Marketplace prompts
            PromptPurchaseFinished=true,PromptGamePassPurchaseFinished=true,
            PromptBundlePurchaseFinished=true,
            PromptThirdPartyPurchaseFinished=true,
            PromptSubscriptionPurchaseFinished=true,
            PlayerEarnedBadge=true,
            -- Capture/Recording
            CaptureBegan=true,RecordingStarted=true,RecordingStopped=true,
            PromptShown=true,PromptHidden=true,
            -- Misc
            ServiceAdded=true,MessageOut=true,MessageOutAdded=true,
            MessageReceived=true,GameplayPaused=true,
            SimulationRadiusChanged=true,CollisionGroupChanged=true,
            MeshChanged=true,CameraChanged=true,
            Equipped=true,Unequipped=true,DroppedFromInventory=true,
            NpcDialogueUpdated=true,CharacterAutoLoaded=true,
            CharacterAutoRemoveEnabled=true,
            MouseClick=true,Move=true,Idle=true,
            -- Event/OnInvoke (BindableEvent/BindableFunction/RemoteEvent)
            Event=true,OnInvoke=true,OnClientEvent=true,OnServerEvent=true,
            OnClientInvoke=true,OnServerInvoke=true,
            -- Changed (property change) - only fires on actual property change
            Changed=true,
        }
        if typeFunction(func) == "function" and not _ownerCreated and not signalPath:match("GetPropertyChangedSignal") and not _noImmediateFire[signalName] then
            local co = coroutine.create(func)
            local success, err = coroutine.resume(co, table.unpack(dummyArgs))
            if not success then
                emitOutput("-- [Event Internally Failed]: " .. tostring(err))
            end
        end
        
        while dumperState.pending_iterator do
            dumperState.indent = dumperState.indent - 1
            emitOutput("end")
            dumperState.pending_iterator = false
        end
        dumperState.indent = dumperState.indent - 1
        emitOutput("end)")
        return connectionProxy
    end
    serviceMethods.ConnectParallel = serviceMethods.Connect
    serviceMethods.Once = function(self, func)
        local signalPath = dumperState.registry[proxy] or "signal"
        local connectionProxy = createProxyObject("connection", false)
        rawset(connectionProxy, "__is_connection", true)
        dumperState.property_store[connectionProxy] = {Connected = true}
        -- [PATCH:SIGNALS] Once() registers a self-disconnecting callback on the keyed bus
        local _cbKey = rawget(proxy, "__sig_key")
        local _sigOwner = rawget(proxy, "__sig_owner")
        if rawget(proxy, "__is_signal") and typeFunction(func) ~= "function" then
            error(func == nil and "Argument 1 missing or nil" or "Attempt to connect failed: Passed value is not a function", 2)
        end
        if _cbKey and typeFunction(func) == "function" then
            local _wrapper
            _wrapper = function(...)
                local cbs = dumperState.event_callbacks[_cbKey]
                if cbs then for i = #cbs, 1, -1 do if cbs[i] == _wrapper then table.remove(cbs, i) end end end
                local ps = dumperState.property_store[connectionProxy]
                if ps then ps.Connected = false end
                return func(...)
            end
            dumperState.event_callbacks = dumperState.event_callbacks or {}
            dumperState.event_callbacks[_cbKey] = dumperState.event_callbacks[_cbKey] or {}
            table.insert(dumperState.event_callbacks[_cbKey], _wrapper)
            rawset(connectionProxy, "__cb_fn", _wrapper)
            rawset(connectionProxy, "__cb_signal", _cbKey)
            dumperState.conns_by_inst = dumperState.conns_by_inst or setmetatable({}, {__mode = "k"})
            local _cl = dumperState.conns_by_inst[_sigOwner]
            if not _cl then _cl = {}; dumperState.conns_by_inst[_sigOwner] = _cl end
            _cl[#_cl + 1] = connectionProxy
            local _sn = rawget(proxy, "__sig_name")
            if _sn == "AncestryChanged" or _sn == "DescendantAdded" or _sn == "DescendantRemoving" then dumperState.anc_listeners = (dumperState.anc_listeners or 0) + 1 end
        end
        local varName = registerVariable(connectionProxy, "conn")
        local signalName = signalPath:match("%.([^%.]+)$") or signalPath
        local args = {"..."}
        local dummyArgs = {}

        local function getCachedEnum(path)
        return robloxApi.enumByPath(path)
        end

        if signalName:match("InputBegan") or signalName:match("InputEnded") or signalName:match("InputChanged") then
            args = {"input", "gameProcessed"}
            local inputObj = createProxyObject("input", false)
            dumperState.property_store[inputObj] = {
                UserInputType = getCachedEnum("Enum.UserInputType.Keyboard"),
                KeyCode = getCachedEnum("Enum.KeyCode.E"),
                UserInputState = getCachedEnum("Enum.UserInputState.Begin")
            }
            dummyArgs = {inputObj, false}
        elseif signalName:match("Heartbeat") or signalName:match("RenderStepped") or signalName:match("Stepped") then
            args = signalName:match("Stepped") and {"time", "deltaTime"} or {"deltaTime"}
            local randDt = 0.016 + (math.random() * 0.001)
            dummyArgs = signalName:match("Stepped") and {get_virtual_clock(), randDt} or {randDt}
        end

        emitOutput(string.format("local %s = %s:Once(function(%s)", varName, signalPath, table.concat(args, ", ")))
        dumperState.indent = dumperState.indent + 1
        
        if typeFunction(func) == "function" and not (_cbKey and _sigOwner ~= nil and rawget(_sigOwner, "__created_instance")) then
            local co = coroutine.create(func)
            local success, err = coroutine.resume(co, table.unpack(dummyArgs))
            if not success then
                emitOutput("-- [Event Internally Failed]: " .. tostring(err)) 
            end
        end
        dumperState.indent = dumperState.indent - 1
        emitOutput("end)")
        return connectionProxy
    end
    serviceMethods.Wait = function(self)
        LG.yield()
        local signalPath = dumperState.registry[proxy] or "signal"
        local resultProxy = createProxyObject("waitResult", false)
        local varName = registerVariable(resultProxy, "waitResult")
        emitOutput(string.format("local %s = %s:Wait()", varName, signalPath))
        -- [PATCH:SIGNALS] Wait() on an instance event really waits: run scheduled tasks until the event fires
        do
            local _wk = rawget(proxy, "__sig_key")
            if _wk and rawget(proxy, "__sig_owner") ~= nil then
                dumperState.event_callbacks = dumperState.event_callbacks or {}
                local cbs = dumperState.event_callbacks[_wk]
                if not cbs then cbs = {}; dumperState.event_callbacks[_wk] = cbs end
                local got
                local cb = function(...) got = table.pack(...) end
                cbs[#cbs + 1] = cb
                -- [PATCH:TWEEN-ENGINE] waiting on a playing tween's Completed advances simulated frames
                do
                    local _ow = rawget(proxy, "__sig_owner")
                    local _ops = typeFunction(_ow) == "table" and dumperState.property_store[_ow]
                    if _ops and _ops.ClassName == "Tween" and rawget(proxy, "__sig_name") == "Completed" then
                        for _ = 1, 100000 do
                            if got or #robloxApi.activeTweens == 0 then break end
                            virtual_time_offset = virtual_time_offset + 1 / 60
                            robloxApi.runFrames(1, 1 / 60)
                        end
                    end
                end
                for _ = 1, 64 do
                    if got then break end
                    local tasks = dumperState.deferred_tasks
                    if not tasks or #tasks == 0 then break end
                    tasks = robloxApi.takeDue(math.huge, true)
                    for ti, tf in ipairsFunction(tasks) do
                        local _d = robloxApi.taskDue[tf]
                        if _d and _d > virtual_time_offset then virtual_time_offset = _d end
                        pcallFunction(tf)
                        if got then
                            -- keep the tasks that did not get to run, ahead of anything queued meanwhile
                            local rest = {}
                            for j = ti + 1, #tasks do rest[#rest + 1] = tasks[j] end
                            for _, f in ipairsFunction(dumperState.deferred_tasks or {}) do rest[#rest + 1] = f end
                            dumperState.deferred_tasks = rest
                            break
                        end
                    end
                end
                for i = #cbs, 1, -1 do if cbs[i] == cb then table.remove(cbs, i) end end
                if got then return table.unpack(got, 1, got.n) end
            end
        end
        -- Fire registered callbacks exactly once using a snapshot, so newly-connected callbacks
        -- (added during a callback) don't fire in the same Wait() call — matching Roblox frame semantics.
        local _dt = 1/60 + (math.random() - 0.5) * 0.002
        -- Advance jump physics for this heartbeat tick
        if signalPath:match("Heartbeat") or signalPath:match("RenderStepped") or signalPath:match("Stepped") then
            local jp = dumperState.jump_physics
            if jp and jp.active then
                local hrpPs = jp.hrp and dumperState.property_store[jp.hrp]
                if hrpPs then
                    local curPos = hrpPs.Position or Vector3.new(0, 5, 0)
                    local prevVy = jp.vy
                    jp.vy = jp.vy - jp.gravity * _dt
                    if prevVy > 0 and jp.vy <= 0 and jp.humanoid then
                        local humPs = dumperState.property_store[jp.humanoid]
                        if humPs and humPs._currentState == "Jumping" then humPs._currentState = "Freefall" end
                    end
                    local newY = curPos.Y + jp.vy * _dt
                    if newY <= jp.base_y then
                        newY = jp.base_y; jp.active = false
                        if jp.humanoid then
                            local humPs = dumperState.property_store[jp.humanoid]
                            if humPs then humPs._currentState = "Running" end
                        end
                    end
                    local newPos = Vector3.new(curPos.X, newY, curPos.Z)
                    hrpPs.Position = newPos
                    hrpPs.CFrame = CFrame.new(newPos.X, newPos.Y, newPos.Z)
                end
            end
        end
        if dumperState.event_callbacks and dumperState.event_callbacks[signalPath] then
            local snapshot = {table.unpack(dumperState.event_callbacks[signalPath])}
            local isStepped = signalPath:match("Stepped") and not signalPath:match("PreSimulation") and not signalPath:match("PostSimulation")
            for _, cb in ipairs(snapshot) do
                if isStepped then
                    pcallFunction(function() cb(get_virtual_clock(), _dt) end)
                else
                    pcallFunction(function() cb(_dt) end)
                end
            end
        end
        local _waitDt = 1/60 + (math.random() - 0.5) * 0.002
        if signalPath:match("Heartbeat") or signalPath:match("RenderStepped") or signalPath:match("PreRender") or signalPath:match("PreSimulation") or signalPath:match("PostSimulation") or signalPath:match("PreAnimation") then return _waitDt end
        if signalPath:match("Stepped") then return get_virtual_clock(), _waitDt end
        return resultProxy
    end
    serviceMethods.Disconnect = function(self)
        local connectionPath = dumperState.registry[proxy] or "connection"
        emitOutput(string.format("%s:Disconnect()", connectionPath))
        dumperState.property_store[proxy] = dumperState.property_store[proxy] or {}
        dumperState.property_store[proxy].Connected = false
        local cbFn = rawget(proxy, "__cb_fn")
        local cbSignal = rawget(proxy, "__cb_signal")
        if cbFn and cbSignal and dumperState.event_callbacks and dumperState.event_callbacks[cbSignal] then
            for i = #dumperState.event_callbacks[cbSignal], 1, -1 do
                if dumperState.event_callbacks[cbSignal][i] == cbFn then
                    table.remove(dumperState.event_callbacks[cbSignal], i)
                    break
                end
            end
        end
    end
    serviceMethods.FireServer = function(self, ...)
        local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName or "Instance"
        if className ~= "RemoteEvent" and not rawget(proxy, "__fabricated") then
            error(string.format("%s is not a valid member of %s", "FireServer", className), 2)
        end
        
        local remotePath = dumperState.registry[proxy] or "remote"
        local args = {...}
        local serializedArgs = {}
        for _, val in ipairsFunction(args) do
            table.insert(serializedArgs, serializeValue(val))
        end
        emitOutput(string.format("%s:FireServer(%s)", remotePath, table.concat(serializedArgs, ", ")))
        table.insert(dumperState.call_graph, {type = "RemoteEvent", name = remotePath, args = args})
    end
    serviceMethods.InvokeServer = function(self, ...)
        local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName or "Instance"
        if className ~= "RemoteFunction" and not rawget(proxy, "__fabricated") then
            error(string.format("%s is not a valid member of %s", "InvokeServer", className), 2)
        end
        
        local remotePath = dumperState.registry[proxy] or "remote"
        local args = {...}
        local serializedArgs = {}
        for _, val in ipairsFunction(args) do
            table.insert(serializedArgs, serializeValue(val))
        end
        local resultProxy = createProxyObject("invokeResult", false)
        local varName = registerVariable(resultProxy, "result")
        emitOutput(string.format("local %s = %s:InvokeServer(%s)", varName, remotePath, table.concat(serializedArgs, ", ")))
        table.insert(dumperState.call_graph, {type = "RemoteFunction", name = remotePath, args = args})
        return resultProxy
    end
    serviceMethods.Fire = function(self, ...)
        local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName or "Instance"
        if className ~= "BindableEvent" and not rawget(proxy, "__fabricated") then
            error(string.format("%s is not a valid member of %s", "Fire", className), 2)
        end
        if dumperState.destroyed_instances and dumperState.destroyed_instances[proxy] then
            return
        end
        
        local eventPath = dumperState.registry[proxy] or "event"
        local args = {...}
        local serializedArgs = {}
        for _, val in ipairsFunction(args) do table.insert(serializedArgs, serializeValue(val)) end
        emitOutput(string.format("%s:Fire(%s)", eventPath, table.concat(serializedArgs, ", ")))
        
        local signalPath = eventPath .. ".Event"
        if dumperState.event_callbacks and dumperState.event_callbacks[signalPath] then
            for _, cb in ipairsFunction(dumperState.event_callbacks[signalPath]) do
                xpcallFunction(function() cb(table.unpack(args)) end, function() end)
            end
        end
        -- [PATCH:BINDABLE-FIRE] connections made through the per-instance signal key (every created BindableEvent)
        -- were never invoked: Fire only looked at the registry-path key, so Event:Connect/Once/Wait never saw Fire.
        if rawget(proxy, "__created_instance") then
            robloxApi.fireKey(robloxApi.sigKey(proxy, "Event"), table.unpack(table.pack(...), 1, select("#", ...)))
        end
    end
    serviceMethods.Invoke = function(self, ...)
        local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName or "Instance"
        if className ~= "BindableFunction" and not rawget(proxy, "__fabricated") then
            error(string.format("%s is not a valid member of %s", "Invoke", className), 2)
        end
        
        local bindablePath = dumperState.registry[proxy] or "bindable"
        local args = {...}
        local serializedArgs = {}
        for _, val in ipairsFunction(args) do
            table.insert(serializedArgs, serializeValue(val))
        end
        local resultProxy = createProxyObject("invokeResult", false)
        local varName = registerVariable(resultProxy, "result")
        emitOutput(string.format("local %s = %s:Invoke(%s)", varName, bindablePath, table.concat(serializedArgs, ", ")))
        
        if dumperState.property_store[proxy] and typeFunction(dumperState.property_store[proxy].OnInvoke) == "function" then
            local packed = table.pack(pcallFunction(dumperState.property_store[proxy].OnInvoke, table.unpack(args)))
            if packed[1] then return table.unpack(packed, 2, packed.n) end
            error(packed[2], 0) -- [PATCH:BINDABLE-INVOKE-ERR] an error inside OnInvoke propagates to the Invoke caller
        end

        return resultProxy
    end
    serviceMethods.Create = function(self, tweenTarget, tweenInfo, tweenProperties)
        -- [PATCH:TWEEN-ENGINE] argument validation
        if tweenTarget == nil then error("Argument 1 missing or nil", 2) end
        if robloxApi.opTn(tweenTarget) ~= "Instance" then error("Unable to cast value to Object", 2) end
        if tweenInfo == nil then error("Argument 2 missing or nil", 2) end
        if robloxApi.opTn(tweenInfo) ~= "TweenInfo" then error("Unable to cast value to TweenInfo", 2) end
        if tweenProperties == nil then error("Argument 3 missing or nil", 2) end
        if typeFunction(tweenProperties) ~= "table" or isProxy(tweenProperties) then
            error("invalid argument #3 to 'Create' (table expected, got " .. robloxApi.argTn(tweenProperties) .. ")", 2)
        end
        do
            local _tps = dumperState.property_store[tweenTarget]
            local _tcn = _tps and _tps.ClassName
            if typeFunction(_tcn) == "string" then
                for k, v in pairsFunction(tweenProperties) do
                    local okm, tk = robloxApi.resolveMember(_tcn, k)
                    if okm and typeFunction(tk) == "string" then
                        local want = (tk == "n" and "number") or tk:match("^D:(.+)$")
                        if want and robloxApi.opTn(v) ~= want then
                            error("Unable to cast " .. robloxApi.opTn(v) .. " to " .. want, 2)
                        end
                    end
                end
            end
        end
        if typeFunction(tweenProperties) == "table" and not isProxy(tweenProperties) then
            if typeFunction(tweenProperties.Position) == "string" or typeFunction(tweenProperties.CFrame) == "boolean" then
                error("Invalid property type", 2)
            end
            -- Validate that properties exist on the target
            local validRobloxProperties = {
                Position=true, Size=true, CFrame=true, Rotation=true, Transparency=true,
                BackgroundTransparency=true, TextTransparency=true, ImageTransparency=true,
                Color=true, BackgroundColor3=true, TextColor3=true, ImageColor3=true,
                AnchorPoint=true, SizeConstraint=true, Visible=true, ZIndex=true,
                FieldOfView=true, Value=true, Brightness=true, Volume=true,
                PlaybackSpeed=true, TextSize=true, LineHeight=true, FontSize=true,
                TextStrokeTransparency=true, TextXAlignment=true, TextYAlignment=true,
                MaxActivationDistance=true, WalkSpeed=true, JumpPower=true, JumpHeight=true,
                Health=true, MaxHealth=true, CameraOffset=true, NameDisplayDistance=true,
                Weight=true, Density=true, Friction=true, Elasticity=true,
                FrictionWeight=true, ElasticityWeight=true, Gravity=true,
                Offset=true, StudsOffset=true, ExtentsOffset=true, Distance=true,
                PixelOffset=true, StudsOffsetWorldSpace=true, FaceId=true,
                Quaternion=true, BodyVelocity=true, BodyForce=true, BodyAngularVelocity=true,
                BodyPosition=true, BodyGyro=true, MaxForce=true, P=true, D=true,
                LinearVelocity=true, AngularVelocity=true, Torque=true, Force=true,
                Archivable=true, Name=true, Parent=true, ClassName=true,
                LightEmission=true, LightInfluence=true, Rate=true, Speed=true,
                SizeOffset=true, WidthScale=true, HeightScale=true,
            }
            local _wps = dumperState.property_store[tweenTarget]
            local _wcn = _wps and _wps.ClassName
            if isProxy(tweenTarget) then
                for k, v in pairsFunction(tweenProperties) do
                    local _known = typeFunction(_wcn) == "string" and robloxApi.resolveMember(_wcn, k)
                    if typeFunction(k) == "string" and not _known and not validRobloxProperties[k] then
                        error("TweenService:Create property " .. tostring(k) .. " is not a valid property of class " .. (dumperState.registry[tweenTarget] or "Instance"), 2)
                    end
                end
            end
        end
        local servicePath = dumperState.registry[proxy] or "TweenService"
        local tweenProxy = createProxyObject("Tween", false)
        rawset(tweenProxy, "__created_instance", true)
        local varName = registerVariable(tweenProxy, "tween")
        emitOutput(string.format("local %s = %s:Create(%s, %s, %s)", varName, servicePath, serializeValue(tweenTarget), serializeValue(tweenInfo), serializeValue(tweenProperties)))
        dumperState.property_store[tweenProxy] = {
            ClassName = "Tween",
            PlaybackState = robloxApi.enumByPath("Enum.PlaybackState.Begin"),
            Instance = tweenTarget,
            TweenInfo = tweenInfo,
            _target = tweenTarget,
            _properties = tweenProperties
        }
        return tweenProxy
    end
    serviceMethods.Play = function(self)
        local tweenPath = dumperState.registry[proxy] or "tween"
        emitOutput(string.format("%s:Play()", tweenPath))
        do
            local _tps = dumperState.property_store[proxy]
            if _tps and _tps.ClassName == "Tween" then return robloxApi.tweenPlay(proxy) end
        end
        
        dumperState.property_store[proxy] = dumperState.property_store[proxy] or {}
        dumperState.property_store[proxy].PlaybackState = robloxApi.enumByPath("Enum.PlaybackState.Playing")
        
        local props = dumperState.property_store[proxy]
        if props._target and props._properties and type(props._properties) == "table" then
            dumperState.property_store[props._target] = dumperState.property_store[props._target] or {}
            for k, v in pairsFunction(props._properties) do
                dumperState.property_store[props._target][k] = v
            end
        end

        task.delay(0.1, function()
            if dumperState.property_store[proxy] then
                dumperState.property_store[proxy].PlaybackState = robloxApi.enumByPath("Enum.PlaybackState.Completed")
            end
        end)
    end
