    serviceMethods.GetNameFromUserIdAsync = function(self, userId)
        local servicePath = dumperState.registry[proxy] or "Players"
        local resolvedId = (typeFunction(userId) == "table" and rawget(userId, "__value")) or userId
        resolvedId = tonumber(resolvedId) or 0
        if resolvedId <= 0 then
            error("invalid userId " .. tostring(resolvedId), 2)
        end
        if resolvedId == dumperState.fake_id then
            emitOutput(string.format("%s:GetNameFromUserIdAsync(%s)", servicePath, serializeValue(userId)))
            return dumperState.fake_name
        end
        -- Resolve the genuine username (live Roblox API + cache). Real executors
        -- return the actual string here, so falling back to a proxy is detectable.
        local resolvedName = resolveNameFromUserId(resolvedId)
        if typeFunction(resolvedName) == "string" then
            emitOutput(string.format("%s:GetNameFromUserIdAsync(%s)", servicePath, serializeValue(userId)))
            return resolvedName
        end
        -- Live lookup unavailable: a real client still returns a string here, so
        -- synthesize a deterministic username rather than a detectable proxy.
        local synthName = "Player" .. string.format("%d", resolvedId)
        _robloxUserId2Name[resolvedId] = synthName
        emitOutput(string.format("%s:GetNameFromUserIdAsync(%s)", servicePath, serializeValue(userId)))
        return synthName
    end
