    serviceMethods.GetPlayerFromCharacter = function(self, character)
        if not character then return nil end
        local lp = dumperState.local_player
        if lp then
            local charRef = dumperState.property_store[lp] and dumperState.property_store[lp].Character
            if charRef == character then return lp end
            local charProps = dumperState.property_store[character]
            if charProps then
                local lpProps = dumperState.property_store[lp]
                if lpProps and lpProps.Name == charProps.Name then return lp end
            end
        end
        return nil
    end
