    serviceMethods.GetMouse = function(self)
        -- :GetMouse() is only valid on the real LocalPlayer. Anywhere
        -- else (e.g. Instance.new("Player")) errors with the exact
        -- Roblox message — a detection that wraps the call in
        --   local ok = pcall(p.GetMouse, p); if ok then fail() end
        -- relies on that error to pass. The method-call dispatcher
        -- (methodMeta.__call) wraps the throw and returns nil to a
        -- non-pcall'd caller so the dump keeps emitting.
        if proxy ~= dumperState.local_player then
            error("GetMouse is not a valid member of Player", 2)
        end
        local playerPath = dumperState.registry[proxy] or "player"
        if dumperState._player_mouse then return dumperState._player_mouse end
        local mouseProxy = createProxyObject("PlayerMouse", false)
        rawset(mouseProxy, "__created_instance", true)
        dumperState.property_store[mouseProxy] = {ClassName = "PlayerMouse", Name = "PlayerMouse"}
        local varName = registerVariable(mouseProxy, "mouse")
        dumperState.registry[mouseProxy] = varName
        emitOutput(string.format("local %s = %s:GetMouse()", varName, playerPath))
        dumperState._player_mouse = mouseProxy
        return mouseProxy
    end
    serviceMethods.GetClientId = function(self)
        local servicePath = dumperState.registry[proxy] or "RbxAnalyticsService"
        if not (INLINER and dumperState.inliner_map) then
            emitOutput(string.format("%s:GetClientId()", servicePath))
        end
        if not dumperState._client_id then
            local tmpl = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx"
            dumperState._client_id = string.gsub(tmpl, "[xy]", function(c)
                local v = (c == "x") and math.random(0, 15) or math.random(8, 11)
                return string.format("%x", v)
            end)
            if INLINER and dumperState.inliner_map then
                local svcVar = dumperState.registry[proxy]
                local inlineExpr = svcVar and (svcVar .. ":GetClientId()") or 'game:GetService("RbxAnalyticsService"):GetClientId()'
                dumperState.inliner_map[dumperState._client_id] = inlineExpr
            end
        end
        return dumperState._client_id
    end
