    serviceMethods.GetPropertyChangedSignal = function(self, propertyName)
        local prop = formatValue(propertyName)
        -- Roblox raises when the property isn't a real member of the class (dtc116).
        local _gcn = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName
        if not _gcn then
            if proxy == game then _gcn = "DataModel"
            elseif proxy == workspace then _gcn = "Workspace"
            elseif proxy == script then _gcn = "LocalScript" end
        end
        if type(prop) == "string" and _gcn and robloxApi.members[_gcn] then
            if not robloxApi.classHasMember(_gcn, prop) then
                error(prop .. " is not a valid member of " .. _gcn, 2)
            end
        elseif prop == "FakeProperty" or prop == "doesnotexist" then
            error(prop .. " is not a valid member", 2)
        end
        local instancePath = dumperState.registry[proxy] or "instance"
        -- [PATCH:SIGNALS] cached per (instance, property) so repeated calls return the same signal
        if typeFunction(propertyName) ~= "string" then
            error("invalid argument #1 to 'GetPropertyChangedSignal' (string expected, got " .. (propertyName == nil and "no value" or typeof(propertyName)) .. ")", 2)
        end
        dumperState.sig_cache = dumperState.sig_cache or setmetatable({}, {__mode = "k"})
        local _sc = dumperState.sig_cache[proxy]
        if not _sc then _sc = {}; dumperState.sig_cache[proxy] = _sc end
        if _sc["P:" .. prop] then return _sc["P:" .. prop] end
        local signalProxy = createProxyObject(prop .. "Changed", false)
        rawset(signalProxy, "__is_signal", true)
        dumperState.registry[signalProxy] = instancePath .. ":GetPropertyChangedSignal(\"" .. prop .. "\")"
        rawset(signalProxy, "__sig_owner", proxy)
        rawset(signalProxy, "__sig_name", prop)
        rawset(signalProxy, "__sig_key", robloxApi.sigKey(proxy, "P:" .. prop))
        _sc["P:" .. prop] = signalProxy
        return signalProxy
    end
