    serviceMethods.IsA = function(self, class)
        -- [PATCH:ARGCHECK] Roblox method argument error
        if class == nil then error("Argument 1 missing or nil", 2) end
        -- The class name is required (dtc118).
        if class == nil then
            error("Argument 1 missing or nil", 2)
        end
        local pathName = dumperState.registry[proxy] or formattedName or ""
        local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName or ""
        if pathName == "game" then
            return class == "DataModel" or class == "Instance" or class == "Object"
        end
        if pathName == "workspace" then
            return class == "Workspace" or class == "WorldRoot" or class == "Model" or class == "Instance" or class == "Object"
        end
        if className ~= "" then
            local ancestors = classAncestors[className]
            if ancestors then
                for _, a in ipairsFunction(ancestors) do if a == class then return true end end
                return false
            end
            return class == className or class == "Instance" or class == "Object"
        end
        local name = pathName:match("^game%.([%w_]+)$") or pathName
        if serviceNames and serviceNames[name] then
            return class == name or class == "Instance" or class == "Object"
        end
        return class == "Instance" or class == "Object"
    end
