    -- Shared spatial-query core for Raycast / Spherecast / Blockcast: pick a
    -- part-like descendant of the workspace that SATISFIES the RaycastParams
    -- filter, and (on a hit) hand back a RaycastResult proxy identical in shape
    -- to Raycast's so `ray.Position == sphere.Position` for the same part (dtc
    -- cross-API). Returns nil when nothing passes -- exactly like Roblox in empty
    -- space. Filter selection is per-candidate (Include keeps only listed
    -- instances / their descendants; Exclude drops them), so leftover parts from
    -- earlier queries can't shadow the one the caller filtered for.
    local function _isDescendantOfAny(obj, list)
        for _, inst in ipairsFunction(list) do
            local cur, guard = obj, 0
            while cur and guard < 256 do
                if cur == inst then return true end
                cur = dumperState.parent_map[cur]
                guard = guard + 1
            end
        end
        return false
    end
    local function _spatialCast(params)
        local filterList, filterInclude = nil, false
        if params and isProxy(params) then
            filterList = rawget(params, "FilterDescendantsInstances") or {}
            local ft = rawget(params, "FilterType")
            local ftName = ft and (dumperState.registry[ft] or "") or "Exclude"
            filterInclude = ftName:match("Include") ~= nil
        end
        local hitPart = nil
        for obj, parent in pairsFunction(dumperState.parent_map) do
            if parent == workspace or parent == proxy then
                local props = dumperState.property_store[obj]
                if props and (props.ClassName == "Part" or props.ClassName == "MeshPart" or props.ClassName == "UnionOperation" or props.ClassName == "WedgePart" or props.ClassName == "TrussPart") then
                    local pass = true
                    if filterList and #filterList > 0 then
                        local inSet = _isDescendantOfAny(obj, filterList)
                        pass = filterInclude and inSet or (not filterInclude and not inSet)
                    elseif filterInclude then
                        -- Include with an empty list hits nothing.
                        pass = false
                    end
                    if pass then hitPart = obj end
                end
            end
        end
        if not hitPart then return nil end
        local hitPos = Vector3.new(0, 0, -15)
        if dumperState.property_store[hitPart] then
            local cf = dumperState.property_store[hitPart].CFrame or CFrame.new()
            local sz = dumperState.property_store[hitPart].Size or Vector3.new(1, 1, 1)
            hitPos = Vector3.new(cf.X, cf.Y, cf.Z + (sz.Z / 2))
        end
        local resultProxy = createProxyObject("RaycastResult", false)
        rawset(resultProxy, "__roblox_type", "RaycastResult")
        dumperState.property_store[resultProxy] = {
            Instance = hitPart,
            Position = hitPos,
            Distance = 15,
            Material = getCachedEnum("Enum.Material.Plastic"),
            Normal = Vector3.new(0, 0, 1)
        }
        return resultProxy
    end
    serviceMethods.Spherecast = function(self, origin, radius, direction, params)
        emitOutput(string.format("%s:Spherecast(%s, %s, %s, %s)", dumperState.registry[proxy] or "workspace", serializeValue(origin), serializeValue(radius), serializeValue(direction), serializeValue(params)))
        return _spatialCast(params)
    end
    serviceMethods.Blockcast = function(self, cframe, size, direction, params)
        emitOutput(string.format("%s:Blockcast(%s, %s, %s, %s)", dumperState.registry[proxy] or "workspace", serializeValue(cframe), serializeValue(size), serializeValue(direction), serializeValue(params)))
        return _spatialCast(params)
    end
    -- [MANUAL] Terrain:ReadVoxels returns TWO Grid3D-shaped tables (materials +
    -- occupancies). They must be real Lua tables (typeof == "table"), carry a
    -- Vector3 .Size, and index as t[x][y][z] to an EnumItem / number respectively
    -- (dtc terrain/region3). The emulator previously handed back a bare proxy.
    serviceMethods.ReadVoxels = function(self, region, resolution)
        emitOutput(string.format("%s:ReadVoxels(%s, %s)", dumperState.registry[proxy] or "workspace.Terrain", serializeValue(region), serializeValue(resolution)))
        local res = tonumber(resolution) or 4
        local function dim(axis)
            local ok, v = pcall(function() return region.Size[axis] end)
            local n = (ok and tonumber(v)) or (4 * res)
            n = math.floor(n / res + 0.5)
            if n < 1 then n = 1 end
            if n > 32 then n = 32 end
            return n
        end
        local nx, ny, nz = dim("X"), dim("Y"), dim("Z")
        -- Empty terrain reads back as Air. Build the EnumItem WITHOUT touching the
        -- shared enum_cache: a half-set-up cached item would shadow the properly
        -- typed one Enum.Material:GetEnumItems() builds later (dtc enum-order).
        local air = robloxApi.enumByPath("Enum.Material.Air")
        dumperState.registry[air] = "Enum.Material.Air"
        local materials = { Size = Vector3.new(nx, ny, nz) }
        local occupancies = { Size = Vector3.new(nx, ny, nz) }
        for x = 1, nx do
            materials[x] = {}; occupancies[x] = {}
            for y = 1, ny do
                materials[x][y] = {}; occupancies[x][y] = {}
                for z = 1, nz do
                    materials[x][y][z] = air
                    occupancies[x][y][z] = 0
                end
            end
        end
        return materials, occupancies
    end
    -- [PATCH:RAYCAST-GEOMETRY] Raycast intersects the oriented boxes of the workspace parts (nearest hit,
    -- real Position/Normal/Distance, filter + CanQuery honoured); a miss returns nil.
    local function _rayGeom(origin, direction, params)
        local filterList, filterInclude = nil, false
        if params and isProxy(params) then
            filterList = rawget(params, "FilterDescendantsInstances") or {}
            local ft = rawget(params, "FilterType")
            filterInclude = ft and (dumperState.registry[ft] or ""):match("Include") ~= nil or false
        end
        local best, bestT, bestN, bestPart
        local dlen = direction.Magnitude
        if dlen == 0 then return nil end
        for obj in pairsFunction(dumperState.parent_map) do
            local props = dumperState.property_store[obj]
            if props and robloxApi.isPartLikeClass(props.ClassName or "") and robloxApi.inDataModel(obj) then
                local pass = true
                if filterList and #filterList > 0 then
                    local inSet = _isDescendantOfAny(obj, filterList)
                    pass = filterInclude and inSet or (not filterInclude and not inSet)
                elseif filterInclude then pass = false end
                local okq, canQuery = pcallFunction(function() return obj.CanQuery end)
                if okq and canQuery == false then pass = false end
                if pass then
                    local ok, cf, sz = pcallFunction(function() return obj.CFrame, obj.Size end)
                    if ok and cf and sz then
                        local lo, ld = cf:PointToObjectSpace(origin), cf:VectorToObjectSpace(direction)
                        local half = {sz.X / 2, sz.Y / 2, sz.Z / 2}
                        local o, d = {lo.X, lo.Y, lo.Z}, {ld.X, ld.Y, ld.Z}
                        local t0, t1, nAxis, nSign = 0, 1, nil, 0
                        local hit = true
                        for ax = 1, 3 do
                            if d[ax] == 0 then
                                if o[ax] < -half[ax] or o[ax] > half[ax] then hit = false; break end
                            else
                                local ta, tb = (-half[ax] - o[ax]) / d[ax], (half[ax] - o[ax]) / d[ax]
                                local sg = -1
                                if ta > tb then ta, tb = tb, ta; sg = 1 end
                                if ta > t0 then t0 = ta; nAxis = ax; nSign = sg end
                                if tb < t1 then t1 = tb end
                                if t0 > t1 then hit = false; break end
                            end
                        end
                        if hit and nAxis and (not bestT or t0 < bestT) then
                            bestT, bestPart = t0, obj
                            local nl = {0, 0, 0}; nl[nAxis] = nSign
                            bestN = cf:VectorToWorldSpace(Vector3.new(nl[1], nl[2], nl[3]))
                        end
                    end
                end
            end
        end
        if not bestPart then return nil end
        local resultProxy = createProxyObject("RaycastResult", false)
        rawset(resultProxy, "__roblox_type", "RaycastResult")
        local okm, mat = pcallFunction(function() return bestPart.Material end)
        dumperState.property_store[resultProxy] = {
            Instance = bestPart,
            Position = origin + direction * bestT,
            Distance = bestT * dlen,
            Material = okm and mat or getCachedEnum("Enum.Material.Plastic"),
            Normal = bestN,
        }
        return resultProxy
    end
    serviceMethods.Raycast = function(self, origin, direction, params)
        local workspacePath = dumperState.registry[proxy] or "workspace"
        -- A real client rejects a missing origin/direction (dtc error-strings).
        if origin == nil or direction == nil then
            error("Unable to cast value to 'Vector3'", 2)
        end
        -- [PATCH:RAYCAST-ARGS] typed argument validation
        if robloxApi.opTn(origin) ~= "Vector3" then error("invalid argument #1 to 'Raycast' (Vector3 expected, got " .. robloxApi.argTn(origin) .. ")", 2) end
        if robloxApi.opTn(direction) ~= "Vector3" then error("invalid argument #2 to 'Raycast' (Vector3 expected, got " .. robloxApi.argTn(direction) .. ")", 2) end
        if params ~= nil and robloxApi.opTn(params) ~= "RaycastParams" then error("invalid argument #3 to 'Raycast' (RaycastParams expected, got " .. robloxApi.argTn(params) .. ")", 2) end
        if params then
            emitOutput(string.format("%s:Raycast(%s, %s, %s)", workspacePath, serializeValue(origin), serializeValue(direction), serializeValue(params)))
        else
            emitOutput(string.format("%s:Raycast(%s, %s)", workspacePath, serializeValue(origin), serializeValue(direction)))
        end
        if robloxApi.opTn(origin) == "Vector3" and robloxApi.opTn(direction) == "Vector3" then return _rayGeom(origin, direction, params) end
        return _spatialCast(params)
    end
