    serviceMethods.ClearAllChildren = function(self)
        local parentPath = dumperState.registry[proxy] or "object"
        if proxy == game then
            error("Cannot call ClearAllChildren on DataModel", 2)
        end
        if parentPath:match("Terrain") or (dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName == "Terrain") then
            error("Cannot call ClearAllChildren on Terrain", 2)
        end
        emitOutput(string.format("%s:ClearAllChildren()", parentPath))
        local function clearRecursive(target)
            for obj, p in pairsFunction(dumperState.parent_map) do
                if p == target then
                    dumperState.parent_map[obj] = nil
                    if dumperState.property_store[obj] then
                        dumperState.property_store[obj].Parent = nil
                    end
                    clearRecursive(obj)
                end
            end
        end
        clearRecursive(proxy)
    end
