    serviceMethods.GetUserIdFromNameAsync = function(self, name)
        local servicePath = dumperState.registry[proxy] or "Players"
        local resolvedName = (typeFunction(name) == "table" and rawget(name, "__value")) or name
        if tostring(resolvedName) == dumperState.fake_name then
            emitOutput(string.format("%s:GetUserIdFromNameAsync(%s)", servicePath, serializeValue(name)))
            return dumperState.fake_id
        end
        -- Resolve the genuine user id (live Roblox API + cache).
        local resolvedId = resolveUserIdFromName(resolvedName)
        if typeFunction(resolvedId) == "number" then
            emitOutput(string.format("%s:GetUserIdFromNameAsync(%s)", servicePath, serializeValue(name)))
            return resolvedId
        end
        -- Live lookup unavailable: a real client still returns an integer userId
        -- here, so synthesize a deterministic id rather than a detectable proxy.
        local s = tostring(resolvedName)
        local synthId = 0
        for i = 1, #s do synthId = (synthId * 31 + string.byte(s, i)) % 2147483647 end
        synthId = synthId + 1
        _robloxUserName2Id[s] = synthId
        emitOutput(string.format("%s:GetUserIdFromNameAsync(%s)", servicePath, serializeValue(name)))
        return synthId
    end
