    serviceMethods.GetPartBoundsInBox = function(self, cframe, size, params)
        local path = dumperState.registry[proxy] or "workspace"
        emitOutput(string.format("%s:GetPartBoundsInBox(%s, %s, %s)", path, serializeValue(cframe), serializeValue(size), serializeValue(params)))
        -- [PATCH:RAYCAST-GEOMETRY] only parts whose bounding box overlaps the query box qualify
        local _qlo, _qhi
        if robloxApi.opTn(cframe) == "CFrame" and robloxApi.opTn(size) == "Vector3" then
            _qlo, _qhi = robloxApi.aabbOf(cframe, size)
        end
        local parts = {}
        for obj, parent in pairsFunction(dumperState.parent_map) do
            local _near = true
            if _qlo then
                _near = false
                local _ops = dumperState.property_store[obj]
                if _ops and robloxApi.isPartLikeClass(_ops.ClassName or "") then
                    local ok, ocf, osz = pcallFunction(function() return obj.CFrame, obj.Size end)
                    if ok and ocf and osz then
                        local lo, hi = robloxApi.aabbOf(ocf, osz)
                        _near = lo.X <= _qhi.X and hi.X >= _qlo.X and lo.Y <= _qhi.Y and hi.Y >= _qlo.Y and lo.Z <= _qhi.Z and hi.Z >= _qlo.Z
                    end
                end
            end
            if _near and (parent == workspace or parent == proxy) then
                local filter = {}
                local filterType = nil
                if params and dumperState.property_store[params] then
                    filter = dumperState.property_store[params].FilterDescendantsInstances or {}
                    filterType = dumperState.property_store[params].FilterType
                end
                
                local isFiltered = false
                for _, v in ipairsFunction(filter) do
                    if v == obj then isFiltered = true; break end
                end
                
                local isExclude = true
                if filterType and dumperState.registry[filterType] and dumperState.registry[filterType]:match("Include") then
                    isExclude = false
                end

                if isExclude then
                    if not isFiltered then table.insert(parts, obj) end
                else
                    if isFiltered then table.insert(parts, obj) end
                end
            end
        end
        return parts
    end
    serviceMethods.GetPartBoundsInRadius = function(self, position, radius, params)
        local path = dumperState.registry[proxy] or "workspace"
        emitOutput(string.format("%s:GetPartBoundsInRadius(%s, %s, %s)", path, serializeValue(position), serializeValue(radius), serializeValue(params)))
        local parts = {}
        local _rok = robloxApi.opTn(position) == "Vector3" and typeFunction(radius) == "number" -- [PATCH:RAYCAST-GEOMETRY]
        for obj, parent in pairsFunction(dumperState.parent_map) do
            local _near = true
            if _rok then
                _near = false
                local _ops = dumperState.property_store[obj]
                if _ops and robloxApi.isPartLikeClass(_ops.ClassName or "") then
                    local ok, ocf, osz = pcallFunction(function() return obj.CFrame, obj.Size end)
                    if ok and ocf and osz then
                        local lo, hi = robloxApi.aabbOf(ocf, osz)
                        local dx = math.max(lo.X - position.X, 0, position.X - hi.X)
                        local dy = math.max(lo.Y - position.Y, 0, position.Y - hi.Y)
                        local dz = math.max(lo.Z - position.Z, 0, position.Z - hi.Z)
                        _near = dx * dx + dy * dy + dz * dz <= radius * radius
                    end
                end
            end
            if _near and (parent == workspace or parent == proxy) then
                table.insert(parts, obj)
            end
        end
        return parts
    end
    -- [MANUAL] Workspace:FindPartsInRegion3(region, ignoreDescendantsInstance,
    -- maxParts) -- a legacy spatial query. Returns part-like descendants of the
    -- workspace inside the region as a real array; the 2nd arg's DESCENDANTS are
    -- ignored (the instance itself still qualifies, matching Roblox), so the
    -- cross-API check that raycast/overlap/region all see the same part holds.
    serviceMethods.FindPartsInRegion3 = function(self, region, ignoreInstance, maxParts)
        local path = dumperState.registry[proxy] or "workspace"
        emitOutput(string.format("%s:FindPartsInRegion3(%s, %s, %s)", path, serializeValue(region), serializeValue(ignoreInstance), serializeValue(maxParts)))
        local cap = tonumber(maxParts) or 20
        local parts = {}
        for obj, parent in pairsFunction(dumperState.parent_map) do
            if (parent == workspace or parent == proxy) then
                local props = dumperState.property_store[obj]
                if props and robloxApi.isPartLikeClass(props.ClassName or "") then
                    local ignored = false
                    if ignoreInstance then
                        local cur, g = dumperState.parent_map[obj], 0
                        while cur and g < 256 do
                            if cur == ignoreInstance then ignored = true; break end
                            cur = dumperState.parent_map[cur]; g = g + 1
                        end
                    end
                    if not ignored and #parts < cap then table.insert(parts, obj) end
                end
            end
        end
        return parts
    end
