    end
    serviceMethods.CreatePath = function(self)
        local p = createProxyObject("Path", false)
        dumperState.registry[p] = "Path"
        -- Blocked / Unblocked are RBXScriptSignals; pre-store them as signal
        -- proxies so `path.Blocked:Connect(...)` / `path.Blocked.Connect` resolve
        -- to a signal rather than a bare method function (dtc pathfinding).
        local function _pathSignal(name)
            local sig = createProxyObject("Path." .. name, false, p)
            dumperState.registry[sig] = "Path." .. name
            rawset(sig, "__is_signal", true)
            return sig
        end
        dumperState.property_store[p] = {
            ClassName = "Path",
            Status = getCachedEnum("Enum.PathStatus.Success"),
            Blocked = _pathSignal("Blocked"),
            Unblocked = _pathSignal("Unblocked"),
        }
        return p
    end
