    serviceMethods.SetEntries = function(self, entries)
        local path = dumperState.registry[proxy] or "LocalizationTable"
        emitOutput(string.format("%s:SetEntries(%s)", path, serializeValue(entries)))
        dumperState.property_store[proxy] = dumperState.property_store[proxy] or {}
        dumperState.property_store[proxy]._entries = entries
    end
