        serviceMethods.GetCountryRegionForPlayerAsync = function(self, player)
        if typeFunction(player) == "thread" or typeFunction(player) == "userdata" or typeFunction(player) == "function" then
            error("Unable to cast value to Object", 2)
        end
        if typeFunction(player) == "table" and not isProxy(player) then
            error("Unable to cast value to Object", 2)
        end
        local servicePath = dumperState.registry[proxy] or "LocalizationService"
        emitOutput(string.format("%s:GetCountryRegionForPlayerAsync(%s)", servicePath, serializeValue(player)))
        return "US"
    end
    serviceMethods.GetPlayerFromCharacter = function(self, character)
        -- [PATCH:PLAYERS-LOOKUP] argument validation like the engine; only characters that belong to a
        -- player resolve (here: the LocalPlayer's), anything else is nil -- no fabricated players.
        if character == nil then error("Argument 1 missing or nil", 2) end
        if typeFunction(character) ~= "table" or not isProxy(character) or not dumperState.property_store[character] then
            error("Unable to cast value to Object", 2)
        end
        if dumperState.local_player then
            local lp = dumperState.local_player
            local charRef = dumperState.property_store[lp] and dumperState.property_store[lp].Character
            if charRef == character then return lp end
            local lc = dumperState.local_character
            if lc ~= nil and lc == character then return lp end
        end
        return nil
    end
    serviceMethods.Interpolate = function(self, endPos, endFocus, duration)
        local function isCFrame(v)
            local t = typeFunction(v)
            if t == "userdata" then return true end
            if t == "table" and dumperState.registry[v] and dumperState.registry[v]:match("CFrame") then return true end
            return false
        end
        if not isCFrame(endPos) then error("invalid argument #1 to 'Interpolate' (CFrame expected)", 2) end
        if not isCFrame(endFocus) then error("invalid argument #2 to 'Interpolate' (CFrame expected)", 2) end
        
        local camPath = dumperState.registry[proxy] or "Camera"
        emitOutput(string.format("%s:Interpolate(%s, %s, %s)", camPath, serializeValue(endPos), serializeValue(endFocus), serializeValue(duration)))
    end
    serviceMethods.GetPlayerByUserId = function(self, userId)
        -- [PATCH:PLAYERS-LOOKUP] numeric userId required; only the LocalPlayer exists in a client
        if userId == nil then error("Argument 1 missing or nil", 2) end
        if typeFunction(userId) == "string" then
            userId = tonumber(userId)
            if userId == nil then error("Unable to cast string to int64", 2) end
        end
        if typeFunction(userId) ~= "number" then error("Unable to cast " .. robloxApi.argTn(userId) .. " to int64", 2) end
        local lp = dumperState.local_player
        if lp then
            local lpid = dumperState.property_store[lp] and dumperState.property_store[lp].UserId
            if userId == dumperState.fake_id or (lpid ~= nil and userId == lpid) then return lp end
        end
        return nil
    end
