    -- [PATCH:RENDERSTEP] bound functions run once per simulated frame, ordered by priority, inside
    -- task.wait/wait (never synchronously at bind time); the first call's output is spliced in place.
    serviceMethods.BindToRenderStep = function(self, name, priority, func)
        if name == nil then error("Argument 1 missing or nil", 2) end
        if typeFunction(name) ~= "string" then error("invalid argument #1 to 'BindToRenderStep' (string expected, got " .. robloxApi.argTn(name) .. ")", 2) end
        if priority == nil then error("Argument 2 missing or nil", 2) end
        if typeFunction(priority) ~= "number" then error("invalid argument #2 to 'BindToRenderStep' (number expected, got " .. robloxApi.argTn(priority) .. ")", 2) end
        if func == nil then error("Argument 3 missing or nil", 2) end
        if typeFunction(func) ~= "function" then error("invalid argument #3 to 'BindToRenderStep' (function expected, got " .. robloxApi.argTn(func) .. ")", 2) end
        if robloxApi.renderFns[name] then error("Name '" .. name .. "' is already bound to RenderStep", 2) end
        local servicePath = dumperState.registry[proxy] or "RunService"
        dumperState._renderStepList = dumperState._renderStepList or {}
        dumperState._renderStepList[name] = priority
        emitOutput(string.format("%s:BindToRenderStep(%s, %s, function(deltaTime)", servicePath, formatStringLiteral(name), serializeValue(priority)))
        local block_id = "--[[RENDER_BLOCK_" .. tostring(math.random(1000000, 9999999)) .. "]]"
        table.insert(dumperState.output, block_id)
        robloxApi.renderSeq = robloxApi.renderSeq + 1
        robloxApi.renderFns[name] = {name = name, priority = priority, func = func, seq = robloxApi.renderSeq, block = block_id, indent = dumperState.indent}
        emitOutput("end)")
    end
    serviceMethods.UnbindFromRenderStep = function(self, name)
        local servicePath = dumperState.registry[proxy] or "RunService"
        if name == nil then error("Argument 1 missing or nil", 2) end
        if typeFunction(name) ~= "string" then error("invalid argument #1 to 'UnbindFromRenderStep' (string expected, got " .. robloxApi.argTn(name) .. ")", 2) end
        dumperState._renderStepList = dumperState._renderStepList or {}
        dumperState._renderStepList[name] = nil
        local _e = robloxApi.renderFns[name]
        if _e and _e.block then robloxApi.runBound(_e, 1 / 60) end
        robloxApi.renderFns[name] = nil
        emitOutput(string.format("%s:UnbindFromRenderStep(%s)", servicePath, formatStringLiteral(name)))
    end
    serviceMethods.GetRenderStepList = function(self)
        dumperState._renderStepList = dumperState._renderStepList or {}
        return dumperState._renderStepList
    end
    serviceMethods.GetFullName = function(self)
        if proxy == game then return "Ugc" end
        local parts = {}
        local current = proxy
        while current do
            if current == game then break end
            if current == workspace then
                table.insert(parts, 1, "Workspace")
                break
            end
            if current == script then
                -- The dumped LocalScript is unparented; its full name is just
                -- its class-derived name "LocalScript" (dtc7).
                table.insert(parts, 1, "LocalScript")
                break
            end
            local props = dumperState.property_store[current]
            local name = (props and props.Name) or (dumperState.registry[current] and dumperState.registry[current]:match("([^%.]+)$")) or "Instance"
            table.insert(parts, 1, name)
            current = dumperState.parent_map[current]
        end
        if #parts == 0 then return dumperState.registry[proxy] or "Instance" end
        return table.concat(parts, ".")
    end
    serviceMethods.GetDebugId = function(self)
        -- Key on the actual instance the method was invoked on (self), and use
        -- a monotonic counter, so every distinct instance gets a distinct id --
        -- game/workspace/Players must never collide (dtc5).
        local target = (isProxy(self) and self) or proxy
        dumperState.debug_ids = dumperState.debug_ids or {}
        if not dumperState.debug_ids[target] then
            dumperState.debug_id_counter = (dumperState.debug_id_counter or 0) + 1
            dumperState.debug_ids[target] = "0_" .. tostring(100000 + dumperState.debug_id_counter * 7 + math.random(0, 6))
            if INLINER and dumperState.inliner_map then
                local objPath = dumperState.registry[target] or "object"
                dumperState.inliner_map[dumperState.debug_ids[target]] = objPath .. ":GetDebugId()"
            end
        end
        return dumperState.debug_ids[target]
    end
    serviceMethods.GetEnumItems = function(self)
        local enumName = dumperState.registry[proxy] or "Enum"
        emitOutput(string.format("%s:GetEnumItems()", enumName))
        dumperState.enum_cache = dumperState.enum_cache or {}
        local categoryName = enumName:match("^Enum%.(.+)$")
        local validItems = categoryName and knownEnumItems[categoryName]
        if validItems then
            local result = {}
            for itemName in pairsFunction(validItems) do
                local itemPath = enumName .. "." .. itemName
                local p = dumperState.enum_cache[itemPath]
                if not p then
                    p = createProxyObject(itemPath, false)
                    dumperState.registry[p] = itemPath
                    dumperState.enum_cache[itemPath] = p
                end
                -- Give each item the EnumItem contract so item.EnumType points
                -- back to its parent Enum (this proxy) instead of being caught by
                -- the generic "*Type" -> dummy-enum guesser (eUNC EnumType check).
                local im = getMetatableFunction(p)
                if type(im) == "table" and not rawget(im, "__enum_item_setup") then
                    rawset(im, "__enum_item_setup", true)
                    local _nm, _cat, _en = itemName, proxy, categoryName
                    im.__index = function(_, propKey)
                        if propKey == proxyList or propKey == "__proxy_id" then return rawget(_, propKey) end
                        if propKey == "Name" then return _nm end
                        if propKey == "Value" then
                            local ev = enumItemValues[_en]
                            if ev ~= nil and ev[_nm] ~= nil then return ev[_nm] end
                            return 0
                        end
                        if propKey == "EnumType" then return _cat end
                        error(tostring(propKey) .. " is not a valid member of EnumItem", 2)
                    end
                end
                table.insert(result, p)
            end
            -- [MANUAL] Roblox returns items ordered by ascending Value. Sort by the
            -- items' own reported Value so the order matches what the caller reads
            -- back, regardless of how each item proxy was cached (dtc56..60).
            table.sort(result, function(a, b)
                local va = a.Value; if typeFunction(va) ~= "number" then va = 0 end
                local vb = b.Value; if typeFunction(vb) ~= "number" then vb = 0 end
                if va == vb then return tostring(a.Name) < tostring(b.Name) end
                return va < vb
            end)
            return result
        end
        local dummyItem = createProxyObject(enumName .. ".Dummy", false)
        dumperState.registry[dummyItem] = enumName .. ".Dummy"
        return { dummyItem }
    end
    serviceMethods.MoveTo = function(self, pos, part)
        -- [PATCH:METHOD-ARGS] MoveTo(location: Vector3, part: BasePart?)
        if robloxApi.opTn(pos) ~= "Vector3" then error("invalid argument #1 to 'MoveTo' (Vector3 expected, got " .. (pos == nil and "no value" or robloxApi.argTn(pos)) .. ")", 2) end
        local humPath = dumperState.registry[proxy] or "humanoid"
        if part then
            emitOutput(string.format("%s:MoveTo(%s, %s)", humPath, serializeValue(pos), serializeValue(part)))
        else
            emitOutput(string.format("%s:MoveTo(%s)", humPath, serializeValue(pos)))
        end
        local function applyMove(targetPos)
            if typeFunction(targetPos) ~= "table" then return end
            local hum = proxy
            local char = dumperState.parent_map[hum]
            if not char then return end
            for obj, parent in pairsFunction(dumperState.parent_map) do
                if parent == char then
                    local props = dumperState.property_store[obj]
                    local cn = props and props.ClassName
                    local nm = props and props.Name
                    if (nm == "HumanoidRootPart") or (cn == "Part" and nm == "HumanoidRootPart") then
                        dumperState.property_store[obj] = props or {}
                        dumperState.property_store[obj].Position = targetPos
                        local okCF, cf = pcall(function() return CFrame.new(targetPos.X, targetPos.Y, targetPos.Z) end)
                        if okCF then dumperState.property_store[obj].CFrame = cf end
                    end
                end
            end
            dumperState.property_store[hum] = dumperState.property_store[hum] or {}
            dumperState.property_store[hum]._lastMoveTarget = targetPos
        end
        applyMove(pos)
    end
