    serviceMethods.TakeDamage = function(self, damage)
        -- [PATCH:METHOD-ARGS] TakeDamage(amount: number)
        if tonumber(damage) == nil then error("invalid argument #1 to 'TakeDamage' (number expected, got " .. (damage == nil and "no value" or robloxApi.argTn(damage)) .. ")", 2) end
        local humPath = dumperState.registry[proxy] or "humanoid"
        -- Mirror real Humanoid:TakeDamage — subtract from Health so a
        -- subsequent .Health read matches what a normal client sees.
        local props = dumperState.property_store[proxy]
        if props then
            local cur = tonumber(props.Health) or 100
            local dmg = tonumber(damage) or 0
            local newHealth = cur - dmg
            if newHealth < 0 then newHealth = 0 end
            props.Health = robloxApi.f32round(newHealth)
        end
        emitOutput(string.format("%s:TakeDamage(%s)", humPath, serializeValue(damage)))
    end
