        if not dumperState.enum_cache[enumStr] then
            local p = createProxyObject(enumStr, false)
            dumperState.registry[p] = enumStr
            dumperState.enum_cache[enumStr] = p
        end
        return dumperState.enum_cache[enumStr]
    end
