    serviceMethods.ApplyAngularImpulse = function(self, impulse)
        local path = dumperState.registry[proxy] or "Part"
        emitOutput(string.format("%s:ApplyAngularImpulse(%s)", path, serializeValue(impulse)))
        local ps = dumperState.property_store[proxy] or {}
        dumperState.property_store[proxy] = ps
        -- Angular impulse divides by the inertia tensor (the raw magnitude is
        -- physically impossible as a resulting angular velocity -- dtc13).
        local _, inertiaY = robloxApi.partMass(ps)
        local base = ps.AssemblyAngularVelocity or Vector3.new(0, 0, 0)
        local ix = (type(impulse) == "table" and impulse.X) or 0
        local iy = (type(impulse) == "table" and impulse.Y) or 0
        local iz = (type(impulse) == "table" and impulse.Z) or 0
        ps.AssemblyAngularVelocity = Vector3.new(base.X + ix / inertiaY, base.Y + iy / inertiaY, base.Z + iz / inertiaY)
        ps._physAngT0 = get_virtual_clock()
    end
    serviceMethods.ApplyImpulse = function(self, impulse)
        local path = dumperState.registry[proxy] or "Part"
        emitOutput(string.format("%s:ApplyImpulse(%s)", path, serializeValue(impulse)))
        local ps = dumperState.property_store[proxy] or {}
        dumperState.property_store[proxy] = ps
        -- Linear impulse divides by the assembly mass (dtc12).
        local mass = robloxApi.partMass(ps)
        local base = ps.AssemblyLinearVelocity or Vector3.new(0, 0, 0)
        local ix = (type(impulse) == "table" and impulse.X) or 0
        local iy = (type(impulse) == "table" and impulse.Y) or 0
        local iz = (type(impulse) == "table" and impulse.Z) or 0
        ps.AssemblyLinearVelocity = Vector3.new(base.X + ix / mass, base.Y + iy / mass, base.Z + iz / mass)
        ps._physVelT0 = get_virtual_clock()
    end
