    serviceMethods.ChangeState = function(self, state)
        -- [PATCH:METHOD-ARGS] ChangeState(state: Enum.HumanoidStateType): a string that is not a state name cannot be cast
        if typeFunction(state) == "string" and not pcallFunction(function() return Enum.HumanoidStateType[state] end) then
            error("Unable to cast string to token", 2)
        elseif state == nil or typeFunction(state) == "boolean" then
            error("invalid argument #1 to 'ChangeState' (HumanoidStateType expected, got " .. (state == nil and "no value" or "boolean") .. ")", 2)
        end
        local humPath = dumperState.registry[proxy] or "humanoid"
        emitOutput(string.format("%s:ChangeState(%s)", humPath, serializeValue(state)))
        dumperState.property_store[proxy] = dumperState.property_store[proxy] or {}
        local stateName = "Running"
        if typeFunction(state) == "table" then
            local reg = dumperState.registry[state]
            if reg then stateName = tostring(reg):match("HumanoidStateType%.(%w+)") or stateName end
        elseif typeFunction(state) == "string" then
            stateName = state
        end
        dumperState.property_store[proxy]._currentState = stateName
        -- [MANUAL] FloorMaterial follows the airborne state: no floor while
        -- jumping / falling / flying, a ground material otherwise (dtc11).
        if stateName == "Jumping" or stateName == "Freefall" or stateName == "Flying" or stateName == "FallingDown" then
            dumperState.property_store[proxy].FloorMaterial = getCachedEnum("Enum.Material.Air")
        else
            dumperState.property_store[proxy].FloorMaterial = getCachedEnum("Enum.Material.Plastic")
        end
        if stateName == "Jumping" then
            local char = dumperState.parent_map[proxy]
            if char then
                dumperState.hrp_cache = dumperState.hrp_cache or {}
                local hrp = dumperState.hrp_cache[char]
                if not hrp then
                    for obj, parent in pairsFunction(dumperState.parent_map) do
                        if parent == char then
                            local nm = dumperState.property_store[obj] and dumperState.property_store[obj].Name
                            if nm == "HumanoidRootPart" then hrp = obj; break end
                        end
                    end
                end
                if hrp then
                    local hrpPs = dumperState.property_store[hrp] or {}
                    dumperState.property_store[hrp] = hrpPs
                    local cur = hrpPs.Position or Vector3.new(0, 5, 0)
                    local humPs = dumperState.property_store[proxy]
                    local jh = (humPs and humPs.JumpHeight) or 7.2
                    local gravity = 196.2
                    local vy0 = math.sqrt(2 * gravity * jh)
                    local newPos = Vector3.new(cur.X, cur.Y + jh, cur.Z)
                    hrpPs.Position = newPos
                    hrpPs.CFrame = CFrame.new(newPos.X, newPos.Y, newPos.Z)
                    dumperState.jump_physics = {hrp = hrp, humanoid = proxy, vy = vy0, gravity = gravity, active = true, base_y = cur.Y}
                end
            end
        end
    end
