    serviceMethods.PivotTo = function(self, cf)
        local modelPath = dumperState.registry[proxy] or "model"
        if robloxApi.opTn(cf) ~= "CFrame" then error("invalid argument #1 to 'PivotTo' (CFrame expected, got " .. (cf == nil and "no value" or robloxApi.argTn(cf)) .. ")", 2) end
        emitOutput(string.format("%s:PivotTo(%s)", modelPath, serializeValue(cf)))
        -- [PATCH:MODEL-GEOM] move the part(s) rigidly so GetPivot()/Position read back what was set
        local ps = dumperState.property_store[proxy]
        if not ps then return end
        local okO, old = pcallFunction(serviceMethods.GetPivot, self)
        if not (okO and robloxApi.opTn(old) == "CFrame") then return end
        local delta = cf * old:Inverse()
        local targets = robloxApi.modelParts(proxy)
        if robloxApi.isPartLikeClass(ps.ClassName or "") then targets[#targets + 1] = proxy end
        for _, part in ipairsFunction(targets) do
            local pps = dumperState.property_store[part]
            local okC, c = pcallFunction(function() return delta * part.CFrame end)
            if okC and c then pps.CFrame = c; pps.Position = c.Position end
        end
        if ps.ClassName == "Model" then
            local okP, pp = pcallFunction(function() return proxy.PrimaryPart end)
            if not (okP and pp) then ps.WorldPivot = cf end
        end
    end
    -- [PATCH:PIVOT] a part's pivot is CFrame * PivotOffset; a model's follows its PrimaryPart (else WorldPivot)
    serviceMethods.GetPivot = function(self)
        local ps = dumperState.property_store[proxy]
        local ok, cf, po = pcallFunction(function()
            if ps and robloxApi.isPartLikeClass(ps.ClassName or "") then return proxy.CFrame, proxy.PivotOffset end
            local pp = proxy.PrimaryPart
            if pp then return pp.CFrame, pp.PivotOffset end
        end)
        if ok and cf then return po and cf * po or cf end
        if ps and robloxApi.opTn(ps.WorldPivot) == "CFrame" then return ps.WorldPivot end
        local bcf = robloxApi.modelBox and robloxApi.modelBox(proxy) -- [PATCH:MODEL-GEOM] default pivot = bounding-box centre
        if bcf then return bcf end
        return CFrame.new(0, 0, 0)
    end
    -- [PATCH:MODEL-GEOM] bounding box / extents / PivotTo / ScaleTo computed from the model's part descendants
    robloxApi.modelParts = function(root)
        local kids, out, queue, qi = {}, {}, {root}, 1
        for obj, par in pairsFunction(dumperState.parent_map) do
            local l = kids[par]; if not l then l = {}; kids[par] = l end
            l[#l + 1] = obj
        end
        while qi <= #queue do
            local cur = queue[qi]; qi = qi + 1
            local cps = dumperState.property_store[cur]
            if cur ~= root and cps and robloxApi.isPartLikeClass(cps.ClassName or "") then out[#out + 1] = cur end
            if kids[cur] then for _, k in ipairsFunction(kids[cur]) do queue[#queue + 1] = k end end
        end
        return out
    end
    robloxApi.modelBox = function(root)
        local parts = robloxApi.modelParts(root)
        if #parts == 0 then return nil end
        local mnx, mny, mnz, mxx, mxy, mxz
        for _, part in ipairsFunction(parts) do
            local sz, cf = part.Size, part.CFrame
            local _, _, _, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
            local px, py, pz = cf.Position.X, cf.Position.Y, cf.Position.Z
            local hx, hy, hz = sz.X / 2, sz.Y / 2, sz.Z / 2
            local ex = math.abs(r00) * hx + math.abs(r01) * hy + math.abs(r02) * hz
            local ey = math.abs(r10) * hx + math.abs(r11) * hy + math.abs(r12) * hz
            local ez = math.abs(r20) * hx + math.abs(r21) * hy + math.abs(r22) * hz
            mnx = mnx and math.min(mnx, px - ex) or px - ex; mxx = mxx and math.max(mxx, px + ex) or px + ex
            mny = mny and math.min(mny, py - ey) or py - ey; mxy = mxy and math.max(mxy, py + ey) or py + ey
            mnz = mnz and math.min(mnz, pz - ez) or pz - ez; mxz = mxz and math.max(mxz, pz + ez) or pz + ez
        end
        return CFrame.new((mnx + mxx) / 2, (mny + mxy) / 2, (mnz + mxz) / 2), Vector3.new(mxx - mnx, mxy - mny, mxz - mnz)
    end
