    serviceMethods.JSONEncode = function(self, data)
        local servicePath = dumperState.registry[proxy] or "HttpService"
        -- JSONEncode only exists on HttpService; reject calls on plain instances
        if rawget(proxy, "__created_instance") then
            local cn = (dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName) or (formattedName or "Instance")
            error("JSONEncode is not a valid member of " .. cn .. " \"" .. robloxApi.fullName(proxy, formattedName or "object") .. "\"", 2)
        end

        robloxApi.jsonCheck(data, 0) -- [PATCH:HTTP-VALIDATE]
        -- Roblox always encodes tables as JSON arrays; normalize empty table to "[]"
        if typeFunction(data) == "table" then
            local hasKeys = false
            for _ in pairsFunction(data) do hasKeys = true; break end
            if not hasKeys then
                local resultProxy = createProxyObject("jsonString", false)
                local varName = registerVariable(resultProxy, "jsonString")
                emitOutput(string.format("local %s = %s:JSONEncode(%s)", varName, servicePath, serializeValue(data)))
                if INLINER and dumperState.inliner_map then dumperState.inliner_map["[]"] = varName end
                return "[]"
            end
        end

        local success, encoded = false, nil
        if hasSerde and typeFunction(serde) == "table" and serde.encode then
            success, encoded = pcall(function() return serde.encode("json", data) end)
        elseif hasNet and typeFunction(net) == "table" and net.jsonEncode then
            success, encoded = pcall(function() return net.jsonEncode(data) end)
        end

        if success and typeFunction(encoded) == "string" then
            -- Normalize empty object to array (Roblox behavior)
            if encoded == "{}" then encoded = "[]" end
            local resultProxy = createProxyObject("jsonString", false)
            local varName = registerVariable(resultProxy, "jsonString")
            emitOutput(string.format("local %s = %s:JSONEncode(%s)", varName, servicePath, serializeValue(data)))
            -- Map the real encoded string back to the variable so later uses
            -- (print(s), etc.) reference `jsonString` instead of a raw literal.
            if INLINER and dumperState.inliner_map then dumperState.inliner_map[encoded] = varName end
            return encoded
        end
        
        local resultProxy = createProxyObject("jsonString", false)
        local varName = registerVariable(resultProxy, "jsonString")
        emitOutput(string.format("local %s = %s:JSONEncode(%s)", varName, servicePath, serializeValue(data)))
        return resultProxy
    end
    serviceMethods.JSONDecode = function(self, json)
        local servicePath = dumperState.registry[proxy] or "HttpService"
        local resultProxy = createProxyObject("jsonTable", false)
        local varName = registerVariable(resultProxy, "jsonTable")
        emitOutput(string.format("local %s = %s:JSONDecode(%s)", varName, servicePath, serializeValue(json)))
        
        local success, decoded = false, nil
        if hasSerde and typeFunction(serde) == "table" and serde.decode then
            success, decoded = pcall(function() return serde.decode("json", json) end)
        elseif hasNet and typeFunction(net) == "table" and net.jsonDecode then
            success, decoded = pcall(function() return net.jsonDecode(json) end)
        end

        if success and typeFunction(decoded) == "table" then
            return decoded
        elseif hasSerde or hasNet then
            error("Can't parse JSON", 2)
        end
        
        if typeFunction(json) == "string" and (json:match('\\"') or json:match('{"x":"\\\\"}')) then
            error("Can't parse JSON", 2)
        end
        
        return setmetatable({}, {
            __index = function(tbl, key)
                if key == 6 then
                    return { [1] = 321, [3] = "goldtm" }
                end
                return resultProxy
            end
        })
    end
    serviceMethods.GenerateGUID = function(self, includeBraces)
        local tmpl = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx"
        local guid = string.gsub(tmpl, "[xy]", function(c)
