            return string.format("%X", v)
        end)
        local servicePath = dumperState.registry[proxy] or "HttpService"
        emitOutput(string.format("%s:GenerateGUID(%s)", servicePath, serializeValue(includeBraces)))
        if includeBraces == false then return guid end
        return "{" .. guid .. "}"
    end
