        local wsMeta = getmetatable(wsProxy)
        local wsMethods = {}
        wsMethods.Send = function(_, msg)
            emitOutput(string.format("%s:Send(%s)", dumperState.registry[wsProxy] or "wsClient", serializeValue(msg)))
        end
        wsMethods.Close = function(_)
            emitOutput(string.format("%s:Close()", dumperState.registry[wsProxy] or "wsClient"))
        end
        wsMethods.Open = function(_)
            emitOutput(string.format("%s:Open()", dumperState.registry[wsProxy] or "wsClient"))
        end
        local origIndex = wsMeta.__index
        wsMeta.__index = function(t, k)
            if k == "Send" or k == "Close" or k == "Open" then return wsMethods[k] end
            if k == "MessageReceived" or k == "Closed" or k == "Opened" then
                local sig = createProxyObject(k, false, wsProxy)
                return sig
            end
            if typeFunction(origIndex) == "function" then return origIndex(t, k) end
            return nil
        end
        return wsProxy
    end
