    serviceMethods.CompressBuffer = function(self, bufferData, algo, level)
        local servicePath = dumperState.registry[proxy] or "EncodingService"
        local resultProxy = createProxyObject("compressedBuf", false)
        local varName = registerVariable(resultProxy, "compressedBuf")
        emitOutput(string.format("local %s = %s:CompressBuffer(%s, %s, %s)", varName, servicePath, serializeValue(bufferData), serializeValue(algo), serializeValue(level)))

        local str = (typeFunction(bufferData) == "buffer" and buffer) and buffer.tostring(bufferData) or tostring(bufferData or "")

        local algoName = "Zstd"
        if typeFunction(algo) == "table" then
            algoName = tostring(rawget(algo, "__value") or rawget(algo, "Name") or "Zstd")
        elseif algo then
            algoName = tostring(algo)
        end
        algoName = algoName:match("([^%.]+)$") or algoName

        local compressed = str
        local serdeOk = false

        if hasSerde and typeFunction(serde) == "table" and serde.compress then
            local effectiveLevel = level
            if effectiveLevel == nil and algoName:lower() == "zstd" then
                effectiveLevel = 3
            end
            local ok, result = pcall(function()
                if effectiveLevel ~= nil then
                    return serde.compress(algoName:lower(), str, effectiveLevel)
                end
                return serde.compress(algoName:lower(), str)
            end)
                        if ok and typeFunction(result) == "string" then
                compressed = result
                serdeOk = true
            end
        end

        if serdeOk and algoName:lower() == "zstd" and #compressed >= 6 and #str <= 255
            and compressed:byte(1) == 0x28 and compressed:byte(2) == 0xB5
            and compressed:byte(3) == 0x2F and compressed:byte(4) == 0xFD then
            local fhd = compressed:byte(5)
            local fcs_flag = math.floor(fhd / 0x40) % 4
            local single_seg = math.floor(fhd / 0x20) % 2
            local dict_flag = fhd % 4
            if single_seg == 0 and dict_flag == 0 then
                local hdr_len = 6 -- magic(4) + FHD(1) + WD(1)
                if fcs_flag == 1 then hdr_len = hdr_len + 2
                elseif fcs_flag == 2 then hdr_len = hdr_len + 4
                elseif fcs_flag == 3 then hdr_len = hdr_len + 8
                end
                if #compressed >= hdr_len then
                    compressed = string.char(0x28, 0xB5, 0x2F, 0xFD, 0x20, #str)
                              .. compressed:sub(hdr_len + 1)
                end
            end
        end

        if not serdeOk and algoName:lower() == "zstd" then
            local function zstd_raw_frame(s)
                local parts = {}
                parts[#parts+1] = string.char(0x28, 0xB5, 0x2F, 0xFD)
                local total = #s
                local fcs_flag, fcs_bytes
                if total < 256 then
                    fcs_flag = 0
                    fcs_bytes = string.char(total % 256)
                elseif total < 65536 + 256 then
                    fcs_flag = 1
                    local adj = total - 256
                    fcs_bytes = string.char(adj % 256, math.floor(adj / 256) % 256)
                else
                    fcs_flag = 2
                    fcs_bytes = string.char(
                        total % 256,
                        math.floor(total / 256) % 256,
                        math.floor(total / 65536) % 256,
                        math.floor(total / 16777216) % 256
                    )
                end
                local fhd = 0x20 + fcs_flag * 0x40
                parts[#parts+1] = string.char(fhd)
                parts[#parts+1] = fcs_bytes
                local pos = 1
                local block_max = 131072
                while pos <= total or total == 0 do
                    local remaining = total - pos + 1
                    local block_len = remaining
                    if block_len > block_max then block_len = block_max end
                    local is_last = (pos + block_len - 1 >= total) and 1 or 0
                    local bh = is_last + (0 * 2) + (block_len * 8)
                    parts[#parts+1] = string.char(
                        bh % 256,
                        math.floor(bh / 256) % 256,
                        math.floor(bh / 65536) % 256
                    )
                    if block_len > 0 then
                        parts[#parts+1] = s:sub(pos, pos + block_len - 1)
                    end
                    pos = pos + block_len
                    if total == 0 then break end
                end
                return table.concat(parts)
            end
            compressed = zstd_raw_frame(str)
        end

        if typeFunction(bufferData) == "buffer" and buffer then
            return buffer.fromstring(compressed)
        end
        return compressed
    end

    serviceMethods.DecompressBuffer = function(self, bufferData, algo)
        local servicePath = dumperState.registry[proxy] or "EncodingService"
        local resultProxy = createProxyObject("decompressedBuf", false)
        local varName = registerVariable(resultProxy, "decompressedBuf")
        emitOutput(string.format("local %s = %s:DecompressBuffer(%s, %s)", varName, servicePath, serializeValue(bufferData), serializeValue(algo)))

        local str = (typeFunction(bufferData) == "buffer" and buffer) and buffer.tostring(bufferData) or tostring(bufferData or "")

        local algoName = "Zstd"
        if typeFunction(algo) == "table" then
            algoName = tostring(rawget(algo, "__value") or rawget(algo, "Name") or "Zstd")
        elseif algo then
            algoName = tostring(algo)
        end
        algoName = algoName:match("([^%.]+)$") or algoName

        local payload = str
        local function zstd_raw_decode(s)
            if #s < 6 then return nil end
            if s:byte(1) ~= 0x28 or s:byte(2) ~= 0xB5 or s:byte(3) ~= 0x2F or s:byte(4) ~= 0xFD then
                return nil
            end
            local fhd = s:byte(5)
            local fcs_flag = math.floor(fhd / 0x40) % 4
            local single_seg = math.floor(fhd / 0x20) % 2
            local pos = 6
            local fcs = 0
            if fcs_flag == 0 and single_seg == 1 then
                fcs = s:byte(pos); pos = pos + 1
            elseif fcs_flag == 1 then
                fcs = s:byte(pos) + s:byte(pos+1) * 256 + 256; pos = pos + 2
            elseif fcs_flag == 2 then
                fcs = s:byte(pos) + s:byte(pos+1)*256 + s:byte(pos+2)*65536 + s:byte(pos+3)*16777216; pos = pos + 4
            elseif fcs_flag == 3 then
                pos = pos + 8
            end
            local out = {}
            while pos <= #s do
                if pos + 2 > #s then return nil end
                local b1, b2, b3 = s:byte(pos), s:byte(pos+1), s:byte(pos+2)
                local bh = b1 + b2 * 256 + b3 * 65536
                local is_last = bh % 2
                local btype = math.floor(bh / 2) % 4
                local bsize = math.floor(bh / 8)
                pos = pos + 3
                if btype == 0 then
                    out[#out+1] = s:sub(pos, pos + bsize - 1)
                    pos = pos + bsize
                else
                    return nil
                end
                if is_last == 1 then break end
            end
            return table.concat(out)
        end
        
        local serdeOk = false
        if hasSerde and typeFunction(serde) == "table" and serde.decompress then
            local ok, result = pcall(function()
                return serde.decompress(algoName:lower(), str)
            end)
            if ok and typeFunction(result) == "string" then
                payload = result
                serdeOk = true
            end
        end

        if not serdeOk and algoName:lower() == "zstd" then
            local decoded = zstd_raw_decode(str)
            if decoded then
                payload = decoded
            end
        end

        if typeFunction(bufferData) == "buffer" and buffer then
            return buffer.fromstring(payload)
        end
        return payload
    end

    serviceMethods.GetDecompressedBufferSize = function(self, bufferData, algo)
        local servicePath = dumperState.registry[proxy] or "EncodingService"
        emitOutput(string.format("%s:GetDecompressedBufferSize(%s, %s)", servicePath, serializeValue(bufferData), serializeValue(algo)))

        local str = (typeFunction(bufferData) == "buffer" and buffer) and buffer.tostring(bufferData) or tostring(bufferData or "")

        local algoName = "Zstd"
        if typeFunction(algo) == "table" then
            algoName = tostring(rawget(algo, "__value") or rawget(algo, "Name") or "Zstd")
        elseif algo then
            algoName = tostring(algo)
        end
        algoName = algoName:match("([^%.]+)$") or algoName

        if hasSerde and typeFunction(serde) == "table" and serde.decompress then
            local success, result = pcall(function() return serde.decompress(algoName:lower(), str) end)
            if success and typeFunction(result) == "string" then
                return #result
            end
        end
        
        return #str
    end

    serviceMethods.Base64Encode = function(self, data)
        local servicePath = dumperState.registry[proxy] or "EncodingService"
        emitOutput(string.format("%s:Base64Encode(%s)", servicePath, serializeValue(data)))

        local str = (typeFunction(data) == "buffer" and buffer) and buffer.tostring(data) or tostring(data or "")
        local enc
        
        local success = false
        if hasSerde and typeFunction(serde) == "table" and serde.encode then
            success, enc = pcall(function() return serde.encode("base64", str) end)
        end
        
        -- Pure Lua Fallback (If serde fails)
        if not success or typeFunction(enc) ~= "string" then
            local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local out = {}
            local n = #str
            local i = 1
            while i <= n do
                local b1 = str:byte(i) or 0
                local b2 = str:byte(i + 1)
                local b3 = str:byte(i + 2)
                local c1 = bit32.rshift(b1, 2)
                local c2 = bit32.bor(bit32.lshift(bit32.band(b1, 3), 4), bit32.rshift(b2 or 0, 4))
                local c3 = bit32.bor(bit32.lshift(bit32.band(b2 or 0, 15), 2), bit32.rshift(b3 or 0, 6))
                local c4 = bit32.band(b3 or 0, 63)
                out[#out + 1] = alphabet:sub(c1 + 1, c1 + 1)
                out[#out + 1] = alphabet:sub(c2 + 1, c2 + 1)
                out[#out + 1] = b2 and alphabet:sub(c3 + 1, c3 + 1) or "="
                out[#out + 1] = b3 and alphabet:sub(c4 + 1, c4 + 1) or "="
                i = i + 3
            end
            enc = table.concat(out)
        end

        if typeFunction(data) == "buffer" and buffer then
            return buffer.fromstring(enc)
        end
        return enc
    end

    serviceMethods.Base64Decode = function(self, data)
        local servicePath = dumperState.registry[proxy] or "EncodingService"
        emitOutput(string.format("%s:Base64Decode(%s)", servicePath, serializeValue(data)))

        local str = (typeFunction(data) == "buffer" and buffer) and buffer.tostring(data) or tostring(data or "")
        local dec
        
        local success = false
        if hasSerde and typeFunction(serde) == "table" and serde.decode then
            success, dec = pcall(function() return serde.decode("base64", str) end)
        end
        
        -- Pure Lua Fallback
        if not success or typeFunction(dec) ~= "string" then
            local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
            local lookup = {}
            for i = 1, #alphabet do lookup[alphabet:sub(i, i)] = i - 1 end
            str = str:gsub("[^A-Za-z0-9+/]", "")
            local out = {}
            local i = 1
            local n = #str
            while i <= n do
                local c1 = lookup[str:sub(i, i)] or 0
                local c2 = lookup[str:sub(i + 1, i + 1)] or 0
                local c3 = lookup[str:sub(i + 2, i + 2)]
                local c4 = lookup[str:sub(i + 3, i + 3)]
                out[#out + 1] = string.char(bit32.bor(bit32.lshift(c1, 2), bit32.rshift(c2, 4)))
                if c3 then out[#out + 1] = string.char(bit32.band(bit32.bor(bit32.lshift(c2, 4), bit32.rshift(c3, 2)), 0xFF)) end
                if c4 then out[#out + 1] = string.char(bit32.band(bit32.bor(bit32.lshift(c3, 6), c4), 0xFF)) end
                i = i + 4
            end
            dec = table.concat(out)
        end

        if typeFunction(data) == "buffer" and buffer then
            return buffer.fromstring(dec)
        end
        return dec
    end
