    serviceMethods.PreloadAsync = function(self, contentTable)
        emitOutput(string.format("%s:PreloadAsync(%s)", dumperState.registry[proxy] or "ContentProvider", serializeValue(contentTable)))
        if contentTable == nil then
            error("invalid argument #1 to 'PreloadAsync' (table expected, got nil)", 2)
        end
        local t = typeFunction(contentTable)
        if t ~= "table" then
            error("invalid argument #1 to 'PreloadAsync' (table expected, got " .. t .. ")", 2)
        end
        -- Detect circular/self-referencing tables
        local seen = {}
        local function checkTable(tbl, depth)
            if depth > 32 then error("invalid argument #1 to 'PreloadAsync' (table is circular)", 2) end
            if seen[tbl] then error("invalid argument #1 to 'PreloadAsync' (table is circular)", 2) end
            seen[tbl] = true
            for k, v in pairsFunction(tbl) do
                local vt = typeFunction(v)
                if vt == "number" then
                    error("invalid argument #1 to 'PreloadAsync' (table contains invalid value: number)", 2)
                end
                if vt == "table" and not isProxy(v) then
                    checkTable(v, depth + 1)
                end
            end
        end
        checkTable(contentTable, 0)
    end
