    -- [PATCH:PHYSICS-GROUPS] PhysicsService keeps a real registry of collision groups
    do
        local function _cg()
            local g = dumperState.coll_groups
            if not g then g = {names = {"Default"}, ids = {Default = 0}, nonCollide = {}}; dumperState.coll_groups = g end
            return g
        end
        local function _nm(v, fn, idx)
            if v == nil then error("Argument " .. idx .. " missing or nil", 3) end
            if typeFunction(v) ~= "string" then error("invalid argument #" .. idx .. " to '" .. fn .. "' (string expected, got " .. robloxApi.argTn(v) .. ")", 3) end
            return v
        end
        serviceMethods.IsCollisionGroupRegistered = function(self, groupName)
            _nm(groupName, "IsCollisionGroupRegistered", 1)
            return _cg().ids[groupName] ~= nil
        end
        local function _register(self, name)
            local g = _cg()
            _nm(name, "RegisterCollisionGroup", 1)
            if g.ids[name] ~= nil then error("Failed to create collision group: '" .. name .. "' already exists", 2) end
            g.names[#g.names + 1] = name
            g.ids[name] = #g.names - 1
        end
        serviceMethods.RegisterCollisionGroup = _register
        serviceMethods.CreateCollisionGroup = _register
        serviceMethods.GetRegisteredCollisionGroups = function(self)
            local g, out = _cg(), {}
            for i, n in ipairsFunction(g.names) do out[i] = {name = n, id = i - 1, mask = 4294967295} end
            return out
        end
        serviceMethods.GetCollisionGroups = serviceMethods.GetRegisteredCollisionGroups
        serviceMethods.GetMaxCollisionGroups = function(self) return 32 end
        serviceMethods.GetCollisionGroupId = function(self, name)
            local id = _cg().ids[_nm(name, "GetCollisionGroupId", 1)]
            if id == nil then error("Collision group '" .. name .. "' is not a valid collision group name", 2) end
            return id
        end
        serviceMethods.GetCollisionGroupName = function(self, id)
            if typeFunction(id) ~= "number" then error("invalid argument #1 to 'GetCollisionGroupName' (number expected, got " .. robloxApi.argTn(id) .. ")", 2) end
            local n = _cg().names[id + 1]
            if n == nil then error("Collision group id " .. tostring(id) .. " is not valid", 2) end
            return n
        end
        serviceMethods.CollisionGroupSetCollidable = function(self, a, b, collidable)
            local g = _cg()
            _nm(a, "CollisionGroupSetCollidable", 1); _nm(b, "CollisionGroupSetCollidable", 2)
            if g.ids[a] == nil then error("Collision group '" .. a .. "' is not a valid collision group name", 2) end
            if g.ids[b] == nil then error("Collision group '" .. b .. "' is not a valid collision group name", 2) end
            if typeFunction(collidable) ~= "boolean" then error("invalid argument #3 to 'CollisionGroupSetCollidable' (boolean expected, got " .. robloxApi.argTn(collidable) .. ")", 2) end
            g.nonCollide[a .. "\0" .. b] = (not collidable) or nil
            g.nonCollide[b .. "\0" .. a] = (not collidable) or nil
        end
        serviceMethods.CollisionGroupsAreCollidable = function(self, a, b)
            local g = _cg()
            _nm(a, "CollisionGroupsAreCollidable", 1); _nm(b, "CollisionGroupsAreCollidable", 2)
            if g.ids[a] == nil then error("Collision group '" .. a .. "' is not a valid collision group name", 2) end
            if g.ids[b] == nil then error("Collision group '" .. b .. "' is not a valid collision group name", 2) end
            return g.nonCollide[a .. "\0" .. b] == nil
        end
        serviceMethods.CollisionGroupContainsPart = function(self, name, part)
            _nm(name, "CollisionGroupContainsPart", 1)
            if _cg().ids[name] == nil then error("Collision group '" .. name .. "' is not a valid collision group name", 2) end
            if robloxApi.opTn(part) ~= "Instance" then error("Unable to cast value to Object", 2) end
            local ok, cg = pcallFunction(function() return part.CollisionGroup end)
            return ok and (cg or "Default") == name
        end
        serviceMethods.SetPartCollisionGroup = function(self, part, name)
            _nm(name, "SetPartCollisionGroup", 2)
            if _cg().ids[name] == nil then error("Collision group '" .. name .. "' is not a valid collision group name", 2) end
            if robloxApi.opTn(part) ~= "Instance" then error("Unable to cast value to Object", 2) end
            part.CollisionGroup = name
        end
    end
