    serviceMethods.AddItem = function(self, item, delayTime)
        -- [PATCH:DEBRIS] arg validation; the item is destroyed once its lifetime elapses on the virtual clock
        if item == nil then error("Argument 1 missing or nil", 2) end
        if not (typeFunction(item) == "table" and isProxy(item) and dumperState.property_store[item] and typeFunction(dumperState.property_store[item].ClassName) == "string") then
            error("Unable to cast value to Object", 2)
        end
        if delayTime ~= nil and typeFunction(delayTime) ~= "number" then
            error("invalid argument #2 to 'AddItem' (number expected, got " .. typeFunction(delayTime) .. ")", 2)
        end
        local servicePath = dumperState.registry[proxy] or "Debris"
        emitOutput(string.format("%s:AddItem(%s, %s)", servicePath, serializeValue(item), serializeValue(delayTime or 10)))
        local _tk = rawget(_G, "task")
        if _tk and _tk.delay and rawget(item, "__created_instance") then
            local _od = dumperState.output
            _tk.delay(math.max(delayTime or 10, 0), function()
                pcallFunction(function() item:Destroy() end)
            end)
        end
    end
    -- [PATCH:INSTANCE-API] Instance method fidelity: attributes (validation, events, one store),
    -- GetAttributeChangedSignal, Destroy (events + connection teardown + tag cleanup).
    do
        local _ATTR_OK = {number = true, string = true, boolean = true}
        local _ATTR_DT = {UDim = true, UDim2 = true, BrickColor = true, Color3 = true, Vector2 = true, Vector3 = true,
            NumberSequence = true, ColorSequence = true, NumberRange = true, Rect = true, Font = true, CFrame = true}
        local function _attrStore(create)
            dumperState.attributes = dumperState.attributes or setmetatable({}, {__mode = "k"})
            local t = dumperState.attributes[proxy]
            if not t and create then t = {}; dumperState.attributes[proxy] = t end
            if t then
                local ps = dumperState.property_store[proxy]
                if ps then ps._attrs = t end
            end
            return t
        end
        serviceMethods.SetAttribute = function(self, name, val)
            if typeFunction(name) ~= "string" then
                error("invalid argument #1 to 'SetAttribute' (string expected, got " .. (name == nil and "no value" or typeof(name)) .. ")", 2)
            end
            if name == "" then error("Attribute name cannot be empty", 2) end
            if #name > 100 then error("Attribute name too long, the maximum length is 100 characters", 2) end
            if name:sub(1, 3) == "RBX" then error("Attribute name cannot start with 'RBX', those are reserved for Roblox", 2) end
            if name:find("[^%w_]") then error("Attribute name can only contain alphanumeric characters or underscore", 2) end
            if val ~= nil then
                local vt = typeof(val)
                if not (_ATTR_OK[vt] or _ATTR_DT[vt]) then
                    error("Unable to set attribute '" .. name .. "': a value of type " .. vt .. " is not supported", 2)
                end
            end
            local p = dumperState.registry[proxy] or "player"
            emitOutput(string.format("%s:SetAttribute(%s, %s)", p, serializeValue(name), serializeValue(val)))
            local t = _attrStore(true)
            local old = t[name]
            t[name] = val
            if old ~= val then
                robloxApi.fireSig(proxy, "A:" .. name)
                robloxApi.fireSig(proxy, "AttributeChanged", name)
            end
        end
        serviceMethods.GetAttribute = function(self, name)
            if name == nil then error("Argument 1 missing or nil", 2) end
            if typeFunction(name) ~= "string" then
                error("invalid argument #1 to 'GetAttribute' (string expected, got " .. typeof(name) .. ")", 2)
            end
            local t = _attrStore(false)
            return t and t[name]
        end
        serviceMethods.GetAttributes = function(self)
            local out = {}
            local t = _attrStore(false)
            if t then for k, v in next, t do out[k] = v end end
            return out
        end
        serviceMethods.GetAttributeChangedSignal = function(self, name)
            if name == nil then error("Argument 1 missing or nil", 2) end
            if typeFunction(name) ~= "string" then
                error("invalid argument #1 to 'GetAttributeChangedSignal' (string expected, got " .. typeof(name) .. ")", 2)
            end
            dumperState.sig_cache = dumperState.sig_cache or setmetatable({}, {__mode = "k"})
            local _sc = dumperState.sig_cache[proxy]
            if not _sc then _sc = {}; dumperState.sig_cache[proxy] = _sc end
            if _sc["A:" .. name] then return _sc["A:" .. name] end
            local sigPath = (dumperState.registry[proxy] or "object") .. ":GetAttributeChangedSignal(" .. serializeValue(name) .. ")"
            local sigProxy = createProxyObject("AttributeChangedSignal", false, proxy)
            rawset(sigProxy, "__is_signal", true)
            dumperState.registry[sigProxy] = sigPath
            rawset(sigProxy, "__sig_owner", proxy)
            rawset(sigProxy, "__sig_name", name)
            rawset(sigProxy, "__sig_key", robloxApi.sigKey(proxy, "A:" .. name))
            _sc["A:" .. name] = sigProxy
            return sigProxy
        end
        local function _isAChain(cn, target)
            local c, g = cn, 0
            while c and g < 64 do
                if c == target then return true end
                c = robloxApi.super and robloxApi.super[c]
