                    if cur == proxy then
                        local instanceName = (dumperState.property_store[proxy] and dumperState.property_store[proxy].Name) or formattedName or "Instance"
                        local newParentName = (dumperState.property_store[val] and dumperState.property_store[val].Name) or dumperState.registry[val] or "Instance"
                        error("Attempt to set parent of " .. instanceName .. " to " .. newParentName .. " would result in circular reference", 2)
                    end
                    cur = dumperState.parent_map[cur]
                end
            end
        end

        if key == "X" or key == "Y" or key == "Z" or key == "R" or key == "G" or key == "B" then
            if pathName:match("Vector") or pathName:match("Color") or pathName:match("CFrame") then
                error(key .. " cannot be assigned to", 2)
            end
        end
        
        local classOnlyProps = {
            Size        = {Part=1,UnionOperation=1,MeshPart=1,SpecialMesh=1,Model=1,Attachment=1,SelectionBox=1,BoxHandleAdornment=1,Frame=1,TextLabel=1,TextButton=1,TextBox=1,ImageLabel=1,ImageButton=1,ScrollingFrame=1,ViewportFrame=1,VideoFrame=1,CanvasGroup=1},
            Position    = {Part=1,UnionOperation=1,MeshPart=1,Attachment=1,Model=1,Frame=1,TextLabel=1,TextButton=1,TextBox=1,ImageLabel=1,ImageButton=1,ScrollingFrame=1,ViewportFrame=1,VideoFrame=1,CanvasGroup=1},
            Orientation = {Part=1,UnionOperation=1,MeshPart=1,Attachment=1},
            Rotation    = {Part=1,UnionOperation=1,MeshPart=1,Model=1,Frame=1,UIGradient=1,TextLabel=1,TextButton=1,TextBox=1,ImageLabel=1,ImageButton=1,ScrollingFrame=1,ViewportFrame=1,VideoFrame=1,CanvasGroup=1},
            -- UI-only
            Text           = {TextLabel=1,TextButton=1,TextBox=1,Hint=1,Message=1,Dialog=1,DialogChoice=1},
            PlaceholderText= {TextBox=1},
            TextSize       = {TextLabel=1,TextButton=1,TextBox=1},
            TextColor3     = {TextLabel=1,TextButton=1,TextBox=1},
            TextTransparency={TextLabel=1,TextButton=1,TextBox=1},
            TextWrapped    = {TextLabel=1,TextButton=1,TextBox=1},
            TextScaled     = {TextLabel=1,TextButton=1,TextBox=1},
            RichText       = {TextLabel=1,TextButton=1,TextBox=1},
            Font           = {TextLabel=1,TextButton=1,TextBox=1},
            -- Sound-only
            SoundId   = {Sound=1},
            Volume    = {Sound=1},
            Looped    = {Sound=1},
            PlaybackSpeed={Sound=1},
            -- Lighting-only
            ClockTime = {Lighting=1},
            TimeOfDay = {Lighting=1},
            -- Image-only
            Image      = {ImageLabel=1,ImageButton=1,Decal=1,Texture=1,SpecialMesh=1},
            ImageColor3= {ImageLabel=1,ImageButton=1},
        }
        local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName
        if not className or className == "" then
            if pathName == "game" then
                className = "DataModel"
            elseif pathName == "workspace" or pathName == "Workspace" then
                className = "Workspace"
            elseif pathName and serviceNames[pathName:match("^game%.([%w_]+)$") or ""] then
                className = pathName:match("^game%.([%w_]+)$") or className
            end
        end

        if className and className ~= "" and classOnlyProps[key] then
            if not classOnlyProps[key][className] then
                error(key .. " is not a valid member of " .. className, 2)
            end
        end

        if key == "Rotation" then
            local t = typeFunction(val)
            local _props = dumperState.property_store[proxy]
            local _cn = _props and _props.ClassName
            local _guiClasses = {Frame=1,ScrollingFrame=1,TextLabel=1,TextButton=1,TextBox=1,ImageLabel=1,ImageButton=1,ViewportFrame=1,VideoFrame=1,CanvasGroup=1,GuiObject=1,UIGradient=1}
            if _cn and _guiClasses[_cn] then
                if t ~= "number" then
                    error("invalid argument #3 (number expected, got " .. t .. ")", 2)
                end
            else
                local isVec = false
                if t == "userdata" then isVec = true end
                if t == "table" and dumperState.registry[val] and (dumperState.registry[val]:match("Vector3") or dumperState.registry[val]:match("Vector2")) then isVec = true end
                if not isVec then
                    error("invalid argument #3 (Vector3 expected, got " .. t .. ")", 2)
                end
            end
        elseif key == "Orientation" or key == "Position" or key == "Size" then
            local t = typeFunction(val)
            local isVecOrUdim = false
            if t == "userdata" then isVecOrUdim = true end
            if t == "table" and dumperState.registry[val] and (dumperState.registry[val]:match("Vector3") or dumperState.registry[val]:match("UDim2") or dumperState.registry[val]:match("Vector2") or dumperState.registry[val]:match("UDim")) then
                isVecOrUdim = true
            end
            if not isVecOrUdim then
                error("invalid argument #3 (Vector3 or UDim2 expected, got " .. t .. ")", 2)
            end
        end

        if key == "CFrame" then
            local t = typeFunction(val)
            if t ~= "userdata" and not (t == "table" and dumperState.registry[val] and dumperState.registry[val]:match("CFrame")) then
                error("invalid argument #3 (CFrame expected, got " .. t .. ")", 2)
            end
            local okP, pos = pcallFunction(function() return val.Position end)
            if okP and pos ~= nil then
                dumperState.property_store[proxy] = dumperState.property_store[proxy] or {}
                dumperState.property_store[proxy].Position = pos
            end
        end

        if key == "Color" then
            local className = dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName
            if className == "ParticleEmitter" or className == "Beam" or className == "Trail" then
                local t = typeFunction(val)
                if t ~= "userdata" and not (t == "table" and dumperState.registry[val] and dumperState.registry[val]:match("ColorSequence")) then
                    error("invalid argument #3 (ColorSequence expected, got " .. t .. ")", 2)
                end
            else
                local okR, r = pcallFunction(function() return val.R end)
                local okG, g = pcallFunction(function() return val.G end)
                local okB, b = pcallFunction(function() return val.B end)
                if okR and okG and okB and typeFunction(r) == "number" and typeFunction(g) == "number" and typeFunction(b) == "number" then
                    if r < 0 or r > 1 or g < 0 or g > 1 or b < 0 or b > 1 then
                        error("invalid argument #3 (Color3 value out of range)", 2)
                    end
                end
            end
        end

        -- [PATCH:PROP-CLAMP] BasePart.Size is clamped to [0.001, 2048] per axis; Humanoid.Health to [0, MaxHealth];
        -- BasePart.Color / BrickColor stay in sync (BrickColor = nearest palette colour of Color).
        do
            local _cps = dumperState.property_store[proxy]
            local _ccn = _cps and rawget(proxy, "__created_instance") and _cps.ClassName
            if typeFunction(_ccn) == "string" then
                if key == "Size" and robloxApi.isPartLikeClass(_ccn) and robloxApi.opTn(val) == "Vector3" then
                    val = Vector3.new(math.clamp(val.X, 0.001, 2048), math.clamp(val.Y, 0.001, 2048), math.clamp(val.Z, 0.001, 2048))
                elseif key == "Health" and _ccn == "Humanoid" and typeFunction(val) == "number" then
                    val = math.clamp(val, 0, tonumber(rawget(_cps, "MaxHealth")) or 100)
                elseif key == "BrickColor" and robloxApi.isPartLikeClass(_ccn) and robloxApi.opTn(val) == "BrickColor" then
                    local okc, c3 = pcallFunction(function() return val.Color end)
                    if okc and c3 ~= nil then rawset(_cps, "Color", c3) end
                elseif key == "Color" and robloxApi.isPartLikeClass(_ccn) and robloxApi.opTn(val) == "Color3" then
                    local okb, bc = pcallFunction(BrickColor.new, val)
                    if okb and bc ~= nil then rawset(_cps, "BrickColor", bc) end
                end
            end
        end
        if pathName:match("Camera") then
            if key == "CameraType" then
                local t = typeFunction(val)
                if t ~= "userdata" and not (t == "table" and dumperState.registry[val] and dumperState.registry[val]:match("Enum%.CameraType")) then
                    error("Unable to assign property CameraType.\nEnum.CameraType expected, got " .. t, 2)
                end
            elseif key == "FieldOfView" then
                if typeFunction(val) ~= "number" then
                    error("Unable to assign property FieldOfView. double expected", 2)
                end
                val = math.clamp(val, 1, 120) 
            end
        end

        if key == "CameraMinZoomDistance" or key == "CameraMaxZoomDistance" then
            if typeFunction(val) ~= "number" or val < 0 then
                error("Property " .. key .. " cannot be less than 0", 2)
            end
        end
        if key == "WaterWaveSpeed" and typeFunction(val) == "number" then
            val = math.clamp(val, 0, 100)
        end
        
        if key == "SelectedObject" and val ~= nil then
            if typeFunction(val) ~= "table" or not isProxy(val) or (dumperState.registry[val] and dumperState.registry[val]:match("Part")) then
                error("SelectedObject must be a GuiObject", 2)
            end
        end
        if serviceMethods[key] or key == "GetService" or key == "FindFirstChild" or key == "WaitForChild" then
            error(tostring(key) .. " cannot be assigned to", 2)
        end
        if key == "GameplayPaused" then
            error("Property GameplayPaused is not scriptable", 2)
        end

        local _strProps = {
            Texture=true, Image=true, SoundId=true, AnimationId=true,
            MeshId=true, TextureId=true, VideoId=true, Script=false,
            Text=true, PlaceholderText=true, TimeOfDay=true,
            Name=false, -- Name already checked above
        }
        if _strProps[key] == true then
            local t = typeFunction(val)
            if val == nil then
                error("invalid argument #3 (string expected, got nil)", 2)
            elseif isProxy(val) or t == "table" then
                error("invalid argument #3 (string expected, got Instance)", 2)
            elseif t ~= "string" then
                error("invalid argument #3 (string expected, got " .. t .. ")", 2)
            end
        end

        local prop = formatValue(key)

        dumperState.property_store[proxy] = dumperState.property_store[proxy] or {}

        local oldVal = dumperState.property_store[proxy][key]
        -- Enum coercion: assigning a string to a property that held an enum proxy coerces
        -- to the same enum type (e.g. Part.Shape = "Cylinder" → Enum.PartType.Cylinder).
        if type(val) == "string" and isProxy(oldVal) then
            local reg = dumperState.registry[oldVal]
            if reg and reg:match("^Enum%.") then
                local enumBase = reg:match("^(Enum%.[^%.]+)%.")
                if enumBase then
                    local newPath = enumBase .. "." .. val
                    dumperState.enum_cache = dumperState.enum_cache or {}
                    if not dumperState.enum_cache[newPath] then
                        local ep = createProxyObject(newPath, false)
                        dumperState.registry[ep] = newPath
                        dumperState.enum_cache[newPath] = ep
                    end
                    val = dumperState.enum_cache[newPath]
                end
            end
        end
        -- [v1.6] float properties are stored as 32-bit floats (the dump below still prints the script's own literal)
        local _stv = val
        if typeFunction(val) == "number" and typeFunction(key) == "string" and key:byte(1) ~= 95 then
            local _fps = dumperState.property_store[proxy]
            local _fcn = _fps and _fps.ClassName
            if typeFunction(_fcn) ~= "string" then
                local _okc, _cc = pcallFunction(robloxApi.foreignGuardClass, proxy, formattedName, pathName)
                _fcn = _okc and _cc or nil
            end
            if typeFunction(_fcn) == "string" and robloxApi.isF32(_fcn, key) then _stv = robloxApi.f32round(val) end
        end
        dumperState.property_store[proxy][key] = _stv

        -- [PATCH:PART-SYNC] Position / Orientation / Rotation / CFrame are views of ONE
        -- transform on a real BasePart (and Attachment). The emulator stored them as
        -- independent values, so `part.Position = v` left `part.CFrame` stale and
        -- `part.Orientation` never followed the CFrame. Keep the CFrame authoritative.
        do
            local _sps = dumperState.property_store[proxy]
            local _scn = _sps and _sps.ClassName
            if _scn and (key == "Position" or key == "CFrame" or key == "Orientation" or key == "Rotation")
                and robloxApi.classHasMember(_scn, "Orientation") and robloxApi.classHasMember(_scn, "CFrame")
                and typeFunction(val) == "table" then
                local _cfl = robloxApi.cf
                local function _curCF()
                    local c = rawget(_sps, "CFrame")
                    if _cfl.isCF(c) then return c end
                    local pp = rawget(_sps, "Position")
                    if typeFunction(pp) == "table" and _cfl.isV3(pp) then
                        local x, y, z = _cfl.vec(pp)
                        return CFrame.new(x, y, z)
                    end
                    return CFrame.new(0, 0, 0)
                end
                if key == "CFrame" then
                    _sps.Orientation = nil; _sps.Rotation = nil
                elseif key == "Position" and _cfl.isV3(val) then
                    local _, _, _, R = _cfl.parts(_curCF())
                    local x, y, z = _cfl.vec(val)
                    rawset(_sps, "CFrame", _cfl.make(x, y, z, R))
                elseif (key == "Orientation" or key == "Rotation") and _cfl.isV3(val) then
                    local ox, oy, oz = _cfl.vec(val)
                    local px, py, pz = _cfl.parts(_curCF())
                    local ori = CFrame.fromOrientation(math.rad(ox), math.rad(oy), math.rad(oz))
                    local _, _, _, R = _cfl.parts(ori)
                    rawset(_sps, "CFrame", _cfl.make(px, py, pz, R))
                    _sps.Orientation = val; _sps.Rotation = val
                end
            end
        end

        if key == "Position" or key == "CFrame" then
            dumperState.property_store[proxy]._physPositionT0 = get_virtual_clock()
        end

        -- [PATCH] Explicitly assigning an assembly velocity restarts the physics
        -- clock so it decays under gravity from the assignment time (dtc15).
        if key == "AssemblyLinearVelocity" or key == "Velocity" then
            dumperState.property_store[proxy]._physVelT0 = get_virtual_clock()
        elseif key == "AssemblyAngularVelocity" or key == "RotVelocity" then
            dumperState.property_store[proxy]._physAngT0 = get_virtual_clock()
        end

        if key == "Jump" and val == true then
            local _humPs = dumperState.property_store[proxy]
            if _humPs and _humPs.ClassName == "Humanoid" then
                local _char = dumperState.parent_map[proxy]
                if _char then
                    dumperState.hrp_cache = dumperState.hrp_cache or {}
                    local _hrp = dumperState.hrp_cache[_char]
                    if _hrp then
                        local _hrpPs = dumperState.property_store[_hrp] or {}
                        dumperState.property_store[_hrp] = _hrpPs
                        local _cur = _hrpPs.Position or Vector3.new(0, 5, 0)
                        local _jh = (_humPs and _humPs.JumpHeight) or 7.2
                        local _gravity = 196.2
                        local _vy0 = math.sqrt(2 * _gravity * _jh)
                        local _newPos = Vector3.new(_cur.X, _cur.Y + _jh, _cur.Z)
                        _hrpPs.Position = _newPos
                        _hrpPs.CFrame = CFrame.new(_newPos.X, _newPos.Y, _newPos.Z)
                        dumperState.jump_physics = {hrp = _hrp, humanoid = proxy, vy = _vy0, gravity = _gravity, active = true, base_y = _cur.Y}
                        local _hPs = dumperState.property_store[proxy] or {}
                        dumperState.property_store[proxy] = _hPs
                        _hPs._currentState = "Jumping"
                    end
                end
            end
        end

        if key == "Parent" then
            local oldParent = dumperState.parent_map[proxy]
            if isProxy(val) then
                dumperState.parent_map[proxy] = val
            elseif val == nil then
                dumperState.parent_map[proxy] = nil
            end
            if oldParent ~= dumperState.parent_map[proxy] then
                robloxApi.hierEvents(proxy, oldParent, dumperState.parent_map[proxy])
            end
            if dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName == "Actor" then
                if dumperState.parent_map[proxy] then
                    local state = dumperState.lua_states and dumperState.lua_states[proxy] or nil
                    if state then dumperState.actor_states[proxy] = state end
                elseif dumperState.actor_states then dumperState.actor_states[proxy] = nil end
            end
        end
        emitOutput(string.format("%s.%s = %s", pathName, prop, serializeValue(val)))

        if oldVal ~= _stv then
            -- [PATCH:SIGNALS] keyed dispatch (PropertyChangedSignal first, like the engine)
            robloxApi.fireSig(proxy, "P:" .. prop)
            -- [PATCH:VALUEBASE-CHANGED] ValueBase.Changed passes the NEW VALUE (not the property name) and fires for Value only
            local _vbps = rawget(proxy, "__created_instance") and dumperState.property_store[proxy]
            if _vbps and typeFunction(_vbps.ClassName) == "string" and _vbps.ClassName:find("Value$") then
                if prop == "Value" then robloxApi.fireSig(proxy, "Changed", val) end
            else
                robloxApi.fireSig(proxy, "Changed", key)
            end
            local changedSignal = pathName .. ".Changed"
            local propSignal = pathName .. ":GetPropertyChangedSignal(\"" .. prop .. "\")"
            if not rawget(proxy, "__created_instance") then
                if dumperState.event_callbacks and dumperState.event_callbacks[changedSignal] then
                    for _, cb in ipairsFunction(dumperState.event_callbacks[changedSignal]) do
                        xpcallFunction(function() cb(key) end, function() end)
                    end
                end
                if dumperState.event_callbacks and dumperState.event_callbacks[propSignal] then
                    for _, cb in ipairsFunction(dumperState.event_callbacks[propSignal]) do
                        xpcallFunction(function() cb() end, function() end)
                    end
                end
            end
        end
    end
    meta.__call = function(tbl, ...)
        local pathName = dumperState.registry[proxy] or formattedName or "func"
        if pathName == "game" or pathName == "workspace" or pathName == "script" then
            error("attempt to call a Instance value", 2)
        end

        -- Throw for Instance objects (created via Instance.new) or Enum/EnumItem/NumberRange
        if rawget(proxy, "__created_instance") then
            error("attempt to call a Instance value", 2)
        end
        if rawget(proxy, "__is_signal") then
            error("attempt to call a RBXScriptSignal value", 2)
        end
        if pathName and pathName:match("^Enum%.[%w_]+%.[%w_]+$") then
            error("attempt to call a EnumItem value", 2)
        end
        if pathName and (pathName:match("^Enum%.") or pathName:match("^Enum$")) then
            error("attempt to call a Enum value", 2)
        end
        if pathName and pathName:match("^NumberRange") then
            error("attempt to call a NumberRange value", 2)
        end
        -- Check if this is an instance registered under a service path (game./workspace. prefix)
        if pathName and (pathName:match("^game[%.:]") or pathName:match("^workspace[%.:]") or pathName:match("^script[%.:]")) then
            -- Only throw if it's definitely not a method-like path
            if not rawget(proxy, "__is_method") and not rawget(proxy, "__is_signal") then
                error("attempt to call a Instance value", 2)
            end
        end

        if pathName == "fenv" or pathName == "getgenv" or pathName:match("env") then
            return proxy
        end
        local args = {...}
        local serializedArgs = {}
        for _, val in ipairsFunction(args) do
            table.insert(serializedArgs, serializeValue(val))
        end
        local resultProxy = createProxyObject("result", false)
        local varName = registerVariable(resultProxy, "result")
        emitOutput(string.format("local %s = %s(%s)", varName, pathName, table.concat(serializedArgs, ", ")))
        return resultProxy
    end
    local function operatorMeta(opSymbol)
        local function metaCall(a, b)
            local proxy, meta = createProxy()
            local strA = "0"
            if a ~= nil then strA = dumperState.registry[a] or serializeValue(a) end
            local strB = "0"
            if b ~= nil then strB = dumperState.registry[b] or serializeValue(b) end
            local expression = "(" .. strA .. " " .. opSymbol .. " " .. strB .. ")"
            dumperState.registry[proxy] = expression
            meta.__tostring = function() return expression end
            meta.__call = function() return proxy end
            meta.__index = function(_, k)
                if k == proxyList or k == "__proxy_id" then return rawget(proxy, k) end
                return createProxyObject(expression .. "." .. formatValue(k), false)
            end
            meta.__add = operatorMeta("+")
            meta.__sub = operatorMeta("-")
            meta.__mul = operatorMeta("*")
            meta.__div = operatorMeta("/")
            meta.__mod = operatorMeta("%")
            meta.__pow = operatorMeta("^")
            meta.__concat = operatorMeta("..")
            meta.__eq = function() return false end
            meta.__lt = function() return false end
            meta.__le = function() return false end
            return proxy
        end
        return metaCall
    end
    -- [PATCH:DT-OPS] Luau's message names BOTH operand types and the operation:
    -- "attempt to perform arithmetic (add) on Instance and number".
    local function _mkInstMath(opname)
        return function(a, b)
            local function tn(v) local okT, r = pcall(_G.typeof, v); return okT and r or typeFunction(v) end
            error("attempt to perform arithmetic (" .. opname .. ") on " .. tn(a) .. " and " .. tn(b), 2)
        end
    end
    local function instanceConcatError(a, b)
        local function tn(v) local okT, r = pcall(_G.typeof, v); return okT and r or typeFunction(v) end
        error("attempt to concatenate " .. tn(a) .. " and " .. tn(b), 2)
    end
    meta.__add = _mkInstMath("add")
    meta.__sub = _mkInstMath("sub")
    meta.__mul = _mkInstMath("mul")
    meta.__div = _mkInstMath("div")
    meta.__mod = _mkInstMath("mod")
    meta.__pow = _mkInstMath("pow")
    meta.__concat = instanceConcatError
    meta.__eq = shared_proxy_eq

    -- Shared closures (see shared_proxy_lt/le): required so Luau actually
    -- dispatches the metamethod when comparing two distinct instances.
    meta.__lt = shared_proxy_lt
    meta.__le = shared_proxy_le
    meta.__unm = function(a)
        error("attempt to perform arithmetic (unm) on " .. robloxApi.opTn(a), 2)
    end
    meta.__len = function(a)
        error("attempt to get length of a " .. robloxApi.opTn(a) .. " value", 2)
    end
    meta.__tostring = function() 
        if proxy == game then return "Ugc" end
        if proxy == workspace then return "Workspace" end

        local regName = dumperState.registry[proxy]
        if type(regName) == "string" and rawget(proxy, "__roblox_type") == nil then
            local _etn = regName:match("^Enum%.([%w_]+)$")
            if _etn then return _etn end -- [v1.6] tostring(Enum.KeyCode) == "KeyCode"
        end
        if regName and regName:match("^game%.([%w_]+)$") then
            local sName = regName:match("^game%.([%w_]+)$")
            local spacedServices = {RunService = "Run Service", SoundService = "Sound Service", ContextActionService = "ContextAction Service", TestService = "Test Service"}
            return spacedServices[sName] or sName
        end

        if formattedName == "Character" then return "workspace" end
        if dumperState.property_store[proxy] and dumperState.property_store[proxy].Name ~= nil then
            return tostring(dumperState.property_store[proxy].Name)
        end
        -- [PATCH] tostring(instance) is the Name only, never a dotted full path
        -- (dtc96). Enum proxies (Enum.X.Y) keep their dotted identity.
        if type(regName) == "string" and not regName:match("^Enum")
            and (rawget(proxy, "__created_instance")
                 or (dumperState.property_store[proxy] and dumperState.property_store[proxy].ClassName)
                 or regName:match("[%.:]")) then
            return regName:match("([^%.:]+)$") or formattedName or "Object"
        end
        return regName or formattedName or "Object"
    end
    meta.__pairs = function()
        local children = {}
        for obj, p in pairsFunction(dumperState.parent_map) do
            if p == proxy then table.insert(children, obj) end
        end
        local i = 0
        return function()
            i = i + 1
            return children[i]
        end, proxy, nil
    end
    meta.__ipairs = function()
        local children = {}
        for obj, p in pairsFunction(dumperState.parent_map) do
            if p == proxy then table.insert(children, obj) end
        end
        local i = 0
        return function()
            i = i + 1
            if children[i] then return i, children[i] end
        end, proxy, nil
    end
    return proxy
end
-- [MANUAL] Valid member sets for the built-in Roblox datatypes. The Roblox API
-- dump only describes Instance classes/enums, not datatypes, so these are hand
-- written from the datatype reference. Reading a member outside this set raises
-- on a real client; the emulator used to return 0 (leaking), which the
-- dt-badmember detections fingerprint (dtc12..37). Datatypes absent from this
-- table stay permissive so they are never falsely rejected.
local _datatypeMembers = {
    Vector3 = {X=1,Y=1,Z=1,Magnitude=1,Unit=1,Cross=1,Dot=1,Lerp=1,Max=1,Min=1,FuzzyEq=1,Angle=1,Abs=1,Ceil=1,Floor=1,Sign=1,x=1,y=1,z=1,magnitude=1,unit=1},
    Vector2 = {X=1,Y=1,Magnitude=1,Unit=1,Cross=1,Dot=1,Lerp=1,Max=1,Min=1,FuzzyEq=1,Angle=1,Abs=1,Ceil=1,Floor=1,Sign=1,x=1,y=1,magnitude=1,unit=1},
    Vector3int16 = {X=1,Y=1,Z=1,Magnitude=1,Unit=1},
    Vector2int16 = {X=1,Y=1,Magnitude=1,Unit=1},
    CFrame = {X=1,Y=1,Z=1,Position=1,p=1,Rotation=1,LookVector=1,RightVector=1,UpVector=1,XVector=1,YVector=1,ZVector=1,Inverse=1,Lerp=1,ToWorldSpace=1,ToObjectSpace=1,PointToWorldSpace=1,PointToObjectSpace=1,VectorToWorldSpace=1,VectorToObjectSpace=1,GetComponents=1,components=1,ToEulerAnglesXYZ=1,ToEulerAnglesYXZ=1,ToEulerAngles=1,ToOrientation=1,ToAxisAngle=1,FuzzyEq=1,AngleBetween=1,Orthonormalize=1,GetPosition=1,mul=1,Mul=1},
    Color3 = {R=1,G=1,B=1,Lerp=1,ToHSV=1,ToHex=1,r=1,g=1,b=1},
    UDim = {Scale=1,Offset=1},
    UDim2 = {X=1,Y=1,Width=1,Height=1,Lerp=1},
    Rect = {Min=1,Max=1,Width=1,Height=1},
    Region3 = {CFrame=1,Size=1,ExpandToGrid=1},
    Region3int16 = {Min=1,Max=1},
    Ray = {Origin=1,Direction=1,Unit=1,ClosestPoint=1,Distance=1},
    NumberRange = {Min=1,Max=1},
    NumberSequence = {Keypoints=1},
    ColorSequence = {Keypoints=1},
    NumberSequenceKeypoint = {Time=1,Value=1,Envelope=1},
    ColorSequenceKeypoint = {Time=1,Value=1},
    BrickColor = {Number=1,Name=1,Color=1,r=1,g=1,b=1,R=1,G=1,B=1},
    TweenInfo = {Time=1,EasingStyle=1,EasingDirection=1,RepeatCount=1,Reverses=1,DelayTime=1},
    PhysicalProperties = {Density=1,Friction=1,Elasticity=1,FrictionWeight=1,ElasticityWeight=1},
    Faces = {Top=1,Bottom=1,Left=1,Right=1,Back=1,Front=1},
    Axes = {X=1,Y=1,Z=1,Top=1,Bottom=1,Left=1,Right=1,Back=1,Front=1},
    PathWaypoint = {Position=1,Action=1,Label=1},
    DateTime = {UnixTimestamp=1,UnixTimestampMillis=1,ToUniversalTime=1,ToLocalTime=1,ToIsoDate=1,FormatUniversalTime=1,FormatLocalTime=1},
    Random = {NextInteger=1,NextNumber=1,NextUnitVector=1,NextGaussian=1,Clone=1,Shuffle=1},
    Font = {Family=1,Weight=1,Style=1,Bold=1},
    FloatCurveKey = {Time=1,Value=1,Interpolation=1,Envelope=1,LeftTangent=1,RightTangent=1},
    RotationCurveKey = {Time=1,Value=1,Interpolation=1,LeftTangent=1,RightTangent=1},
    ValueCurveKey = {Time=1,Value=1,Interpolation=1,Envelope=1},
}
-- Expose to the instance proxy __index (defined earlier in the file) so proxies
-- tagged as datatypes -- e.g. NumberRange, built via createProxyObject -- get the
-- same foreign-member rejection.
robloxApi._datatypeMembers = _datatypeMembers

-- [PATCH:DT-LEGACY] Legacy lowercase members that a real Roblox client still resolves on
-- value datatypes (Vector3.x/.unit/.magnitude, CFrame.p/.lookVector/:inverse(),
-- Color3.r ...). They are folded onto the canonical member BEFORE the allow-list and
-- handler cascade, so `v.x` and `v.X` return the same value (previously `v.x` raised
-- and Color3.r returned 0).
robloxApi._sigLegacy = {connect = "Connect", wait = "Wait"}
robloxApi._connLegacy = {connected = "Connected", disconnect = "Disconnect"}
robloxApi._dtLegacy = {
    Vector3 = {x="X", y="Y", z="Z", unit="Unit", magnitude="Magnitude", dot="Dot", cross="Cross", lerp="Lerp"},
    Vector2 = {x="X", y="Y", unit="Unit", magnitude="Magnitude"},
    CFrame = {x="X", y="Y", z="Z", lookVector="LookVector", rightVector="RightVector", upVector="UpVector",
              inverse="Inverse", lerp="Lerp", toWorldSpace="ToWorldSpace", toObjectSpace="ToObjectSpace",
              pointToWorldSpace="PointToWorldSpace", pointToObjectSpace="PointToObjectSpace",
              vectorToWorldSpace="VectorToWorldSpace", vectorToObjectSpace="VectorToObjectSpace",
              toEulerAnglesXYZ="ToEulerAnglesXYZ", toEulerAnglesYXZ="ToEulerAnglesYXZ"},
    Color3 = {r="R", g="G", b="B"},
}
-- Members the emulator used to accept on CFrame although a real CFrame has no such member.
_datatypeMembers.CFrame.GetPosition = nil
_datatypeMembers.CFrame.mul = nil
_datatypeMembers.CFrame.Mul = nil
-- Static members (Vector3.new, CFrame.Angles ...). Anything else is a hard error on a
-- real client ("Zero is not a valid member of Vector3"), previously the emulator
-- silently returned nil for e.g. Vector3.Zero / CFrame.Identity / Color3.fromrgb.
robloxApi._dtStatics = {
    Vector3 = {new=1, FromNormalId=1, FromAxis=1, fromNormalId=1, fromAxis=1, zero=1, one=1, xAxis=1, yAxis=1, zAxis=1},
    Vector2 = {new=1, zero=1, one=1, xAxis=1, yAxis=1},
    CFrame = {new=1, identity=1, lookAt=1, lookAlong=1, fromRotationBetweenVectors=1, fromEulerAngles=1,
              fromEulerAnglesXYZ=1, fromEulerAnglesYXZ=1, Angles=1, fromOrientation=1, fromAxisAngle=1, fromMatrix=1},
    Color3 = {new=1, fromRGB=1, fromHSV=1, fromHex=1},
    UDim = {new=1}, UDim2 = {new=1, fromScale=1, fromOffset=1}, Rect = {new=1}, Ray = {new=1},
    Region3 = {new=1}, Region3int16 = {new=1}, TweenInfo = {new=1}, NumberSequence = {new=1},
    NumberSequenceKeypoint = {new=1}, ColorSequence = {new=1}, ColorSequenceKeypoint = {new=1},
    PhysicalProperties = {new=1}, Font = {new=1, fromEnum=1, fromName=1, fromId=1},
    BrickColor = {new=1, palette=1, random=1, White=1, Gray=1, DarkGray=1, Black=1, Red=1, Yellow=1, Green=1, Blue=1},
}

-- [PATCH:CFRAME-MATH] Numeric CFrame algebra on the stored (__cf_pos, __cf_rot) pair.
-- The original code returned the *input* from VectorToWorldSpace/VectorToObjectSpace,
-- ignored rotation in PointToWorldSpace and `CFrame * Vector3`, built Inverse() as
-- "negated position, identity rotation", lerped only the translation and returned
-- unevaluated "(a + b)" expression proxies for `CFrame +/- Vector3`.
robloxApi.cf = {}
do
    local cf = robloxApi.cf
    local ID = {1,0,0, 0,1,0, 0,0,1}
    local _atan2 = math.atan2 or function(y, x) return math.atan(y, x) end
    local function clean(x)
        if x ~= x or x == math.huge or x == -math.huge then return x end
        if x == 0 or math.abs(x) < 1e-12 then return 0 end
        return x
    end
    function cf.tn(v)
        if typeFunction(v) == "table" then
            local rt = rawget(v, "__roblox_type"); if typeFunction(rt) == "string" then return rt end
        end
        return typeFunction(v)
    end
    function cf.isCF(v) return typeFunction(v) == "table" and rawget(v, "__roblox_type") == "CFrame" end
    function cf.isV3(v) return typeFunction(v) == "table" and rawget(v, "__roblox_type") == "Vector3" end
    function cf.parts(c)
        local cp = rawget(c, "__cf_pos")
        local R = rawget(c, "__cf_rot") or ID
        if typeFunction(cp) ~= "table" then
            local function g(k) local ok, r = pcall(function() return c[k] end); return (ok and typeFunction(r) == "number") and r or 0 end
            cp = {g("X"), g("Y"), g("Z")}
        end
        return cp[1] or 0, cp[2] or 0, cp[3] or 0, R
    end
    function cf.vec(v)
        local function g(k) local ok, r = pcall(function() return v[k] end); return (ok and typeFunction(r) == "number") and r or 0 end
        return g("X"), g("Y"), g("Z")
    end
    function cf.make(px, py, pz, R)
        px, py, pz = clean(px), clean(py), clean(pz)
        local ident = true
        local r = {}
        for i = 1, 9 do r[i] = clean(R[i]); if r[i] ~= ID[i] then ident = false end end
        if ident then return CFrame.new(px, py, pz) end
        return CFrame.new(px, py, pz, r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9])
    end
    function cf.mul3(a, b)
        local r = {}
        for i = 0, 2 do for j = 0, 2 do
            r[i*3+j+1] = a[i*3+1]*b[j+1] + a[i*3+2]*b[3+j+1] + a[i*3+3]*b[6+j+1]
        end end
        return r
    end
    function cf.mulv(R, x, y, z)
        return R[1]*x + R[2]*y + R[3]*z, R[4]*x + R[5]*y + R[6]*z, R[7]*x + R[8]*y + R[9]*z
    end
    function cf.tr(R) return {R[1],R[4],R[7], R[2],R[5],R[8], R[3],R[6],R[9]} end
    function cf.compose(a, b)
        local ax, ay, az, aR = cf.parts(a)
        local bx, by, bz, bR = cf.parts(b)
        local rx, ry, rz = cf.mulv(aR, bx, by, bz)
        return cf.make(ax + rx, ay + ry, az + rz, cf.mul3(aR, bR))
    end
    function cf.inverse(a)
        local ax, ay, az, aR = cf.parts(a)
        local T = cf.tr(aR)
        local x, y, z = cf.mulv(T, ax, ay, az)
        return cf.make(-x, -y, -z, T)
    end
    local function toQuat(R)
        local t = R[1] + R[5] + R[9]
        local x, y, z, w
        if t > 0 then
            local s = math.sqrt(t + 1) * 2
            w = 0.25 * s; x = (R[8]-R[6])/s; y = (R[3]-R[7])/s; z = (R[4]-R[2])/s
        elseif R[1] > R[5] and R[1] > R[9] then
            local s = math.sqrt(1 + R[1] - R[5] - R[9]) * 2
            w = (R[8]-R[6])/s; x = 0.25 * s; y = (R[2]+R[4])/s; z = (R[3]+R[7])/s
        elseif R[5] > R[9] then
            local s = math.sqrt(1 + R[5] - R[1] - R[9]) * 2
            w = (R[3]-R[7])/s; x = (R[2]+R[4])/s; y = 0.25 * s; z = (R[6]+R[8])/s
        else
            local s = math.sqrt(1 + R[9] - R[1] - R[5]) * 2
            w = (R[4]-R[2])/s; x = (R[3]+R[7])/s; y = (R[6]+R[8])/s; z = 0.25 * s
        end
        return x, y, z, w
    end
    local function fromQuat(x, y, z, w)
        local l = math.sqrt(x*x + y*y + z*z + w*w); if l == 0 then l = 1 end
        x, y, z, w = x/l, y/l, z/l, w/l
        return {1 - 2*(y*y + z*z), 2*(x*y - z*w), 2*(x*z + y*w),
                2*(x*y + z*w), 1 - 2*(x*x + z*z), 2*(y*z - x*w),
                2*(x*z - y*w), 2*(y*z + x*w), 1 - 2*(x*x + y*y)}
    end
    function cf.lerp(a, b, t)
        local ax, ay, az, aR = cf.parts(a)
        local bx, by, bz, bR = cf.parts(b)
        local px, py, pz = ax + (bx-ax)*t, ay + (by-ay)*t, az + (bz-az)*t
        local x1, y1, z1, w1 = toQuat(aR)
        local x2, y2, z2, w2 = toQuat(bR)
        local d = x1*x2 + y1*y2 + z1*z2 + w1*w2
        if d < 0 then x2, y2, z2, w2, d = -x2, -y2, -z2, -w2, -d end
        local qx, qy, qz, qw
        if d > 0.9995 then
            qx, qy, qz, qw = x1 + (x2-x1)*t, y1 + (y2-y1)*t, z1 + (z2-z1)*t, w1 + (w2-w1)*t
        else
            local th = math.acos(d)
            local s = math.sin(th)
            local k1, k2 = math.sin((1-t)*th)/s, math.sin(t*th)/s
            qx, qy, qz, qw = x1*k1 + x2*k2, y1*k1 + y2*k2, z1*k1 + z2*k2, w1*k1 + w2*k2
        end
        return cf.make(px, py, pz, fromQuat(qx, qy, qz, qw))
    end
    -- R = Rx(a) * Ry(b) * Rz(c)
    function cf.eulerXYZ(R)
        local sb = math.max(-1, math.min(1, R[3]))
        local b = math.asin(sb)
        if math.abs(R[3]) < 0.9999999 then
            return _atan2(-R[6], R[9]), b, _atan2(-R[2], R[1])
        end
        return _atan2(R[8], R[5]), b, 0
    end
    -- R = Ry(b) * Rx(a) * Rz(c); returns a, b, c (the ToOrientation order: x, y, z)
    function cf.eulerYXZ(R)
        local a = math.asin(math.max(-1, math.min(1, -R[6])))
        if math.abs(R[6]) < 0.9999999 then
            return a, _atan2(R[3], R[9]), _atan2(R[4], R[5])
        end
        return a, _atan2(-R[7], R[1]), 0
    end
    local function argCF(v, i, fname)
        if not cf.isCF(v) then
            error("invalid argument #" .. i .. " to '" .. fname .. "' (CFrame expected, got " .. (v == nil and "nil" or robloxApi.cf.tn(v)) .. ")", 3)
        end
    end
    local function argV3(v, i, fname)
        if not cf.isV3(v) then
            error("invalid argument #" .. i .. " to '" .. fname .. "' (Vector3 expected, got " .. (v == nil and "nil" or robloxApi.cf.tn(v)) .. ")", 3)
        end
    end
    cf.methods = {
        Inverse = function(self) return cf.inverse(self) end,
        ToWorldSpace = function(self, o) argCF(o, 1, "ToWorldSpace"); return cf.compose(self, o) end,
        ToObjectSpace = function(self, o) argCF(o, 1, "ToObjectSpace"); return cf.compose(cf.inverse(self), o) end,
        PointToWorldSpace = function(self, v)
            argV3(v, 1, "PointToWorldSpace")
            local px, py, pz, R = cf.parts(self); local x, y, z = cf.vec(v)
            local rx, ry, rz = cf.mulv(R, x, y, z)
            return Vector3.new(clean(px + rx), clean(py + ry), clean(pz + rz))
        end,
        PointToObjectSpace = function(self, v)
            argV3(v, 1, "PointToObjectSpace")
            local px, py, pz, R = cf.parts(self); local x, y, z = cf.vec(v)
            local rx, ry, rz = cf.mulv(cf.tr(R), x - px, y - py, z - pz)
            return Vector3.new(clean(rx), clean(ry), clean(rz))
        end,
        VectorToWorldSpace = function(self, v)
            argV3(v, 1, "VectorToWorldSpace")
            local _, _, _, R = cf.parts(self); local x, y, z = cf.vec(v)
            local rx, ry, rz = cf.mulv(R, x, y, z)
            return Vector3.new(clean(rx), clean(ry), clean(rz))
        end,
        VectorToObjectSpace = function(self, v)
            argV3(v, 1, "VectorToObjectSpace")
            local _, _, _, R = cf.parts(self); local x, y, z = cf.vec(v)
            local rx, ry, rz = cf.mulv(cf.tr(R), x, y, z)
            return Vector3.new(clean(rx), clean(ry), clean(rz))
        end,
        Lerp = function(self, o, t)
            argCF(o, 1, "Lerp")
            if typeFunction(t) ~= "number" then error("invalid argument #2 to 'Lerp' (number expected, got " .. (t == nil and "nil" or typeFunction(t)) .. ")", 2) end
            return cf.lerp(self, o, t)
        end,
        ToEulerAnglesXYZ = function(self) local _, _, _, R = cf.parts(self); local a, b, c = cf.eulerXYZ(R); return clean(a), clean(b), clean(c) end,
        ToEulerAngles = function(self) local _, _, _, R = cf.parts(self); local a, b, c = cf.eulerXYZ(R); return clean(a), clean(b), clean(c) end,
        ToEulerAnglesYXZ = function(self) local _, _, _, R = cf.parts(self); local a, b, c = cf.eulerYXZ(R); return clean(a), clean(b), clean(c) end,
        ToOrientation = function(self) local _, _, _, R = cf.parts(self); local a, b, c = cf.eulerYXZ(R); return clean(a), clean(b), clean(c) end,
    }
    -- binary operators; returns nil when the combination is not handled here
    function cf.op(symbol, a, b)
        if cf.isCF(a) then
            if symbol == "*" then
                if cf.isCF(b) then return cf.compose(a, b) end
                if cf.isV3(b) then
                    local px, py, pz, R = cf.parts(a); local x, y, z = cf.vec(b)
                    local rx, ry, rz = cf.mulv(R, x, y, z)
                    return Vector3.new(clean(px + rx), clean(py + ry), clean(pz + rz))
                end
            elseif (symbol == "+" or symbol == "-") and cf.isV3(b) then
                local px, py, pz, R = cf.parts(a); local x, y, z = cf.vec(b)
                if symbol == "-" then x, y, z = -x, -y, -z end
                return cf.make(px + x, py + y, pz + z, R)
            end
        end
        return nil
    end
    function cf.eq(a, b)
        if not (cf.isCF(a) and cf.isCF(b)) then return false end
        local ax, ay, az, aR = cf.parts(a)
        local bx, by, bz, bR = cf.parts(b)
        if ax ~= bx or ay ~= by or az ~= bz then return false end
        for i = 1, 9 do if aR[i] ~= bR[i] then return false end end
        return true
    end
end
-- Luau names the operator ("add"/"sub"/...), not the symbol, in arithmetic errors.
robloxApi.arithErr = function(symbol, a, b)
    local names = {["+"]="add", ["-"]="sub", ["*"]="mul", ["/"]="div", ["//"]="idiv", ["%"]="mod", ["^"]="pow"}
    local function tn(v)
        -- [PATCH:DT-OPS] Luau names the *typeof* of both operands (EnumItem, Instance, RBXScriptSignal, ...)
        local okT, r = pcall(_G.typeof, v)
        if okT and typeFunction(r) == "string" then return r end
        return typeFunction(v)
    end
    error("attempt to perform arithmetic (" .. (names[symbol] or symbol) .. ") on " .. tn(a) .. " and " .. tn(b), 3)
end

robloxApi.derivedOrientation = function(proxy, cn)
    local ps = dumperState.property_store[proxy]
    local c = ps and rawget(ps, "CFrame")
    if c ~= nil and robloxApi.cf.isCF(c) and cn and robloxApi.classHasMember(cn, "Orientation")
        and robloxApi.classHasMember(cn, "CFrame") then
        local _, _, _, R = robloxApi.cf.parts(c)
        local a, b, cc = robloxApi.cf.eulerYXZ(R)
        local function d(r) local v = math.deg(r); if math.abs(v) < 1e-5 then v = 0 end; return v end
        return Vector3.new(d(a), d(b), d(cc))
    end
    return nil
end

-- [PATCH:CASE-GUARD] Full case-insensitive member guard.
-- Roblox member lookup is case-sensitive EXCEPT for the first character (see
-- [API-CASE] in the instance __index). Any OTHER spelling of a real member --
-- `LocalPlayer.UserID`, `part.ANCHORED`, `workspace.currentcamera`,
-- `game:FindFirstChildofclass(...)` -- is simply not a member, and unless a child
-- with exactly that name exists the real client raises
-- `<key> is not a valid member of <Class> "<Name>"`. The permissive proxy used to
-- fabricate a child (or a method stub) for these spellings, which is the
-- "lowercase compared with uppercase" family of environment-logger detections.
-- The merged per-class member set (members + proptypes + readonly + methods +
-- events along the whole inheritance chain) is built lazily and cached.
robloxApi._ciCache = {}
robloxApi.memberSetFor = function(cls)
    local cached = robloxApi._ciCache[cls]
    if cached then return cached.exact, cached.lower end
    local exact, lower = {}, {}
    local c, g = cls, 0
    while c and g < 128 do
        for _, tbl in ipairs({robloxApi.members, robloxApi.proptypes, robloxApi.readonly,
                              robloxApi.methods, robloxApi.events}) do
            local set = tbl and tbl[c]
            if type(set) == "table" then
                for name in pairs(set) do
                    if type(name) == "string" then
                        exact[name] = true
                        lower[string.lower(name)] = true
                    end
                end
            end
        end
        c = robloxApi.msuper[c] or (robloxApi.super and robloxApi.super[c]) or (robloxApi.psuper and robloxApi.psuper[c])
        g = g + 1
    end
    robloxApi._ciCache[cls] = {exact = exact, lower = lower}
    return exact, lower
end
-- First child of `proxy` (in parenting order) whose Name is exactly `name`.
robloxApi.findNamedChild = function(proxy, name)
    for obj, p in pairsFunction(dumperState.parent_map) do
        if p == proxy then
            local ps = dumperState.property_store[obj]
            if ps and ps.Name == name then return obj end
        end
    end
    local cc = dumperState.child_cache and dumperState.child_cache[proxy]
    if cc and cc[name] ~= nil then return cc[name] end
    return nil
end
-- Engine-style GetFullName used inside "<key> is not a valid member of <Class> "<FullName>"".
-- DataModel prints as its Name ("Ugc"); services/instances print their dotted
-- ancestor path without the DataModel prefix (e.g. `Part "Workspace.Model.Part"`).
robloxApi.fullName = function(proxy, fallback)
    if proxy == game then return "Ugc" end
    if proxy == workspace then return "Workspace" end
    local parts, cur, guard = {}, proxy, 0
    while cur and cur ~= game and guard < 64 do
        local ps = dumperState.property_store[cur]
        local nm = ps and type(ps.Name) == "string" and ps.Name or nil
        if not nm and cur == workspace then nm = "Workspace" end
        if not nm then
            if cur == proxy then return fallback end
            nm = ps and ps.ClassName or "?"
        end
        table.insert(parts, 1, nm)
        cur = dumperState.parent_map[cur]
        guard = guard + 1
    end
    if #parts == 0 then return fallback end
    return table.concat(parts, ".")
end
-- Instance Name / ClassName as the engine reports them (the DataModel is "Ugc", the
-- Workspace singleton "Workspace", services their service name).
robloxApi.instName = function(obj)
    local ps = dumperState.property_store[obj]
    if ps and type(ps.Name) == "string" then return ps.Name end
    if obj == game then return "Ugc" end
    if obj == workspace then return "Workspace" end
    local reg = dumperState.registry[obj]
    local svc = type(reg) == "string" and reg:match("^game%.([%w_]+)$")
    return svc or nil
end
robloxApi.instClass = function(obj)
    return robloxApi.resolveClass(obj, dumperState.registry[obj], nil)
end
-- Accurate ancestry test. Script-created instances have a fully known parent chain; a
-- chain that dead-ends in an emulator-fabricated object is "unknown" and answers true
-- (the dumper keeps exploring that branch, as it did before).
robloxApi.isDescendantOf = function(inst, ancestor)
    local cur, guard = inst, 0
    while cur ~= nil and guard < 256 do
        local par = dumperState.parent_map[cur]
        if par == nil then
            if cur == game or rawget(cur, "__created_instance") then return false end
            return true
        end
        if par == ancestor then return true end
        cur = par
        guard = guard + 1
    end
    return false
end
-- [v1.6] "m" / "e" when `key` is a method / event of `cls` or of one of its ancestors (class-aware guard for the name-based fallbacks)
robloxApi.classCallable = function(cls, key)
    local c, g = cls, 0
    while c and g < 128 do
        local m = robloxApi.methods and robloxApi.methods[c]
        if m and m[key] then return "m" end
        local e = robloxApi.events and robloxApi.events[c]
        if e and e[key] then return "e" end
        c = (robloxApi.msuper and robloxApi.msuper[c]) or (robloxApi.super and robloxApi.super[c]) or (robloxApi.psuper and robloxApi.psuper[c])
        g = g + 1
    end
    return nil
end
-- [v1.6] cached Enum item proxy for a dotted path
robloxApi.fontEnum = function(path)
    local ec = dumperState.enum_cache or {}
    local p = ec[path]
    if not p then
        p = robloxApi.enumByPath(path)
        dumperState.registry[p] = path
        ec[path] = p
        dumperState.enum_cache = ec
    end
    return p
end
-- [v1.6] Enum.Font item -> family file, weight name, style name (Font.fromEnum)
robloxApi.fontFromEnum = function(name)
    local R = "rbxasset://fonts/families/"
    local map = {
        Legacy = {"LegacyArial"}, Arial = {"Arial"}, ArialBold = {"Arial", "Bold"}, Arimo = {"Arimo"}, ArimoBold = {"Arimo", "Bold"},
        SourceSans = {"SourceSansPro"}, SourceSansBold = {"SourceSansPro", "Bold"}, SourceSansSemibold = {"SourceSansPro", "SemiBold"},
        SourceSansLight = {"SourceSansPro", "Light"}, SourceSansItalic = {"SourceSansPro", "Regular", "Italic"},
        Gotham = {"GothamSSm"}, GothamMedium = {"GothamSSm", "Medium"}, GothamBold = {"GothamSSm", "Bold"}, GothamBlack = {"GothamSSm", "Heavy"},
        BuilderSans = {"BuilderSans"}, BuilderSansMedium = {"BuilderSans", "Medium"}, BuilderSansBold = {"BuilderSans", "Bold"}, BuilderSansExtraBold = {"BuilderSans", "ExtraBold"},
        Code = {"Inconsolata"}, Garamond = {"EBGaramond"}, Unknown = {"SourceSansPro"},
    }
    local e = map[name]
    if e then return R .. e[1] .. ".json", e[2] or "Regular", e[3] or "Normal" end
    return R .. tostring(name) .. ".json", "Regular", "Normal"
end
-- [v1.6] host-global names a script environment must not resolve through its fallback to the logger's own _G
robloxApi.hiddenHostGlobals = {Logger = true, originalError = true, dofile = true, loadfile = true}
robloxApi.hasNamedChild = function(proxy, name)
    return robloxApi.findNamedChild(proxy, name) ~= nil
end
-- Returns the "not a valid member" message when `key` is a wrong-case spelling
-- of a real member of the proxy's class (and no such child exists); nil otherwise.
robloxApi.caseGuardMessage = function(proxy, key, formattedName, pathName)
    if typeFunction(key) ~= "string" or key == "" or key:find("^__", 1) then return nil end
    local cls = robloxApi.foreignGuardClass(proxy, formattedName, pathName)
    if not cls then return nil end
    local exact, lower = robloxApi.memberSetFor(cls)
    if exact[key] then return nil end
    -- an exact service name is a real child of the DataModel (game.Debris, game.TextService, ...)
    if cls == "DataModel" and serviceNames[key] then return nil end
    local lk = string.lower(key)
    local isSvc = false
    if cls == "DataModel" then
        for sn in pairsFunction(serviceNames) do
            if string.lower(sn) == lk then isSvc = true; break end
        end
    end
    if not (lower[lk] or isSvc) then return nil end
    -- first-letter flip names a member => legal alias (resolved elsewhere)
    local f = key:sub(1, 1)
    local flip = (f:match("%l") and f:upper() or f:lower()) .. key:sub(2)
    if exact[flip] or (cls == "DataModel" and serviceNames[flip]) then return nil end
    if robloxApi.hasNamedChild(proxy, key) then return nil end
    local ps = dumperState.property_store[proxy]
    local nm = robloxApi.fullName(proxy, (ps and type(ps.Name) == "string" and ps.Name) or formattedName or cls)
    return key .. " is not a valid member of " .. cls .. " \"" .. tostring(nm) .. "\""
end

