-- [MANUAL] Non-zero / non-generic property defaults the API dump does not carry.
-- A fresh Instance.new(class) must read these back as the engine's defaults, not
-- the emulator's generic 0/white/empty guesses (dtc61..72). Values that are enums
-- or datatypes are stored as thunks so they build against the globals at read
-- time. Looked up along the class's inheritance chain.
robloxApi.classDefaults = {
    BasePart = { Position = function() return Vector3.new(0, 0, 0) end },
    Part = { Shape = function() return Enum.PartType.Block end },
    Light = { Brightness = 1, Color = function() return Color3.new(1, 1, 1) end },
    Sound = { RollOffMaxDistance = 10000 },
    ClickDetector = { MaxActivationDistance = 32 },
    Fire = { Size = 5 },
    Humanoid = { MaxSlopeAngle = 89 },
    TextLabel = { Text = "Label" },
    TextButton = { Text = "Button" },
    TextBox = { Text = "" },
}
robloxApi.classDefault = function(className, key)
    local c, g = className, 0
    while c and g < 128 do
        local set = robloxApi.classDefaults[c]
        if set then
            local v = set[key]
            if v ~= nil then
                if typeFunction(v) == "function" then return true, v() end
                return true, v
            end
        end
        c = robloxApi.msuper[c] or (robloxApi.super and robloxApi.super[c]) or (robloxApi.psuper and robloxApi.psuper[c])
        g = g + 1
    end
    return false, nil
end
