DateTime = createTypeDa("DateTime", {now = true, fromUnixTimestamp = true, fromUnixTimestampMillis = true, fromIsoDate = true})
-- [PATCH:DATETIME] Real DateTime datatype (the createTypeDa stub returned constants:
-- ToUniversalTime was always 1970-01-01, FormatUniversalTime ignored its format,
-- fromUniversalTime/fromIsoDate did not exist, DateTime.now() never advanced).
-- All values are UTC; ToLocalTime == ToUniversalTime (the emulated client runs in UTC).
do
    local MONTHS = {"January","February","March","April","May","June","July","August","September","October","November","December"}
    local DAYS = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"}
    local function daysFromCivil(y, m, d)
        y = (m <= 2) and (y - 1) or y
        local era = math.floor(y / 400)
        local yoe = y - era * 400
        local doy = math.floor((153 * (m + (m > 2 and -3 or 9)) + 2) / 5) + d - 1
        local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
        return era * 146097 + doe - 719468
    end
    local function civilFromDays(z)
        z = z + 719468
        local era = math.floor(z / 146097)
        local doe = z - era * 146097
        local yoe = math.floor((doe - math.floor(doe / 1460) + math.floor(doe / 36524) - math.floor(doe / 146096)) / 365)
        local y = yoe + era * 400
        local doy = doe - (365 * yoe + math.floor(yoe / 4) - math.floor(yoe / 100))
        local mp = math.floor((5 * doy + 2) / 153)
        local d = doy - math.floor((153 * mp + 2) / 5) + 1
        local m = mp + (mp < 10 and 3 or -9)
        if m <= 2 then y = y + 1 end
        return y, m, d
    end
    local function fields(ms)
        local secs = math.floor(ms / 1000)
        local milli = ms - secs * 1000
        local days = math.floor(secs / 86400)
        local rem = secs - days * 86400
        local y, mo, d = civilFromDays(days)
        return {Year = y, Month = mo, Day = d, Hour = math.floor(rem / 3600), Minute = math.floor(rem % 3600 / 60),
                Second = rem % 60, Millisecond = milli, _wd = (days + 4) % 7}
    end
    local meta = {}
    local function newDT(ms, expr)
        local o = {}
        rawset(o, "__roblox_type", "DateTime")
        rawset(o, "__dt_ms", ms)
        dumperState.registry[o] = expr or ("DateTime.fromUnixTimestampMillis(" .. string.format("%d", ms) .. ")")
        return setmetatable(o, meta)
    end
    local function fmt(ms, f)
        local t = fields(ms)
        local h12 = t.Hour % 12; if h12 == 0 then h12 = 12 end
        local function two(n) return string.format("%02d", n) end
        local tok
        tok = {
            LLLL = function() return DAYS[t._wd + 1] .. ", " .. MONTHS[t.Month] .. " " .. t.Day .. ", " .. t.Year .. " " .. h12 .. ":" .. two(t.Minute) .. " " .. (t.Hour < 12 and "AM" or "PM") end,
            LLL = function() return MONTHS[t.Month] .. " " .. t.Day .. ", " .. t.Year .. " " .. h12 .. ":" .. two(t.Minute) .. " " .. (t.Hour < 12 and "AM" or "PM") end,
            LTS = function() return h12 .. ":" .. two(t.Minute) .. ":" .. two(t.Second) .. " " .. (t.Hour < 12 and "AM" or "PM") end,
            LL = function() return MONTHS[t.Month] .. " " .. t.Day .. ", " .. t.Year end,
            LT = function() return h12 .. ":" .. two(t.Minute) .. " " .. (t.Hour < 12 and "AM" or "PM") end,
            L = function() return two(t.Month) .. "/" .. two(t.Day) .. "/" .. t.Year end,
            llll = function() return string.sub(DAYS[t._wd + 1], 1, 3) .. ", " .. string.sub(MONTHS[t.Month], 1, 3) .. " " .. t.Day .. ", " .. t.Year .. " " .. h12 .. ":" .. two(t.Minute) .. " " .. (t.Hour < 12 and "AM" or "PM") end,
            lll = function() return string.sub(MONTHS[t.Month], 1, 3) .. " " .. t.Day .. ", " .. t.Year .. " " .. h12 .. ":" .. two(t.Minute) .. " " .. (t.Hour < 12 and "AM" or "PM") end,
            ll = function() return string.sub(MONTHS[t.Month], 1, 3) .. " " .. t.Day .. ", " .. t.Year end,
            l = function() return t.Month .. "/" .. t.Day .. "/" .. t.Year end,
            YYYY = function() return string.format("%04d", t.Year) end,
            YY = function() return two(t.Year % 100) end,
            MMMM = function() return MONTHS[t.Month] end,
            MMM = function() return string.sub(MONTHS[t.Month], 1, 3) end,
            MM = function() return two(t.Month) end,
            M = function() return tostring(t.Month) end,
            DD = function() return two(t.Day) end,
            D = function() return tostring(t.Day) end,
            dddd = function() return DAYS[t._wd + 1] end,
            ddd = function() return string.sub(DAYS[t._wd + 1], 1, 3) end,
            dd = function() return string.sub(DAYS[t._wd + 1], 1, 2) end,
            d = function() return tostring(t._wd) end,
            HH = function() return two(t.Hour) end,
            H = function() return tostring(t.Hour) end,
            hh = function() return two(h12) end,
            h = function() return tostring(h12) end,
            mm = function() return two(t.Minute) end,
            m = function() return tostring(t.Minute) end,
            ss = function() return two(t.Second) end,
            s = function() return tostring(t.Second) end,
            SSS = function() return string.format("%03d", t.Millisecond) end,
            A = function() return t.Hour < 12 and "AM" or "PM" end,
            a = function() return t.Hour < 12 and "am" or "pm" end,
            ZZ = function() return "+0000" end,
            Z = function() return "+00:00" end,
        }
        local order = {"LLLL","LLL","LTS","LL","LT","llll","lll","YYYY","MMMM","dddd","SSS","ll","YY","MMM","MM","DD","ddd","HH","hh","mm","ss","dd","ZZ","L","l","M","D","d","H","h","m","s","A","a","Z"}
        local out, i, n = {}, 1, #f
        while i <= n do
            local c = string.sub(f, i, i)
            if c == "[" then
                local j = string.find(f, "]", i, true)
                if j then out[#out + 1] = string.sub(f, i + 1, j - 1); i = j + 1 else out[#out + 1] = c; i = i + 1 end
            else
                local hit
                for _, k in ipairs(order) do
                    if string.sub(f, i, i + #k - 1) == k then hit = k; break end
                end
                if hit then out[#out + 1] = tok[hit](); i = i + #hit else out[#out + 1] = c; i = i + 1 end
            end
        end
        return table.concat(out)
    end
    local function tname(v) local okT, r = pcall(_G.typeof, v); return okT and r or typeFunction(v) end
    local function badArg(i, fn, want, v)
        error("invalid argument #" .. i .. " to '" .. fn .. "' (" .. want .. " expected, got " .. (v == nil and "no value" or tname(v)) .. ")", 3)
    end
    local methods = {}
    local function self_ms(self, name)
        local ms = typeFunction(self) == "table" and rawget(self, "__dt_ms")
        if not ms then error("Expected ':' not '.' calling member function " .. name, 3) end
        return ms
    end
    function methods.ToIsoDate(self)
        local t = fields(self_ms(self, "ToIsoDate"))
        return string.format("%04d-%02d-%02dT%02d:%02d:%02dZ", t.Year, t.Month, t.Day, t.Hour, t.Minute, t.Second)
    end
    local function toTable(self, name)
        local t = fields(self_ms(self, name)); t._wd = nil; return t
    end
    function methods.ToUniversalTime(self) return toTable(self, "ToUniversalTime") end
    function methods.ToLocalTime(self) return toTable(self, "ToLocalTime") end
    function methods.FormatUniversalTime(self, f, locale)
        local ms = self_ms(self, "FormatUniversalTime")
        if typeFunction(f) ~= "string" then badArg(1, "FormatUniversalTime", "string", f) end
        return fmt(ms, f)
    end
    function methods.FormatLocalTime(self, f, locale)
        local ms = self_ms(self, "FormatLocalTime")
        if typeFunction(f) ~= "string" then badArg(1, "FormatLocalTime", "string", f) end
        return fmt(ms, f)
    end
    meta.__index = function(self, k)
        local ms = rawget(self, "__dt_ms")
        if k == "UnixTimestamp" then return math.floor(ms / 1000) end
        if k == "UnixTimestampMillis" then return ms end
        if methods[k] then return methods[k] end
        error(tostring(k) .. " is not a valid member of DateTime", 2)
    end
    meta.__newindex = function(self, k) error("Unable to assign property " .. tostring(k) .. ". Property is read only", 2) end
    meta.__eq = function(a, b) return rawget(a, "__dt_ms") == rawget(b, "__dt_ms") end
    local function cmpArgs(a, b)
        local ma = typeFunction(a) == "table" and rawget(a, "__dt_ms")
        local mb = typeFunction(b) == "table" and rawget(b, "__dt_ms")
        if not (ma and mb) then error("attempt to compare " .. tname(a) .. " < " .. tname(b), 3) end
        return ma, mb
    end
    meta.__lt = function(a, b) local x, y = cmpArgs(a, b); return x < y end
    meta.__le = function(a, b) local x, y = cmpArgs(a, b); return x <= y end
    meta.__tostring = function() return "DateTime" end
    meta.__metatable = "The metatable is locked"
    for opn, opname in pairs({__add = "add", __sub = "sub", __mul = "mul", __div = "div", __mod = "mod", __pow = "pow", __idiv = "idiv"}) do
        meta[opn] = function(a, b) error("attempt to perform arithmetic (" .. opname .. ") on " .. tname(a) .. " and " .. tname(b), 2) end
    end
    meta.__unm = function(a) error("attempt to perform arithmetic (unm) on DateTime", 2) end
    meta.__concat = function(a, b) error("attempt to concatenate " .. tname(a) .. " and " .. tname(b), 2) end
    meta.__len = function() error("attempt to get length of a DateTime value", 2) end
    meta.__call = function() error("attempt to call a DateTime value", 2) end

    local api = {}
    local function nowMs() return math.floor(_G.tick() * 1000) end
    function api.now() return newDT(nowMs(), "DateTime.now()") end
    function api.fromUnixTimestamp(n)
        if typeFunction(n) ~= "number" then badArg(1, "fromUnixTimestamp", "number", n) end
        return newDT(math.floor(n * 1000), "DateTime.fromUnixTimestamp(" .. tostring(n) .. ")")
    end
    function api.fromUnixTimestampMillis(n)
        if typeFunction(n) ~= "number" then badArg(1, "fromUnixTimestampMillis", "number", n) end
        return newDT(math.floor(n), "DateTime.fromUnixTimestampMillis(" .. tostring(n) .. ")")
    end
    local function fromParts(fname, y, mo, d, h, mi, s, ms)
        local a = {y, mo, d, h, mi, s, ms}
        local def = {1970, 1, 1, 0, 0, 0, 0}
        for i = 1, 7 do
            if a[i] == nil then a[i] = def[i]
            elseif typeFunction(a[i]) ~= "number" then badArg(i, fname, "number", a[i]) end
        end
        local days = daysFromCivil(a[1], a[2], a[3])
        local total = ((days * 24 + a[4]) * 60 + a[5]) * 60 + a[6]
        return newDT(math.floor(total * 1000 + a[7]), "DateTime." .. fname .. "(" .. table.concat({tostring(a[1]), tostring(a[2]), tostring(a[3]), tostring(a[4]), tostring(a[5]), tostring(a[6]), tostring(a[7])}, ", ") .. ")")
    end
    function api.fromUniversalTime(...) return fromParts("fromUniversalTime", ...) end
    function api.fromLocalTime(...) return fromParts("fromLocalTime", ...) end
    function api.fromIsoDate(s)
        if typeFunction(s) ~= "string" then badArg(1, "fromIsoDate", "string", s) end
        local y, mo, d, h, mi, sec, frac = string.match(s, "^(%d%d%d%d)%-(%d%d)%-(%d%d)T(%d%d):(%d%d):(%d%d)(%.?%d*)Z$")
        if not y then
            y, mo, d = string.match(s, "^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
            if not y then return nil end
            h, mi, sec, frac = 0, 0, 0, ""
        end
        local ms = 0
        if frac ~= "" and frac ~= "." then ms = math.floor((tonumber("0" .. frac) or 0) * 1000 + 0.5) end
        local days = daysFromCivil(tonumber(y), tonumber(mo), tonumber(d))
        return newDT(math.floor((((days * 24 + tonumber(h)) * 60 + tonumber(mi)) * 60 + tonumber(sec)) * 1000 + ms), "DateTime.fromIsoDate(" .. string.format("%q", s) .. ")")
    end
    DateTime = setmetatable({}, {
        __index = function(_, k)
            local v = api[k]
            if v ~= nil then return v end
            error(tostring(k) .. " is not a valid member of DateTime", 2)
        end,
        __newindex = function() error("Attempt to modify a readonly table", 2) end,
        __metatable = "The metatable is locked",
    })
    for k, v in pairs(api) do rawset(DateTime, k, nil) end
end
SharedTable = createTypeDa("SharedTable", {new = true})
SharedTable.clear = function(st)
    local data = rawget(st, "__shared_data")
    if data then
        for key in pairsFunction(data) do data[key] = nil end
    end
end
SharedTable.increment = function(st, key, amount)
    local previous = st[key] or 0
    st[key] = previous + (amount or 1)
    return previous
end
-- Atomically transform a value: the callback receives the OLD value and its
-- return becomes the new one (dtc104).
SharedTable.update = function(st, key, fn)
    local old = st[key]
    local new = fn(old)
    st[key] = new
    return new
end
SharedTable.clone = function(st, deep)
    local copy = SharedTable.new()
    local source = rawget(st, "__shared_data") or {}
    for key, value in pairsFunction(source) do
        if deep and typeFunction(value) == "table" and rawget(value, "__roblox_type") == "SharedTable" then
            value = SharedTable.clone(value, true)
        end
        copy[key] = value
    end
    return copy
end
SharedTable.cloneAndFreeze = function(st)
    local copy = SharedTable.clone(st, true)
    rawset(copy, "__shared_frozen", true)
    return copy
end
SharedTable.isFrozen = function(st)
    return rawget(st, "__shared_frozen") == true
end
SharedTable.size = function(st)
    local sd = rawget(st, "__shared_data")
    if sd then
        local count = 0
        for _ in pairs(sd) do count = count + 1 end
        return count
    end
    return 0
end
