Random = {new = function(seed)
        local obj = {}
        local _rng_ctr = (dumperState._rng_counter or 0) + 1
        dumperState._rng_counter = _rng_ctr
        if seed ~= nil and typeFunction(seed) ~= "number" then
            error("invalid argument #1 to 'new' (number expected, got " .. typeFunction(seed) .. ")", 2)
        end
        local s = seed
        if s == nil then s = os.time() + _rng_ctr end
        local _seedInt = math.floor(s) % 2147483648
        -- Per-instance deterministic stream: re-seed the native (engine-identical)
        -- RNG to this seed and replay the recorded draw history before each new
        -- draw, so the sequence matches Roblox regardless of NextInteger /
        -- NextNumber mixing, and instances stay isolated from one another.
        local _hist = {}
        local function exec(opfn)
            _nativeRandomseed(_seedInt)
            for i = 1, #_hist do _hist[i]() end
            local result = opfn()
            if #_hist < 100000 then _hist[#_hist + 1] = opfn end
            return result
        end
        function obj:NextInteger(min, max)
            min, max = min or 0, max or 1
            min, max = math.floor(min), math.floor(max)
            return exec(function() return _nativeRandom(min, max) end)
        end
        function obj:NextNumber(min, max)
            if min == nil then return exec(function() return _nativeRandom() end) end
            return exec(function() return min + _nativeRandom() * (max - min) end)
        end
        function obj:NextUnitVector()
            local v = exec(function()
                local x = _nativeRandom() * 2 - 1
                local y = _nativeRandom() * 2 - 1
                local z = _nativeRandom() * 2 - 1
                local m = math.sqrt(x * x + y * y + z * z)
                if m == 0 then return {0, 1, 0} end
                return {x / m, y / m, z / m}
            end)
            return Vector3.new(v[1], v[2], v[3])
        end
        function obj:Shuffle(tab) return tab end
        function obj:Clone() return Random.new(_seedInt) end
        function obj:NextGaussian(mean, sd)
            mean, sd = mean or 0, sd or 1
            return exec(function()
                local u1 = _nativeRandom(); if u1 <= 0 then u1 = 1e-12 end
                local u2 = _nativeRandom()
                return mean + sd * math.sqrt(-2 * math.log(u1)) * math.cos(2 * math.pi * u2)
            end)
        end
        rawset(obj, "__roblox_type", "Random")
        -- Register as a proxy so type() returns "userdata"
        proxyStore[obj] = true
        local _seedStr = seed ~= nil and tostring(tonumber(seed) or 0) or ""
        dumperState.registry[obj] = _seedStr ~= "" and ("Random.new(" .. _seedStr .. ")") or "Random.new()"
        -- [MANUAL] Reading a member Random doesn't have raises on a real client
        -- (dtc34). Defined methods are rawset on obj so only unknown keys hit here.
        setmetatable(obj, {
            __index = function(_, k)
