                if typeFunction(k) == "number" or k == nil then
                    error(tostring(k) .. " is not a valid member of Random", 2)
                end
                return nil
            end,
            __newindex = function(_, k) error(tostring(k) .. " is not a valid member of Random", 2) end, -- [PATCH:NUMKEY3]
            __metatable = "The metatable is locked",
            __len = function(a) error("attempt to get length of a Random value", 2) end,
            __unm = function(a) error("attempt to perform arithmetic (unm) on Random", 2) end,
            __call = function(a) error("attempt to call a Random value", 2) end,
            __concat = function(a, b)
                error("attempt to concatenate " .. robloxApi.opTn(a) .. " and " .. robloxApi.opTn(b), 2)
            end,
            __lt = robloxApi.cmpLt, __le = robloxApi.cmpLt,
            __add = function(a, b) robloxApi.arithErr("+", a, b) end,
            __sub = function(a, b) robloxApi.arithErr("-", a, b) end,
            __mul = function(a, b) robloxApi.arithErr("*", a, b) end,
            __div = function(a, b) robloxApi.arithErr("/", a, b) end,
            __mod = function(a, b) robloxApi.arithErr("%", a, b) end,
            __pow = function(a, b) robloxApi.arithErr("^", a, b) end,
        })
        return obj
    end}
