-- For enums not in enumItemValues, auto-assign sequential values so items are
-- always distinct and non-zero (except the first = 0).
do
    local function buildAutoValues(items)
        local sorted = {}
        for k in pairsFunction(items) do sorted[#sorted+1] = k end
        table.sort(sorted)
        local t = {}
        for i, k in ipairsFunction(sorted) do t[k] = i - 1 end
        return t
    end
    for enumName, items in pairsFunction(knownEnumItems) do
        if not enumItemValues[enumName] then
            enumItemValues[enumName] = buildAutoValues(items)
        else
            -- API dumps occasionally differ in membership from the legacy enum
            -- name table. Keep every exposed item's value distinct even when the
            -- authoritative table supplies only a partial numeric mapping.
            local values, used = enumItemValues[enumName], {}
            local nextValue = 0
            for _, value in pairsFunction(values) do
                if typeFunction(value) == "number" then
                    used[value] = true
                    if value >= nextValue then nextValue = value + 1 end
                end
            end
            for itemName in pairsFunction(items) do
                if values[itemName] == nil then
                    while used[nextValue] do nextValue = nextValue + 1 end
                    values[itemName] = nextValue
                    used[nextValue] = true
                    nextValue = nextValue + 1
                end
            end
        end
    end
end
