Instance = {new = function(className, parent)
        if className == nil then error("Argument 1 missing or nil", 2) end
        do -- [v1.6] luaL_checkstring: only strings (and numbers, which convert) name a class
            local _tc = typeFunction(className)
            if _tc ~= "string" and _tc ~= "number" then
                error("invalid argument #1 to 'new' (string expected, got " .. robloxApi.argTn(className) .. ")", 2)
            end
        end
        local name = formatValue(className)
        if name:match("Fake") or name:match("Invalid") then
            error("Invalid class name", 2)
        end

        if not validInstanceClasses[name] then
            error("Unable to create an Instance of type \"" .. name .. "\"", 2)
        end

        local restrictedClasses = {DataModel = true, Workspace = true, CoreGui = true, CorePackages = true}
        if restrictedClasses[name] then
            error("Cannot create instance of type " .. name, 2)
        end

        -- Ghost proxy: when more than BULK_THRESHOLD same-class instances are created in a run,
        -- stop emitting individual declarations and track only by child-count on the parent.
        -- This prevents O(n) output accumulation for large mass-creation loops.
        local BULK_THRESHOLD = 1000
        dumperState.instance_count = dumperState.instance_count or {}
        dumperState.instance_count[name] = (dumperState.instance_count[name] or 0) + 1
        if dumperState.instance_count[name] > BULK_THRESHOLD then
            -- Reuse a single shared ghost proxy per class to avoid allocating thousands of tables.
            -- Ghost proxies absorb all property assignments silently and only track child-counts.
            dumperState.ghost_proxies = dumperState.ghost_proxies or {}
            if not dumperState.ghost_proxies[name] then
                local ghost = createProxyObject(name, false)
                rawset(ghost, "__ghost", true)
                rawset(ghost, "__created_instance", true)
                dumperState.property_store[ghost] = {Name = name, ClassName = name}
                dumperState.ghost_proxies[name] = ghost
            end
            local ghost = dumperState.ghost_proxies[name]
            if parent and isProxy(parent) then
                dumperState.child_counts = dumperState.child_counts or {}
                dumperState.child_counts[parent] = (dumperState.child_counts[parent] or 0) + 1
            end
            return ghost
        end

        local proxy = createProxyObject(name, false)
        rawset(proxy, "__created_instance", true)
        dumperState.property_store[proxy] = {Name = name, ClassName = name}
        if name == "Actor" then
            dumperState.all_actors = dumperState.all_actors or setmetatable({}, {__mode = "k"})
            dumperState.all_actors[proxy] = true
        end
        -- [PATCH] Stamp physics birth time for BasePart-derived instances so an
        -- unanchored part accumulates gravity/force over elapsed virtual time.
        if robloxApi.isPartLikeClass(name) then
            dumperState.property_store[proxy]._phys_t0 = get_virtual_clock()
        end
        local varName = registerVariable(proxy, name)

        if name == "SkateboardController" then
            dumperState.property_store[proxy].Steer = 0
            dumperState.property_store[proxy].Throttle = 0
            local sigProxy = createProxyObject(name .. ".AxisChanged", false, proxy)
            rawset(sigProxy, "__is_signal", true)
            dumperState.property_store[proxy].AxisChanged = sigProxy
        end

        if name == "HumanoidDescription" then
            local ps = dumperState.property_store[proxy]
            ps.HeadScale = 1; ps.HeightScale = 1; ps.WidthScale = 1
            ps.BodyTypeScale = 0; ps.ProportionsScale = 0; ps.DepthScale = 1
            ps.HatAccessory = ""; ps.HairAccessory = ""; ps.FaceAccessory = ""
            ps.NeckAccessory = ""; ps.ShouldersAccessory = ""; ps.FrontAccessory = ""
            ps.BackAccessory = ""; ps.WaistAccessory = ""
        end
        
        if parent ~= nil and typeFunction(parent) ~= "userdata" and not isProxy(parent) then
            error("invalid argument #2 to 'new' (Instance expected, got " .. typeFunction(parent) .. ")", 2)
        end
        if parent then
            local parentPath = dumperState.registry[parent] or serializeValue(parent)
            emitOutput(string.format("local %s = Instance.new(%s, %s)", varName, formatStringLiteral(name), parentPath))
            dumperState.parent_map[proxy] = parent
            robloxApi.hierEvents(proxy, nil, parent) -- [PATCH:SIGNALS] ChildAdded/DescendantAdded for Instance.new(cls, parent)
        else
            emitOutput(string.format("local %s = Instance.new(%s)", varName, formatStringLiteral(name)))
        end
        return proxy
    end}
