-- [v1.6] argument checks of the engine's scheduler functions (luaL_checknumber / function-or-thread parameters)
robloxApi.taskNumArg = function(fname, idx, nargs, v, optional)
    local tv = typeFunction(v)
    if tv == "number" then return v end
    if tv == "string" then
        local n = toNumberFunction(v)
        if n ~= nil then return n end
    end
    if v == nil and optional then return nil end
    if idx > nargs then
        errorFunction("missing argument #" .. idx .. " to '" .. fname .. "' (number expected)", 3)
    end
    errorFunction("invalid argument #" .. idx .. " to '" .. fname .. "' (number expected, got " .. robloxApi.argTn(v) .. ")", 3)
end
robloxApi.taskFnArg = function(fname, idx, nargs, v)
    local tv = typeFunction(v)
    if tv == "function" or tv == "thread" then return end
    if tv == "table" then
        if rawget(v, "__is_method") then return end
        local mt = getMetatableFunction(v)
        if typeFunction(mt) == "table" and typeFunction(mt.__call) == "function" then return end
    end
    if idx > nargs then
        errorFunction("missing argument #" .. idx .. " to '" .. fname .. "' (function or thread expected)", 3)
    end
    errorFunction("invalid argument #" .. idx .. " to '" .. fname .. "' (function or thread expected, got " .. robloxApi.argTn(v) .. ")", 3)
end

task = {
    wait = function(sec)
        sec = robloxApi.taskNumArg("wait", 1, 1, sec, true)
        check_timeout()
        LG.yield() -- [v1.6] stagnation-aware loop guard (replaces the child-coroutine-only yield counter)

        local t = sec or 0.03
        if t ~= t or t < 0 then t = 0 elseif t > 1e7 then t = 1e7 end -- a negative / NaN duration waits a single frame
        if t < 0.0167 then t = 0.0167 end -- no resume earlier than the next frame
        if sec then emitOutput(string.format("task.wait(%s)", serializeValue(sec))) else emitOutput("task.wait()") end
        -- Cooperative scheduling: a task.wait() inside a spawned coroutine yields
        -- control back to the scheduler (the main thread / a parent task.wait),
        -- so the spawned body resumes only after the caller next yields -- giving
        -- the real interleaved order (A,C,B,D for spawn+wait -- eUNC task check).
        do
            local _curCo = coroutine.running()
            if _curCo ~= nil and dumperState.scheduled_cos and dumperState.scheduled_cos[_curCo] then
                local _coAdv = t + (0.0035 + (math.random() * 0.0055))
                virtual_time_offset = virtual_time_offset + _coAdv
                coroutine.yield()
                return _coAdv -- [PATCH:WAIT-RETURN] task.wait returns the real elapsed time (one value)
            end
        end
        -- A real scheduler resumes after *at least* the requested time, always
        -- overshooting by a sub-frame amount. Advancing the virtual clock by
        -- exactly `t` makes the elapsed delta match the request too perfectly,
        -- which timing-based anti-tampers flag (they expect abs(delta - t) to
        -- exceed a few ms). Add a small realistic jitter so the clock behaves
        -- like a genuine client without affecting normal logging.
        local _jitter = 0.0035 + (math.random() * 0.0055)
        virtual_time_offset = virtual_time_offset + t + _jitter
        local _elapsedRet = t + _jitter -- [PATCH:WAIT-RETURN] elapsed time differs per call, as on a real scheduler

        -- Always advance jump physics each task.wait, even without heartbeat connections
        if dumperState.jump_physics and dumperState.jump_physics.active then
            local _jp = dumperState.jump_physics
            local _subFrames = math.max(1, math.floor(t * 60))
            local _subDt = t / _subFrames
            for _fi = 1, _subFrames do
                if not _jp.active then break end
                local _hrpPs = _jp.hrp and dumperState.property_store[_jp.hrp]
                if _hrpPs then
                    local _cp = _hrpPs.Position or Vector3.new(0, 5, 0)
                    local _pvy = _jp.vy
                    _jp.vy = _jp.vy - _jp.gravity * _subDt
                    if _pvy > 0 and _jp.vy <= 0 and _jp.humanoid then
                        local _hps = dumperState.property_store[_jp.humanoid]
                        if _hps and _hps._currentState == "Jumping" then _hps._currentState = "Freefall" end
                    end
                    local _ny = _cp.Y + _jp.vy * _subDt
                    if _ny <= _jp.base_y then
                        _ny = _jp.base_y; _jp.active = false
                        if _jp.humanoid then
                            local _hps = dumperState.property_store[_jp.humanoid]
                            if _hps then _hps._currentState = "Running" end
                        end
                    end
                    local _np = Vector3.new(_cp.X, _ny, _cp.Z)
                    _hrpPs.Position = _np
                    _hrpPs.CFrame = CFrame.new(_np.X, _np.Y, _np.Z)
                end
            end
        end

        if robloxApi.frameWork() then
            local fps = dumperState.fps_cap or 60
            if fps <= 0 then fps = 60 end
            if fps > 240 then fps = 240 end
            local frames = math.floor(t * fps + 0.5)
            if frames < 1 then frames = 1 end
            if frames > 300 then frames = 300 end
            local dt = 1 / fps
            local function _advanceJumpPhysics(frameDt)
                local jp = dumperState.jump_physics
                if not jp or not jp.active then return end
                local hrpPs = jp.hrp and dumperState.property_store[jp.hrp]
                if not hrpPs then jp.active = false; return end
                local curPos = hrpPs.Position or Vector3.new(0, 5, 0)
                local prevVy = jp.vy
                jp.vy = jp.vy - jp.gravity * frameDt
                -- Transition to Freefall at apex
                if prevVy > 0 and jp.vy <= 0 and jp.humanoid then
                    local humPs = dumperState.property_store[jp.humanoid]
                    if humPs and humPs._currentState == "Jumping" then humPs._currentState = "Freefall" end
                end
                local newY = curPos.Y + jp.vy * frameDt
                if newY <= jp.base_y then
                    newY = jp.base_y
                    jp.active = false
                    -- Transition to Running when landed
                    if jp.humanoid then
                        local humPs = dumperState.property_store[jp.humanoid]
                        if humPs then humPs._currentState = "Running" end
                    end
                end
                local newPos = Vector3.new(curPos.X, newY, curPos.Z)
                hrpPs.Position = newPos
                hrpPs.CFrame = CFrame.new(newPos.X, newPos.Y, newPos.Z)
            end
            robloxApi.runFrames(frames, dt, _advanceJumpPhysics) -- [PATCH:RENDERSTEP]
        end
        
        if dumperState.deferred_tasks and #dumperState.deferred_tasks > 0 then
            -- A task scheduled while the current frame is executing becomes
            -- runnable on the following frame. Draining recursively here turns
            -- a single task.wait into an unbounded synchronous work loop and
            -- destroys Roblox's observable task ordering.
            local tasks = robloxApi.takeDue(virtual_time_offset)
            for _, tFunc in ipairs(tasks) do pcall(tFunc) end
        end
        
        return _elapsedRet
    end,
    spawn = function(...)
        local f = ...
        robloxApi.taskFnArg("spawn", 1, select("#", ...), f)
        local args = {select(2, ...)}
        -- Support callable tables (tables with __call metamethod)
        if type(f) == "table" then
            local mt = getMetatableFunction(f)
            if mt and type(mt.__call) == "function" then
                local _f = f
                f = function(...) return _f(...) end
            end
        end
        dumperState.deferred_tasks = dumperState.deferred_tasks or {}
        -- cap deferred tasks to avoid OOM/timeout from mass task.spawn calls
        if #dumperState.deferred_tasks >= 200 then
            if type(f) == "thread" then return f end
            return coroutine.create(f)
        end
        if type(f) == "thread" then
            emitOutput("task.spawn(thread)")
            -- Roblox runs task.spawn(coroutine) synchronously (resumes until first yield/return).
            xpcallFunction(function() coroutine.resume(f, table.unpack(args)) end,
                function(err) emitOutput("-- [VM Error]: " .. tostring(err)) end)
            return f
        else
            emitOutput("task.spawn(function()")
            dumperState.indent = dumperState.indent + 1
            local co = coroutine.create(f)
            -- Mark this coroutine as scheduler-managed so its task.wait() yields
            -- cooperatively rather than busy-advancing the clock (eUNC task order).
            dumperState.scheduled_cos = dumperState.scheduled_cos or setmetatable({}, {__mode = "k"})
            dumperState.scheduled_cos[co] = true
            -- Roblox task.spawn runs the function synchronously until its first yield.
            local ok, err = coroutine.resume(co, table.unpack(args))
            if not ok and err then
                emitOutput("-- [VM Error]: " .. tostring(err))
            end
            -- If not finished, schedule the rest to resume during next task.wait()
            if coroutine.status(co) ~= "dead" then
                dumperState.deferred_tasks = dumperState.deferred_tasks or {}
                if #dumperState.deferred_tasks < 200 then
                    table.insert(dumperState.deferred_tasks, function()
                        if dumperState.cancelled_threads and dumperState.cancelled_threads[co] then return end
                        local ok2, err2 = coroutine.resume(co)
                        if not ok2 and err2 and tostring(err2) ~= "cannot resume dead coroutine" then
                            emitOutput("-- [VM Error]: " .. tostring(err2))
                        end
                    end)
                end
            end
            dumperState.indent = dumperState.indent - 1
            emitOutput("end)")
            return co
        end
    end,
    defer = function(...)
        local f = ...
        robloxApi.taskFnArg("defer", 1, select("#", ...), f)
        local args = {select(2, ...)}
        dumperState.deferred_tasks = dumperState.deferred_tasks or {}
        if type(f) == "thread" then
            emitOutput("task.defer(thread)")
            table.insert(dumperState.deferred_tasks, function() coroutine.resume(f, table.unpack(args)) end)
            return f
        else
            emitOutput("task.defer(function()")
            local block_id = "--[[DEFER_BLOCK_" .. tostring(math.random(1000000, 9999999)) .. "]]"
            table.insert(dumperState.output, block_id)
            local current_indent = dumperState.indent
            local co = coroutine.create(f)
            dumperState.scheduled_cos = dumperState.scheduled_cos or setmetatable({}, {__mode = "k"})
            dumperState.scheduled_cos[co] = true
            local resumeDeferred
            resumeDeferred = function()
                local old_output = dumperState.output
                local old_indent = dumperState.indent
                local old_last = dumperState.last_emitted_line
                local captured = {}

                dumperState.output = captured
                dumperState.indent = current_indent + 1
                dumperState.last_emitted_line = nil

                local ok, err = coroutine.resume(co, table.unpack(args))
                if not ok and err then
                    emitOutput("-- [VM Error]: " .. tostring(err))
                elseif coroutine.status(co) ~= "dead" then
                    dumperState.deferred_tasks = dumperState.deferred_tasks or {}
