-- dtc3: inline these scalar time sources so a script that does
-- `os.time() + 1` (or any arithmetic) still sees the call expression
-- in the dump instead of a raw frozen number.
local function _inlineTimeResult(val, expr)
    if INLINER and dumperState.inliner_map and val ~= nil then
        -- Register under both the value key and the tostring key so later
        -- __INLINEARITH/__INLINECAT lookups hit the original call name
        -- (otherwise a derived `(os.time() + 0)` would win the numeric
        -- key and bleed back into unrelated reads of the same number).
        if not dumperState.inliner_map[val] then
            dumperState.inliner_map[val] = expr
        end
        local key = tostring(val)
        if not dumperState.inliner_map[key] then
            dumperState.inliner_map[key] = expr
        end
    end
    return val
end

tick = function() return _inlineTimeResult(get_virtual_time(), "tick()") end
time = function() return _inlineTimeResult(get_virtual_clock(), "time()") end
elapsedTime = function() return _inlineTimeResult(get_virtual_clock(), "elapsedTime()") end

local customOs = {}
customOs.clock = function()
    return _inlineTimeResult(get_virtual_clock(), "os.clock()")
end
customOs.time = function(t)
    if t == nil then
        return _inlineTimeResult(math.floor(get_virtual_time()), "os.time()")
    end
    if isProxy(t) then
        error("invalid argument #1 to 'time' (table or nil expected, got Instance)", 2)
    end
    return osLibrary.time(t)
end
customOs.date = osLibrary.date
customOs.difftime = osLibrary.difftime

-- [PATCH:LUAU-LIBS] Roblox's os library only has clock/date/difftime/time; every other
-- member (os.execute, os.getenv, os.exit, ...) is simply nil, not a "disabled" stub.
_G.os = customOs
local globalEnv = {}
local dummy = 999999999
local function getDummy(key, val) return val end
-- Track all setupEnv tables so type() returns "userdata" for them (not "table"),
-- preventing detections like `if type(e) == "table"`.
local envTableSet = setmetatable({}, {__mode = "k"})
local function setupEnv()
    local env = {}
    envTableSet[env] = true
    setmetatable(env, {
        __call = function(self, ...) return self end,
        __index = function(self, key)
            if _G[key] ~= nil then return getDummy(key, _G[key]) end
            if key == "game" then return game end
            if key == "workspace" then return workspace end
            if key == "script" then return script end
            if key == "Enum" then return Enum end
            
            if RECONSTRUCT_MODE then
                local fuzzedProxy = createProxyObject(tostring(key), false)
                emitOutput("-- Forced execution for missing global: " .. tostring(key))
                return fuzzedProxy
            end
            
            return nil
        end,
        __newindex = function(self, key, val)
            _G[key] = val
            globalEnv[key] = 0
            emitOutput(string.format("_G.%s = %s", formatValue(key), serializeValue(val)))
        end
    })
    return env
end
