local function createGetGenv(path)
    local proxy = {}
    local meta = {}
    
    local function formatPath(d, k)
        local prop = formatValue(k)
        if prop:match("^[%a_][%w_]*$") then
            if d then return d .. "." .. prop end
            return prop
        else
            local escaped = prop:gsub("'", "\\\\'")
            if d then return d .. "['" .. escaped .. "']" end
            return "['" .. escaped .. "']"
        end
    end
    
    meta.__index = function(_, key)
        if not path and _G[key] ~= nil and key ~= "Logger" and key ~= "originalError" then -- [v1.6] logger internals are not globals
            return _G[key]
        end
        return nil
    end
    
    meta.__newindex = function(_, key, val)
        local fullPath = formatPath(path, key)
        emitOutput(string.format("getgenv().%s = %s", fullPath, serializeValue(val)))
        
        if not path then
            _G[key] = val
        end
    end
    
    meta.__call = function() return proxy end
    
    meta.__pairs = function() return pairsFunction(_G) end
    
    return setmetatable(proxy, meta)
end

local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function real_base64_encode(data)
    return ((data:gsub('.', function(x) 
        local r,b='',x:byte()
        for i=8,1,-1 do r=r..(b%2^i-b%2^(i-1)>0 and '1' or '0') end
        return r;
    end)..'0000'):gsub('%d%d%d?%d?%d?%d?', function(x)
        if (#x < 6) then return '' end
        local c=0
        for i=1,6 do c=c+(x:sub(i,i)=='1' and 2^(6-i) or 0) end
        return b64chars:sub(c+1,c+1)
    end)..({ '', '==', '=' })[#data%3+1])
end

local function real_base64_decode(data)
    data = string.gsub(data, '[^'..b64chars..'=]', '')
    return (data:gsub('.', function(x)
        if (x == '=') then return '' end
        local r,f='',(b64chars:find(x)-1)
        for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
        return r;
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if (#x ~= 8) then return '' end
        local c=0
        for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
        return string.char(c)
    end))
end

local function generate_random_bytes(len)
    local res = {}
    for i = 1, len do table.insert(res, string.char(math.random(0, 255))) end
    return table.concat(res)
end

-- Will be populated after mathLib/stringLib/tableLib are created
local _stdlibWrapperFns = {}

-- True when `f` is one of our Lua wrappers that emulates a Roblox C function
-- (print, typeof, the bit32/table/string library functions, ...). Real Roblox
-- exposes these as C closures, so introspection like debug.getupvalue(typeof)
-- must error the same way it would on a genuine C function rather than leaking
-- our wrapper's upvalues (dtc3/9). Detection is universal: it consults the
-- builtin tag table, the stdlib-wrapper set, and the closure's reported source.
local function _isEmulatedCFunction(f)
    if type(f) ~= "function" then return false end
    if dumperState and dumperState.builtin_tags and dumperState.builtin_tags[f] then return true end
    if _stdlibWrapperFns[f] then return true end
    -- Use the REAL debug (captured before the emulated debug shadows it) so we
    -- see the genuine chunk source of our wrappers, not the faked "[C]" the
    -- emulated debug.info hands the analysed script.
    local ok, src = pcall(debugLibrary.info, f, "s")
    if ok and type(src) == "string"
        and (src == "[C]" or src:match("^%[C") or src:match("envlogger")
             or src:match("@lune") or src:match("container")) then
        return true
    end
    return false
end

-- Qualified name for a pcall(fn, ...) target only when fn is a genuine builtin/
-- library function -- never the analysed script's own Lua closures, which keep
-- their `pcall(function() ... end)` body so traced operations stay nested.
local function pcallInlineName(f)
    if not _isEmulatedCFunction(f) then return nil end
    return resolveBuiltinName(f)
end
-- A pcall(builtin, args...) is only rendered inline when its arguments are
-- small/simple. A plain (unregistered) table or an over-long string argument --
-- e.g. pcall(table.concat, hugeNestedTable, ...) -- would otherwise serialize
-- into a massive (or circular) literal that floods the dump, so those fall back
-- to the nested `pcall(function() ... end)` body instead. Scalars, proxies,
-- registered tables, the emulated-userdata env globals, and functions are all
-- cheap to serialize and stay inline.
local function pcallArgInlineSafe(v)
    local t = typeFunction(v)
    if t == "nil" or t == "boolean" or t == "number" or t == "function" or t == "thread" then return true end
    if t == "string" then return #v <= 200 end
    if t == "table" then
        if isProxy(v) then return true end
        if dumperState.registry[v] then return true end
        if envTableSet[v] then return true end
        return false
    end
    return false
end
local function pcallArgsInlineSafe(...)
    for i = 1, select("#", ...) do
        if not pcallArgInlineSafe((select(i, ...))) then return false end
    end
    return true
end

