        -- legacy predicate-table form.  Start with the objects visible to the
        -- emulator, then apply every requested predicate instead of returning
        -- a shape-only placeholder.
        if typeFunction(kind) == "table" and options == nil then
            options, kind = kind, "function"
        end
        options = typeFunction(options) == "table" and options or {}
        local all = exploitFuncs.getgc(true)
        local wantFunctions = kind == nil or kind == "function" or kind == "functions"
