        local function info(fn, what)
            local ok, value = pcall(debugLibrary.info, fn, what)
            return ok and value or nil
        end
        local function countUpvalues(fn)
            if not _vm.getupvalue then return 0 end
            local n = 0
            for i = 1, 1000 do
                local ok, name = pcall(_vm.getupvalue, fn, i)
                if not ok or name == nil or name == "" then break end
                n = n + 1
            end
            return n
        end
