            if not _vm.getconstants then return 0 end
            local ok, constants = pcall(_vm.getconstants, fn)
            return ok and typeFunction(constants) == "table" and #constants or 0
        end
        local function matches(fn)
            if typeFunction(fn) ~= "function" then return false end
            if options.Environment ~= nil then
                local env = exploitFuncs.getfenv(fn)
                if env ~= options.Environment then return false end
            end
            if options.StartLine ~= nil and info(fn, "l") ~= options.StartLine then return false end
            if options.Source ~= nil then
                local src = info(fn, "s")
                if src ~= options.Source and src ~= "@" .. tostring(options.Source) then return false end
            end
            if options.UpvalueCount ~= nil and countUpvalues(fn) ~= options.UpvalueCount then return false end
            if options.ConstantCount ~= nil and countConstants(fn) ~= options.ConstantCount then return false end
