    lz4compress = function(s) 
        emitOutput(string.format("lz4compress(%s)", serializeValue(s)))
        if typeFunction(s) ~= "string" then return s end
        dumperState.lz4_store = dumperState.lz4_store or {}
        local n = #s
        if n == 0 then return "" end
        local seen = {}
        local unique = 0
        for i = 1, math.max(n - 3, 1) do
            local tok = s:sub(i, i + 3)
            if not seen[tok] then
                seen[tok] = true
                unique = unique + 1
            end
        end
        local total = math.max(n - 3, 1)
        local uniqRatio = unique / total
        local ratio
        if uniqRatio < 0.4 then
            ratio = 0.50 + uniqRatio * 0.6
        elseif uniqRatio < 0.7 then
            ratio = 0.74 + (uniqRatio - 0.4) * 0.3
        else
            ratio = 0.83 + (uniqRatio - 0.7) * 0.5
        end
        local outLen = math.max(8, math.floor(n * ratio + 0.5))
        local bytes = {}
        local seed = n
        for j = 1, n do seed = (seed * 31 + s:byte(j)) % 65536 end
        for j = 1, outLen do
            seed = (seed * 1103515245 + 12345) % 2147483648
            bytes[j] = string.char(seed % 256)
        end
        local result = table.concat(bytes)
        dumperState.lz4_store[result] = s
        return result
    end,
    lz4decompress = function(s) 
        emitOutput(string.format("lz4decompress(%s)", serializeValue(s)))
        dumperState.lz4_store = dumperState.lz4_store or {}
        if typeFunction(s) == "string" and dumperState.lz4_store[s] then
            return dumperState.lz4_store[s]
        end
        if typeFunction(s) == "string" and s:sub(1,4) == "LZ4_" then
            return real_base64_decode(s:sub(5))
        end
        return s 
    end,
