    getreg = function()
        local seed = dumperState.reg_seed
        if not seed then
            seed = math.random(100000, 999999)
            dumperState.reg_seed = seed
        end
        local rng = Random.new(seed)
        local function regHex()
            local hi = rng:NextInteger(0, 2^31 - 1)
            local lo = rng:NextInteger(0, 2^31 - 1)
            return string.format("0x%08x%08x", hi, lo)
        end
        local results = {}
        local count = rng:NextInteger(800, 950)
        local threadCount = rng:NextInteger(8, 18)
        local threadAddrs = {}
        for i = 1, threadCount do threadAddrs[i] = regHex() end
        for i = 1, count do
            local kind = rng:NextInteger(1, 100)
            if kind <= 45 then
                local addr = threadAddrs[rng:NextInteger(1, threadCount)]
                local proxy = createProxyObject("thread: " .. addr, false)
                table.insert(results, proxy)
            elseif kind <= 90 then
                local proxy = createProxyObject("table: " .. regHex(), false)
                table.insert(results, proxy)
            elseif kind <= 95 then
                local ls = createProxyObject("LocalScript", false)
                dumperState.property_store[ls] = {ClassName = "LocalScript", Name = "LocalScript"}
                table.insert(results, ls)
            else
                table.insert(results, rng:NextInteger(700, 800))
            end
        end
        table.insert(results, script)
        local hookProxy = createProxyObject("function: " .. regHex(), false)
        table.insert(results, hookProxy)
        if not (INLINER and dumperState.inliner_map) then emitOutput("getreg()") end
        if INLINER and dumperState.inliner_map then
            setmetatable(results, { __iter = makeCountingIterN(#results) })
        end
        return results
    end,
