            end
        end
        if #conns == 0 then table.insert(conns, { Function = function() end, State = true, Connected = true, Enabled = true, Enable = function() end, Disable = function() end, Disconnect = function() end, Defer = function() end, Fire = function() end }) end
        return conns
    end,
