    readfile = function(path)
        local rawPath = (typeFunction(path) == "table" and rawget(path, "__value")) or path
        if rawPath == nil then errorFunction("missing argument #1 for readfile (string expected)", 2) end
        if typeFunction(rawPath) ~= "string" then errorFunction("invalid argument #1 for readfile (string expected, got " .. typeFunction(rawPath) .. ")", 2) end
        local resolvedPath = tostring(rawPath):gsub("%.%.", ""):gsub("^[/\\]+", "")
        resolvedPath = "scripts/" .. resolvedPath
        emitOutput(string.format("readfile(%s)", serializeValue(resolvedPath)))
        dumperState.virtual_fs = dumperState.virtual_fs or {}
        if dumperState.virtual_fs[resolvedPath] then return dumperState.virtual_fs[resolvedPath] end
        local s, c = pcall(function() return fs.readFile(resolvedPath) end)
        if s and type(c) == "string" then return c end
        -- A real executor's readfile throws on a non-existent file; emulators
        -- that quietly return "" are fingerprinted (dtc5/1). Sandbox note: the
        -- path was already constrained to scripts/ (".." stripped, leading
        -- slashes removed) so this can never reach the host's envlogger source.
        errorFunction(tostring(rawPath) .. " does not exist or is not a file", 2)
    end,
    writefile = function(path, contents)
        local rawPath = (typeFunction(path) == "table" and rawget(path, "__value")) or path
        if rawPath == nil then errorFunction("missing argument #1 for writefile (string expected)", 2) end
        if typeFunction(rawPath) ~= "string" then errorFunction("invalid argument #1 for writefile (string expected, got " .. typeFunction(rawPath) .. ")", 2) end
        local rawContents = (typeFunction(contents) == "table" and rawget(contents, "__value")) or contents
        if rawContents == nil then errorFunction("missing argument #2 for writefile (string expected)", 2) end
        if typeFunction(rawContents) ~= "string" then errorFunction("invalid argument #2 for writefile (string expected, got " .. typeFunction(rawContents) .. ")", 2) end
        local resolvedPath = tostring(rawPath):gsub("%.%.", ""):gsub("\\", "/"):gsub("^/+", ""):gsub("/+", "/"):gsub("/+$", "")
        if resolvedPath:match("%.exe$") or resolvedPath:match("%.dll$") or resolvedPath:match("%.scr$") then
            errorFunction("writefile: invalid file extension", 2)
        end
        resolvedPath = "scripts/" .. resolvedPath
        local strContents = rawContents
        if #strContents > 51200 then strContents = string.sub(strContents, 1, 51200) end

        emitOutput(string.format("writefile(%s, <size: %d>)", serializeValue(resolvedPath), #strContents))
        dumperState.virtual_fs = dumperState.virtual_fs or {}
        dumperState.virtual_fs[resolvedPath] = strContents
        dumperState.virtual_fs_folders = dumperState.virtual_fs_folders or {}
        do
            local _parent = resolvedPath:match("^(.*)/[^/]+$")
            while _parent and _parent ~= "" and _parent ~= "scripts" do
                dumperState.virtual_fs_folders[_parent] = true
                _parent = _parent:match("^(.*)/[^/]+$")
            end
        end
        pcall(function()
            local parts = {}
            for seg in resolvedPath:gmatch("[^/]+") do table.insert(parts, seg) end
            local cur = ""
            for i = 1, #parts - 1 do
                cur = (i == 1) and parts[i] or (cur .. "/" .. parts[i])
                if not fs.isDir(cur) then fs.writeDir(cur) end
            end
            fs.writeFile(resolvedPath, strContents)
        end)
    end,
    appendfile = function(path, contents)
        local rawPath = (typeFunction(path) == "table" and rawget(path, "__value")) or path
        if rawPath == nil then errorFunction("missing argument #1 for appendfile (string expected)", 2) end
        if typeFunction(rawPath) ~= "string" then errorFunction("invalid argument #1 for appendfile (string expected, got " .. typeFunction(rawPath) .. ")", 2) end
        local rawContents = (typeFunction(contents) == "table" and rawget(contents, "__value")) or contents
        if rawContents == nil then errorFunction("missing argument #2 for appendfile (string expected)", 2) end
        if typeFunction(rawContents) ~= "string" then errorFunction("invalid argument #2 for appendfile (string expected, got " .. typeFunction(rawContents) .. ")", 2) end
        local resolvedPath = tostring(rawPath):gsub("%.%.", ""):gsub("^[/\\]+", "")
        resolvedPath = "scripts/" .. resolvedPath
        local strContents = rawContents

        emitOutput(string.format("appendfile(%s, <size: %d>)", serializeValue(resolvedPath), #strContents))
        dumperState.virtual_fs = dumperState.virtual_fs or {}
        local existing = dumperState.virtual_fs[resolvedPath] or (pcall(fs.readFile, resolvedPath) and fs.readFile(resolvedPath) or "")
        local newContents = existing .. strContents
        if #newContents > 51200 then newContents = string.sub(newContents, 1, 51200) end
        dumperState.virtual_fs[resolvedPath] = newContents
        pcall(function()
            local parts = {}
            for seg in resolvedPath:gmatch("[^/]+") do table.insert(parts, seg) end
            local cur = ""
            for i = 1, #parts - 1 do
                cur = (i == 1) and parts[i] or (cur .. "/" .. parts[i])
                if not fs.isDir(cur) then fs.writeDir(cur) end
            end
            fs.writeFile(resolvedPath, newContents)
        end)
    end,
    dofile = function(path)
        local rawPath = (typeFunction(path) == "table" and rawget(path, "__value")) or path
        if rawPath == nil then errorFunction("missing argument #1 for dofile (string expected)", 2) end
        if typeFunction(rawPath) ~= "string" then errorFunction("invalid argument #1 for dofile (string expected, got " .. typeFunction(rawPath) .. ")", 2) end
