    loadfile = function(path)
        local rawPath = (typeFunction(path) == "table" and rawget(path, "__value")) or path
        if rawPath == nil then errorFunction("missing argument #1 for loadfile (string expected)", 2) end
        if typeFunction(rawPath) ~= "string" then errorFunction("invalid argument #1 for loadfile (string expected, got " .. typeFunction(rawPath) .. ")", 2) end
        local resolvedPath = tostring(rawPath):gsub("%.%.", ""):gsub("^[/\\]+", "")
        resolvedPath = "scripts/" .. resolvedPath
        emitOutput(string.format("loadfile(%s)", serializeValue(resolvedPath)))
        -- Never compile the host's own sources. These are reported exactly like
        -- a missing file so the block is indistinguishable from "not found" and
        -- cannot be used to confirm/leak the envlogger source (the RCE concern
        -- in dtc5): loadfile('envlogger.lua') just errors "does not exist".
        if resolvedPath:match("envlogger") or resolvedPath:match("bot") or resolvedPath:match("lune") then
            errorFunction(tostring(rawPath) .. " does not exist or is not a file", 2)
        end
        local content = dumperState.virtual_fs and dumperState.virtual_fs[resolvedPath]
        if not content then
            local success, fileData = pcall(function() return fs.readFile(resolvedPath) end)
            if success and type(fileData) == "string" then content = fileData end
        end
        -- Real executors throw when the target file does not exist, so a probe
        -- like pcall(loadfile, "missing.lol") fails rather than succeeding with
        -- (nil, err) -- which an emulator returning two values would leak (dtc5/2).
        if content == nil then
            errorFunction(tostring(rawPath) .. " does not exist or is not a file", 2)
        end
        return loadstring(content, resolvedPath)
    end,
    listfiles = function(folder)
        local rawFolder = (typeFunction(folder) == "table" and rawget(folder, "__value")) or folder
        if rawFolder == nil then errorFunction("missing argument #1 for listfiles (string expected)", 2) end
        if typeFunction(rawFolder) ~= "string" then errorFunction("invalid argument #1 for listfiles (string expected, got " .. typeFunction(rawFolder) .. ")", 2) end
        local resolvedFolder = tostring(rawFolder):gsub("%.%.", ""):gsub("\\", "/"):gsub("^/+", ""):gsub("/+", "/"):gsub("/+$", "")
        resolvedFolder = resolvedFolder == "" and "scripts" or ("scripts/" .. resolvedFolder)
        emitOutput(string.format("listfiles(%s)", serializeValue(resolvedFolder)))
        local files = {}
        local seen = {}
        local prefixPattern = "^" .. resolvedFolder:gsub("[%-%.%+%*%?%[%]%(%)%^%$%%]", "%%%0")
        if dumperState.virtual_fs then
            for k, _ in pairs(dumperState.virtual_fs) do
                if k:match(prefixPattern) and not seen[k] then
                    seen[k] = true
                    table.insert(files, k)
                end
            end
        end
        if dumperState.virtual_fs_folders then
            for k, _ in pairs(dumperState.virtual_fs_folders) do
                if k:match(prefixPattern) and k ~= resolvedFolder and not seen[k] then
                    seen[k] = true
                    table.insert(files, k)
                end
            end
        end
        pcall(function()
            if fs.isDir(resolvedFolder) then
                for _, name in ipairs(fs.readDir(resolvedFolder)) do
                    local full = resolvedFolder .. "/" .. name
                    if not seen[full] then
                        seen[full] = true
                        table.insert(files, full)
                    end
                end
            end
        end)
        --if #files == 0 then return {resolvedFolder .. "/mock1.txt"} end
        return files
    end,
