                local ln = lines[li]
                for w in ln:gmatch("[%a_][%w_]*") do
                    if w=="function" or w=="do" or w=="if" or w=="for" or w=="while" then depth=depth+1
                    elseif w=="end" or w=="until" then depth=depth-1 end
                end
                -- collect quoted string literals
                for s in ln:gmatch('"([^"]*)"') do
                    if not seen[s] then seen[s]=true; table.insert(consts, s) end
                end
                for s in ln:gmatch("'([^']*)'") do
                    if not seen[s] then seen[s]=true; table.insert(consts, s) end
                end
                if li > fn_line and depth <= 0 then break end
            end
            return consts
        end,
        getprotos = function(func) return exploitFuncs.getprotos(func) end,
        info = function(f, options, ...)
            -- [PATCH] Thread form debug.info(thread, level, options): delegate to
            -- the real engine so the reported frame functions are the genuine
            -- suspended-stack closures (rawequal to the script's own A/B -- dtc102).
            if typeFunction(f) == "thread" and typeFunction(options) == "number" then
                local opts = ...
                local packed = table.pack(pcall(debugLibrary.info, f, options, opts))
                if packed[1] then return table.unpack(packed, 2, packed.n) end
                return nil
            end
            -- The real debug.info only accepts a stack level (number), a
            -- function, or a thread as its first argument; anything else (nil
            -- from a dead coroutine's empty return, a string, a table, ...)
            -- raises an error. Mirror that so anti-tamper probes such as
            -- pcall(debug.info, coroutine.wrap(function()end)(), 's') see the
            -- expected failure instead of a silently-nil result.
            do
                local _tf = typeFunction(f)
                -- Instance-method proxies are tables under the hood but present
                -- as real (C) functions to the sandbox, so debug.info must
                -- accept them and report [C] just like any engine method.
                if _tf ~= "function" and _tf ~= "number" and _tf ~= "thread"
                   and not (_tf == "table" and rawget(f, "__is_method")) then
                    error("invalid argument #1 to 'info' (function or level expected)", 2)
                end
                if _tf == "number" and f < 0 then
                    error("invalid argument #1 to 'info' (level can't be negative)", 2)
                end
                if options == nil then
                    error("missing argument #2 to 'info' (string expected)", 2)
                end
                -- [PATCH:BASELIB] unknown option letters raise like native Luau
                if typeFunction(options) == "string" and options:find("[^slnaf]") then
                    error("invalid argument #2 to 'info' (invalid option)", 2)
                end
            end
            -- Number (stack level) form: map the script-relative level to the
            -- real Luau stack level by walking frames that belong to the running
            -- script (skipping our own wrapper frames). Without this, level 1
            -- resolves to this wrapper -- whose source the dumper treats as
            -- "[C]" -- so debug.info(1,"s")/("l") leak a [C]/-1 that a real
            -- engine never reports for the caller's own frame (dtc87/88/154/158).
            if typeFunction(f) == "number" and type(options) == "string" then
                local want = dumperState.script_source
                local realLevel
                if want ~= nil and f >= 1 then
                    local seen = 0
                    for L = 1, 80 do
                        local okS, src = pcall(debugLibrary.info, L, "s")
                        if not okS or src == nil then break end
                        if src == want then
                            seen = seen + 1
                            if seen == f then realLevel = L break end
                        end
                    end
                end
                if realLevel then
                    local res = {}
                    for i = 1, #options do
                        local c = options:sub(i, i)
                        if c == "s" then
                            local okS, src = pcall(debugLibrary.info, realLevel, "s")
                            table.insert(res, (okS and src) or want)
                        elseif c == "l" then
                            local okL, line = pcall(debugLibrary.info, realLevel, "l")
                            table.insert(res, (okL and line) or -1)
                        elseif c == "n" then
                            local okN, name = pcall(debugLibrary.info, realLevel, "n")
                            table.insert(res, (okN and name) or "")
                        elseif c == "a" then
                            local okA, np, va = pcall(debugLibrary.info, realLevel, "a")
                            table.insert(res, (okA and np) or 0)
                            table.insert(res, (okA and va) or false)
                        elseif c == "f" then
                            local okF, fn = pcall(debugLibrary.info, realLevel, "f")
                            table.insert(res, (okF and fn) or nil)
                        else
                            table.insert(res, nil)
                        end
                    end
                    return table.unpack(res)
                end
            end
            local cFuncNames = {
                [_G.print] = "print", [_G.warn] = "warn", [_G.error] = "error",
                [_G.tostring] = "tostring", [_G.tonumber] = "tonumber",
                [_G.type] = "type", [_G.typeof] = "typeof",
                [_G.pcall] = "pcall", [_G.xpcall] = "xpcall", [_G.select] = "select",
                [_G.pairs] = "pairs", [_G.ipairs] = "ipairs", [_G.next] = "next",
                [_G.rawget] = "rawget", [_G.rawset] = "rawset", [_G.rawequal] = "rawequal",
                [_G.rawlen] = "rawlen", [_G.unpack] = "unpack",
                [_G.setmetatable] = "setmetatable", [_G.getmetatable] = "getmetatable",
                [_G.require] = "require", [_G.assert] = "assert",
                [_G.loadstring] = "loadstring",
                [_G.getfenv] = "getfenv", [_G.setfenv] = "setfenv",
                [exploitFuncs and exploitFuncs.getfenv] = "getfenv",
                [exploitFuncs and exploitFuncs.setfenv] = "setfenv",
                [exploitFuncs and exploitFuncs.getgenv] = "getgenv",
                [exploitFuncs and exploitFuncs.getrenv] = "getrenv",
                [_G.math.abs] = "abs", [_G.math.floor] = "floor", [_G.math.ceil] = "ceil",
                [_G.math.sqrt] = "sqrt", [_G.math.max] = "max", [_G.math.min] = "min",
                [_G.math.clamp] = "clamp", [_G.math.sign] = "sign",
                [_G.math.round] = "round", [_G.math.rad] = "rad", [_G.math.deg] = "deg",
                [_G.math.noise] = "noise", [_G.math.atan2] = "atan2", [_G.math.asin] = "asin",
                [_G.math.acos] = "acos", [_G.math.atan] = "atan",
                [_G.math.random] = "random", [_G.math.sin] = "sin", [_G.math.cos] = "cos",
                [_G.math.tan] = "tan", [_G.math.exp] = "exp", [_G.math.log] = "log",
                [_G.math.pow] = "pow", [_G.math.fmod] = "fmod", [_G.math.modf] = "modf",
                [_G.math.randomseed] = "randomseed", [_G.math.huge] = nil,
                [_G.string.byte] = "byte", [_G.string.char] = "char",
                [_G.string.find] = "find", [_G.string.sub] = "sub",
                [_G.string.format] = "format", [_G.string.lower] = "lower",
                [_G.string.upper] = "upper", [_G.string.len] = "len",
                [_G.string.rep] = "rep", [_G.string.gsub] = "gsub", [_G.string.match] = "match",
                [_G.table.insert] = "insert", [_G.table.remove] = "remove",
                [_G.table.concat] = "concat", [_G.table.unpack] = "unpack",
                [_G.table.pack] = "pack", [_G.table.sort] = "sort",
            }
            local cFuncArity = {
                [_G.print] = {0, true}, [_G.warn] = {0, true}, [_G.error] = {2, false},
                [_G.tostring] = {0, true}, [_G.tonumber] = {2, false},
                [_G.type] = {1, false}, [_G.typeof] = {1, false},
                [_G.pcall] = {1, true}, [_G.xpcall] = {2, true}, [_G.select] = {1, true},
                [_G.pairs] = {1, false}, [_G.ipairs] = {1, false}, [_G.next] = {2, false},
                [_G.rawget] = {2, false}, [_G.rawset] = {3, false}, [_G.rawequal] = {2, false},
                [_G.rawlen] = {1, false}, [_G.unpack] = {1, true},
                [_G.setmetatable] = {2, false}, [_G.getmetatable] = {1, false},
                [_G.require] = {1, false}, [_G.assert] = {1, true},
                [_G.loadstring] = {2, false},
                [_G.getfenv] = {1, false}, [_G.setfenv] = {2, false},
                [exploitFuncs and exploitFuncs.getfenv] = {1, false},
                [exploitFuncs and exploitFuncs.setfenv] = {2, false},
                [exploitFuncs and exploitFuncs.getgenv] = {0, false},
                [exploitFuncs and exploitFuncs.getrenv] = {0, false},
                [_G.math.abs] = {1, false}, [_G.math.floor] = {1, false},
                [_G.math.ceil] = {1, false}, [_G.math.sqrt] = {1, false},
                [_G.math.max] = {1, true}, [_G.math.min] = {1, true},
                [_G.math.clamp] = {3, false}, [_G.math.sign] = {1, false},
                [_G.math.round] = {1, false}, [_G.math.rad] = {1, false}, [_G.math.deg] = {1, false},
                [_G.math.noise] = {3, false}, [_G.math.atan2] = {2, false}, [_G.math.asin] = {1, false},
                [_G.math.acos] = {1, false}, [_G.math.atan] = {1, false},
                [_G.string.byte] = {3, false}, [_G.string.char] = {0, true},
                [_G.string.find] = {4, false}, [_G.string.sub] = {3, false},
                [_G.string.format] = {1, true}, [_G.string.lower] = {1, false},
                [_G.string.upper] = {1, false}, [_G.string.len] = {1, false},
                [_G.string.rep] = {3, false}, [_G.string.gsub] = {4, false},
                [_G.string.match] = {3, false},
                [_G.table.insert] = {3, false}, [_G.table.remove] = {2, false},
                [_G.table.concat] = {4, false}, [_G.table.unpack] = {3, false},
                [_G.table.pack] = {0, true}, [_G.table.sort] = {2, false},
            }

            local function resolveBuiltin(fn)
                if typeFunction(fn) ~= "function" then return nil end
                if cFuncNames[fn] then return cFuncNames[fn], cFuncArity[fn] end
                -- coroutine.wrap results should appear as C closures
                if _coroutineWrapFns and _coroutineWrapFns[fn] then
                    return "wrap", {1, false}
                end
                local ok, src = pcall(debugLibrary.info, fn, "s")
                local isC = ok and type(src) == "string" and (src == "[C]" or src:match("^%[C"))
                -- Only C closures may be reported as builtins. A named *Luau*
                -- closure (e.g. `local function f(a,b,c)`) also has a non-empty
                -- "n" name, but it must keep its real source/line/nparams so
                -- anti-tamper probes (debug.info nparams / linedefined) see the
                -- genuine Luau values rather than a fabricated {0, vararg, [C]}.
                local ok2, name = pcall(debugLibrary.info, fn, "n")
                if isC and ok2 and type(name) == "string" and #name > 0 then
                    local arity = cFuncArity[fn] or {0, true}
                    local commonArity = {
                        print = {0, true}, warn = {0, true}, error = {2, false},
                        tostring = {0, true}, tonumber = {2, false},
                        type = {1, false}, typeof = {1, false},
                        pcall = {1, true}, xpcall = {2, true}, select = {1, true},
                        pairs = {1, false}, ipairs = {1, false}, next = {2, false},
                        rawget = {2, false}, rawset = {3, false}, rawequal = {2, false},
                        rawlen = {1, false}, unpack = {1, true},
                        setmetatable = {2, false}, getmetatable = {1, false},
                        require = {1, false}, assert = {1, true},
                        loadstring = {2, false}, load = {2, false},
                        getfenv = {1, false}, setfenv = {2, false},
                        getgenv = {0, false}, getrenv = {0, false},
                    }
                    if commonArity[name] then arity = commonArity[name] end
                    return name, arity
                end
                if isC then
                    return "", {0, true}
                end
                return nil
            end

            local function _dbgCName(fn)
                local nm
                if typeFunction(fn) == "table" then
                    local reg = dumperState.registry[fn]
                    if typeFunction(reg) == "string" then nm = reg:match("([%a_][%w_]*)$") end
                else
                    local q = resolveBuiltinName(fn)
                    if typeFunction(q) == "string" then nm = q:match("([^%.]+)$") end
                    if nm == nil then
                        -- constructors and other members of the datatype tables (Instance.new, Vector3.new, ...)
                        local cm = dumperState._dbg_ctor_map
                        if cm == nil then
                            cm = {}
                            local function scanTbl(t)
                                if typeFunction(t) ~= "table" then return end
                                for k, v in nextFunction, t do
                                    if typeFunction(k) == "string" and typeFunction(v) == "table" then
                                        for k2, v2 in nextFunction, v do
                                            if typeFunction(k2) == "string" and typeFunction(v2) == "function" then
                                                local old = cm[v2]
                                                if old == nil or k2 == "new" or (old ~= "new" and k2 < old) then cm[v2] = k2 end
                                            end
                                        end
                                    end
                                end
                            end
                            pcallFunction(scanTbl, _G)
                            pcallFunction(scanTbl, dumperState.script_env)
                            dumperState._dbg_ctor_map = cm
                        end
                        nm = cm[fn]
                    end
                    if nm == nil then
                        local reg = dumperState.registry[fn]
                        if typeFunction(reg) == "string" then nm = reg:match("^[%a_][%w_%.]*%.([%a_][%w_]*)$") end
                    end
                end
                return nm
            end
            local resolvedName, resolvedArity
            if typeFunction(f) == "function" and dumperState.builtin_tags and dumperState.builtin_tags[f] then
                local tag = dumperState.builtin_tags[f]
                resolvedName = tag.name
                resolvedArity = tag.arity
            else
                resolvedName, resolvedArity = resolveBuiltin(f)
            end
            local isKnownC = resolvedName ~= nil
            local isBuiltinLike = (typeFunction(f) == "table" and rawget(f, "__is_method")) or
                                  (type(f) == "function" and tostring(f):match("builtin")) or
                                  isKnownC

            if isBuiltinLike then
                if not options then return {source = "=[C]", what = "C", name = resolvedName or cFuncNames[f] or "unknown", short_src = "[C]", currentline = -1, nups = 0, numparams = 0, is_vararg = 1, func = f} end
                local res = {}
                for i = 1, #options do
                    local c = options:sub(i, i)
                    if c == "s" then table.insert(res, "[C]")
                    elseif c == "n" then table.insert(res, (not (_coroutineWrapFns and _coroutineWrapFns[f]) and (resolvedName or cFuncNames[f] or _dbgCName(f))) or "")
                    elseif c == "a" then
                        table.insert(res, 0)
                        table.insert(res, true)
                    elseif c == "l" then table.insert(res, -1)
                    elseif c == "f" then table.insert(res, f)
                    else table.insert(res, nil) end
                end
                return table.unpack(res)
            end
            local results = {pcall(debugLibrary.info, f, options)}
            if not results[1] then return nil end
            -- Decide wrapped/C status from the function's actual source, not just
            -- the requested fields -- so debug.info(fn, "l") on its own (a numeric
            -- result) is consistent with debug.info(fn, "s") and reports -1 for an
            -- emulated C function (eUNC table.find check).
            local looksWrapped = false
            local _srcOk, _srcVal = pcall(debugLibrary.info, f, "s")
            if _srcOk and typeFunction(_srcVal) == "string"
               and (_srcVal:match("envlogger") or _srcVal:match("lune") or _srcVal:match("container")
                    or _srcVal:match("unpack_fn") or _srcVal:match("25ms")
                    or _srcVal == "[C]" or _srcVal:match("^%[C")) then
                looksWrapped = true
            end
            for i = 2, #results do
                if typeFunction(results[i]) == "string" and (results[i]:match("envlogger") or results[i]:match("lune") or results[i]:match("container") or results[i]:match("unpack_fn") or results[i]:match("25ms")) then
                    looksWrapped = true
                end
            end
            if looksWrapped and type(options) == "string" then
                local res = {}
                for i = 1, #options do
                    local c = options:sub(i, i)
                    if c == "s" then table.insert(res, "[C]")
                    elseif c == "n" then table.insert(res, (not (_coroutineWrapFns and _coroutineWrapFns[f]) and _dbgCName(f)) or "")
                    elseif c == "l" then table.insert(res, -1)
                    elseif c == "a" then table.insert(res, 0); table.insert(res, true)
                    elseif c == "f" then table.insert(res, f)
                    else table.insert(res, nil) end
                end
                return table.unpack(res)
            end
            return table.unpack(results, 2)
        end,
        setconstant = function(func, i, val) return exploitFuncs.setconstant(func, i, val) end,
        getregistry = function() return exploitFuncs.getreg() end,
        resetmemorycategory = function() end
    },
    rconsoleprint = function(s) end,
    rconsoleclear = function() end,
    rconsolecreate = function() end,
    rconsoledestroy = function() end,
    rconsoleinput = function() return "" end,
    rconsoleinfo = function(s) end,
    rconsolewarn = function(s) end,
    rconsoleerr = function(s) end,
    rconsolename = function(name) end,
    printconsole = function(s) end,
    setfflag = function(flag, val) end,
    getfflag = function(flag) return "" end,
    setfpscap = function(cap) 
        local capVal = (type(cap) == "table" and rawget(cap, "__value")) or cap
        emitOutput(string.format("setfpscap(%s)", serializeValue(capVal))) 
        local n = toNumberFunction(capVal)
        if n and n > 0 then
            dumperState.fps_cap = n
        else
            dumperState.fps_cap = 240
        end
    end,
    getfpscap = function() return dumperState.fps_cap or 240 end,
    isnetworkowner = function(part) return true end,
    gethiddenproperty = function(obj, prop)
        if typeFunction(obj) ~= "table" and typeFunction(obj) ~= "userdata" then
            error("invalid argument #1 to 'gethiddenproperty' (Instance expected)", 2)
        end
        if not isProxy(obj) then
            error("invalid argument #1 to 'gethiddenproperty' (Instance expected)", 2)
        end
        emitOutput(string.format("gethiddenproperty(%s, %s)", serializeValue(obj), serializeValue(prop)))
        -- Return the genuine typed property value with isHidden=false for a
        -- readable property (e.g. Name -> the instance's name, Position -> a
        -- UDim2, AbsolutePosition -> a Vector2). Only fall back to the hidden
        -- placeholder when the property cannot be resolved (dtc130..137,165,166).
        local ok, val = pcall(function() return obj[prop] end)
        if ok and val ~= nil then
            return val, false
        end
        -- [PATCH] The property is genuinely hidden/security-gated (e.g. DataCost,
        -- an int). Resolve its real value-type from the API dump so the returned
        -- value has the correct typeof (not a placeholder string -- dtc5).
        local cn = robloxApi.resolveClass(obj,
            dumperState.registry[obj], (dumperState.property_store[obj] and dumperState.property_store[obj].ClassName))
        if cn and robloxApi.hiddenprops then
            local c, g = cn, 0
            while c and g < 64 do
                local set = robloxApi.hiddenprops[c]
                if set and set[prop] ~= nil then return robloxApi.typedDefault(set[prop], prop, c), true end
                local set2 = robloxApi.proptypes[c]
                if set2 and set2[prop] ~= nil then return robloxApi.typedDefault(set2[prop], prop, c), true end
                c = robloxApi.psuper and robloxApi.psuper[c]
                g = g + 1
            end
        end
        return "test", true
    end,
    sethiddenproperty = function(obj, prop, val)
        emitOutput(string.format("sethiddenproperty(%s, %s, %s)", serializeValue(obj), serializeValue(prop), serializeValue(val)))
        dumperState.property_store[obj] = dumperState.property_store[obj] or {}
        local oldVal = dumperState.property_store[obj][prop]
        dumperState.property_store[obj][prop] = val
        return true, oldVal
    end,
    setsimulationradius = function(radius, maxRadius) emitOutput(string.format("setsimulationradius(%s%s)", serializeValue(radius), maxRadius and ", " .. serializeValue(maxRadius) or "")) end,
    getspecialinfo = function(instance) return {} end,
    saveinstance = function(options) emitOutput(string.format("saveinstance(%s)", serializeValue(options or {}))) end,
    decompile = function(scr)
        emitOutput(string.format("decompile(%s)", serializeValue(scr)))
        return "-- failed to get script bytecode"
    end,
    getscriptbytecode = function(scr)
        if scr == nil then error("Argument 1 missing or nil", 2) end
        local isCreated = typeFunction(scr) == "table" and rawget(scr, "__created_instance")
        if isCreated then return nil end
        local scrName = (typeFunction(scr) == "table" and dumperState.registry[scr]) or tostring(scr)
        emitOutput(string.format("getscriptbytecode(%s)", serializeValue(scrName)))
        -- Real bytecode is a non-trivial binary blob; emulate with a stable,
        -- engine-version-prefixed pseudo-bytecode well over the 32-byte floor
        -- so it never equals the literal "bytecode" (dtc107, 108).
        return string.char(6) .. "Luau" .. hexHash("bytecode:" .. scrName, 256)
    end,
    getscripthash = function(scr)
        emitOutput(string.format("getscripthash(%s)", serializeValue(scr)))
        -- sUNC: hex-represented SHA256 (64 hex chars) of the script's bytecode.
        local scrName = (typeFunction(scr) == "table" and dumperState.registry[scr]) or tostring(scr)
        return hexHash("scripthash:" .. scrName, 64)
    end,
    getcallingscript = function()
        emitOutput("getcallingscript()")
        return script
    end,
    getloadedmodules = function()
        emitOutput("getloadedmodules()")
        if not dumperState.animate_script then
            local animateProxy = createProxyObject("Animate", false)
            dumperState.property_store[animateProxy] = {ClassName = "LocalScript", Name = "Animate"}
            dumperState.animate_script = animateProxy
        end
        return { game }
    end,
    getrunningscripts = function()
        emitOutput("getrunningscripts()")
        if not dumperState.animate_script then
            local animProxy = createProxyObject("Animate", false)
            dumperState.property_store[animProxy] = {ClassName = "LocalScript", Name = "Animate"}
            dumperState.registry[animProxy] = "Animate"
            dumperState.animate_script = animProxy
        end
        local results = {}
        for proxy, name in pairsFunction(dumperState.registry) do
            if typeFunction(proxy) == "table" and not rawget(proxy, "__created_instance") then
                local props = dumperState.property_store[proxy]
                if props and (props.ClassName == "LocalScript" or props.ClassName == "Script" or props.ClassName == "ModuleScript") then
                    table.insert(results, proxy)
                end
            end
        end
        table.insert(results, script)
        return results
    end,
    getscripts = function()
        emitOutput("getscripts()")
        return { script }
    end,
    getinstances = function()
        local proxy = createProxyObject("InstanceList", false)
        local varName = registerVariable(proxy, "instances")
        emitOutput(string.format("local %s = getinstances()", varName))
        local p1 = createProxyObject("Part1", false)
        dumperState.property_store[p1] = {ClassName = "Part"}
        return { game, workspace, p1 }
    end,
    getnilinstances = function()
        emitOutput("getnilinstances()")
        local p1 = createProxyObject("Part", false)
        dumperState.created_instances = dumperState.created_instances or setmetatable({}, {__mode = "k"})
        dumperState.created_instances[p1] = true
        dumperState.property_store[p1] = {ClassName = "Part"}
        return { p1 }
    end,
    setrawmetatable = function(obj, mt)
        emitOutput(string.format("setrawmetatable(%s, %s)", serializeValue(obj), serializeValue(mt)))
        if typeFunction(obj) == "table" and typeFunction(mt) == "table" and not isProxyTable(obj) then
            -- A plain setmetatable() raises on a protected (__metatable) table;
            -- setrawmetatable must succeed regardless. If we recorded the live
            -- metatable, mutate it in place so the new __index/__metatable take
            -- effect without needing to "replace" the locked metatable.
            local ref = dumperState.metatable_ref and dumperState.metatable_ref[obj]
            local ok = pcall(setmetatable, obj, mt)
            if not ok and typeFunction(ref) == "table" then
                for k in pairs(ref) do ref[k] = nil end
                for k, v in pairs(mt) do ref[k] = v end
            elseif ok then
                dumperState.metatable_ref = dumperState.metatable_ref or setmetatable({}, {__mode = "k"})
                dumperState.metatable_ref[obj] = mt
            end
        end
        return true
    end,
    cloneref = function(obj)
        -- Real executors reject a non-Instance argument (the error text uses a
        -- capital "Instance", matching Roblox's reflection messages -- dtc10).
        if not isProxy(obj) then
            error("invalid argument #1 for cloneref (Instance expected, got " .. typeFunction(obj) .. ")", 2)
        end
        emitOutput(string.format("cloneref(%s)", serializeValue(obj)))
        local objReg = dumperState.registry[obj] or "clone"
        local clone = createProxyObject(objReg, false)
        -- give clone a unique registry entry so (~=) comparison with original returns true
        dumperState.registry[clone] = objReg .. "_cloneref_" .. tostring(math.random(1000, 9999))
        dumperState.property_store[clone] = dumperState.property_store[obj]
        dumperState.parent_map[clone] = dumperState.parent_map[obj]
        if rawget(obj, "__created_instance") then
            rawset(clone, "__created_instance", true)
        end
        if rawget(obj, "__is_signal") then
            rawset(clone, "__is_signal", true)
        end
        -- cloneref returns a distinct reference (clone ~= obj) that nonetheless
        -- points at the SAME underlying instance, so compareinstances(clone,
        -- obj) must be true (dtc142..146). Record the canonical origin.
        dumperState.cloneref_origin = dumperState.cloneref_origin or setmetatable({}, {__mode = "k"})
        dumperState.cloneref_origin[clone] = dumperState.cloneref_origin[obj] or obj
        return clone
    end,
    clonefunction = function(f)
        -- Real executors reject a non-function argument with this exact message
        -- rather than passing it through (dtc107).
        if typeFunction(f) ~= "function" then
            error("invalid argument #1 to 'clonefunction' (function expected, got " .. typeFunction(f) .. ")", 2)
        end
        emitOutput(string.format("clonefunction(%s)", serializeValue(f)))
        local clone = function(...) return f(...) end
        -- clonefunction preserves the closure type: cloning an L-closure yields
        -- an L-closure, cloning a C-closure yields a C-closure. The clone is
        -- itself defined in host source, so classify it explicitly via the
        -- tracking tables that islclosure/iscclosure consult first (dtc101..103,
        -- 169).
        if exploitFuncs.islclosure(f) then
            dumperState.lclosures = dumperState.lclosures or setmetatable({}, {__mode = "k"})
            dumperState.lclosures[clone] = true
        else
            dumperState.cclosures = dumperState.cclosures or {}
            dumperState.cclosures[clone] = true
        end
        return clone
    end,
    compareinstances = function(a, b)
        emitOutput(string.format("compareinstances(%s, %s)", serializeValue(a), serializeValue(b)))
        -- Resolve cloneref clones back to their canonical instance so a clone
        -- and its original compare as the same instance (dtc142..146).
        local origin = dumperState.cloneref_origin
        local ca = (origin and origin[a]) or a
        local cb = (origin and origin[b]) or b
        return rawEqualFunction(ca, cb) or ca == cb
    end,
    restorefunction = function(f)
        emitOutput(string.format("restorefunction(%s)", dumperState.registry[f] or "func"))
        dumperState.hooked_functions = dumperState.hooked_functions or {}
        dumperState.hook_reverse = dumperState.hook_reverse or {}
        dumperState.hook_records = dumperState.hook_records or {}

        -- sUNC: restores a hooked function back to the very first original,
        -- even if it was hooked multiple times. Accept either the current hook
        -- value (what the name now resolves to) or the original reference.
        local trueOriginal = dumperState.hook_reverse[f]
        if not trueOriginal and dumperState.hook_records[f] then trueOriginal = f end
        if not trueOriginal then
            error("restorefunction: function is not hooked", 2)
        end

        local rec = dumperState.hook_records[trueOriginal]
        if rec then
            for _, loc in ipairs(rec.locations) do
                if loc.tbl ~= nil then
                    loc.tbl[loc.key] = trueOriginal
