    local _origGetinfo = exploitFuncs.debug.getinfo
    exploitFuncs.debug.getinfo = function(f, options)
        -- dtc3: return *real* frame information for the running script so
        -- anti-tamper checks like debug.getinfo(1,"f").func == self and the
        -- what/source fields all line up. The real debug.getinfo errors on a
        -- non-function/non-number argument, so we do too (dtc3/4).
        local tf = typeFunction(f)
        if tf ~= "function" and tf ~= "number"
           and not (tf == "table" and rawget(f, "__is_method")) then
            error("invalid argument #1 (function or number expected)", 2)
        end
        if tf == "table" and rawget(f, "__is_method") then
