        if tf == "number" then
            -- Map the script-relative level to a real stack level by walking
            -- the live stack and counting frames that belong to the running
            -- script (skipping our own wrapper / C frames). NOTE: the scan and
            -- the field reads must run at the same depth (this function body),
            -- so no helper calls in between or the levels would shift.
            local want = dumperState.script_source
            local realLevel
            if want ~= nil and f >= 1 then
                local seen = 0
                for L = 1, 80 do
                    local okS, src = pcall(debugLibrary.info, L, "s")
                    if not okS or src == nil then break end
                    if src == want then
                        seen = seen + 1
                        if seen == f then realLevel = L break end
                    end
                end
            end
            if realLevel then
                local okF, fn = pcall(debugLibrary.info, realLevel, "f")
                local okS, src = pcall(debugLibrary.info, realLevel, "s")
                local okL, line = pcall(debugLibrary.info, realLevel, "l")
                local okN, name = pcall(debugLibrary.info, realLevel, "n")
                local okA, np, va = pcall(debugLibrary.info, realLevel, "a")
                result = {
                    func = (okF and typeFunction(fn) == "function") and fn or nil,
                    source = "@" .. ((okS and src) or "?"),
                    short_src = (okS and src) or "?",
                    currentline = (okL and line) or -1,
                    name = (okN and name) or "",
                    what = "Lua",
                    nups = 0,
                    numparams = (okA and np) or 0,
                    is_vararg = (okA and va) and 1 or 0,
                    linedefined = -1,
                }
            else
                local ok, errOrRes = pcall(_origGetinfo, f, options)
                result = ok and errOrRes or nil
            end
        else
            -- A function was passed: describe that function directly.
            local okS, src = pcall(debugLibrary.info, f, "s")
            local okN, name = pcall(debugLibrary.info, f, "n")
            local okA, np, va = pcall(debugLibrary.info, f, "a")
            local okL, ld = pcall(debugLibrary.info, f, "l")
            -- A function is C if its source is [C], if it is a registered engine
            -- builtin, or if it is one of our host-side wrappers (print/warn/...
            -- and other functions defined in the envlogger/lune source). Real
            -- Roblox reports what=="C" for these (dtc4).
            local isWrapped = okS and type(src) == "string"
                and (src:match("envlogger") or src:match("lune") or src:match("container")
                     or src:match("unpack_fn") or src:match("25ms"))
            local isTaggedBuiltin = dumperState.builtin_tags ~= nil and dumperState.builtin_tags[f] ~= nil
            local isNamedBuiltin = (f == _G.print or f == _G.warn or f == _G.error
                or f == print or f == warn)
            local isC = (okS and (src == "[C]" or tostring(src):match("^%[C") ~= nil))
                or isWrapped or isTaggedBuiltin or isNamedBuiltin
            -- For a function argument, debug.info(f, "l") yields its *definition*
            -- line (linedefined), which must be the genuine positive line for a
            -- Luau closure -- anti-tamper probes read linedefined/lastlinedefined
            -- and reject a fabricated -1.
            local realLine = (not isC and okL and type(ld) == "number") and ld or -1
            result = {
                func = f,
                source = isC and "[C]" or ("@" .. ((okS and src) or "?")),
                short_src = isC and "[C]" or ((okS and src) or "?"),
                currentline = isC and -1 or realLine,
                name = (okN and name) or "",
                namewhat = (okN and type(name) == "string" and #name > 0) and "global" or "",
                what = isC and "C" or "Lua",
                nups = 0,
                numparams = (okA and np) or 0,
                is_vararg = (okA and va) and 1 or 0,
                linedefined = isC and -1 or realLine,
                lastlinedefined = isC and -1 or realLine,
