            -- otherwise serialize it. Without this guard the env table
            -- would unfold into hundreds of lines in the dump.
            local argExpr
            if type(f) == "table" and dumperState.booboo_env_exprs[f] then
                argExpr = dumperState.booboo_env_exprs[f]
            else
                argExpr = serializeValue(f)
            end
            if options ~= nil then
                dumperState.booboo_env_exprs[result] = "debug.getinfo(" .. argExpr .. ", " .. serializeValue(options) .. ")"
