-- [v1.6] Content library: fromUri / fromAssetId / fromObject / none. Values are tracked proxies registered under
-- their constructor expression (so dumps print them verbatim) and typeof() reports "Content".
_G.Content = {}
do
    local C = _G.Content
    local function mk(reg, props)
        local proxy = createProxyObject("Content", false)
        dumperState.registry[proxy] = reg
        dumperState.property_store[proxy] = props
        return proxy
    end
    local function src(kind) return robloxApi.enumByPath("Enum.ContentSourceType." .. kind) end
    local function bad(fname, expected, ...)
        if select("#", ...) == 0 then
            error("missing argument #1 to '" .. fname .. "' (" .. expected .. " expected)", 3)
        end
        error("invalid argument #1 to '" .. fname .. "' (" .. expected .. " expected, got " .. typeof((...)) .. ")", 3)
    end
    C.fromUri = function(...)
        local uri = ...
        if typeFunction(uri) == "number" then uri = tostring(uri) end
        if typeFunction(uri) ~= "string" then bad("fromUri", "string", ...) end
        return mk(string.format("Content.fromUri(%s)", serializeValue(uri)), {Uri = uri, SourceType = src("Uri")})
    end
    C.fromAssetId = function(...)
        local id = ...
        if typeFunction(id) ~= "number" then bad("fromAssetId", "number", ...) end
        return mk(string.format("Content.fromAssetId(%s)", serializeValue(id)),
            {Uri = "rbxassetid://" .. string.format("%d", id), SourceType = src("Uri")})
    end
    C.fromObject = function(...)
        local obj = ...
        if not isProxy(obj) or typeof(obj) ~= "Instance" then bad("fromObject", "Object", ...) end
        return mk(string.format("Content.fromObject(%s)", serializeValue(obj)), {Object = obj, SourceType = src("Object")})
    end
    setmetatable(C, {__index = function(t, k)
        if k == "none" then
            local v = mk("Content.none", {SourceType = src("None")})
            rawset(t, "none", v)
            return v
        end
    end})
end
-- INLINER support for debug.getinfo (and getinfo) results.
-- The dumper unrolls `for k,v in t do ... end` by executing the body per
-- iteration. For a getinfo result that means the loop leaks the table's real
-- fields (source/what/...) into the output. Under INLINER we instead register
-- the result with its call expression and give it the same counting `__iter`
-- that getgenv/getrenv/getfenv and the stdlib tables already use, so the loop
-- no longer reveals the table's contents/source.
local function _inlinerFinalizeGetinfo(result, f)
    if not INLINER then return result end
    if typeFunction(result) ~= "table" then return result end
    -- Register the call expression so references reconstruct as debug.getinfo(<arg>).
    if dumperState.registry[result] == nil then
        local okSer, argExpr = pcallFunction(serializeValue, f)
        dumperState.registry[result] = "debug.getinfo(" .. ((okSer and argExpr) or "function() end") .. ")"
    end
    local mt = getMetatableFunction(result)
    if typeFunction(mt) == "table" then
        if not rawget(mt, "__iter_inliner_patched") then
            pcallFunction(function() mt.__iter_inliner_patched = true; mt.__iter = makeCountingIter(result) end)
        end
    else
        pcallFunction(setmetatable, result, { __iter = makeCountingIter(result), __iter_inliner_patched = true })
    end
    return result
end
do
    local _origGetinfo = exploitFuncs.getinfo
    exploitFuncs.getinfo = function(f, options)
        return _inlinerFinalizeGetinfo(_origGetinfo(f, options), f)
    end
    if typeFunction(exploitFuncs.debug) == "table" and exploitFuncs.debug.getinfo then
        local _origDbgGetinfo = exploitFuncs.debug.getinfo
        exploitFuncs.debug.getinfo = function(f, options)
            return _inlinerFinalizeGetinfo(_origDbgGetinfo(f, options), f)
        end
    end
end
for name, func in pairsFunction(exploitFuncs) do
    _G[name] = func
end

