local function safeNum(n)
    if typeFunction(n) == "table" and rawget(n, "__value") ~= nil then 
        return tonumber(rawget(n, "__value")) or 0 
    end
    return tonumber(n) or 0
end

local function safeStr(s)
    if s == nil then return "" end
    if typeFunction(s) == "table" and isProxyTable(s) then 
        return tostring(rawget(s, "__value") or "") 
    end
    return tostring(s)
end

local nativeBit32 = table.clone(bit32)
local bitLibrary = table.clone(nativeBit32)

local function toBit(n)
    n = safeNum(n)
    n = n % 4294967296
    if n < 0 then n = n + 4294967296 end
    return math.floor(n)
end

bitLibrary.tobit = toBit
bitLibrary.tohex = function(n, len) return string.format("%0" .. (len or 8) .. "x", toBit(n)) end

for k, v in pairsFunction(nativeBit32) do
    if typeFunction(v) == "function" then
        -- [PATCH:BIT32-ARGS] forward the caller's EXACT arguments (a missing / nil / non-numeric argument raises the
        -- engine's "missing argument #N" / "number expected, got X" instead of being silently coerced to 0);
        -- only datatype proxies carrying a numeric __value are unwrapped.
        bitLibrary[k] = function(...)
            local n = select("#", ...)
            local args
            local odd = n < 2
            for i = 1, n do
                local a = (select(i, ...))
                local ta = typeFunction(a)
                if ta == "table" then
                    if isProxy(a) then
                        error("invalid argument #" .. i .. " to '" .. k .. "' (number expected, got Instance)", 2)
                    end
                    local rv = rawget(a, "__value")
                    if rv ~= nil then args = args or {...}; args[i] = rv else odd = true end
                elseif ta ~= "number" then
                    odd = true
                end
            end
            -- odd arguments go through cleanCall so the native message carries no host path (obfuscated-input mode)
            if odd then
                if args then return robloxApi.cleanCall(v, 2, table.unpack(args, 1, n)) end
                return robloxApi.cleanCall(v, 2, ...)
            end
            if args then return v(table.unpack(args, 1, n)) end
            return v(...)
        end
    end
end
-- For the hot arithmetic operations (bxor/band/bor/bnot/lshift/rshift/lrotate/rrotate),
-- keep the native C function directly in bitLibrary so that the target script captures
-- a direct C reference rather than a Lua wrapper.  Any Lua-level wrapper adds ~100ns
-- per call; obfuscator VMs (MoonVeil etc.) call these hundreds of millions of times so
-- even a one-liner wrapper causes O(minutes) of overhead.
-- Proxy objects are never passed to arithmetic bit ops in practice, so the generic
-- wrapper's proxy-check/tonumber path is not needed here.
-- The hot ops keep the native C function on the fast path (numbers only, so
-- obfuscator VMs that call these hundreds of millions of times pay no wrapper
-- overhead) but, when a table/proxy argument IS passed, mirror Roblox's
-- "number expected, got Instance" error instead of leaking the raw Lua "table"
-- type (dtc93..97, 175..177).
do
    local function guarded(name, fn)
        return function(...)
            -- IMPORTANT: forward the caller's EXACT argument list. The old
            -- signature `function(a, b, ...)` + `fn(a, b, ...)` silently padded a
            -- missing second argument with nil, turning a legitimate one-argument
            -- call `bit32.band(x)` into `bit32.band(x, nil)` -- which native
            -- bit32 rejects ("number expected, got nil"). Obfuscator VMs
            -- (Luraph et al.) call the bit ops with a single argument during
            -- decoding, so that padding corrupted the decode and surfaced much
            -- later as a spurious band/bor nil error. Roblox never pads, so it
            -- "worked in Roblox but errored here" (improvement #1).
            local n = select("#", ...)
            local sawTable = false
            for i = 1, n do
                if typeFunction((select(i, ...))) == "table" then sawTable = true break end
            end
            if not sawTable then
                return fn(...)
            end
            -- [PATCH:BIT32-ARGS] errors below are raised through cleanCall (no host path under a raw native pcall)
            -- Slow path: a table/proxy argument was passed. Coerce datatype
            -- proxies that carry a numeric __value; error on everything else
            -- exactly as Roblox does (dtc3/1..3, dtc93..97), instead of
            -- silently defaulting to 0.
            local args = {...}
            for i = 1, n do
                local v = args[i]
                if typeFunction(v) == "table" then
                    if isProxy(v) then
                        error("invalid argument #" .. i .. " to '" .. name .. "' (number expected, got Instance)", 2)
                    end
                    local num = tonumber(rawget(v, "__value"))
                    if num == nil then
                        -- [PATCH:BIT32-ARGS] a plain table is left in place so the native function raises its own
                        -- argument-order-correct message ("missing argument #2" / "number expected, got table")
                        if envTableSet[v] then
                            error("invalid argument #" .. i .. " to '" .. name .. "' (number expected, got userdata)", 2)
                        end
                    else
                        args[i] = num
                    end
                end
            end
            return robloxApi.cleanCall(fn, 2, table.unpack(args, 1, n))
        end
    end
    bitLibrary.bxor    = guarded("bxor", nativeBit32.bxor)
    bitLibrary.band    = guarded("band", nativeBit32.band)
    bitLibrary.bor     = guarded("bor", nativeBit32.bor)
    bitLibrary.bnot    = guarded("bnot", nativeBit32.bnot)
    bitLibrary.lshift  = guarded("lshift", nativeBit32.lshift)
    bitLibrary.rshift  = guarded("rshift", nativeBit32.rshift)
    bitLibrary.lrotate = guarded("lrotate", nativeBit32.lrotate)
    bitLibrary.rrotate = guarded("rrotate", nativeBit32.rrotate)
    bitLibrary.countrz = bitLibrary.countrz and guarded("countrz", nativeBit32.countrz) or bitLibrary.countrz
    bitLibrary.countlz = bitLibrary.countlz and guarded("countlz", nativeBit32.countlz) or bitLibrary.countlz
end

bitLibrary.bswap = function(n)
    local val = toBit(n)
    local a = nativeBit32.band(nativeBit32.rshift(val, 24), 0xFF)
    local b = nativeBit32.band(nativeBit32.rshift(val, 8), 0xFF00)
    local c = nativeBit32.band(nativeBit32.lshift(val, 8), 0xFF0000)
    local d = nativeBit32.band(nativeBit32.lshift(val, 24), 0xFF000000)
    return toBit(nativeBit32.bor(nativeBit32.bor(a, b), nativeBit32.bor(c, d)))
end
robloxApi.genericArshift = bitLibrary.arshift -- [PATCH:BIT32-ARGS]
bitLibrary.arshift = function(...)
    local n, shift = ...
    if select("#", ...) < 2 or typeFunction(n) ~= "number" or typeFunction(shift) ~= "number" then
        if typeFunction(n) == "table" or typeFunction(shift) == "table" then return robloxApi.genericArshift(...) end
        return robloxApi.cleanCall(nativeBit32.arshift, 2, ...)
    end
    local nVal, sVal = n, shift
    
    local z = nativeBit32.arshift(toBit(nVal), sVal)
    -- [PATCH:ARSHIFT-UNSIGNED] bit32 results are unsigned: bit32.arshift(-8, 1) == 4294967292 (it used to return -4)
    return z
end

-- [v1.6] v1.5 exposed ONE table under both names (bit == bit32, and bit32.tobit / tohex / bswap existed -- members a
-- real client's bit32 does not have). bit32 is now Roblox's library; `bit` stays the executor-style superset.
do
    local _b32 = {}
    for _k, _v in pairsFunction(bitLibrary) do
        if _k ~= "tobit" and _k ~= "tohex" and _k ~= "bswap" then _b32[_k] = _v end
    end
    LG.bit32 = _b32
    bitLibrary.rol = bitLibrary.lrotate
    bitLibrary.ror = bitLibrary.rrotate
end
bit32 = LG.bit32
bit = bitLibrary
_G.bit = bitLibrary
_G.bit32 = LG.bit32
local tableLib = table.clone(table)

local originalTableCreate = table.create
if originalTableCreate then
    tableLib.create = function(...)
        local size, value = ...
        -- [PATCH:TABLE-CREATE] missing / non-numeric / negative sizes raise the engine's own message
        if select("#", ...) == 0 or (typeFunction(size) == "table" and rawget(size, "__value") == nil)
            or (typeFunction(size) ~= "table" and typeFunction(size) ~= "number") or (typeFunction(size) == "number" and size < 0) then
            return robloxApi.cleanCall(originalTableCreate, 2, ...)
        end
        local s = tonumber((typeFunction(size) == "table" and rawget(size, "__value")) or size) or 0
        
        -- [v1.6] sizes the engine rejects raise the engine's own error ("size out of range" for NaN / negative /
        -- beyond INT_MAX, "table overflow" above 2^26) instead of silently handing back an empty table
        if s ~= s or s < 0 or s > 67108864 then
            return robloxApi.cleanCall(originalTableCreate, 2, s, value)
        end
        if s > 16777216 then
            emitOutput(string.format("-- Prevented table.create crash: %s", tostring(s)))
            return {}
        end
        
        local success, res = pcallFunction(originalTableCreate, s, value)
        if success then return res end
        return {}
    end
end

if buffer and buffer.create then
    local _origBuf = table.clone(buffer)
    local safeBufferLib = table.clone(buffer)

    -- For obfuscated input the buffer library is (almost always) the
    -- obfuscator's own internal VM plumbing, not something the analysed program
    -- meaningfully does. Luraph v14.7 decodes and runs its inner bytecode
    -- through a `buffer`, issuing tens of thousands of readu8/writeu8 calls per
    -- build (one small v14.7 sample emitted 53k `buffer.*` lines, 52k of them
    -- `buffer.readu8`), which buries the real payload in noise. Mute the
    -- per-op buffer self-logging for obfuscated input -- the library still runs
    -- and returns real values so the VM unpacks -- and drop a single breadcrumb
    -- the first time it happens so the reader knows buffer plumbing ran.
    -- Hand-written scripts (not obfuscated) keep full, line-by-line buffer
    -- logging.
    local function emitBuf(line)
        if dumperState.input_is_obfuscated then
            if not dumperState.buffer_spam_noted then
                dumperState.buffer_spam_noted = true
                emitComment("buffer operations from obfuscated VM suppressed")
            end
            return
        end
        return emitOutput(line)
    end

    -- Buffer variable name tracking: tostring(buf) → varname
    local _bufVarNames = {}
    local _bufVarCount = 0
    local function _bufName(b)
        local key = tostring(b)
        if not _bufVarNames[key] then
            _bufVarCount = _bufVarCount + 1
            _bufVarNames[key] = _bufVarCount == 1 and "buf" or ("buf_" .. _bufVarCount)
        end
        return _bufVarNames[key]
    end
    local function _bufSer(b)
        if typeFunction(b) == "buffer" then return _bufName(b) end
        return serializeValue and serializeValue(b) or tostring(b)
    end

    safeBufferLib.create = function(...)
        local size = ...
        if select("#", ...) == 0 then error("missing argument #1 to 'create' (number expected)", 2) end
        if isProxy(size) then error("invalid argument #1 to 'create' (number expected, got Instance)", 2) end
        -- Non-numeric arguments (emulated-userdata env globals, plain tables)
        -- must error like Roblox rather than defaulting to a 0-length buffer
        -- (dtc3/8).
        local s = tonumber((typeFunction(size) == "table" and rawget(size, "__value")) or size)
        if s == nil then
            local got = envTableSet[size] and "userdata" or typeFunction(size)
            error("invalid argument #1 to 'create' (number expected, got " .. got .. ")", 2)
        end
        -- [PATCH:BASELIB] native: invalid size raises
        -- [v1.6] the size is truncated toward zero first (luaL_checkinteger): buffer.create(-0.5) is a valid empty buffer
        if s ~= s or s <= -1 or s > 1073741824 then error("invalid argument #1 to 'create' (size)", 2) end
        local ok, res = pcallFunction(_origBuf.create, s)
        local b = (ok and res) or _origBuf.create(0)
        local vn = _bufName(b)
        emitBuf(string.format("local %s = buffer.create(%s)", vn, tostring(s >= 0 and math.floor(s) or math.ceil(s))))
        return b
    end

    if _origBuf.fromstring then
        safeBufferLib.fromstring = function(str)
            if isProxy(str) then error("invalid argument #1 to 'fromstring' (string expected, got Instance)", 2) end
            local b = _origBuf.fromstring(str)
            local vn = _bufName(b)
            emitBuf(string.format("local %s = buffer.fromstring(%s)", vn, serializeBufferString(str)))
            return b
        end
    end

    if _origBuf.tostring then
        safeBufferLib.tostring = function(b)
            if isProxy(b) then error("invalid argument #1 to 'tostring' (buffer expected, got Instance)", 2) end
            emitBuf(string.format("buffer.tostring(%s)", _bufSer(b)))
            return _origBuf.tostring(b)
        end
    end

    if _origBuf.copy then
        safeBufferLib.copy = function(dst, dstOff, src, srcOff, count)
            emitBuf(string.format("buffer.copy(%s, %s, %s, %s, %s)",
                _bufSer(dst), tostring(dstOff), _bufSer(src), tostring(srcOff or 0), tostring(count or "nil")))
            return _origBuf.copy(dst, dstOff, src, srcOff, count)
        end
    end

    if _origBuf.fill then
        safeBufferLib.fill = function(b, off, val, count)
            emitBuf(string.format("buffer.fill(%s, %s, %s%s)",
                _bufSer(b), tostring(off), tostring(val), count ~= nil and (", " .. tostring(count)) or ""))
            return _origBuf.fill(b, off, val, count)
        end
    end

    local _origBufferLen = _origBuf.len
    safeBufferLib.len = function(b)
        if isProxy(b) then error("invalid argument #1 to 'len' (buffer expected, got Instance)", 2) end
        return _origBufferLen and _origBufferLen(b) or 0
    end

    -- Read operations: emit but still return the real value
    for _, op in ipairs({"readu8","readu16","readu32","readi8","readi16","readi32","readf32","readf64"}) do
        local orig = _origBuf[op]
        if orig then
            safeBufferLib[op] = function(b, offset)
                emitBuf(string.format("buffer.%s(%s, %s)", op, _bufSer(b), tostring(offset)))
                return orig(b, offset)
            end
        end
    end
    if _origBuf.readstring then
        safeBufferLib.readstring = function(b, offset, count)
            emitBuf(string.format("buffer.readstring(%s, %s, %s)", _bufSer(b), tostring(offset), tostring(count)))
            return _origBuf.readstring(b, offset, count)
        end
    end

    -- Write operations
    for _, op in ipairs({"writeu8","writeu16","writeu32","writei8","writei16","writei32","writef32","writef64"}) do
        local orig = _origBuf[op]
        if orig then
            safeBufferLib[op] = function(b, offset, value)
                emitBuf(string.format("buffer.%s(%s, %s, %s)", op, _bufSer(b), tostring(offset), tostring(value)))
                return orig(b, offset, value)
            end
        end
    end
    if _origBuf.writestring then
        safeBufferLib.writestring = function(b, offset, str, count)
            emitBuf(string.format("buffer.writestring(%s, %s, %s%s)",
                _bufSer(b), tostring(offset), serializeBufferString(str),
                count ~= nil and (", " .. tostring(count)) or ""))
            return _origBuf.writestring(b, offset, str, count)
        end
    end

    -- [PATCH:BUFFER-MISSING-ARG] a call with NO arguments must report the engine's "missing argument #1 to 'x'"
    -- (the wrappers above forward an explicit nil, which reads "got nil"). Tail calls keep error levels intact.
    for k, w in pairsFunction(table.clone(safeBufferLib)) do
        local o = _origBuf[k]
        if typeFunction(w) == "function" and typeFunction(o) == "function" and w ~= o then
            safeBufferLib[k] = function(...)
                if select("#", ...) == 0 then return robloxApi.cleanCall(o, 2) end
                return w(...)
            end
        end
    end
    _G.buffer = safeBufferLib
end

tableLib.getn = tableLib.getn or function(t) return #t end
tableLib.foreach = tableLib.foreach or function(t, func) for k, v in pairsFunction(t) do func(k, v) end end
tableLib.foreachi = tableLib.foreachi or function(t, func) for i, v in ipairsFunction(t) do func(i, v) end end
tableLib.move = tableLib.move or function(src, start, endIdx, dest, target)
