local _nativeByte = string.byte
local _nativeChar = string.char
local _nativeSub  = string.sub
local _nativeLen  = string.len
local _nativeFind = string.find
local _nativeStringSnapshot = table.clone(string)  -- snapshot of native string before wrappers
local stringLib = table.clone(string)
local charByteOnlyNumbers = {char = true, byte = true}
local _strFuncNames = {byte="byte", format="format", rep="rep", upper="upper", lower="lower",
    match="match", find="find", gsub="gsub", sub="sub", len="len", char="char", gmatch="gmatch",
    reverse="reverse", split="split", pack="pack"}
