local function _registerStringMethodResult(fname, result, src, args, nargs)
    if not (INLINER and dumperState.inliner_map) then return end
    if type(result) ~= "string" then return end
    if type(src) ~= "string" then return end
    local srcExpr = dumperState.inliner_map[src]
    if not srcExpr then return end
    local parts = {}
    for i = 1, nargs do
        local a = args[i]
        local at = typeFunction(a)
        if at == "string" or at == "number" or at == "boolean" or at == "nil" then
            parts[#parts + 1] = serializeValue(a)
        else
            -- Bail on complex args (function/table/userdata) — we don't
            -- have a faithful textual form for them here.
            return
        end
    end
    local expr = srcExpr .. ":" .. fname .. "(" .. table.concat(parts, ", ") .. ")"
    if not dumperState.inliner_map[result] then
        dumperState.inliner_map[result] = expr
    end
end
