            -- Check all varargs for proxy objects too
            local allArgs = {s, ...}
            for i = 2, #allArgs do
                if isProxy(allArgs[i]) then
                    local regName = dumperState and dumperState.registry and dumperState.registry[allArgs[i]]
                    local argTypeName = "Instance"
                    if regName then
