local originalStringUnpack = string.unpack
local _unpackCrashStreak = 0
local _MAX_UNPACK_CRASH_STREAK = 50
if originalStringUnpack then
    stringLib.unpack = function(fmt, s, pos)
        local resolvedFmt = tostring((typeFunction(fmt) == "table" and rawget(fmt, "__value")) or fmt)
        local resolvedS = tostring((typeFunction(s) == "table" and rawget(s, "__value")) or s)
        local resolvedPos = tonumber((typeFunction(pos) == "table" and rawget(pos, "__value")) or pos) or 1

        local results = table.pack(pcallFunction(originalStringUnpack, resolvedFmt, resolvedS, resolvedPos))
        local success = results[1]

        if success then
            _unpackCrashStreak = 0
            return table.unpack(results, 2, results.n)
        end

        _unpackCrashStreak = _unpackCrashStreak + 1

        -- A long unbroken run of failures means the target script entered a
        -- crash loop (env-check anti-deobf).  Flush whatever we have and exit
        -- cleanly rather than spinning for the full 60-second timeout.
        if _unpackCrashStreak >= _MAX_UNPACK_CRASH_STREAK then
            if dumperState and not dumperState.limit_reached then
                dumperState.limit_reached = true
                if flushPartialOutput then
                    pcall(flushPartialOutput,
                        "string.unpack crash loop detected (" .. _unpackCrashStreak ..
                        " consecutive failures); partial dump saved.", true, true)
                end
            end
            process.exit(0)
        end

        -- Only log the first few individual failures; once the streak is
        -- long we know it's a detection-triggered crash loop and stay quiet.
        if _unpackCrashStreak <= 3 then
            emitOutput(string.format("-- Prevented string.unpack crash: %s", tostring(results[2])))
        end

        local dummyReturns = {}
        local idx = 1

        for char in resolvedFmt:gmatch("[%a]") do
            if string.find("csz", char) then
                dummyReturns[idx] = ""
                idx = idx + 1
            elseif string.find("bBhHiIlLnfd", char) then
                dummyReturns[idx] = 0
                idx = idx + 1
            end
        end
        dummyReturns[idx] = resolvedPos + 1

        return table.unpack(dummyReturns, 1, idx)
    end
end

-- [PATCH:BASELIB] Native (C) library functions called from a Lua wrapper report the
-- wrapper's host path ("/.../envlogger:23860: missing argument #1 to 'abs'") where a real
-- client reports the *script* position (or none). cleanCall runs the native function under
-- pcall and re-raises string errors with the host-path prefix removed at `lvl` (the caller of
-- the wrapper, so the engine re-adds the script's own position).
robloxApi.cleanCall = function(fn, lvl, ...)
    local r = table.pack(pcallFunction(fn, ...))
    if r[1] then return table.unpack(r, 2, r.n) end
    local e = r[2]
    if typeFunction(e) == "string" and not e:find("TIMEOUT", 1, true) then
        local stripped, cnt = e:gsub("^[^:\n]*/[^:\n]*:%d+: ", "")
        -- [PATCH:CLEANCALL-LEVEL] `lvl` is counted from the *wrapper* (2 == the wrapper's caller); cleanCall is one frame
        -- deeper, so raise at lvl + 1. With lvl == 2 the position used to be the wrapper's own host-path line
        -- ("/home/..../envlogger:27556:"), visible through a raw native pcall (obfuscated-input mode).
        if cnt > 0 then errorFunction(stripped, lvl + 1) end
        -- bare native message (raised under pcall, so no position): the engine would have
        -- prefixed the calling script's position
        if not e:find("^[^\n]-:%d+: ") then errorFunction(e, lvl + 1) end
    end
    errorFunction(e, 0)
end
