        failed = setmetatable({}, {__mode = "k"}),  -- guarded threads that died with an error -> {errorValue}
        sy = setmetatable({}, {__mode = "k"}),      -- thread -> true while suspended by a script-level yield
        yv = setmetatable({}, {__mode = "k"}),      -- thread -> packed values of its last script-level yield
