    -- known URL (HttpGet). Scanning arbitrary deobfuscated code for short
    -- substrings like "dex" produces false positives on identifiers such
    -- as ZIndex/index, swapping the real payload for a Dex/Library stub
    -- and silently dropping the dump.
    local libName = nil
    if httpUrl then
        local lowerUrl = httpUrl:lower()
        local libs = {{pattern = "rayfield", name = "Rayfield"}, {pattern = "orion", name = "OrionLib"}, {pattern = "kavo", name = "Kavo"}, {pattern = "venyx", name = "Venyx"}, {pattern = "sirius", name = "Sirius"}, {pattern = "linoria", name = "Linoria"}, {pattern = "wally", name = "Wally"}, {pattern = "dex", name = "Dex"}, {pattern = "infinite", name = "InfiniteYield"}, {pattern = "hydroxide", name = "Hydroxide"}, {pattern = "simplespy", name = "SimpleSpy"}, {pattern = "remotespy", name = "RemoteSpy"}}
        for _, lib in ipairsFunction(libs) do if lowerUrl:find(lib.pattern) then libName = lib.name; break end end
    end

    if libName then
        local proxy = createProxyObject(libName, false)
        dumperState.registry[proxy] = libName
        dumperState.names_used[libName] = true
        return function() return proxy end
    end

    if httpUrl and httpUrl:match("^https?://") and code == httpUrl then
        -- Network access can be unavailable in a restricted runtime. Preserve
        -- the historical library placeholder only when HttpGet returned the URL
        -- itself, rather than replacing genuine fetched source.
        local proxy = createProxyObject("Library", false)
        emitOutput(string.format('local url = loadstring(game:HttpGet("%s"))()', httpUrl))
        return function() return proxy end
    end

    emitOutput(string.format("loadstring(%s)", serializeValue(code)))

    if typeFunction(code) == "string" then code = processString(code) end
    local okCompile, fnOrErr = pcallFunction(loadFunction, code, {
        debugName = chunkName or nextScriptSource(),
        environment = dumperState.script_env_table or dumperState.cached_genv or _G
    })
    if okCompile and typeFunction(fnOrErr) == "function" then
