require = function(module)
    dumperState.require_cache = dumperState.require_cache or {}

    if typeFunction(module) == "number" then
        error("invalid argument #1 to 'require' (ModuleScript expected, got number)", 2)
    end

    if dumperState.require_cache[module] then
        return dumperState.require_cache[module]
    end

    if typeFunction(module) == "string" and module:match("^@") then
        printFunction("[SECURITY] Blocked attempt to require host module: " .. module)
        error("path contains unsupported alias", 2)
    end

    if typeFunction(module) == "string" and (module == "lfs" or module == "ffi") then
        error("module '" .. module .. "' not found", 2)
    end

    local modName = dumperState.registry[module] or serializeValue(module)
    local proxy = createProxyObject("RequiredModule", false)
    local varName = registerVariable(proxy, "module")
    emitOutput(string.format("local %s = require(%s)", varName, modName))
    
    dumperState.require_cache[module] = proxy
    return proxy
end
