            rawItems[i] = tostring(typeFunction(val) == "table" and rawget(val, "__value") or val)
        end
    end
    emitOutput(string.format("warn(%s)", table.concat(items, ", ")))
    
    if dumperState and dumperState.event_callbacks and dumperState.event_callbacks["game.LogService.MessageOut"] then
        local msg = table.concat(rawItems, " ")
        local enumProxy = dumperState.enum_cache and dumperState.enum_cache["Enum.MessageType.MessageWarning"]
        if not enumProxy then
            enumProxy = robloxApi.enumByPath("Enum.MessageType.MessageWarning")
            dumperState.registry[enumProxy] = "Enum.MessageType.MessageWarning"
            dumperState.enum_cache = dumperState.enum_cache or {}
            dumperState.enum_cache["Enum.MessageType.MessageWarning"] = enumProxy
        end
        for _, cb in ipairsFunction(dumperState.event_callbacks["game.LogService.MessageOut"]) do
            xpcallFunction(function() cb(msg, enumProxy) end, function() end)
        end
    end
end
