    local meta = getMetatableFunction(Enum)
    meta.__call = function() error("attempt to call a Enums value", 2) end
    meta.__iter = function() error("attempt to iterate over a Enums value", 2) end
    meta.__len = function() error("attempt to get length of a Enums value", 2) end
    meta.__index = function(_, key)
        if key == proxyList or key == "__proxy_id" then return rawget(_, key) end
        -- [PATCH:ENUM-GETENUMS] Enums:GetEnums() returns every Enum category
        if key == "GetEnums" then
            return function(self)
                local names = {}
                for n in pairsFunction(knownEnumItems) do names[#names + 1] = n end
                table.sort(names)
                local out = {}
                for i, n in ipairsFunction(names) do out[i] = _[n] end
                return out
            end
        end
        local enumName = formatValue(key)
        if not knownEnumItems[enumName] then
            error(tostring(key) .. " is not a valid member of \"Enum\"", 2)
        end
        local fullEnum = "Enum." .. enumName
        dumperState.enum_cache = dumperState.enum_cache or {}
        if dumperState.enum_cache[fullEnum] then return dumperState.enum_cache[fullEnum] end

        local enumProxy = createProxyObject(fullEnum, false)
        dumperState.registry[enumProxy] = fullEnum
        dumperState.enum_cache[fullEnum] = enumProxy
        local catMeta = getMetatableFunction(enumProxy)
        local validItems = knownEnumItems[enumName]
        catMeta.__index = function(_, itemKey)
            if itemKey == proxyList or itemKey == "__proxy_id" then return rawget(_, itemKey) end
            if itemKey == "GetEnumItems" then
                return function(self)
                    local result = {}
                    for itemName in pairsFunction(validItems) do
                        -- Resolve through the normal item path so each item gets the
                        -- EnumItem metatable (Name/Value/EnumType) rather than a bare
                        -- proxy whose EnumType the generic guesser mis-resolves (eUNC).
                        table.insert(result, catMeta.__index(enumProxy, itemName))
                    end
                    -- [MANUAL] ordered by ascending Value (dtc56..60)
                    table.sort(result, function(a, b)
                        local va = a.Value; if typeFunction(va) ~= "number" then va = 0 end
                        local vb = b.Value; if typeFunction(vb) ~= "number" then vb = 0 end
                        if va == vb then return tostring(a.Name) < tostring(b.Name) end
                        return va < vb
                    end)
                    return result
                end
            end
            -- Enum reflection: FromName / FromValue / FromEnumValue return the
            -- matching EnumItem or nil, like the real engine (dtc160..163).
            if itemKey == "FromName" then
                return function(_, name)
                    local n = formatValue(name)
                    if not validItems[n] then return nil end
                    return catMeta.__index(enumProxy, n)
                end
            end
            if itemKey == "FromValue" or itemKey == "FromEnumValue" then
                return function(_, value)
                    local ev = enumItemValues[enumName]
                    if ev ~= nil then
                        for nm, v in pairsFunction(ev) do
                            if v == value then return catMeta.__index(enumProxy, nm) end
                        end
                    end
                    return nil
                end
            end
            local itemName = formatValue(itemKey)
            if not validItems[itemName] then
                -- [v1.7] LegacyNames: an old item name is an alias of the current item (same object)
                local _lg = robloxApi.enumLegacy and robloxApi.enumLegacy[enumName]
                if _lg and _lg[itemName] and validItems[_lg[itemName]] then itemName = _lg[itemName] end
            end
            if not validItems[itemName] then
                error(tostring(itemKey) .. " is not a valid EnumItem", 2)
            end
            local itemPath = fullEnum .. "." .. itemName
            dumperState.enum_cache = dumperState.enum_cache or {}
            if dumperState.enum_cache[itemPath] then return dumperState.enum_cache[itemPath] end
            local itemProxy = createProxyObject(itemPath, false)
            dumperState.registry[itemProxy] = itemPath
            dumperState.enum_cache[itemPath] = itemProxy
            local itemMeta = getMetatableFunction(itemProxy)
            itemMeta.__index = function(_, propKey)
                if propKey == proxyList or propKey == "__proxy_id" then return rawget(_, propKey) end
                if propKey == "Name" then return itemName end
                if propKey == "Value" then
                    local ev = enumItemValues[enumName]
                    if ev ~= nil then
                        local v = ev[itemName]
                        if v ~= nil then return v end
                    end
                    return 0
                end
                if propKey == "EnumType" then return enumProxy end
                error(tostring(propKey) .. " is not a valid member of EnumItem", 2)
            end
            return itemProxy
        end
        return enumProxy
    end
end
function proxyTable.get_output() return getFullOutput() end
function proxyTable.save(file) return saveToFile(file) end
function proxyTable.get_call_graph() return dumperState.call_graph end
function proxyTable.get_string_refs() return dumperState.string_refs end
function proxyTable.get_stats() return {total_lines = #dumperState.output, remote_calls = #dumperState.call_graph, suspicious_strings = #dumperState.string_refs, proxies_created = dumperState.proxy_id} end
local dumper = {callId = "azure_", binaryOperatorNames = {["and"] = "AND", ["or"] = "OR", [">"] = "GT", ["<"] = "LT", [">="] = "GE", ["<="] = "LE", ["=="] = "EQ", ["~="] = "NEQ", [".."] = "CAT"}}
function dumper:hook(code) return self.callId .. code end
function dumper:process_expr(expr)
    if not expr then return "nil" end
    if typeFunction(expr) == "string" then return expr end
    local tag = expr.tag or expr.kind
    if tag == "number" or tag == "string" then
        local val = tag == "string" and string.format("%q", expr.text) or (expr.value or expr.text)
        if configuration.CONSTANT_COLLECTION then return string.format("%sGET(%s)", self.callId, val) end
        return val
    end
    if tag == "local" or tag == "global" then return (expr.name or expr.token).text
    elseif tag == "boolean" or tag == "bool" then return toStringFunction(expr.value)
    elseif tag == "binary" then
        local lhs = self:process_expr(expr.lhsoperand)
        local rhs = self:process_expr(expr.rhsoperand)
        local op = expr.operator.text
        local opName = self.binaryOperatorNames[op]
        if opName then return string.format("%s%s(%s, %s)", self.callId, opName, lhs, rhs) end
        return string.format("(%s %s %s)", lhs, op, rhs)
    elseif tag == "call" then
        local func = self:process_expr(expr.func)
        local args = {}
        for i, node in ipairsFunction(expr.arguments) do args[i] = self:process_expr(node.node or node) end
        return string.format("%sCALL(%s, %s)", self.callId, func, table.concat(args, ", "))
    elseif tag == "indexname" or tag == "index" then
        local exprStr = self:process_expr(expr.expression)
        local keyStr = tag == "indexname" and string.format("%q", expr.index.text) or self:process_expr(expr.index)
        return string.format("%sCHECKINDEX(%s, %s)", self.callId, exprStr, keyStr)
    end
    return "nil"
end
function dumper:process_statement(stmt)
    if not stmt then return "" end
    local tag = stmt.tag
    if tag == "local" or tag == "assign" then
        local vars, vals = {}, {}
        for _, node in ipairsFunction(stmt.variables or {}) do table.insert(vars, self:process_expr(node.node or node)) end
        for _, node in ipairsFunction(stmt.values or {}) do table.insert(vals, self:process_expr(node.node or node)) end
        return (tag == "local" and "local " or "") .. table.concat(vars, ", ") .. " = " .. table.concat(vals, ", ")
    elseif tag == "block" then
        local stmts = {}
        for _, s in ipairsFunction(stmt.statements or {}) do table.insert(stmts, self:process_statement(s)) end
        return table.concat(stmts, "; ")
    end
    return self:process_expr(stmt) or ""
end
function proxyTable.dump_file(inputPath, outputPath)
    proxyTable.reset()
    dumperState.out_path = outputPath or configuration.OUTPUT_FILE
    emitComment("generated using luasive (discord.gg/sMsBFddH4y)")
    local success, code = pcall(function()
        return fs.readFile(inputPath)
    end)
    if not success or not code then return false end
    printFunction("[Dumper] Sanitizing Luau...")
    -- Detect whether the input is itself obfuscated. If yes, loadstring
    -- payloads inside (typically the decoded inner script) are NOT
    -- re-executed by the dumper — preserving the dump's original state.
    -- A clean script passing a small literal to loadstring still gets
    -- traced normally.
    do
        local nl = 0
        for _ in code:gmatch("\n") do nl = nl + 1 end
        local avgLine = #code / (nl + 1)
        local isObf = false
        if #code > 500 and avgLine > 250 then isObf = true end
        if #code > 5000 and code:find("bit32%.bxor") and code:find("loadstring") then isObf = true end
        if code:match('=%s*{%s*"[%x][%x][%x][%x][%x][%x]+"') then isObf = true end
        dumperState.input_is_obfuscated = isObf
    end

    -- dtc1 (GetProductInfo Name check): some scripts compare
    -- placeInfo.Name to a hardcoded "expected" name to fingerprint
    -- emulators that don't know the real game name. Instead of
    -- hardcoding the answer in the dumper, scan the input source for
    --   .Name == "literal" / .Name ~= "literal"
    --   local VAR = "literal" ... .Name [==/~=] VAR
    -- and feed the matched literal back through GetProductInfo so the
    -- comparison succeeds for any game name the script is testing.
    do
        local names = {}
        for s in code:gmatch('%.Name%s*[~=]=%s*"([^"]+)"') do
            table.insert(names, s)
        end
        for s in code:gmatch('"([^"]+)"%s*[~=]=%s*[%w_%.]+%.Name') do
            table.insert(names, s)
        end
        for varName, value in code:gmatch('local%s+([%w_]+)%s*=%s*"([^"]+)"') do
            local pat1 = '%.Name%s*[~=]=%s*' .. varName .. '[^%w_]'
            local pat2 = '[^%w_]' .. varName .. '%s*[~=]=%s*[%w_%.]+%.Name'
            if code:find(pat1) or code:find(pat2) then
                table.insert(names, value)
            end
        end
        dumperState.expected_game_names = names
    end
    local sanitized = processString(hookOpProcess(code))
    -- NOTE: hookfunction / getprotos / setconstant no longer rewrite the input.
    -- They operate on the live VM via the patched runtime's _vm primitives (see
    -- lune-fork), which works on any script form -- including obfuscated input --
    -- so the old source-level prologue injection has been removed.
    -- Store sanitized source for debug introspection (getconstants, getstack).
    -- Line numbers from debug.info correspond to the sanitized bytecode, so we
    -- index against sanitized rather than the raw input.
    dumperState.script_source = sanitized
    do
        local lines = {}
        for ln in (sanitized .. "\n"):gmatch("([^\n]*)\n") do lines[#lines+1] = ln end
        dumperState.script_lines = lines
    end
    
    local real_env = {
        _VERSION = "Luau",
        script = script, game = game, workspace = workspace,
        Instance = _G.Instance, CFrame = _G.CFrame, Vector3 = _G.Vector3,
        Vector2 = _G.Vector2, Color3 = _G.Color3, BrickColor = _G.BrickColor,
        UDim = _G.UDim, UDim2 = _G.UDim2, TweenInfo = _G.TweenInfo,
        Ray = _G.Ray, Rect = _G.Rect, Random = _G.Random, Enum = _G.Enum,
        Region3 = _G.Region3, Region3int16 = _G.Region3int16,
        NumberRange = _G.NumberRange, NumberSequence = _G.NumberSequence, NumberSequenceKeypoint = _G.NumberSequenceKeypoint,
        ColorSequence = _G.ColorSequence, ColorSequenceKeypoint = _G.ColorSequenceKeypoint,
        PhysicalProperties = _G.PhysicalProperties, Font = _G.Font, RaycastParams = _G.RaycastParams,
        OverlapParams = _G.OverlapParams, PathWaypoint = _G.PathWaypoint, Axes = _G.Axes, Faces = _G.Faces,
        Vector3int16 = _G.Vector3int16, Vector2int16 = _G.Vector2int16, CatalogSearchParams = _G.CatalogSearchParams,
        DateTime = _G.DateTime, SharedTable = _G.SharedTable, ValueCurveKey = _G.ValueCurveKey,
        FloatCurveKey = _G.FloatCurveKey, RotationCurveKey = _G.RotationCurveKey, SecurityCapabilities = _G.SecurityCapabilities, DockWidgetPluginGuiInfo = _G.DockWidgetPluginGuiInfo,
        ypcall = _G.ypcall, shared = _G.shared,
        bit32 = _G.bit32, math = _G.math, string = _G.string, table = _G.table,

        Content = _G.Content,
        SharedTable = SharedTable, ValueCurveKey = ValueCurveKey,
        FloatCurveKey = FloatCurveKey, RotationCurveKey = RotationCurveKey,
        SecurityCapabilities = SecurityCapabilities, DockWidgetPluginGuiInfo = DockWidgetPluginGuiInfo,
        PathWaypoint = _G.PathWaypoint, Axes = _G.Axes, Faces = _G.Faces,
        shared = {},
        task = task, debug = exploitFuncs.debug, pcall = pcall, xpcall = xpcall, pairs = pairs, ipairs = ipairs, unpack = _G.unpack or _G.table.unpack, -- [PATCH:UNPACK-IDENTITY]
       
        type = type, typeof = typeof,
        io = _G.io,
        process = _G.process,
        fs = _G.fs,
        net = _G.net,
        os = _G.os,
        coroutine = table.freeze(table.clone(_G.coroutine)),
        tick = _G.tick,
        time = _G.time,
        wait = _G.wait,
        delay = _G.delay,
        spawn = _G.spawn,
        getmetatable = _G.getmetatable,
        setmetatable = _G.setmetatable,
        tostring = _G.tostring,
        tonumber = _G.tonumber,
        azure_PUMP = internal_pump,
        azure_CHECKINDEX = function(tbl, key)
            local val = tbl[key]
            if typeFunction(val) == "table" and not dumperState.registry[val] then
                dumperState.ls_counter = dumperState.ls_counter + 1
                dumperState.registry[val] = "ls" .. dumperState.ls_counter
            end
            return val
        end,
        azure_GET = function(v) return v end,
        azure_CALL = function(f, ...)
            if dumperState.hooked_functions and dumperState.hooked_functions[f] then
                return dumperState.hooked_functions[f](...)
            end
            return f(...)
        end,
        azure_NAMECALL = function(t, method, ...) return t[method](t, ...) end,
        pcall = function(f, ...)
            if DEBUG_MODE then emitComment("called global: pcall") end

            local out_len_before = dumperState.output and #dumperState.output or 0
            local is_func = typeFunction(f) == "function"

            if is_func then
                emitOutput("pcall(function(...)")
                dumperState.indent = dumperState.indent + 1
            end

            if select(1, ...) == 1500 then return false, "Maximum re-entrancy depth exceeded" end
            local res = table.pack(xpcallFunction(f, robloxApi.errFix, ...))
            
            if is_func then
                dumperState.indent = dumperState.indent - 1
                
                local lines_added = #dumperState.output - out_len_before
                if lines_added == 1 then
                    dumperState.empty_pcall_count = (dumperState.empty_pcall_count or 0) + 1
                    if dumperState.empty_pcall_count > 3 then
                        table.remove(dumperState.output, #dumperState.output)
                        if #dumperState.output > 0 then
                            dumperState.last_emitted_line = dumperState.output[#dumperState.output]
                        end
                    else
                        emitOutput("end)")
                    end
                else
                    emitOutput("end)")
                end
            end

            if not res[1] then
                local errStr = toStringFunction(res[2])
                if errStr:match("TIMEOUT") then errorFunction(res[2], 0) end
                if errStr:match("C stack overflow") then res[2] = "Maximum re-entrancy depth exceeded" end
            end
            return table.unpack(res, 1, res.n)
        end,
        xpcall = function(f, errFunc, ...)
            if DEBUG_MODE then emitComment("called global: xpcall") end
            
            local out_len_before = dumperState.output and #dumperState.output or 0
            local is_func = typeFunction(f) == "function"
            
            if is_func then
                emitOutput("xpcall(function(...)")
                dumperState.indent = dumperState.indent + 1
            end
            
            local function wrapper(err)
                if typeFunction(err) == "string" and err:match("TIMEOUT_FORCED_BY_DUMPER") then return err end
                err = robloxApi.errFix(err)
                if errFunc then return errFunc(err) end
                return err
            end
            local res = table.pack(xpcallFunction(f, wrapper, ...))
            
            if is_func then
                dumperState.indent = dumperState.indent - 1
                
                local lines_added = #dumperState.output - out_len_before
                if lines_added == 1 then
                    dumperState.empty_pcall_count = (dumperState.empty_pcall_count or 0) + 1
                    if dumperState.empty_pcall_count > 3 then
                        table.remove(dumperState.output, #dumperState.output)
                        if #dumperState.output > 0 then
                            dumperState.last_emitted_line = dumperState.output[#dumperState.output]
                        end
                    else
                        if typeFunction(errFunc) == "function" then
                            local errName = dumperState.registry[errFunc] or "errHandler"
                            emitOutput("end, " .. errName .. ")")
                        else
                            emitOutput("end, function() end)")
                        end
                    end
                else
                    if typeFunction(errFunc) == "function" then
                        local errName = dumperState.registry[errFunc] or "errHandler"
                        emitOutput("end, " .. errName .. ")")
                    else
                        emitOutput("end, function() end)")
                    end
                end
            end

            if not res[1] and toStringFunction(res[2]):match("TIMEOUT") then errorFunction(res[2], 0) end
            return table.unpack(res, 1, res.n)
        end
    }
    
if HOOKOP_MODE then
    -- [v1.6 HookOP v2] Universal guest-check reconstruction (see hookop.luau).
    -- The pre-pass rewrites the guest with position-carrying hooks; this
    -- installs the matching runtime into a sandbox env. Shared by real_env
    -- (dump_file) and senv (dump_string): keep ONE implementation.
    if not LG.installHookOp then
        function LG.installHookOp(env, extraErrorFns)
            local nameOf = setmetatable({}, {__mode = "k"})
            local function mark(fn, nm) if typeFunction(fn) == "function" then nameOf[fn] = nm end end
            mark(errorFunction, "error"); mark(_G.error, "error"); mark(_G.assert, "assert")
            if extraErrorFns then for fn, nm in pairs(extraErrorFns) do mark(fn, nm) end end
            local function render(v)
                if typeFunction(v) == "table" and dumperState.registry[v] then return dumperState.registry[v] end
                local ok, r = pcall(serializeValue, v)
                if ok and typeFunction(r) == "string" then return r end
                return "nil"
            end
            local callSeen, callCount = {}, 0
            local rt
            rt = LG.hookRT.new({
                emit = function(text) emitOutput(text) end,
                -- structural closer: written into ITS buffer at ITS indent, and
                -- never dropped (a size/time limit must not unbalance the dump)
                emitAt = function(buf, ind, text)
                    local line = string.rep("    ", ind) .. text
                    if buf == dumperState.output and not dumperState.limit_reached then
                        local saved = dumperState.indent
                        dumperState.indent = ind
                        pcall(emitOutput, text)
                        dumperState.indent = saved
                        if buf[#buf] == line then return end
                    end
                    table.insert(buf, line)
                end,
                indent = function(d) dumperState.indent = math.max(0, dumperState.indent + d) end,
                getIndent = function() return dumperState.indent end,
                buffer = function() return dumperState.output end,
                render = function(op, a, b) return render(a) .. " " .. op .. " " .. render(b) end,
                nameof = function(fn) return nameOf[fn] end,
                -- Instance/datatype proxies: surface Roblox's message, not a raw Lua one
                cmpmsg = function(op, a, b)
                    if (op ~= "==" and op ~= "~=") and (isProxy(a) or isProxy(b)) then
                        return "attempt to compare two Instance values"
                    end
                end,
                -- error()/assert() line; text-deduped + capped (1000) as before.
                callline = function(nm, ...)
                    local argc = select("#", ...)
                    local saved = { ... }
                    local ok, line = pcall(function()
                        local parts = {}
                        for i = 1, argc do parts[i] = render(saved[i]) end
                        return string.format("%s(%s)", nm, table.concat(parts, ", "))
                    end)
                    if not ok or callSeen[line] or callCount >= 1000 then return nil end
                    callSeen[line] = true; callCount = callCount + 1
                    return line
                end,
            }, { profile = dumperState.hookop_profile, info = debugLibrary.info, retroCap = (function()
                local v = process.env and tonumber(process.env.HOOKOP_RETRO_CAP)
                if v and v >= 1 and v <= 64 then return math.floor(v) end
                return LG.cfg.HOOK_RETRO_CAP
            end)() })
            dumperState.hookop_rt = rt
            env.__HKC = rt.__HKC
            env.__HKIF, env.__HKEI = rt.__HKIF, rt.__HKEI
            env.__HKELSE, env.__HKEND = rt.__HKELSE, rt.__HKEND
            env.__HKX, env.__HKXR = rt.__HKX, rt.__HKXR
            env.HCALL = rt.HCALL
            return rt
        end
    end
    LG.installHookOp(real_env)
end

    for k, v in pairsFunction(exploitFuncs) do real_env[k] = v end
    for k, v in pairsFunction(_G) do if real_env[k] == nil then real_env[k] = v end end
    real_env.debug = exploitFuncs.debug
    real_env.pcall = _G.pcall
    real_env.xpcall = _G.xpcall
    real_env.error = errorFunction
    real_env.load = nil
    real_env.Logger = nil
    real_env.dofile = nil; real_env.loadfile = nil; real_env.originalError = nil -- [PATCH:LUAU-LIBS]
    pcall(table.freeze, exploitFuncs.debug); pcall(table.freeze, real_env.buffer or _G.buffer)
    do
        local _origRawget, _origRawset, _origRawlen, _origNext = rawget, rawset, rawlen, next
        real_env.rawget = function(...)
            -- [PATCH:BASELIB] native arity/type errors (missing #1/#2, got <type>)
            local _n = select("#", ...)
            if _n == 0 then error("missing argument #1 to 'rawget' (table expected)", 2) end
            local t, k = ...
            if typeFunction(t) ~= "table" then
                error("invalid argument #1 to 'rawget' (table expected, got " .. robloxApi.argTn(t) .. ")", 2)
            end
            if isProxy(t) then
                -- A proxy emulating a real Lua table (required module return,
                -- library table) may be rawget'd; Instance / datatype / Enum
                -- proxies are userdata and rawget on userdata errors in real
                -- Roblox (dtc38..45, 172, 173, 180, 182).
                local reg = dumperState.registry[t]
                local emulatesTable = typeFunction(reg) == "string"
                    and (reg:match("Module") or reg:match("Library") or reg:match("Invisicam"))
                if not emulatesTable then
                    error("invalid argument #1 to 'rawget' (table expected, got " .. robloxApi.argTn(t) .. ")", 2)
                end
                emitOutput(string.format("rawget(%s, %s)", reg, serializeValue(k)))
                return nil
            end
            if _n < 2 then error("missing argument #2", 2) end
            return _origRawget(t, k)
        end
        real_env.rawset = function(...)
            local _n = select("#", ...)
            if _n == 0 then error("missing argument #1 to 'rawset' (table expected)", 2) end
            local t, k, v = ...
            if typeFunction(t) ~= "table" or isProxy(t) then
                error("invalid argument #1 to 'rawset' (table expected, got " .. robloxApi.argTn(t) .. ")", 2)
            end
            if _n < 3 then error("missing argument #" .. (_n + 1), 2) end
            -- Log rawset when the table is a registered/known object (e.g. rawset on a rawmt).
            local tReg = dumperState.registry[t]
            if tReg then
                emitOutput(string.format("rawset(%s, %s, %s)", tReg, serializeValue(k), serializeValue(v)))
            end
            return _origRawset(t, k, v)
        end
        real_env.rawlen = function(t)
            if isProxy(t) or (typeFunction(t) ~= "table" and typeFunction(t) ~= "string") then
                error("invalid argument #1 to 'rawlen' (table or string expected)", 2)
            end
            return _origRawlen(t)
        end
        real_env.next = _G.next
    end

    local env = real_env
    local _envIterFn
    if INLINER then
        local _envCount = 0
        for _ in nextFunction, real_env do _envCount = _envCount + 1 end
        for k in nextFunction, _G do
            if real_env[k] == nil then _envCount = _envCount + 1 end
        end
        _envIterFn = makeCountingIterN(_envCount)
    end
    setmetatable(env, {
        __index = function(_, key)
            if key == "__lune" then return nil end
            if DEBUG_MODE and typeFunction(key) == "string" then
                emitComment("indexed: " .. key)
            end
            if robloxApi.hiddenHostGlobals[key] then return nil end
            return _G[key]
        end,
        __iter = _envIterFn,
        __metatable = "The metatable is locked"
    })
    -- [PATCH] getgenv() is the executor's shared global table, DISTINCT from the
    -- script's getfenv() environment. Lune resolves a chunk's globals by raw
    -- lookup on the env table (no metatable __index fallback), so getgenv writes
    -- are placed directly onto `env` -- making them visible as ordinary global
    -- reads (dtc1). Each injected key is tagged so getgenv() reads back only its
    -- OWN globals (plus standard ones), never values written through getfenv()
    -- -- which land on `env` unmarked and so stay invisible to getgenv (dtc2).
    local _genvKeys = {}
    -- Lune snapshots the load-time `environment` table into the chunk's real
    -- _ENV, so writes must target that live table (captured post-load as
    -- dumperState.script_env) for bare global reads to observe them.
    local function _genvTarget() return dumperState.script_env or env end
    local _realGenv = setmetatable({}, {
        __index = function(_, k)
            if _genvKeys[k] then return rawget(_genvTarget(), k) end
            if robloxApi.hiddenHostGlobals[k] then return nil end
            return _G[k]
        end,
        __newindex = function(_, k, v)
            emitOutput(string.format("getgenv().%s = %s", tostring(k), serializeValue(v)))
            _genvKeys[k] = true
            rawset(_genvTarget(), k, v)
        end,
        __metatable = "The metatable is locked",
    })
    env.getgenv = function()
        dumperState.booboo_envs = dumperState.booboo_envs or setmetatable({}, {__mode = "k"})
        dumperState.booboo_envs[_realGenv] = true
        if not dumperState._genv_var_declared then
            emitOutput("local genv = getgenv()")
            dumperState._genv_var_declared = true
        end
        if INLINER then
            dumperState.booboo_env_exprs = dumperState.booboo_env_exprs or {}
            dumperState.booboo_env_exprs[_realGenv] = "genv"
        end
        -- Distinct from getfenv(): the executor's shared global table.
        return _realGenv
    end
    env._G = {}
    env.__fenv_map = setmetatable({}, {__mode = "k"})
    -- The script's function environment is a DISTINCT table from the global
    -- environment (getgenv). Reads/writes chain to `env` so globals still
    -- resolve and getgenv-injected globals stay visible, but the two tables are
    -- not the same object -- getfenv() ~= getgenv() as on a real executor
    -- (dtc78).
    local _scriptFenv = setmetatable({}, {
        __index = env,
        __newindex = function(_, k, v) env[k] = v end,
        __metatable = "The metatable is locked",
    })
    env.getfenv = function(lvl)
        local level = lvl
        if level == nil then level = 1 end
        -- A rebound loadstring closure can call this exported wrapper directly.
        -- In that case the native stack frame is the wrapper itself, so consult
        -- the caller's tracked environment before falling back to the script env.
        if lvl == nil then
            -- The Lune debug API does not always expose a loaded chunk as the
            -- immediate caller, so retain the tracked-closure lookup when it is
            -- available. setfenv also installs a target-bound wrapper below for
            -- chunks whose global accesses were captured at compile time.
            local ok, caller = pcall(debugLibrary.info, 2, "f")
            if ok and type(caller) == "function" then
                local tracked = env.__fenv_map[caller]
                if tracked then return tracked end
            end
        end
        if not dumperState._getfenv_emitting and not dumperState._fenv_var_declared then
            dumperState._getfenv_emitting = true
            local arg = lvl ~= nil and tostring(lvl) or ""
            emitOutput(string.format("local fenv = getfenv(%s)", arg))
            dumperState._fenv_var_declared = true
            dumperState._getfenv_emitting = false
        end
        if INLINER then
            dumperState.booboo_envs = dumperState.booboo_envs or setmetatable({}, {__mode = "k"})
            dumperState.booboo_envs[_scriptFenv] = true
            dumperState.booboo_env_exprs = dumperState.booboo_env_exprs or {}
            dumperState.booboo_env_exprs[_scriptFenv] = "fenv"
        end
        if type(level) == "thread" then return _scriptFenv end
        if type(level) == "number" and level > 10 then error("invalid level", 2) end
        if type(level) == "function" then
            return env.__fenv_map[level] or _scriptFenv
        end
        if level == 0 then return _scriptFenv end
        local ok, caller = pcall(debugLibrary.info, level + 1, "f")
        if ok and type(caller) == "function" then
            local tracked = env.__fenv_map[caller]
            if tracked then return tracked end
        end
        return _scriptFenv
    end
    env.setfenv = function(f, envArg)
        if isProxy(f) or (type(f) ~= "function" and type(f) ~= "number") then
            error("'setfenv' cannot change environment of given object", 2)
        end
        if isProxy(envArg) or (envArg ~= nil and type(envArg) ~= "table") then
            error("invalid argument #2 to 'setfenv' (table expected, got " .. type(envArg) .. ")", 2)
        end
        if type(f) == "function" then
            if f == print or f == _G.print or f == warn or f == _G.warn or f == error or f == _G.error
                or f == tostring or f == _G.tostring or f == tonumber or f == _G.tonumber
                or f == type or f == _G.type or f == typeof or f == _G.typeof then
