    dumperState.builtin_tags[env.tostring or _G.tostring] = {name = "tostring", arity = {0, true}}
    dumperState.builtin_tags[env.tonumber or _G.tonumber] = {name = "tonumber", arity = {2, false}}
    dumperState.builtin_tags[env.type or _G.type] = {name = "type", arity = {1, false}}
