    dumperState.builtin_tags[senv.print or print] = {name = "print", arity = {0, true}}
    dumperState.builtin_tags[senv.warn or warn] = {name = "warn", arity = {0, true}}
    dumperState.builtin_tags[senv.tostring or _G.tostring] = {name = "tostring", arity = {0, true}}
