if args[1] then
    local success = proxyTable.dump_file(args[1], args[2])
    if success then
        printFunction("Saved to: " .. (args[2] or configuration.OUTPUT_FILE))
        local stats = proxyTable.get_stats()
        printFunction(string.format("Lines: %d | Remotes: %d | Strings: %d", stats.total_lines, stats.remote_calls, stats.suspicious_strings))
    end
else
    local exists = pcall(function() return fs.readFile("obfuscated.lua") end)
    if exists then
        local success = proxyTable.dump_file("obfuscated.lua")
        if success then
            printFunction("Saved to: " .. configuration.OUTPUT_FILE)
            printFunction(proxyTable.get_output())
        end
    else
        printFunction("Usage: lune run dumper.lua <input> [output] [key]")
    end
end
return proxyTable
